#!/usr/bin/env bash
# Also works as: /data/data/com.termux/files/usr/bin/bash
# ═══════════════════════════════════════════════════════════════════════════
# BB AI RECON ENGINE V8.0 IMMORTAL — 998 Modules (75 Base/Adv + 320 RedTeam + 220 BlackTeam + 20 Heal + 75 ExtTools + 288 CVE + 115 Core)
# ═══════════════════════════════════════════════════════════════════════════

# Ctrl+C kills immediately
trap 'echo -e "\n[!] TERMINATED BY USER (Ctrl+C) — SHUTTING DOWN"; kill -9 $$ 2>/dev/null; exit 1' INT

# Immortality: never exit on errors, but Ctrl+C always works
trap '' ERR
trap '' TERM
trap '' HUP
set +e
set +u
set +o pipefail
unset IFS

BASE="$HOME/bb_v7_ultimate"
mkdir -p "$BASE"

# =========================
# COLORS
# =========================
GREEN="\e[1;32m"
CYAN="\e[1;36m"
YELLOW="\e[1;33m"
RED="\e[1;31m"
MAGENTA="\e[1;35m"
WHITE="\e[1;37m"
BLUE="\e[1;34m"
RESET="\e[0m"

log(){ echo -e "${CYAN}[*]${RESET} $1"; }
ok(){ echo -e "${GREEN}[+]${RESET} $1"; }
run(){ echo -e "${YELLOW}[>]${RESET} $1"; }
err(){ echo -e "${RED}[!]${RESET} $1"; }
info(){ echo -e "${WHITE}[i]${RESET} $1"; }
adv(){ echo -e "${MAGENTA}[ADV]${RESET} $1"; }

# ═══════════════════════════════════════════════════════════════════════════
# ═══ UNIVERSAL TOOL INSTALLER & SELF-HEALING ENGINE ═══
# ═══════════════════════════════════════════════════════════════════════════

SCRIPT_START=$(date +%s)
SCAN_COUNT=0
HEAL_COUNT=0
SKIP_COUNT=0

heal(){ echo -e "${GREEN}[HEAL]${RESET} $1"; }

bt(){ echo -e "${MAGENTA}[BT]${RESET} $1"; }
rt(){ echo -e "${RED}[RT]${RESET} $1"; }

# Safe curl wrapper — GLOBAL for all modules
_curl() { curl --connect-timeout 15 --max-time 30 -s -L "$@" 2>/dev/null; }

# HTTP status checker — GLOBAL
_status() { _curl -o /dev/null -w "%{http_code}" "$1" 2>/dev/null || echo "000"; }

# Print section divider — GLOBAL
_section() {
    echo ""
    echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${RESET}"
    echo -e "${BLUE}  $1${RESET}"
    echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${RESET}"
}

install_tool() {
    local tool="$1"
    local pkg_name="${2:-$1}"
    info "Attempting to install: $tool (package: $pkg_name)..."
    if command -v pkg >/dev/null 2>&1; then
        pkg install -y "$pkg_name" >/dev/null 2>&1 && { ok "$tool installed via pkg"; return 0; }
    fi
    if command -v apt >/dev/null 2>&1; then
        apt-get update -qq >/dev/null 2>&1
        apt install -y "$pkg_name" >/dev/null 2>&1 && { ok "$tool installed via apt"; return 0; }
    fi
    if command -v apt-get >/dev/null 2>&1; then
        apt-get update -qq >/dev/null 2>&1
        apt-get install -y "$pkg_name" >/dev/null 2>&1 && { ok "$tool installed via apt-get"; return 0; }
    fi
    if command -v yum >/dev/null 2>&1; then
        yum install -y "$pkg_name" >/dev/null 2>&1 && { ok "$tool installed via yum"; return 0; }
    fi
    if command -v dnf >/dev/null 2>&1; then
        dnf install -y "$pkg_name" >/dev/null 2>&1 && { ok "$tool installed via dnf"; return 0; }
    fi
    if command -v pacman >/dev/null 2>&1; then
        pacman -Sy --noconfirm "$pkg_name" >/dev/null 2>&1 && { ok "$tool installed via pacman"; return 0; }
    fi
    if command -v apk >/dev/null 2>&1; then
        apk add --no-cache "$pkg_name" >/dev/null 2>&1 && { ok "$tool installed via apk"; return 0; }
    fi
    info "[SKIP] Cannot install $tool - continuing without it"
    SKIP_COUNT=$((SKIP_COUNT + 1))
    return 1
}

check_tool() {
    local tool="$1"
    local pkg="${2:-$1}"
    if ! command -v "$tool" >/dev/null 2>&1; then
        install_tool "$tool" "$pkg" || return 1
    fi
    command -v "$tool" >/dev/null 2>&1
}

# ─── 20 SELF-HEALING FUNCTIONS ───
heal_01_disk() {
    find /tmp -type f -mtime +1 -delete 2>/dev/null || true
    [ -d "$HOME/.cache" ] && find "$HOME/.cache" -type f -atime +7 -delete 2>/dev/null || true
    [ -d "$PREFIX/tmp" ] && find "$PREFIX/tmp" -type f -mtime +1 -delete 2>/dev/null || true
    heal "HEAL-01: Disk temp cleanup done"
}
heal_02_memory() {
    [ -f /proc/sys/vm/drop_caches ] && (echo 1 > /proc/sys/vm/drop_caches 2>/dev/null) || true
    (swapoff -a 2>/dev/null && swapon -a 2>/dev/null) || true
    heal "HEAL-02: Memory caches dropped"
}
heal_03_zombies() {
    local zombies=$(ps aux 2>/dev/null | awk '$8~/^[Zz]/ {print $2}' | head -20)
    [ -n "$zombies" ] && for z in $zombies; do kill -9 "$z" 2>/dev/null || true; done
    heal "HEAL-03: Zombie processes reaped"
}
heal_04_dns() {
    command -v resolvectl >/dev/null 2>&1 && resolvectl flush-caches 2>/dev/null || true
    touch /etc/resolv.conf 2>/dev/null || true
    heal "HEAL-04: DNS cache flushed"
}
heal_05_network() {
    [ -f /proc/net/tcp ] && awk '$4=="08" {print $10}' /proc/net/tcp 2>/dev/null | head -5 | while read p; do
        fuser -k "$((16#${p}))" 2>/dev/null || true
    done
    heal "HEAL-05: Stale connections cleared"
}
heal_06_logs() {
    for ldir in /var/log "$HOME/.local/share" "$PREFIX/var/log"; do
        [ -d "$ldir" ] || continue
        find "$ldir" -type f -size +50M -exec sh -c 'gzip -c "$1" > "${1}.old.gz" && : > "$1"' _ {} \; 2>/dev/null
    done
    heal "HEAL-06: Large logs rotated"
}
heal_07_orphans() {
    local pids=$(ps -eo pid,ppid,comm 2>/dev/null | awk '$2==1 && $3 ~ /(curl|wget)/ {print $1}' | head -10)
    [ -n "$pids" ] && for p in $pids; do kill -15 "$p" 2>/dev/null || true; done
    heal "HEAL-07: Orphaned processes cleaned"
}
heal_08_pipes() {
    find /tmp -type p 2>/dev/null | while read f; do (echo > "$f" 2>/dev/null) || rm -f "$f" 2>/dev/null || true; done
    heal "HEAL-08: Broken pipes cleaned"
}
heal_09_symlinks() {
    local c=0
    for d in /tmp "$HOME" "$PREFIX/tmp"; do
        [ -d "$d" ] || continue
        find "$d" -xtype l 2>/dev/null | head -20 | while read l; do rm -f "$l" 2>/dev/null && c=$((c+1)); done
    done
    heal "HEAL-09: Dangling symlinks removed"
}
heal_10_shm() {
    command -v ipcs >/dev/null 2>&1 && {
        ipcs -m 2>/dev/null | awk '/^0x/ {print $2}' | while read id; do ipcrm -m "$id" 2>/dev/null || true; done
        ipcs -s 2>/dev/null | awk '/^0x/ {print $2}' | while read id; do ipcrm -s "$id" 2>/dev/null || true; done
    }
    heal "HEAL-10: Shared memory cleaned"
}
heal_11_iface() {
    local iface=$(ip route 2>/dev/null | awk '/default/ {print $5; exit}')
    [ -n "$iface" ] && [ "$(cat /sys/class/net/${iface}/carrier 2>/dev/null || echo 0)" = "0" ] && {
        ip link set "$iface" down 2>/dev/null || true; sleep 1; ip link set "$iface" up 2>/dev/null || true
    }
    heal "HEAL-11: Network interface checked"
}
heal_12_inode() {
    [ -f /proc/sys/vm/drop_caches ] && (echo 2 > /proc/sys/vm/drop_caches 2>/dev/null) || true
    sync 2>/dev/null || true
    heal "HEAL-12: Inode cache freed"
}
heal_13_sessions() {
    [ -d "$HOME/bb_v7_ultimate" ] && find "$HOME/bb_v7_ultimate" -type d -mtime +7 -exec rm -rf {} + 2>/dev/null
    heal "HEAL-13: Old sessions purged"
}
heal_14_multiplexers() {
    command -v screen >/dev/null 2>&1 && screen -ls 2>/dev/null | grep -i dead | awk '{print $1}' | while read d; do screen -wipe "$d" 2>/dev/null || true; done
    command -v tmux >/dev/null 2>&1 && tmux kill-server 2>/dev/null || true
    heal "HEAL-14: Defunct multiplexers cleaned"
}
heal_15_pkgcache() {
    apt-get autoclean >/dev/null 2>&1 || true
    yum clean all >/dev/null 2>&1 || true
    pacman -Sc --noconfirm >/dev/null 2>&1 || true
    npm cache clean --force >/dev/null 2>&1 || true
    heal "HEAL-15: Package caches cleaned"
}
heal_16_dnspoison() {
    local gip=$(dig +short google.com A 2>/dev/null | head -1)
    case "$gip" in 127.*|10.*|172.1[6-9].*|172.2[0-9].*|172.3[0-1].*|192.168.*)
        heal_04_dns; heal "HEAL-16: DNS poisoning detected and flushed" ;;
    esac
}
heal_17_watchdog() {
    local pid=$$ mem=$(awk '/VmRSS/ {print $2}' /proc/$$/status 2>/dev/null || echo 0)
    [ "$mem" -gt 1048576 ] 2>/dev/null && { heal_02_memory; heal_12_inode; sync; heal "HEAL-17: Aggressive cleanup triggered"; }
}
heal_18_perms() {
    chmod 1777 /tmp 2>/dev/null || true
    chmod 755 "$HOME" 2>/dev/null || true
    [ -d "$PREFIX/tmp" ] && chmod 1777 "$PREFIX/tmp" 2>/dev/null || true
    heal "HEAL-18: Permissions fixed"
}
heal_19_thermal() {
    local tz=$(find /sys/class/thermal -name "thermal_zone*" -maxdepth 1 2>/dev/null | head -1)
    [ -n "$tz" ] && [ -f "${tz}/temp" ] && {
        local tc=$(($(cat "${tz}/temp" 2>/dev/null || echo 0) / 1000))
        [ "$tc" -gt 85 ] 2>/dev/null && { heal "HEAL-19: Throttling ${tc}C"; sleep 30; }
    }
}
heal_20_loopback() {
    ping -c 1 -W 2 127.0.0.1 >/dev/null 2>&1 || { ip link set lo up 2>/dev/null || ifconfig lo up 2>/dev/null || true; }
    [ ! -w /dev/null ] && chmod 666 /dev/null 2>/dev/null || true
    heal "HEAL-20: Loopback health verified"
}

run_all_healing() {
    heal "=== HEALING CYCLE #$HEAL_COUNT ==="
    heal_01_disk; heal_02_memory; heal_03_zombies; heal_04_dns; heal_05_network
    heal_06_logs; heal_07_orphans; heal_08_pipes; heal_09_symlinks; heal_10_shm
    heal_11_iface; heal_12_inode; heal_13_sessions; heal_14_multiplexers; heal_15_pkgcache
    heal_16_dnspoison; heal_17_watchdog; heal_18_perms; heal_19_thermal; heal_20_loopback
    HEAL_COUNT=$((HEAL_COUNT + 1))
}


