rt_01_dns_brute() {
    _section "[RT 1/30] DNS SUBDOMAIN BRUTEFORCE"
    run "Brute-forcing subdomains..."
    > "$SESSION/rt/dns_brute.txt"
    local WORDS=(www mail ftp admin api dev test staging backup db vpn git)
    local found=0
    for sub in "${WORDS[@]}"; do
        local ip=$(dig +short "${sub}.${TARGET}" A 2>/dev/null | head -1)
        [ -n "$ip" ] && { echo "${sub}.${TARGET} -> $ip" >> "$SESSION/rt/dns_brute.txt"; found=$((found+1)); }
    done
    [ "$found" -gt 0 ] && ok "$found subdomains found" && rt "DNS brute: $found"
}

rt_02_reverse_dns() {
    _section "[RT 2/30] REVERSE DNS SWEEP"
    run "Reverse DNS on /24..."
    > "$SESSION/rt/reverse_dns.txt"
    local bip=$(echo "$IP" | cut -d. -f1-3)
    [ "$bip" != "UNRESOLVED" ] && for i in $(seq 1 254); do
        local ptr=$(dig +short -x "${bip}.${i}" 2>/dev/null | head -1)
        [ -n "$ptr" ] && echo "${bip}.${i} -> $ptr" >> "$SESSION/rt/reverse_dns.txt"
    done
}

rt_03_asn_enum() {
    _section "[RT 3/30] ASN & BGP ENUM"
    run "ASN lookup..."
    whois -h whois.radb.net "!g$TARGET" 2>/dev/null > "$SESSION/rt/asn.txt" || whois "$IP" > "$SESSION/rt/asn.txt" 2>/dev/null
    curl -s "https://api.bgpview.io/ip/$IP" --connect-timeout 10 > "$SESSION/rt/bgp.json" 2>/dev/null
}

rt_04_cert_san() {
    _section "[RT 4/30] CERTIFICATE SAN EXTRACTION"
    run "Extracting SAN from TLS cert..."
    echo | openssl s_client -connect "$TARGET:443" -servername "$TARGET" 2>/dev/null |         openssl x509 -noout -text 2>/dev/null | grep -o "DNS:[^,]*" | sed 's/DNS://g' | sort -u > "$SESSION/rt/cert_san.txt"
}

rt_05_honeypot() {
    _section "[RT 5/30] HONEYPOT DETECTION"
    run "Checking for honeypot signs..."
    > "$SESSION/rt/honeypot.txt"
    local t1=$(curl -s -o /dev/null -w "%{time_total}" "https://$TARGET" --connect-timeout 10 2>/dev/null)
    local t2=$(curl -s -o /dev/null -w "%{time_total}" "https://$TARGET" --connect-timeout 10 2>/dev/null)
    local t3=$(curl -s -o /dev/null -w "%{time_total}" "https://$TARGET" --connect-timeout 10 2>/dev/null)
    [ -n "$t1" ] && [ -n "$t2" ] && [ -n "$t3" ] && {
        local d1=$(awk "BEGIN{d=$t1-$t2; if(d<0)d=-d; print d}")
        local d2=$(awk "BEGIN{d=$t2-$t3; if(d<0)d=-d; print d}")
        awk "BEGIN{exit !($d1 < 0.001 && $d2 < 0.001)}" &&             echo "SUSPICIOUS: Identical response times" >> "$SESSION/rt/honeypot.txt"
    }
    local unusual=0
    for p in 22 23 25 110 143 445 3306 3389 5900; do
        timeout 2 bash -c "echo > /dev/tcp/$TARGET/$p" 2>/dev/null && unusual=$((unusual+1))
    done
    [ "$unusual" -gt 5 ] && echo "SUSPICIOUS: $unusual unusual open ports" >> "$SESSION/rt/honeypot.txt"
}

rt_06_dir_brute() {
    _section "[RT 6/30] DIRECTORY BRUTEFORCE"
    run "Brute-forcing directories..."
    > "$SESSION/rt/dirs_found.txt"
    local DIRS=(admin api backup config db debug files upload wp-content phpmyadmin)
    for d in "${DIRS[@]}"; do
        local c=$(curl -s -o /dev/null -w "%{http_code}" "https://$TARGET/$d" --connect-timeout 8 2>/dev/null)
        [ "$c" = "200" ] || [ "$c" = "301" ] || [ "$c" = "403" ] && echo "[$c] /$d" >> "$SESSION/rt/dirs_found.txt"
    done
}

rt_07_param_fuzz() {
