    echo "$r2" | grep -qiE "success|admin" && echo "ROLE ASSIGNMENT" >> "$SESSION/rt/business_logic.txt"
}

rt_17_api_auth_bypass() {
    _section "[RT 17/30] API AUTH BYPASS"
    run "Testing auth bypass headers..."
    > "$SESSION/rt/api_auth_bypass.txt"
    local HDRS=("X-Original-URL:/admin" "X-Forwarded-For:127.0.0.1" "X-Client-IP:127.0.0.1")
