rt_37_subdomain_takeover_fingerprints() {
    _section "[RT 37/60] SUBDOMAIN TAKEOVER FINGERPRINTS"
    run "Checking for takeover-prone dangling subdomains..."
    > "$SESSION/rt/subdomain_takeover.txt"
    [ ! -s "$SESSION/recon/subdomains_all.txt" ] && { info "No subdomains to check"; return; }
    local SERVICES=("github.io:There isn't a GitHub Pages site here"
        "herokuapp.com:No such app"
        "azurewebsites.net:404 Web Site not found"
        "surge.sh:project not found"
        "bitbucket.io:Repository not found"
        "fastly.net:Fastly error: unknown domain"
        "cloudfront.net:Bad Request"
        "feedburner.com:The feed has not been found"
        "zendesk.com:Help Center Closed"
        "readme.io:Project doesnt exist"
        "myshopify.com:Sorry, this shop is currently unavailable"
        "statuspage.io:Statuspage"
        " ghost.io:404"
        " pantheon.io:404"
        " unbouncepages.com:The requested URL was not found on this server")
    while read -r sub; do
        [ -z "$sub" ] && continue
        local cname=$(dig +short "$sub" CNAME 2>/dev/null | head -1)
        [ -z "$cname" ] && continue
        for svc in "${SERVICES[@]}"; do
            local domain="${svc%%:*}" fingerprint="${svc##*:}"
            echo "$cname" | grep -qi "$domain" || continue
            local body=$(curl -s "http://$sub" --connect-timeout 10 --max-time 15 2>/dev/null)
            echo "$body" | grep -qi "$fingerprint" && \
                { echo "TAKEOVER: $sub → $cname ($domain)" >> "$SESSION/rt/subdomain_takeover.txt"; }
        done
    done < "$SESSION/recon/subdomains_all.txt"
    [ -s "$SESSION/rt/subdomain_takeover.txt" ] && rt "Subdomain takeover candidates found!"
}

