rt_60_http_method_override() {
    _section "[RT 60/60] HTTP METHOD OVERRIDE RCE"
    run "Testing X-HTTP-Method-Override for PUT/DELETE access..."
    > "$SESSION/rt/method_override.txt"
    local METHOD_OVERRIDES=("PUT" "DELETE" "PATCH" "TRACE")
    local OVERRIDES=("X-HTTP-Method-Override" "X-HTTP-Method" "X-Method-Override" "_method")
    for hdr in "${OVERRIDES[@]}"; do
        for method in "${METHOD_OVERRIDES[@]}"; do
            local code=$(curl -s -o /dev/null -w "%{http_code}" -X POST -H "$hdr: $method" "https://$TARGET/" --connect-timeout 8 2>/dev/null)
            [ "$code" = "200" ] || [ "$code" = "405" ] || [ "$code" = "204" ] && \
                echo "METHOD OVERRIDE: $hdr: $method -> HTTP $code" >> "$SESSION/rt/method_override.txt"
        done
    done
    # Test if PUT with override allows file upload
    local put_code=$(curl -s -o /dev/null -w "%{http_code}" -X POST -H "X-HTTP-Method-Override: PUT" -d "TEST" "https://$TARGET/upload.txt" --connect-timeout 8 2>/dev/null)
    [ "$put_code" = "200" ] || [ "$put_code" = "201" ] && \
        { echo "PUT override UPLOAD WORKS" >> "$SESSION/rt/method_override.txt"; rt "HTTP method override allows uploads!"; }
    [ -s "$SESSION/rt/method_override.txt" ] && rt "HTTP method override vectors found"
}

