rt_61_version_cve_lookup() {
    _section "[RT 61/85] VERSION-BASED CVE LOOKUP"
    run "Mapping detected technologies to known CVEs..."
    > "$SESSION/rt/version_cves.txt"
    local tech="$SESSION/advanced/tech_stack.txt"
    [ ! -f "$tech" ] && { info "No tech fingerprinting data"; return; }
    # Apache version CVEs
    local apache=$(grep -oiE "Apache/[0-9]\.[0-9]+\.[0-9]+" "$tech" 2>/dev/null | head -1)
    [ -n "$apache" ] && {
        local ver=$(echo "$apache" | sed 's/Apache\///')
        echo "Apache $ver -> CVE-2021-44790 (RCE if >=2.4.49), CVE-2021-41773 (path traversal if 2.4.49)" >> "$SESSION/rt/version_cves.txt"
        echo "$ver" | grep -qE "^2\.4\.4[9]" && echo "  CRITICAL: Path traversal CVE-2021-41773 APPLIES" >> "$SESSION/rt/version_cves.txt"
        echo "$ver" | grep -qE "^2\.4\.5[0-9]" && echo "  CRITICAL: RCE CVE-2021-44790 APPLIES" >> "$SESSION/rt/version_cves.txt"
    }
    # Nginx version CVEs
    local nginx=$(grep -oiE "nginx/[0-9]\.[0-9]+\.[0-9]+" "$tech" 2>/dev/null | head -1)
    [ -n "$nginx" ] && {
        local ver=$(echo "$nginx" | sed 's/nginx\///')
        echo "Nginx $ver -> CVE-2021-23017 (resolver off-by-one if <=1.20.0), CVE-2022-41741 (memory corruption)" >> "$SESSION/rt/version_cves.txt"
    }
    # PHP version CVEs
    local php=$(grep -oiE "PHP/[0-9]\.[0-9]+" "$tech" 2>/dev/null | head -1)
    [ -n "$php" ] && {
        local ver=$(echo "$php" | sed 's/PHP\///')
        echo "PHP $ver -> CVE-2019-11043 (RCE if PHP-FPM+Nginx), CVE-2020-7069, CVE-2021-21707" >> "$SESSION/rt/version_cves.txt"
        echo "$ver" | grep -qE "^7\.[0-3]" && echo "  CRITICAL: CVE-2019-11043 PHP-FPM RCE may apply" >> "$SESSION/rt/version_cves.txt"
    }
    # OpenSSL version
    local ssl=$(grep -oiE "OpenSSL/[0-9]\.[0-9]+\.[0-9]+[a-z]?" "$tech" 2>/dev/null | head -1)
    [ -n "$ssl" ] && {
        local ver=$(echo "$ssl" | sed 's/OpenSSL\///')
        echo "OpenSSL $ver -> CVE-2022-1292 (c_rehash RCE), CVE-2022-0778 (infinite loop), CVE-2023-0286 (X.400 name constraint)" >> "$SESSION/rt/version_cves.txt"
    }
    # WordPress version
    local wp=$(grep -oiE "WordPress [0-9]\.[0-9]+" "$tech" 2>/dev/null | head -1)
    [ -n "$wp" ] && {
        local ver=$(echo "$wp" | sed 's/WordPress //')
        echo "WordPress $ver -> CVE-2024-4439 (SSRF), CVE-2023-6553 (property deser RCE)" >> "$SESSION/rt/version_cves.txt"
    }
    # jQuery version
    local jq=$(grep -oiE 'jquery-[0-9]\.[0-9]+\.[0-9]+' "$SESSION/web/index.html" 2>/dev/null | head -1)
    [ -n "$jq" ] && {
        local ver=$(echo "$jq" | sed 's/jquery-//')
        echo "jQuery $ver -> CVE-2020-11022/11023 (XSS if <3.5.0), check for $.html() injection" >> "$SESSION/rt/version_cves.txt"
    }
    local cve_count=$(grep -c "CVE-" "$SESSION/rt/version_cves.txt" 2>/dev/null || echo 0)
    [ "$cve_count" -gt 0 ] && ok "$cve_count CVE mappings found" && rt "CVE lookup: $cve_count potential exploits"
}

rt_62_cve_2021_41773_apache_traversal() {
    _section "[RT 62/85] CVE-2021-41773 APACHE PATH TRAVERSAL"
    run "Testing Apache 2.4.49 path traversal..."
    > "$SESSION/rt/cve_2021_41773.txt"
