        local pids=()
        for i in $(seq 1 10); do
            (
                curl -skX POST --max-time 10 \
                    -H "Content-Type: application/json" \
                    -H "User-Agent: $UA" \
                    -d "{\"id\":\"test123\",\"amount\":1,\"coupon\":\"TEST\"}" \
                    "${target}${ep}" 2>/dev/null > "$OUTPUT_DIR/rt95_race_${ep//\//_}_${i}.txt"
