    if [[ -n "$dnskey" ]]; then
        echo "[DNSSEC] ${domain} has DNSKEY records" >> "$OUTPUT_DIR/rt103_dnssec_walk.txt"
        # Attempt NSEC walking
        local nsec; nsec=$(dig +short NSEC "$domain" 2>/dev/null | head -5)
        if [[ -n "$nsec" ]]; then
            echo "[DNSSEC-NSEC] ${domain} NSEC records found: ${nsec}" >> "$OUTPUT_DIR/rt103_dnssec_walk.txt"
        fi
        # NSEC3 check
        local nsec3; nsec3=$(dig +short NSEC3PARAM "$domain" 2>/dev/null | head -3)
        if [[ -n "$nsec3" ]]; then
            echo "[DNSSEC-NSEC3] ${domain} NSEC3PARAM found" >> "$OUTPUT_DIR/rt103_dnssec_walk.txt"
        fi
    else
        echo "[DNSSEC] ${domain} no DNSSEC" >> "$OUTPUT_DIR/rt103_dnssec_walk.txt"
    fi
}

