rt_120_zero_day_fuzz_harness() {
    local target="${1:-$TARGET}"
    echo "[RT-120] Zero-Day Fuzzing Harness"
    local fuzz_targets=('/api/' '/graphql' '/rest/' '/v1/' '/v2/' '/ws/' '/search' '/query' '/filter' '/sort')
    local mutation_chars=("%00" "%0d%0a" "%27" "%22" "%3c%3e" "%7b%7d" "%5b%5d" "%60" "$" "@" "!" "|" "&" ";" "#")
    local base_params=("id=1" "q=test" "search=test" "page=1" "limit=10" "offset=0" "sort=id")
    for ft in "${fuzz_targets[@]}"; do
        for mc in "${mutation_chars[@]}"; do
            for bp in "${base_params[@]}"; do
                local mutated; mutated=$(echo "$bp" | sed "s/=/${mc}=/g; s/1/${mc}1/g")
                local resp; resp=$(curl -sk --max-time 5 \
                    -H "User-Agent: $UA" \
                    "${target}${ft}?${mutated}" 2>/dev/null)
                if echo "$resp" | grep -qiE '(error|exception|stack|trace|debug|syntax|unexpected|fatal)'; then
                    echo "[FUZZ-HIT] ${ft}?${mutated} -> error page" >> "$OUTPUT_DIR/rt120_fuzz_harness.txt"
                fi
                if echo "$resp" | grep -qiE '(mysql|postgresql|sqlite|oracle|mssql|mongodb)'; then
                    echo "[FUZZ-DB] ${ft}?${mutated} -> database error" >> "$OUTPUT_DIR/rt120_fuzz_harness.txt"
                fi
            done
        done
    done
}


