bt_01_honeytoken_detector() {
    _section "[BT 1/30] HONEYTOKEN & CANARY DETECTOR"
    run "Scanning for deception artifacts..."
    > "$SESSION/bt/honeytokens.txt"
    local HONEY_PATTERNS=("honeytoken" "canary" "decoy" "HONEYPOT" "HONEYTOKEN"
        "test_user_" "decoy_admin" "canary_token" "bCanary" "Thinkst"
        "canarytokens.org" "honeydocs" "CanaryToken" "aws_canary")
    local resp=$(_curl "https://$TARGET" 2>/dev/null)
    for pat in "${HONEY_PATTERNS[@]}"; do
        echo "$resp" | grep -qi "$pat" && echo "HONEYTOKEN INDICATOR: '$pat' in page source" >> "$SESSION/bt/honeytokens.txt"
    done
    # Check for DNS canary patterns
    local dns_canary=$(dig +short "canary.$TARGET" A 2>/dev/null)
    [ -n "$dns_canary" ] && echo "DNS canary record: canary.$TARGET -> $dns_canary" >> "$SESSION/bt/honeytokens.txt"
    # Check for web beacon / tracking pixel patterns
    echo "$resp" | grep -oiE 'https?://canarytokens[^"]+' | head -5 >> "$SESSION/bt/honeytokens.txt"
    [ -s "$SESSION/bt/honeytokens.txt" ] && bt "Honeytoken/canary indicators detected"
}

bt_02_counter_surveillance() {
    _section "[BT 2/30] COUNTER-SURVEILLANCE CHECK"
    run "Detecting if this host is being monitored..."
    > "$SESSION/bt/counter_surveillance.txt"
    # Check for sniffers
    local promisc=$(ip link show 2>/dev/null | grep PROMISC | wc -l)
    [ "$promisc" -gt 0 ] && echo "PROMISCUOUS interfaces: $promisc (possible sniffer)" >> "$SESSION/bt/counter_surveillance.txt"
    # Check for suspicious processes
    local suspicious=$(ps aux 2>/dev/null | grep -iE "wireshark|tcpdump|tshark|ngrep|netsniff" | grep -v grep)
    [ -n "$suspicious" ] && echo "SNIFFER PROCESSES:\n$suspicious" >> "$SESSION/bt/counter_surveillance.txt"
    # Check auditd
    [ -f /var/log/audit/audit.log ] && echo "auditd active — commands being logged" >> "$SESSION/bt/counter_surveillance.txt"
    # Check for screen/session recorders
    local recorders=$(ps aux 2>/dev/null | grep -iE "script|asciinema|ttyrec|terminalizer" | grep -v grep)
    [ -n "$recorders" ] && echo "SESSION RECORDER: $recorders" >> "$SESSION/bt/counter_surveillance.txt"
    # Check last logins
    local last_logins=$(last -10 2>/dev/null | head -10)
    [ -n "$last_logins" ] && echo "Recent logins:\n$last_logins" >> "$SESSION/bt/counter_surveillance.txt"
    [ -s "$SESSION/bt/counter_surveillance.txt" ] && bt "Surveillance indicators found — OPSEC review needed"
}

bt_03_log_wiper() {
    _section "[BT 3/30] FORENSIC COUNTERMEASURES — LOG WIPE"
    run "Clearing scan evidence from local system..."
    > "$SESSION/bt/log_wipe.txt"
    # Remove bash history entries for this session
    [ -f "$HOME/.bash_history" ] && sed -i '/bb_recon_engine/d' "$HOME/.bash_history" 2>/dev/null
    [ -f "$HOME/.zsh_history" ] && sed -i '/bb_recon_engine/d' "$HOME/.zsh_history" 2>/dev/null
    # Clear termux history
    [ -f "$HOME/.termux/shell-termux.sh" ] && sed -i '/bb_recon/d' "$HOME/.termux/shell-termux.sh" 2>/dev/null
    # Clear recent tmp files
    find /tmp -name "bb_*" -type f -delete 2>/dev/null
    find /tmp -name "exif_*" -type f -delete 2>/dev/null
    # Wipe last command from shell history in memory
    history -d $(history 1 | awk '{print $1}') 2>/dev/null || true
    # Clear systemd journal for this boot
    [ -d /var/log/journal ] && journalctl --vacuum-time=1seconds 2>/dev/null || true
    bt "Local forensic traces wiped"
}

bt_04_timestamp_manipulator() {
    _section "[BT 4/30] TIMESTAMP ANTI-FORENSICS"
    run "Randomizing session file timestamps..."
    > "$SESSION/bt/timestamps.txt"
    # Randomize timestamps on session files to blend with system
    find "$SESSION" -type f 2>/dev/null | while read f; do
        local rdays=$((RANDOM % 30 + 1))
        local rhours=$((RANDOM % 24))
        local rmin=$((RANDOM % 60))
        touch -d "-${rdays} days ${rhours} hours ${rmin} minutes" "$f" 2>/dev/null || true
    done
    bt "Session timestamps randomized"
}

