    ss -tuln 2>/dev/null | head -20 >> "$SESSION/bt/network_topology.txt"
    # Check for Docker networks
    [ -f /var/run/docker.sock ] && echo "Docker socket accessible — container escape possible" >> "$SESSION/bt/network_topology.txt"
    # Check for Kubernetes service account
    [ -f /var/run/secrets/kubernetes.io/serviceaccount/token ] && {
        local k8s_ns=$(cat /var/run/secrets/kubernetes.io/serviceaccount/namespace 2>/dev/null)
        echo "INSIDE KUBERNETES POD — namespace: $k8s_ns" >> "$SESSION/bt/network_topology.txt"
        bt "KUBERNETES POD DETECTED — lateral movement available"
    }
    bt "Network topology mapped"
}

