bt_30_remote_desktop_credential_inject() {
    _section "[BT 30/30] RDP CREDENTIAL INJECTION / HASH RELAY"
    run "Testing RDP for Pass-the-Hash and credential injection..."
    > "$SESSION/bt/rdp_hash_relay.txt"
    timeout 3 bash -c "echo > /dev/tcp/$TARGET/3389" 2>/dev/null || { info "RDP :3389 closed"; return; }
    # Check for NLA (Network Level Auth) — if disabled = easier
    local nla_check=$(timeout 5 bash -c "
exec 3<>/dev/tcp/$TARGET/3389
# RDP connection request
printf '\x03\x00\x00\x13\x0e\xe0\x00\x00\x00\x00\x00\x01\x00\x08\x00\x03\x00\x00\x00' >&3
cat <&3" 2>/dev/null | xxd -p | tr -d '\n')
    [ -n "$nla_check" ] && {
        echo "RDP handshake captured: ${nla_check:0:40}" >> "$SESSION/bt/rdp_hash_relay.txt"
        # Check CredSSP/NLA requirement
        echo "$nla_check" | grep -qiE "0300|0301|0302" && echo "NLA likely enabled" >> "$SESSION/bt/rdp_hash_relay.txt" || echo "NLA may be disabled — easier access" >> "$SESSION/bt/rdp_hash_relay.txt"
    }
    # Check for xfreerdp availability
    command -v xfreerdp3 >/dev/null 2>&1 || command -v xfreerdp >/dev/null 2>/dev/null && {
        echo "xfreerdp available — can attempt PTH with /pth:hash" >> "$SESSION/bt/rdp_hash_relay.txt"
    }
    # Check for rdesktop
    command -v rdesktop >/dev/null 2>&1 && echo "rdesktop available" >> "$SESSION/bt/rdp_hash_relay.txt"
    bt "RDP credential injection vectors mapped"
}


