    # Check for CAP_SYS_ADMIN
    local caps=$(cat /proc/self/status 2>/dev/null | grep CapEff)
    [ -n "$caps" ] && echo "Capabilities: $caps" >> "$SESSION/bt/docker_escape.txt"
    [ -s "$SESSION/bt/docker_escape.txt" ] && bt "Container escape vectors found"
