# ═══════════════════════════════════════════════════════════════════════════
# ═══ 50 EXTERNAL PRIVATE TOOLS — RED TEAM + BLACK TEAM INTEGRATION ═══
# ═══════════════════════════════════════════════════════════════════════════
# Each tool: auto-install via OS package manager → execute real commands

# ─── TOOL INSTALLER WRAPPER ───
install_tool_wrapper() {
    local tool="$1"
    local pkg_name="${2:-$1}"
    command -v "$tool" >/dev/null 2>&1 && return 0
    info "Installing $tool..."
    if command -v apt >/dev/null 2>&1; then
        apt-get update -qq 2>/dev/null && apt-get install -y -qq "$pkg_name" 2>/dev/null && return 0
    elif command -v yum >/dev/null 2>&1; then
        yum install -y "$pkg_name" 2>/dev/null && return 0
    elif command -v dnf >/dev/null 2>&1; then
        dnf install -y "$pkg_name" 2>/dev/null && return 0
    elif command -v pacman >/dev/null 2>&1; then
        pacman -Sy --noconfirm "$pkg_name" 2>/dev/null && return 0
    elif command -v apk >/dev/null 2>&1; then
        apk add --no-cache "$pkg_name" 2>/dev/null && return 0
    elif command -v pkg >/dev/null 2>&1; then
        pkg install -y "$pkg_name" 2>/dev/null && return 0
    elif command -v brew >/dev/null 2>&1; then
        brew install "$pkg_name" 2>/dev/null && return 0
    fi
    # Try pip/go/npm as fallback
    pip3 install "$pkg_name" 2>/dev/null && return 0
    go install "github.com/projectdiscovery/${pkg_name}@latest" 2>/dev/null && return 0
    npm install -g "$pkg_name" 2>/dev/null && return 0
    return 1
}

