bt_79_memory_forensics() {
    _section "[BT-79] MEMORY FORENSICS — VOLATILE ANALYSIS"
    run "Performing volatile memory forensics..."
    > "$SESSION/bt/memory_forensics.txt"
    [ "$(id -u)" -ne 0 ] && { info "Memory forensics requires root"; return; }
    # Check for suspicious processes in memory
    local mem_suspicious=$(ps aux 2>/dev/null | grep -iE 'keylogger|rat|trojan|backdoor|rootkit|c2|meterpreter| Cobalt |empire|metasploit' | grep -v grep)
    [ -n "$mem_suspicious" ] && { echo "SUSPICIOUS PROCESSES:\n$mem_suspicious" >> "$SESSION/bt/memory_forensics.txt"; bt "Suspicious memory processes!"; }
    # Check /proc for injected code
    for pid_dir in /proc/[0-9]*; do
        local pid=$(basename "$pid_dir")
        [ -f "$pid_dir/maps" ] && grep -qE 'rwxp|deleted' "$pid_dir/maps" 2>/dev/null && {
            local cmdline=$(cat "$pid_dir/cmdline" 2>/dev/null | tr '\0' ' ')
            echo "PID $pid has RWX or deleted mappings: $cmdline" >> "$SESSION/bt/memory_forensics.txt"
        }
    done
    [ -s "$SESSION/bt/memory_forensics.txt" ] && bt "Memory forensics complete" || info "No memory anomalies"
}

