    _section "[BT-95] SMART CONTRACT EXPLOITATION"
    run "Detecting exposed smart contract interfaces..."
    > "$SESSION/bt/smart_contract.txt"
    local ENDPOINTS=("/api/web3" "/api/contract" "/web3" "/contract" "/rpc" "/api/v1/eth")
    for ep in "${ENDPOINTS[@]}"; do
        local resp=$(curl -skX POST --max-time 8 \
            -H "Content-Type: application/json" \
            -d '{"jsonrpc":"2.0","method":"eth_blockNumber","params":[],"id":1}' \
            "https://$TARGET${ep}" 2>/dev/null)
        echo "$resp" | grep -qiE '(result|0x[0-9a-f]+)"' && {
            echo "ETH RPC: $ep -> $(echo "$resp" | grep -oP '"result":"\K[^"]+' | head -1)" >> "$SESSION/bt/smart_contract.txt"
            rt "Ethereum RPC exposed at $ep!"
        }
    done
    # Check for hardcoded private keys
    local resp2=$(curl -sk --max-time 5 "https://$TARGET/" 2>/dev/null)
    echo "$resp2" | grep -oiE '0x[a-f0-9]{64}' | head -5 >> "$SESSION/bt/smart_contract.txt"
    [ -s "$SESSION/bt/smart_contract.txt" ] && bt "Smart contract vectors found" || info "No smart contract endpoints"
}

