bt_161_enterprise_hardening_assess() {
    local target="${1:-$TARGET}"
    _section "[BT-161] ENTERPRISE HARDENING ASSESSMENT"
    run "Analyzing enterprise security hardening measures..."
    > "$SESSION/bt/enterprise_hardening.txt"
    # Check for common enterprise security indicators
    local headers=$(curl -skI --max-time 10 "https://${target}/" 2>/dev/null)
    [ -n "$headers" ] && {
        echo "=== ENTERPRISE SECURITY HEADERS ===" >> "$SESSION/bt/enterprise_hardening.txt"
        echo "$headers" | grep -iE 'x-frame-options|content-security-policy|strict-transport-security|x-content-type-options|referrer-policy|permissions-policy' >> "$SESSION/bt/enterprise_hardening.txt"
        echo "" >> "$SESSION/bt/enterprise_hardening.txt"
        echo "=== COOKIE SECURITY FLAGS ===" >> "$SESSION/bt/enterprise_hardening.txt"
        echo "$headers" | grep -i 'set-cookie' >> "$SESSION/bt/enterprise_hardening.txt"
    }
    # Check for WAF presence
    local waf_sig=$(curl -skI --max-time 10 "https://${target}/?test=<script>alert(1)</script>" 2>/dev/null)
    [ -n "$waf_sig" ] && {
        echo "" >> "$SESSION/bt/enterprise_hardening.txt"
        echo "=== WAF RESPONSE ANALYSIS ===" >> "$SESSION/bt/enterprise_hardening.txt"
        echo "$waf_sig" | grep -iE 'server|x-powered-by|x-amz|cf-ray|x-waf|x-firewall' >> "$SESSION/bt/enterprise_hardening.txt"
    }
    # Test for rate limiting
    for i in 1 2 3; do
        local resp=$(curl -skI --max-time 8 "https://${target}/" 2>/dev/null | head -1)
        [ -n "$resp" ] && echo "Rate limit test $i: $resp" >> "$SESSION/bt/enterprise_hardening.txt"
    done
    [ -s "$SESSION/bt/enterprise_hardening.txt" ] && bt "Enterprise hardening analysis complete" || info "Enterprise hardening minimal"
}

bt_162_compliance_gap_analysis() {
    local target="${1:-$TARGET}"
    _section "[BT-162] COMPLIANCE GAP ANALYSIS"
    run "Checking regulatory compliance indicators (PCI DSS, SAMA, ISO 27001)..."
    > "$SESSION/bt/compliance_gap.txt"
    # SSL/TLS compliance check
    local ssl_info=$(timeout 10 openssl s_client -connect "${target}:443" -servername "${target}" 2>/dev/null | openssl x509 -noout -text 2>/dev/null)
    [ -n "$ssl_info" ] && {
        echo "=== SSL/TLS COMPLIANCE ===" >> "$SESSION/bt/compliance_gap.txt"
        local key_size=$(echo "$ssl_info" | grep "Public-Key" | grep -oP '\d+' | head -1)
        local sig_algo=$(echo "$ssl_info" | grep "Signature Algorithm" | head -1)
        [ -n "$key_size" ] && echo "Key Size: ${key_size} bits (PCI requires 2048+)" >> "$SESSION/bt/compliance_gap.txt"
        [ -n "$sig_algo" ] && echo "Signature: $sig_algo" >> "$SESSION/bt/compliance_gap.txt"
    }
    # Check for HTTPS enforcement
    local http_resp=$(curl -skI --max-time 8 "http://${target}/" 2>/dev/null | head -1)
    local https_resp=$(curl -skI --max-time 8 "https://${target}/" 2>/dev/null | head -1)
    echo "" >> "$SESSION/bt/compliance_gap.txt"
    echo "=== PROTOCOL ENFORCEMENT ===" >> "$SESSION/bt/compliance_gap.txt"
    [ -n "$http_resp" ] && echo "HTTP response: $http_resp" >> "$SESSION/bt/compliance_gap.txt"
    [ -n "$https_resp" ] && echo "HTTPS response: $https_resp" >> "$SESSION/bt/compliance_gap.txt"
    # Check HSTS preload eligibility
    local hsts=$(curl -skI --max-time 8 "https://${target}/" 2>/dev/null | grep -i "strict-transport-security")
    [ -n "$hsts" ] && echo "HSTS: $hsts" >> "$SESSION/bt/compliance_gap.txt" || echo "HSTS: MISSING (compliance gap)" >> "$SESSION/bt/compliance_gap.txt"
    [ -s "$SESSION/bt/compliance_gap.txt" ] && bt "Compliance gap analysis complete" || info "Compliance check minimal"
}

bt_163_dns_security_deep() {
    local target="${1:-$TARGET}"
    _section "[BT-163] DNS SECURITY DEEP ANALYSIS"
    run "Analyzing DNSSEC, SPF, DMARC, DKIM for enterprise mail security..."
    > "$SESSION/bt/dns_security_deep.txt"
    # DNSSEC check
    local dnssec=$(dig @8.8.8.8 +short "${target}" DNSKEY 2>/dev/null)
    [ -n "$dnssec" ] && echo "DNSSEC: ENABLED" >> "$SESSION/bt/dns_security_deep.txt" || echo "DNSSEC: NOT ENABLED" >> "$SESSION/bt/dns_security_deep.txt"
    # SPF record
    local spf=$(dig @8.8.8.8 +short "${target}" TXT 2>/dev/null | grep "v=spf1")
    [ -n "$spf" ] && echo "SPF: $spf" >> "$SESSION/bt/dns_security_deep.txt" || echo "SPF: MISSING" >> "$SESSION/bt/dns_security_deep.txt"
    # DMARC record
    local dmarc=$(dig @8.8.8.8 +short "_dmarc.${target}" TXT 2>/dev/null)
    [ -n "$dmarc" ] && echo "DMARC: $dmarc" >> "$SESSION/bt/dns_security_deep.txt" || echo "DMARC: MISSING" >> "$SESSION/bt/dns_security_deep.txt"
    # DKIM selectors (common)
    for selector in default mail google dkim selector1 selector2; do
        local dkim=$(dig @8.8.8.8 +short "${selector}._domainkey.${target}" TXT 2>/dev/null)
        [ -n "$dkim" ] && echo "DKIM ($selector): $dkim" >> "$SESSION/bt/dns_security_deep.txt"
    done
    # MX records with priority
    local mx=$(dig @8.8.8.8 +short "${target}" MX 2>/dev/null)
    [ -n "$mx" ] && echo "" >> "$SESSION/bt/dns_security_deep.txt" && echo "MX RECORDS:" >> "$SESSION/bt/dns_security_deep.txt" && echo "$mx" >> "$SESSION/bt/dns_security_deep.txt"
    # MTA-STS check
    local mtasts=$(curl -sk --max-time 8 "https://mta-sts.${target}/.well-known/mta-sts.txt" 2>/dev/null)
    [ -n "$mtasts" ] && echo "" >> "$SESSION/bt/dns_security_deep.txt" && echo "MTA-STS:" >> "$SESSION/bt/dns_security_deep.txt" && echo "$mtasts" >> "$SESSION/bt/dns_security_deep.txt"
    [ -s "$SESSION/bt/dns_security_deep.txt" ] && bt "DNS security deep analysis complete" || info "DNS security check minimal"
}

bt_164_infrastructure_intel() {
    local target="${1:-$TARGET}"
    _section "[BT-164] INFRASTRUCTURE INTELLIGENCE"
    run "Gathering hosting, CDN, WAF, and cloud infrastructure intel..."
    > "$SESSION/bt/infra_intel.txt"
    # IP and hosting info
    local ip=$(dig @8.8.8.8 +short "${target}" A 2>/dev/null | head -1)
    [ -n "$ip" ] && {
        echo "IP: $ip" >> "$SESSION/bt/infra_intel.txt"
        # ASN lookup
        local asn=$(whois -h whois.radb.net "$ip" 2>/dev/null | grep -oP 'origin:\s*AS\K[0-9]+' | head -1)
        [ -n "$asn" ] && echo "ASN: AS$asn" >> "$SESSION/bt/infra_intel.txt"
        # IP geolocation
        local geo=$(curl -sk --max-time 6 "https://ipinfo.io/${ip}/json" 2>/dev/null | grep -oE '"(city|region|country|org)":"[^"]*"' | head -4)
        [ -n "$geo" ] && echo "GEO: $geo" >> "$SESSION/bt/infra_intel.txt"
    }
    # Server technology fingerprinting
    local srv=$(curl -skI --max-time 8 "https://${target}/" 2>/dev/null | grep -i "server:")
    [ -n "$srv" ] && echo "SERVER: $srv" >> "$SESSION/bt/infra_intel.txt"
    # CDN detection via headers
    local cdn=$(curl -skI --max-time 8 "https://${target}/" 2>/dev/null | grep -iE 'cf-ray|x-amz-cf-id|x-akamai|x-cdn|x-fastly|x-cache|x-edge|x-vercel|x-nextjs|netlify')
    [ -n "$cdn" ] && echo "CDN/WAF: $cdn" >> "$SESSION/bt/infra_intel.txt"
    # WAF detection
    local waf=$(curl -skI --max-time 8 "https://${target}/?test=../../etc/passwd" 2>/dev/null | grep -iE 'x-waf|x-firewall|blocked|denied|mod_security|imperva|akamai|cloudflare|f5|big-ip')
    [ -n "$waf" ] && echo "WAF TRIGGERED: $waf" >> "$SESSION/bt/infra_intel.txt"
    [ -s "$SESSION/bt/infra_intel.txt" ] && bt "Infrastructure intelligence complete" || info "Infra intel minimal"
}

bt_165_certificate_transparency_recon() {
