        echo "$ct_subs" | grep -oP '"name_value":\s*"[^"]*"' | sed 's/"name_value":\s*"//;s/"$//' | sort -u | head -50 >> "$SESSION/bt/ct_recon.txt"
        local ct_count=$(echo "$ct_subs" | grep -o '"name_value"' | wc -l)
