        echo "=== CENSYS CERTIFICATE DATA ===" >> "$SESSION/bt/ct_recon.txt"
        echo "$censys" | grep -oP '"[a-z0-9_-]+\.${target}"' | sort -u | head -25 >> "$SESSION/bt/ct_recon.txt"
    }
    [ -s "$SESSION/bt/ct_recon.txt" ] && bt "Certificate transparency recon complete ($ct_count entries)" || info "CT recon minimal"
}

