bt_175_wp_plugin_theme_vuln() {
    local target="${1:-$TARGET}"
    _section "[BT-175] WORDPRESS PLUGIN/THEME VULNERABILITY CHECK"
    run "Checking detected plugins and themes against known vulnerabilities..."
    > "$SESSION/bt/wp_vulns.txt"
    # Get theme version
    local theme_info=$(curl -sk --max-time 10 "https://${target}/wp-content/themes/" 2>/dev/null)
    [ -n "$theme_info" ] && echo "THEME DIR LISTING: $theme_info" >> "$SESSION/bt/wp_vulns.txt"
    # Check readme files for version disclosure
    local readme=$(curl -sk --max-time 8 "https://${target}/readme.html" 2>/dev/null | grep -oP 'Version [0-9.]+' | head -1)
    [ -n "$readme" ] && echo "WP VERSION (readme): $readme" >> "$SESSION/bt/wp_vulns.txt"
    # Check for known vulnerable paths
    local vuln_paths=(
        "/wp-content/plugins/akismet/readme.txt"
        "/wp-content/plugins/jetpack/readme.txt"
        "/wp-content/plugins/yoast-seo/readme.txt"
        "/wp-content/plugins/elementor/readme.txt"
        "/wp-content/plugins/wordfence/readme.txt"
        "/wp-content/plugins/wp-super-cache/readme.txt"
        "/wp-content/plugins/contact-form-7/readme.txt"
    )
    for path in "${vuln_paths[@]}"; do
        local vresp=$(curl -skI --max-time 5 "https://${target}${path}" 2>/dev/null | head -1)
        [[ "$vresp" == *200* ]] && echo "PLUGIN FOUND: $path — $vresp" >> "$SESSION/bt/wp_vulns.txt"
    done
    # Check for TimThumb (historical RCE)
    local timthumb=$(curl -skI --max-time 5 "https://${target}/wp-content/themes/timthumb.php" 2>/dev/null | head -1)
    [[ "$timthumb" == *200* ]] && echo "TIMTHUMB: POTENTIALLY PRESENT — $timthumb" >> "$SESSION/bt/wp_vulns.txt"
    # Check for upload directory listing
    local upload_dir=$(curl -sk --max-time 8 "https://${target}/wp-content/uploads/" 2>/dev/null)
    [ -n "$upload_dir" ] && echo "UPLOAD DIR: Directory listing may be enabled" >> "$SESSION/bt/wp_vulns.txt"
    [ -s "$SESSION/bt/wp_vulns.txt" ] && bt "Plugin/theme vulnerability check complete" || info "WP vuln check minimal"
