bt_177_wp_external_link_hijack() {
    local target="${1:-$TARGET}"
    _section "[BT-177] WORDPRESS EXTERNAL LINK HIJACK DETECTION"
    run "Scanning for external links pointing to hijacked/compromised domains..."
    > "$SESSION/bt/wp_link_hijack.txt"
    # Extract all external links from homepage
    local links=$(curl -sk --max-time 15 "https://${target}/" 2>/dev/null | grep -oP 'https?://[^"<>\s]+' | grep -v "${target}\|wordpress.com\|wp.com\|gravatar.com\|w.org\|gmpg.org\|schema.org\|w3.org\|mozilla.org" | sort -u)
    [ -n "$links" ] && {
        echo "=== EXTERNAL LINKS FOUND ===" >> "$SESSION/bt/wp_link_hijack.txt"
        echo "$links" | head -30 >> "$SESSION/bt/wp_link_hijack.txt"
        echo "" >> "$SESSION/bt/wp_link_hijack.txt"
        echo "=== REDIRECT ANALYSIS ===" >> "$SESSION/bt/wp_link_hijack.txt"
        # Check each external domain for redirects
        local domains=$(echo "$links" | grep -oP 'https?://\K[^/]+' | sort -u | head -10)
        for domain in $domains; do
            local redirect=$(curl -skI --max-time 10 -L "http://${domain}/" 2>/dev/null | grep -i "location" | tail -1)
            [ -n "$redirect" ] && echo "$domain REDIRECTS TO: $redirect" >> "$SESSION/bt/wp_link_hijack.txt"
            # Check if domain resolves
            local resolved=$(dig @8.8.8.8 +short "$domain" A 2>/dev/null | head -1)
            [ -z "$resolved" ] && echo "$domain: NXDOMAIN (EXPIRED/HIJACKED)" >> "$SESSION/bt/wp_link_hijack.txt"
        done
    }
    [ -s "$SESSION/bt/wp_link_hijack.txt" ] && bt "External link hijack detection complete" || info "Link hijack check minimal"
}

