bt_182_wp_content_scrape_intel() {
    local target="${1:-$TARGET}"
    _section "[BT-182] WORDPRESS CONTENT SCRAPING INTEL"
    run "Scraping all public content for operational intelligence..."
    > "$SESSION/bt/wp_content_intel.txt"
    # Scrape all post slugs and dates
    local all_posts=""
    for page in $(seq 1 10); do
        local posts=$(curl -sk --max-time 15 "https://public-api.wordpress.com/wp/v2/sites/${target}/posts?per_page=100&page=${page}&_fields=slug,date,link,author" 2>/dev/null)
        [ -z "$posts" ] || [ "$posts" = "[]" ] && break
        local page_posts=$(echo "$posts" | grep -oP '"link":"[^"]*"' | sed 's/"link":"//;s/"$//')
        [ -n "$page_posts" ] && all_posts="${all_posts}${page_posts}\n"
        local author_ids=$(echo "$posts" | grep -oP '"author":[0-9]+' | sort -u)
