    done
    [ -n "$all_posts" ] && {
        local total_posts=$(echo -e "$all_posts" | grep -c "http")
        echo "TOTAL POSTS SCRAPED: $total_posts" >> "$SESSION/bt/wp_content_intel.txt"
        echo "" >> "$SESSION/bt/wp_content_intel.txt"
        echo "=== FIRST 20 POSTS ===" >> "$SESSION/bt/wp_content_intel.txt"
        echo -e "$all_posts" | head -20 >> "$SESSION/bt/wp_content_intel.txt"
    }
    # Extract all external links from content
    local ext_links=$(curl -sk --max-time 15 "https://${target}/" 2>/dev/null | grep -oP 'https?://[^"<>\s]+' | grep -v "${target}\|wordpress.com\|wp.com\|gravatar.com\|w.org\|gmpg.org\|schema.org\|w3.org\|mozilla.org" | sort -u)
    [ -n "$ext_links" ] && {
        echo "" >> "$SESSION/bt/wp_content_intel.txt"
