bt_186_cloudflare_recon() {
    local target="${1:-$TARGET}"
    _section "[BT-186] CLOUDFLARE PROTECTION RECON"
    run "Analyzing Cloudflare protection level and configuration..."
    > "$SESSION/bt/cloudflare_recon.txt"
    # Check for Cloudflare headers
    local headers=$(curl -skI --max-time 10 "https://${target}/" 2>/dev/null)
    [ -n "$headers" ] && {
        echo "=== CLOUDFLARE HEADERS ===" >> "$SESSION/bt/cloudflare_recon.txt"
        echo "$headers" | grep -iE 'cloudflare|cf-|cdn' >> "$SESSION/bt/cloudflare_recon.txt"
        # Determine protection level
        echo "$headers" | grep -q "cf-mitigated: challenge" && echo "PROTECTION: Managed Challenge (JavaScript required)" >> "$SESSION/bt/cloudflare_recon.txt"
        echo "$headers" | grep -q "cf-mitigated: managed" && echo "PROTECTION: Managed Challenge" >> "$SESSION/bt/cloudflare_recon.txt"
        echo "$headers" | grep -q "cf-ray" && echo "CLOUDFLARE: ACTIVE (cf-ray present)" >> "$SESSION/bt/cloudflare_recon.txt"
        echo "$headers" | grep -q "server: cloudflare" && echo "SERVER: Cloudflare edge" >> "$SESSION/bt/cloudflare_recon.txt"
        # Extract CF-Ray for colocation identification
        local cfray=$(echo "$headers" | grep -i "cf-ray" | head -1)
        [ -n "$cfray" ] && echo "CF-RAY: $cfray" >> "$SESSION/bt/cloudflare_recon.txt"
        # Content-Security-Policy analysis
        local csp=$(echo "$headers" | grep -i "content-security-policy" | head -1)
        [ -n "$csp" ] && echo "CSP: $csp" >> "$SESSION/bt/cloudflare_recon.txt"
    }
    # cdn-cgi trace endpoint
    local trace=$(curl -sk --max-time 10 "https://${target}/cdn-cgi/trace" 2>/dev/null)
    [ -n "$trace" ] && {
        echo "" >> "$SESSION/bt/cloudflare_recon.txt"
        echo "=== CDN-CGI TRACE ===" >> "$SESSION/bt/cloudflare_recon.txt"
        echo "$trace" >> "$SESSION/bt/cloudflare_recon.txt"
    }
    # Test direct IP access
    local ip=$(dig @8.8.8.8 +short "${target}" A 2>/dev/null | head -1)
    [ -n "$ip" ] && {
        echo "" >> "$SESSION/bt/cloudflare_recon.txt"
        echo "RESOLVED IP: $ip" >> "$SESSION/bt/cloudflare_recon.txt"
        local ip_direct=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 8 --resolve "${target}:443:${ip}" "https://${target}/" -A "Mozilla/5.0" 2>/dev/null)
        echo "DIRECT IP ACCESS: HTTP $ip_direct" >> "$SESSION/bt/cloudflare_recon.txt"
    }
    [ -s "$SESSION/bt/cloudflare_recon.txt" ] && bt "Cloudflare recon complete" || info "Cloudflare recon minimal"
}

bt_187_cloudflare_bypass_attempts() {
    local target="${1:-$TARGET}"
    _section "[BT-187] CLOUDFLARE BYPASS ATTEMPTS"
    run "Testing multiple Cloudflare bypass techniques..."
    > "$SESSION/bt/cloudflare_bypass.txt"
    local bypass_count=0
    # Technique 1: Different User-Agents
    local uas=(
        "Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)"
        "Mozilla/5.0 (Linux; Android 6.0.1; Nexus 5X Build/MMB29P) AppleWebKit/537.36"
        "curl/7.68.0"
        "Wget/1.20.3"
        "Mozilla/5.0 (Windows NT 6.1; WOW64; rv:40.0) Gecko/20100101 Firefox/40.0"
    )
    for ua in "${uas[@]}"; do
        local code=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 8 -A "$ua" "https://${target}/" 2>/dev/null)
        [ "$code" = "200" ] && { echo "BYPASS: UA '${ua:0:30}' -> HTTP 200" >> "$SESSION/bt/cloudflare_bypass.txt"; bypass_count=$((bypass_count+1)); }
    done
    # Technique 2: HTTP/1.1 downgrade
    local h11=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 8 --http1.1 -A "Mozilla/5.0" "https://${target}/" 2>/dev/null)
    [ "$h11" = "200" ] && { echo "BYPASS: HTTP/1.1 -> HTTP 200" >> "$SESSION/bt/cloudflare_bypass.txt"; bypass_count=$((bypass_count+1)); }
    # Technique 3: X-Forwarded-For header
    local xff=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 8 -H "X-Forwarded-For: 1.1.1.1" -A "Mozilla/5.0" "https://${target}/" 2>/dev/null)
    [ "$xff" = "200" ] && { echo "BYPASS: X-Forwarded-For -> HTTP 200" >> "$SESSION/bt/cloudflare_bypass.txt"; bypass_count=$((bypass_count+1)); }
    # Technique 4: Non-standard paths
    local paths=("/robots.txt" "/sitemap.xml" "/favicon.ico" "/.well-known/security.txt" "/cdn-cgi/trace")
    for path in "${paths[@]}"; do
        local code=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 8 -A "Mozilla/5.0" "https://${target}${path}" 2>/dev/null)
        [ "$code" = "200" ] && { echo "BYPASS: Path $path -> HTTP 200" >> "$SESSION/bt/cloudflare_bypass.txt"; bypass_count=$((bypass_count+1)); }
    done
    # Technique 5: HTTP instead of HTTPS
    local http_code=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 8 -A "Mozilla/5.0" "http://${target}/" 2>/dev/null)
    [ "$http_code" = "200" ] && { echo "BYPASS: HTTP plaintext -> HTTP 200" >> "$SESSION/bt/cloudflare_bypass.txt"; bypass_count=$((bypass_count+1)); }
    echo "" >> "$SESSION/bt/cloudflare_bypass.txt"
    echo "TOTAL BYPASSES: $bypass_count" >> "$SESSION/bt/cloudflare_bypass.txt"
    [ "$bypass_count" -gt 0 ] && bt "$bypass_count Cloudflare bypasses found" || info "No Cloudflare bypasses found"
}

