bt_191_internal_host_discovery() {
    local target="${1:-$TARGET}"
    _section "[BT-191] INTERNAL HOST DISCOVERY"
    run "Discovering live hosts on the internal network..."
    > "$SESSION/bt/internal_hosts.txt"
    local ip_prefix=$(echo "$target" | cut -d. -f1-3)
    for i in $(seq 1 254); do
        local host="${ip_prefix}.${i}"
        ping -c 1 -W 1 "$host" >/dev/null 2>&1 && {
            echo "HOST UP: $host" >> "$SESSION/bt/internal_hosts.txt"
            for port in 22 80 443 445 3389 8080; do
                timeout 2 bash -c "echo > /dev/tcp/${host}/${port}" 2>/dev/null && echo "  PORT ${port} OPEN on $host" >> "$SESSION/bt/internal_hosts.txt"
            done
        } &
        [ $((i % 50)) -eq 0 ] && wait
    done
    wait
    which arp-scan >/dev/null 2>&1 && {
        local iface=$(ip route 2>/dev/null | grep default | awk '{print $5}' | head -1)
        [ -n "$iface" ] && timeout 60 arp-scan -I "$iface" "${ip_prefix}.0/24" 2>/dev/null >> "$SESSION/bt/internal_hosts.txt"
    }
    [ -s "$SESSION/bt/internal_hosts.txt" ] && bt "Internal hosts discovered" || info "Host discovery minimal"
}

