bt_211_bb_platform_recon() {
    local target="${1:-$TARGET}"
    _section "[BT-211] BUG BOUNTY PLATFORM RECON"
    run "Reconnaissance on bug bounty platform infrastructure..."
    > "$SESSION/bt/bb_platform_recon.txt"
    # DNS analysis
    local ip=$(dig @8.8.8.8 +short "$target" A 2>/dev/null | head -1)
    local ns=$(dig @8.8.8.8 +short "$target" NS 2>/dev/null | tr '\n' ' ')
    local mx=$(dig @8.8.8.8 +short "$target" MX 2>/dev/null | head -5)
    local txt=$(dig @8.8.8.8 +short "$target" TXT 2>/dev/null | head -10)
    [ -n "$ip" ] && echo "IP: $ip" >> "$SESSION/bt/bb_platform_recon.txt"
    [ -n "$ns" ] && echo "NS: $ns" >> "$SESSION/bt/bb_platform_recon.txt"
    [ -n "$mx" ] && { echo "MX:" >> "$SESSION/bt/bb_platform_recon.txt"; echo "$mx" >> "$SESSION/bt/bb_platform_recon.txt"; }
    [ -n "$txt" ] && { echo "TXT:" >> "$SESSION/bt/bb_platform_recon.txt"; echo "$txt" >> "$SESSION/bt/bb_platform_recon.txt"; }
    # Platform type detection
    local headers=$(curl -skI --max-time 10 "https://${target}/" 2>/dev/null)
    [ -n "$headers" ] && {
        echo "" >> "$SESSION/bt/bb_platform_recon.txt"
        echo "=== HEADERS ===" >> "$SESSION/bt/bb_platform_recon.txt"
        echo "$headers" | grep -iE 'server|x-powered-by|via|x-frame-options|content-security-policy|strict-transport-security' >> "$SESSION/bt/bb_platform_recon.txt"
    }
    # Shodan lookup
    [ -n "$ip" ] && {
        local shodan=$(curl -sk --max-time 10 "https://internetdb.shodan.io/${ip}" 2>/dev/null)
        [ -n "$shodan" ] && { echo "" >> "$SESSION/bt/bb_platform_recon.txt"; echo "SHODAN: $shodan" >> "$SESSION/bt/bb_platform_recon.txt"; }
    }
    # IP geolocation
    [ -n "$ip" ] && {
        local geo=$(curl -sk --max-time 8 "https://ipinfo.io/${ip}/json" 2>/dev/null | grep -oE '"(city|region|country|org)":"[^"]*"' | head -4)
        [ -n "$geo" ] && { echo "" >> "$SESSION/bt/bb_platform_recon.txt"; echo "GEO: $geo" >> "$SESSION/bt/bb_platform_recon.txt"; }
    }
    [ -s "$SESSION/bt/bb_platform_recon.txt" ] && bt "Bug bounty platform recon complete" || info "BB platform recon minimal"
}

