    # cdn-cgi trace
    local trace=$(curl -sk --max-time 10 "https://${target}/cdn-cgi/trace" 2>/dev/null)
    [ -n "$trace" ] && { echo "=== CDN-CGI TRACE ===" >> "$SESSION/bt/bb_cf_bypass.txt"; echo "$trace" >> "$SESSION/bt/bb_cf_bypass.txt"; }
    # Test with old TLS
    local old_tls=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 8 --tlsv1.0 -A "Mozilla/5.0" "https://${target}/" 2>/dev/null)
    echo "" >> "$SESSION/bt/bb_cf_bypass.txt"
    echo "TLS 1.0: HTTP ${old_tls}" >> "$SESSION/bt/bb_cf_bypass.txt"
    # Test with specific Accept header
    local accept=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 8 -A "Mozilla/5.0" -H "Accept: application/json" "https://${target}/api" 2>/dev/null)
    echo "Accept: application/json: HTTP ${accept}" >> "$SESSION/bt/bb_cf_bypass.txt"
    # Test IP literal
    local ip=$(dig @8.8.8.8 +short "$target" A 2>/dev/null | head -1)
    [ -n "$ip" ] && {
        local direct=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 8 -H "Host: ${target}" -A "Mozilla/5.0" "https://${ip}/" 2>/dev/null)
        echo "Direct IP ${ip}: HTTP ${direct}" >> "$SESSION/bt/bb_cf_bypass.txt"
        # Shodan ports
        local shodan=$(curl -sk --max-time 8 "https://internetdb.shodan.io/${ip}" 2>/dev/null)
        [ -n "$shodan" ] && echo "SHODAN: ${shodan}" >> "$SESSION/bt/bb_cf_bypass.txt"
    }
    # Try alternate subdomains
    local alts=("api" "www" "staging" "dev" "test" "old" "origin" "direct")
    for sub in "${alts[@]}"; do
        local sub_ip=$(dig @8.8.8.8 +short "${sub}.${target}" A 2>/dev/null | head -1)
        [ -n "$sub_ip" ] && echo "${sub}.${target} -> ${sub_ip}" >> "$SESSION/bt/bb_cf_bypass.txt"
    done
    [ -s "$SESSION/bt/bb_cf_bypass.txt" ] && bt "CF bypass analysis complete" || info "CF bypass minimal"
}

