pt_321_edu_platform_recon() {
    local target="${1:-$TARGET}"
    _section "[PT-321] EDUCATION PLATFORM RECON"
    run "Comprehensive reconnaissance for security training platforms..."
    > "$SESSION/bt/edu_recon.txt"
    local ip=$(dig @8.8.8.8 +short "$target" A 2>/dev/null | head -1)
    [ -n "$ip" ] && echo "TARGET_IP: $ip" >> "$SESSION/bt/edu_recon.txt"
    local ns=$(dig +short "$target" NS 2>/dev/null | tr '
' ' ')
    [ -n "$ns" ] && echo "NS: $ns" >> "$SESSION/bt/edu_recon.txt"
    local mx=$(dig +short "$target" MX 2>/dev/null | head -3 | tr '
' ' ')
    [ -n "$mx" ] && echo "MX: $mx" >> "$SESSION/bt/edu_recon.txt"
    local spf=$(dig +short "$target" TXT 2>/dev/null | grep -i "v=spf1")
    [ -n "$spf" ] && echo "SPF: $spf" >> "$SESSION/bt/edu_recon.txt"
    local dmarc=$(dig +short "_dmarc.${target}" TXT 2>/dev/null)
    [ -n "$dmarc" ] && echo "DMARC: $dmarc" >> "$SESSION/bt/edu_recon.txt"
    local ssl=$(timeout 10 openssl s_client -connect "${target}:443" -servername "${target}" 2>/dev/null | openssl x509 -noout -text 2>/dev/null | grep -E 'Subject:|Issuer:|DNS:|Not After' | head -5)
    [ -n "$ssl" ] && { echo "SSL:" >> "$SESSION/bt/edu_recon.txt"; echo "$ssl" >> "$SESSION/bt/edu_recon.txt"; }
    local shodan=$(curl -sk --max-time 10 "https://internetdb.shodan.io/${ip}" 2>/dev/null)
    [ -n "$shodan" ] && echo "SHODAN: $shodan" >> "$SESSION/bt/edu_recon.txt"
    [ -s "$SESSION/bt/edu_recon.txt" ] && bt "Education platform recon complete" || info "Edu recon minimal"
}

