pt_324_github_osint_edu() {
    local target="${1:-$TARGET}"
    _section "[PT-324] GITHUB OSINT FOR EDUCATION PLATFORMS"
    run "Searching GitHub for exposed source code and configuration..."
    > "$SESSION/bt/github_edu.txt"
    local org_name=$(echo "$target" | sed 's/\.[^.]*\.[^.]*$//;s/\.[^.]*$//')
    local repos=$(curl -sk --max-time 15 "https://api.github.com/search/repositories?q=${org_name}+in:name&sort=updated&per_page=10" -H "Accept: application/vnd.github.v3+json" 2>/dev/null)
    [ -n "$repos" ] && {
        local repo_list=$(echo "$repos" | grep -oP '"full_name":\s*"[^"]+"' | sed 's/"full_name":\s*"//;s/"$//')
