rt_338_wordpress_cookie_integrity_bypass() {
    local target="${1:-$TARGET}"
    _section "[RT-338] WORDPRESS COOKIE INTEGRITY BYPASS"
    run "CVE-2008-1930: WordPress cookie integrity bypass → admin access..."
    > "$SESSION/rt/wp_cookie_bypass.txt"
