        local cookie_val=$(echo "$wp_cookie" | grep -oP 'wordpress_logged_in_[^=]+=\K[^;]+')
        local decoded=$(echo "$cookie_val" | python3 -c "import sys,urllib.parse; print(urllib.parse.unquote(sys.stdin.read().strip()))" 2>/dev/null)
        echo "DECODED: ${decoded:0:200}" >> "$SESSION/rt/wp_cookie_bypass.txt"
        # CVE-2008-1930: wordpress uses md5($secret . $data) for cookie integrity
        # If secret is known/weak, we can forge admin cookies
        echo "VULN: CVE-2008-1930 — md5(secret+data) integrity check" >> "$SESSION/rt/wp_cookie_bypass.txt"
    }
    local wp_login=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 5 -A "Mozilla/5.0" "https://${target}/wp-login.php" 2>/dev/null)
    [ "$wp_login" = "200" ] && echo "WP_LOGIN: /wp-login.php accessible" >> "$SESSION/rt/wp_cookie_bypass.txt"
