# ═══ SMART CVE EXPLOITATION SYSTEM PT 341-360 / RT 341-360 ═══
# 150+ Real CVEs with tech-aware auto-detection
# ═══════════════════════════════════════════════════════════════════════════

pt_341_smart_os_tech_detector() {
    local target="${1:-$TARGET}"
    _section "[PT-341] SMART OS & TECHNOLOGY DETECTOR"
    run "Fingerprinting target OS, server, framework, and CMS for CVE matching..."
    > "$SESSION/bt/tech_fingerprint.txt"

    # Server header detection
    local headers=$(curl -skI --max-time 10 -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" "https://${target}/" 2>/dev/null)
    [ -n "$headers" ] && echo "$headers" >> "$SESSION/bt/tech_fingerprint.txt"

    local server=$(echo "$headers" | grep -i "^server:" | sed 's/[Ss]erver: //' | tr -d '\r')
    local powered=$(echo "$headers" | grep -i "^x-powered-by:" | sed 's/.*: //' | tr -d '\r')
    local via=$(echo "$headers" | grep -i "^via:" | sed 's/.*: //' | tr -d '\r')

    # Technology flags
    local is_wordpress=false is_drupal=false is_joomla=false is_rails=false
    local is_php=false is_apache=false is_nginx=false is_iis=false
    local is_tomcat=false is_jboss=false is_weblogic=false
    local is_python=false is_django=false is_flask=false
    local is_dotnet=false is_aspnet=false
    local is_mysql=false is_postgres=false is_redis=false is_mongo=false
    local is_docker=false is_k8s=false
    local os_type="unknown"

    # Server detection
    [ -n "$server" ] && {
        echo "$server" | grep -qi "apache" && { is_apache=true; echo "SERVER: Apache detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
        echo "$server" | grep -qi "nginx" && { is_nginx=true; echo "SERVER: nginx detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
        echo "$server" | grep -qi "IIS" && { is_iis=true; echo "SERVER: IIS detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
        echo "$server" | grep -qi "tomcat" && { is_tomcat=true; echo "SERVER: Tomcat detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
        echo "$server" | grep -qi "JBoss\|WildFly" && { is_jboss=true; echo "SERVER: JBoss/WildFly detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
        echo "$server" | grep -qi "WebLogic" && { is_weblogic=true; echo "SERVER: WebLogic detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
        echo "$server" | grep -qi "Play\|play" && echo "FRAMEWORK: Play Framework detected" >> "$SESSION/bt/tech_fingerprint.txt"
        echo "$server" | grep -qi "Kestrel" && { is_dotnet=true; echo "FRAMEWORK: ASP.NET Core (Kestrel) detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
    }

    # X-Powered-By detection
    [ -n "$powered" ] && {
        echo "$powered" | grep -qi "PHP" && { is_php=true; echo "LANG: PHP detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
        echo "$powered" | grep -qi "ASP.NET" && { is_aspnet=true; echo "FRAMEWORK: ASP.NET detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
        echo "$powered" | grep -qi "Express" && { is_python=true; echo "FRAMEWORK: Express.js detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
    }

    # Body fingerprinting
    local body=$(curl -sk --max-time 10 -A "Mozilla/5.0" "https://${target}/" 2>/dev/null)

    # WordPress detection
    echo "$body" | grep -qi "wp-content\|wp-includes\|wordpress" && { is_wordpress=true; echo "CMS: WordPress detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
    echo "$headers" | grep -qi "set-cookie.*wordpress" && { is_wordpress=true; echo "CMS: WordPress cookie detected" >> "$SESSION/bt/tech_fingerprint.txt"; }

    # Drupal detection
    echo "$body" | grep -qi "drupal\|Drupal.settings" && { is_drupal=true; echo "CMS: Drupal detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
    echo "$headers" | grep -i "x-drupal" >> "$SESSION/bt/tech_fingerprint.txt" 2>/dev/null && is_drupal=true

    # Joomla detection
    echo "$body" | grep -qi "joomla\|Joomla!" && { is_joomla=true; echo "CMS: Joomla detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
    echo "$headers" | grep -i "set-cookie.*joomla" >> "$SESSION/bt/tech_fingerprint.txt" 2>/dev/null && is_joomla=true

    # Rails detection
    echo "$body" | grep -qi "csrf-param.*authenticity_token" && { is_rails=true; echo "FRAMEWORK: Ruby on Rails detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
    echo "$headers" | grep -qi "x-runtime" >> "$SESSION/bt/tech_fingerprint.txt" 2>/dev/null && is_rails=true
    echo "$headers" | grep -qi "set-cookie.*_session" | grep -q "--" >> "$SESSION/bt/tech_fingerprint.txt" 2>/dev/null && is_rails=true

    # Python framework detection
    echo "$body" | grep -qi "__NEXT_DATA__\|_next/static" && echo "FRAMEWORK: Next.js detected" >> "$SESSION/bt/tech_fingerprint.txt"
    echo "$body" | grep -qi "csrftoken" && { is_django=true; is_python=true; echo "FRAMEWORK: Django detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
    echo "$headers" | grep -qi "werkzeug" && { is_flask=true; is_python=true; echo "FRAMEWORK: Flask detected" >> "$SESSION/bt/tech_fingerprint.txt"; }

    # PHP detection (additional)
    echo "$body" | grep -qi "\.php\|phpinfo\|<?php" && { is_php=true; echo "LANG: PHP file extensions detected" >> "$SESSION/bt/tech_fingerprint.txt"; }

    # Database hints
    echo "$body" | grep -qi "mysql\|mysqli\|pdo" && { is_mysql=true; echo "DB: MySQL hints in response" >> "$SESSION/bt/tech_fingerprint.txt"; }
    echo "$body" | grep -qi "postgresql\|psycopg\|pg_" && { is_postgres=true; echo "DB: PostgreSQL hints" >> "$SESSION/bt/tech_fingerprint.txt"; }
    echo "$headers" | grep -qi "x-redis" && { is_redis=true; echo "CACHE: Redis hint" >> "$SESSION/bt/tech_fingerprint.txt"; }

    # Container/Cloud detection
    echo "$headers" | grep -qi "x-docker" && { is_docker=true; echo "CONTAINER: Docker detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
    echo "$headers" | grep -qi "x-kubernetes" && { is_k8s=true; echo "ORCHESTRATION: Kubernetes detected" >> "$SESSION/bt/tech_fingerprint.txt"; }
    echo "$body" | grep -qi "kubernetes\|k8s\|docker" && echo "CONTAINER: Container mentions in body" >> "$SESSION/bt/tech_fingerprint.txt"

    # OS detection via TTL
    local ip=$(dig +short "$target" A 2>/dev/null | head -1)
    [ -n "$ip" ] && {
        local ttl=$(ping -c 1 -W 2 "$ip" 2>/dev/null | grep -oP 'ttl=\K[0-9]+')
        [ -n "$ttl" ] && {
            [ "$ttl" -le 64 ] && os_type="linux" && echo "OS: Linux (TTL=${ttl})" >> "$SESSION/bt/tech_fingerprint.txt"
            [ "$ttl" -gt 64 ] && [ "$ttl" -le 128 ] && os_type="windows" && echo "OS: Windows (TTL=${ttl})" >> "$SESSION/bt/tech_fingerprint.txt"
            [ "$ttl" -gt 128 ] && os_type="other" && echo "OS: Other/BSD (TTL=${ttl})" >> "$SESSION/bt/tech_fingerprint.txt"
        }
    }

    # Write detection results for CVE matcher
    cat > "$SESSION/bt/cve_match_config.txt" << CVECFG
IS_WORDPRESS=${is_wordpress}
IS_DRUPAL=${is_drupal}
IS_JOOMLA=${is_joomla}
IS_RAILS=${is_rails}
IS_PHP=${is_php}
IS_APACHE=${is_apache}
IS_NGINX=${is_nginx}
IS_IIS=${is_iis}
IS_TOMCAT=${is_tomcat}
IS_JBOSS=${is_jboss}
IS_WEBLOGIC=${is_weblogic}
IS_PYTHON=${is_python}
IS_DJANGO=${is_django}
IS_FLASK=${is_flask}
IS_DOTNET=${is_dotnet}
IS_ASPNET=${is_aspnet}
IS_MYSQL=${is_mysql}
IS_POSTGRES=${is_postgres}
IS_REDIS=${is_redis}
IS_MONGO=${is_mongo}
IS_DOCKER=${is_docker}
IS_K8S=${is_k8s}
OS_TYPE=${os_type}
SERVER_HEADER=${server}
POWERED_BY=${powered}
CVECFG

    bt "Smart detector complete — detected=$(grep -c detected "$SESSION/bt/tech_fingerprint.txt") technologies found"
}

