pt_348_smart_cve_matcher() {
    local target="${1:-$TARGET}"
    _section "[PT-348] SMART CVE MATCHER"
    run "Automatically matching detected technologies to applicable CVEs..."
    > "$SESSION/bt/smart_cve_match.txt"

    local total_cves=0
    [ -f "$SESSION/rt/cve_wordpress.txt" ] && {
        local wp_cves=$(grep -c "CVE-" "$SESSION/rt/cve_wordpress.txt" 2>/dev/null || echo 0)
        echo "WordPress CVEs tested: ${wp_cves}" >> "$SESSION/bt/smart_cve_match.txt"
        total_cves=$((total_cves + wp_cves))
    }
    [ -f "$SESSION/rt/cve_php.txt" ] && {
        local php_cves=$(grep -c "CVE-" "$SESSION/rt/cve_php.txt" 2>/dev/null || echo 0)
        echo "PHP CVEs tested: ${php_cves}" >> "$SESSION/bt/smart_cve_match.txt"
        total_cves=$((total_cves + php_cves))
    }
    [ -f "$SESSION/rt/cve_webserver.txt" ] && {
        local ws_cves=$(grep -c "CVE-" "$SESSION/rt/cve_webserver.txt" 2>/dev/null || echo 0)
        echo "Apache/Nginx CVEs tested: ${ws_cves}" >> "$SESSION/bt/smart_cve_match.txt"
        total_cves=$((total_cves + ws_cves))
    }
    [ -f "$SESSION/rt/cve_java.txt" ] && {
        local java_cves=$(grep -c "CVE-" "$SESSION/rt/cve_java.txt" 2>/dev/null || echo 0)
        echo "Java CVEs tested: ${java_cves}" >> "$SESSION/bt/smart_cve_match.txt"
        total_cves=$((total_cves + java_cves))
    }
    [ -f "$SESSION/rt/cve_drupal_joomla.txt" ] && {
        local cms_cves=$(grep -c "CVE-" "$SESSION/rt/cve_drupal_joomla.txt" 2>/dev/null || echo 0)
        echo "Drupal/Joomla CVEs tested: ${cms_cves}" >> "$SESSION/bt/smart_cve_match.txt"
        total_cves=$((total_cves + cms_cves))
    }
    [ -f "$SESSION/rt/cve_frameworks.txt" ] && {
        local fw_cves=$(grep -c "CVE-" "$SESSION/rt/cve_frameworks.txt" 2>/dev/null || echo 0)
        echo "Framework CVEs tested: ${fw_cves}" >> "$SESSION/bt/smart_cve_match.txt"
        total_cves=$((total_cves + fw_cves))
    }
    [ -f "$SESSION/rt/cve_infra.txt" ] && {
        local inf_cves=$(grep -c "CVE-" "$SESSION/rt_infra.txt" 2>/dev/null || echo 0)
        echo "Infra CVEs tested: ${inf_cves}" >> "$SESSION/bt/smart_cve_match.txt"
        total_cves=$((total_cves + inf_cves))
    }

    echo "TOTAL_CVES_TESTED: ${total_cves}" >> "$SESSION/bt/smart_cve_match.txt"
    bt "Smart CVE matcher: ${total_cves} CVEs tested against detected technologies"
}

