# ─── ADV 20. JAVASCRIPT SECRETS & API KEY EXTRACTION ───
_section "[ADV 20/60] JS SECRETS & API KEY EXTRACTION"
run "Deep-scanning JavaScript for secrets..."
> "$SESSION/advanced/js_secrets.txt"
# Download and scan each JS file
if [ -s "$SESSION/web/js_files.txt" ]; then
    mkdir -p "$SESSION/web/js_downloaded"
    while read -r js_path; do
        [ -z "$js_path" ] && continue
        # Build full URL
        [[ "$js_path" == http* ]] && JS_URL="$js_path" || JS_URL="https://$TARGET$js_path"
        JS_BASENAME=$(basename "$js_path" | sed 's/[^a-zA-Z0-9._-]/_/g')
        _curl "$JS_URL" > "$SESSION/web/js_downloaded/${JS_BASENAME}" 2>/dev/null
    done < "$SESSION/web/js_files.txt"

    # Scan all JS for secrets
    cat "$SESSION/web/js_downloaded"/* 2>/dev/null | grep -Eoi \
        '(api[_-]?key|api[_-]?secret|auth[_-]?token|access[_-]?token|password|passwd|secret|private[_-]?key)\s*[:=]\s*["'\''`][^"'\''`]{8,}' \
        | head -20 >> "$SESSION/advanced/js_secrets.txt"

    # AWS keys
    cat "$SESSION/web/js_downloaded"/* 2>/dev/null | grep -Eoi 'AKIA[0-9A-Z]{16}' | head -5 >> "$SESSION/advanced/js_secrets.txt"
    # GitHub tokens
    cat "$SESSION/web/js_downloaded"/* 2>/dev/null | grep -Eoi 'ghp_[a-zA-Z0-9]{36}' | head -5 >> "$SESSION/advanced/js_secrets.txt"
    # Google API
    cat "$SESSION/web/js_downloaded"/* 2>/dev/null | grep -Eoi 'AIza[0-9A-Za-z_-]{35}' | head -5 >> "$SESSION/advanced/js_secrets.txt"
    # URLs with tokens
    cat "$SESSION/web/js_downloaded"/* 2>/dev/null | grep -Eoi 'https?://[^"<>\s]+[?&](token|key|auth|api_key)=[^"<>\s&]{10,}' | head -10 >> "$SESSION/advanced/js_secrets.txt"
    # Internal IPs
    cat "$SESSION/web/js_downloaded"/* 2>/dev/null | grep -Eoi '(10\.[0-9]+\.[0-9]+\.[0-9]+|172\.(1[6-9]|2[0-9]|3[01])\.[0-9]+\.[0-9]+|192\.168\.[0-9]+\.[0-9]+|127\.[0-9]+\.[0-9]+\.[0-9]+)' | sort -u | head -10 >> "$SESSION/advanced/js_secrets.txt"

    SEC_COUNT=$(grep -c '.' "$SESSION/advanced/js_secrets.txt" 2>/dev/null || echo 0)
    if [ "$SEC_COUNT" -gt 0 ]; then
        ok "$SEC_COUNT potential secret(s) found in JS!"
        ADV_SCORE=$((ADV_SCORE + 20))
        EXPOSURE_SCORE=$((EXPOSURE_SCORE + 15))
    else
        info "No hardcoded secrets found in JS"
    fi
else
    info "No JS files to analyze"
fi


# ─── ADV 21. SQL INJECTION DETECTION (ERROR-BASED) ───
_section "[ADV 21/60] SQL INJECTION DETECTION"
run "Testing for error-based SQL injection..."
SQLI_PAYLOADS=(
    "'"
    "''"
    "' OR '1'='1"
