# ─── ADV 25. HOST HEADER INJECTION ───
_section "[ADV 25/60] HOST HEADER INJECTION"
run "Testing for Host header injection..."
HOST_PAYLOADS=(
    "evil.com"
    "$TARGET.evil.com"
    "127.0.0.1"
    "localhost"
    "::1"
)
HOST_VULN=0
for payload in "${HOST_PAYLOADS[@]}"; do
    RESP=$(curl -s -I -H "Host: $payload" --connect-timeout 10 "https://$TARGET" 2>/dev/null)
    LOC=$(echo "$RESP" | grep -i "^location:" | awk -F': ' '{print $2}' | tr -d '\r')
    ACAO=$(echo "$RESP" | grep -i "access-control-allow-origin" | awk -F': ' '{print $2}' | tr -d '\r')
    if [ -n "$LOC" ] && echo "$LOC" | grep -qi "$payload"; then
        echo "⚠️  Host header redirect to: $payload" >> "$SESSION/advanced/host_header_vulns.txt"
        HOST_VULN=1
    fi
    if [ -n "$ACAO" ] && echo "$ACAO" | grep -qi "$payload"; then
        echo "⚠️  Host reflected in ACAO: $payload" >> "$SESSION/advanced/host_header_vulns.txt"
        HOST_VULN=1
    fi
    # X-Forwarded-Host test
    RESP2=$(curl -s -I -H "X-Forwarded-Host: $payload" --connect-timeout 10 "https://$TARGET" 2>/dev/null)
    LOC2=$(echo "$RESP2" | grep -i "^location:" | awk -F': ' '{print $2}' | tr -d '\r')
    if [ -n "$LOC2" ] && echo "$LOC2" | grep -qi "$payload"; then
        echo "⚠️  X-Forwarded-Host poisoning: $payload" >> "$SESSION/advanced/host_header_vulns.txt"
        HOST_VULN=1
    fi
done
if [ $HOST_VULN -eq 1 ]; then
    ok "Host header injection vulnerability found!"
    ADV_SCORE=$((ADV_SCORE + 20))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 15))
else
    info "No Host header injection detected"
fi

# ─── ADV 26. HTTP REQUEST SMUGGLING (CL.TE) ───
_section "[ADV 26/60] HTTP REQUEST SMUGGLING DETECTION"
run "Testing for CL.TE request smuggling..."
SMUGGLE_TEST=$(printf 'POST / HTTP/1.1\r\nHost: %s\r\nContent-Length: 6\r\nTransfer-Encoding: chunked\r\n\r\n0\r\n\r\nG' "$TARGET" | \
    openssl s_client -connect "$TARGET:443" -servername "$TARGET" -quiet 2>/dev/null | head -20)
if echo "$SMUGGLE_TEST" | grep -qiE "timeout|unexpected|error|invalid"; then
    info "CL.TE desync not confirmed"
else
    # Send follow-up request to detect desync
    FOLLOW_UP=$(printf 'GET / HTTP/1.1\r\nHost: %s\r\n\r\n' "$TARGET" | \
        openssl s_client -connect "$TARGET:443" -servername "$TARGET" -quiet 2>/dev/null | head -10)
    if echo "$FOLLOW_UP" | grep -qiE "400|500|405|unrecognized"; then
        echo "⚠️  Potential CL.TE request smuggling detected" >> "$SESSION/advanced/http_smuggle.txt"
        ok "HTTP Request Smuggling (CL.TE) potentially vulnerable!"
        ADV_SCORE=$((ADV_SCORE + 25))
        EXPOSURE_SCORE=$((EXPOSURE_SCORE + 20))
    else
        info "CL.TE desync not detected"
    fi
fi

