# ─── ADV 30. SESSION FIXATION DETECTION ───
_section "[ADV 30/60] SESSION FIXATION TEST"
run "Testing for session fixation vulnerability..."
# Request 1: Get initial session
SESS1=$(curl -s -I -c "$SESSION/advanced/cookies1.txt" "https://$TARGET" --connect-timeout 10 2>/dev/null)
SESS_ID1=$(echo "$SESS1" | grep -i "set-cookie" | grep -oiE "(PHPSESSID|sessionid|JSESSIONID|ASP.NET_SessionId|connect.sid)=[^;]*" | head -1)
# Request 2: Get session after auth flow (re-use same cookie jar)
SESS2=$(curl -s -I -b "$SESSION/advanced/cookies1.txt" -c "$SESSION/advanced/cookies2.txt" "https://$TARGET/login" --connect-timeout 10 2>/dev/null)
SESS_ID2=$(echo "$SESS2" | grep -i "set-cookie" | grep -oiE "(PHPSESSID|sessionid|JSESSIONID|ASP.NET_SessionId|connect.sid)=[^;]*" | head -1)
if [ -n "$SESS_ID1" ] && [ -n "$SESS_ID2" ]; then
    SESS_VAL1=$(echo "$SESS_ID1" | cut -d= -f2)
    SESS_VAL2=$(echo "$SESS_ID2" | cut -d= -f2)
    if [ "$SESS_VAL1" = "$SESS_VAL2" ]; then
        echo "⚠️  Session fixation: Same session ID after auth boundary" >> "$SESSION/advanced/session_fixation.txt"
        ok "Session fixation vulnerability detected!"
        ADV_SCORE=$((ADV_SCORE + 15))
        AUTH_SCORE=$((AUTH_SCORE + 10))
    else
