# ─── ADV 32. RATE LIMITING & BRUTE FORCE PROTECTION ───
_section "[ADV 32/60] RATE LIMITING ANALYSIS"
run "Testing rate limiting protection..."
RATE_FOUND=0
> "$SESSION/advanced/rate_limit.txt"
# Send 15 rapid requests and check for rate limit responses
for i in $(seq 1 15); do
    CODE=$(curl -s -o /dev/null -w "%{http_code}" "https://$TARGET/login" --connect-timeout 5 2>/dev/null)
    if [ "$CODE" = "429" ] || [ "$CODE" = "503" ]; then
        echo "Rate limited after $i requests (HTTP $CODE)" >> "$SESSION/advanced/rate_limit.txt"
        RATE_FOUND=1
        break
    fi
done
if [ $RATE_FOUND -eq 1 ]; then
    ok "Rate limiting is active"
else
    echo "⚠️  No rate limiting detected after 15 rapid requests" >> "$SESSION/advanced/rate_limit.txt"
    info "No rate limiting detected — brute force may be possible"
    ADV_SCORE=$((ADV_SCORE + 10))
fi

# ─── ADV 33. GRAPHQL ADVANCED (QUERY COST / BATCHING) ───
_section "[ADV 33/60] GRAPHQL ADVANCED TESTS"
run "Testing GraphQL for advanced vulnerabilities..."
# Query nesting depth test (DoS)
DEEP_QUERY='{"query": "query { user { posts { comments { author { posts { comments { author { name } } } } } } } }"}'
GQL_DEEP=$(curl -s -X POST -H "Content-Type: application/json" -d "$DEEP_QUERY" "https://$TARGET/graphql" --connect-timeout 10 2>/dev/null)
if echo "$GQL_DEEP" | grep -qiE "depth exceeded|complexity|too deep"; then
    ok "GraphQL has query depth protection"
elif echo "$GQL_DEEP" | grep -q '"data"'; then
    echo "⚠️  GraphQL deep query accepted — potential DoS" >> "$SESSION/advanced/graphql_advanced.txt"
    ADV_SCORE=$((ADV_SCORE + 10))
fi
# Query batching test
BATCH_QUERY='[{"query": "{ __typename }"}, {"query": "{ __typename }"}, {"query": "{ __typename }"}]'
GQL_BATCH=$(curl -s -X POST -H "Content-Type: application/json" -d "$BATCH_QUERY" "https://$TARGET/graphql" --connect-timeout 10 2>/dev/null)
BATCH_COUNT=$(echo "$GQL_BATCH" | grep -c '"data"' 2>/dev/null)
if [ "$BATCH_COUNT" -gt 1 ]; then
    echo "⚠️  GraphQL query batching enabled ($BATCH_COUNT queries accepted)" >> "$SESSION/advanced/graphql_advanced.txt"
    ok "GraphQL batching detected — potential for brute force amplification!"
    ADV_SCORE=$((ADV_SCORE + 15))
else
    info "GraphQL batching not detected"
fi

# ─── ADV 34. SUBDOMAIN TAKEOVER DETECTION ───
_section "[ADV 34/60] SUBDOMAIN TAKEOVER"
run "Checking for subdomain takeover via dangling CNAMEs..."
> "$SESSION/advanced/subdomain_takeover.txt"
TAKEOVER_PATTERNS=(
    "azurewebsites.net:Microsoft Azure"
    "cloudapp.azure.com:Microsoft Azure"
    "blob.core.windows.net:Azure Blob Storage"
    "herokuapp.com:Heroku"
    "github.io:GitHub Pages"
    "s3.amazonaws.com:AWS S3"
    "awsglobalaccelerator.com:AWS Global Accelerator"
    "fastly.net:Fastly"
    "cloudfront.net:AWS CloudFront"
    "surge.sh:Surge.sh"
    "vercel.app:Vercel"
    "netlify.app:Netlify"
    "firebaseapp.com:Firebase"
    "ghost.io:Ghost"
    "myshopify.com:Shopify"
    "wordpress.com:WordPress"
    "helpjuice.com:Helpjuice"
    "helpscoutdocs.com:Help Scout"
    "custom.bnc.lt:Branch"
    "cargocollective.com:Cargo"
    "statuspage.io:Statuspage"
    "amazonaws.com:AWS"
)
while read -r sub; do
    [ -z "$sub" ] && continue
    CNAME=$(dig +short "$sub" CNAME 2>/dev/null | head -1)
    if [ -n "$CNAME" ]; then
        for pattern in "${TAKEOVER_PATTERNS[@]}"; do
            PAT_DOMAIN=$(echo "$pattern" | cut -d: -f1)
            PAT_SERVICE=$(echo "$pattern" | cut -d: -f2)
            if echo "$CNAME" | grep -qi "$PAT_DOMAIN"; then
                # Check if the subdomain actually resolves
                SUB_IP=$(dig +short "$sub" A 2>/dev/null | head -1)
                if [ -z "$SUB_IP" ]; then
                    echo "⚠️  TAKEOVER: $sub -> $CNAME ($PAT_SERVICE) — dangling CNAME!" >> "$SESSION/advanced/subdomain_takeover.txt"
                fi
            fi
        done
    fi
done < "$SESSION/recon/subdomains_all.txt" 2>/dev/null
if [ -s "$SESSION/advanced/subdomain_takeover.txt" ]; then
    ok "Subdomain takeover candidate(s) found!"
    ADV_SCORE=$((ADV_SCORE + 30))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 25))
else
    info "No subdomain takeover indicators"
fi

# ─── ADV 35. WAF DETECTION & FINGERPRINTING ───
_section "[ADV 35/60] WAF DETECTION & FINGERPRINTING"
run "Identifying Web Application Firewall..."
WAF_TRIGGERS=(
    "<script>alert(1)</script>"
    "../../etc/passwd"
    "UNION SELECT NULL"
    "; DROP TABLE users--"
)
> "$SESSION/advanced/waf_detected.txt"
for trigger in "${WAF_TRIGGERS[@]}"; do
    ENC_TRIG=$(printf '%s' "$trigger" | python3 -c 'import urllib.parse,sys; print(urllib.parse.quote(sys.stdin.read().strip()))' 2>/dev/null || echo "$trigger")
    RESP=$(curl -s -I "https://$TARGET/?q=$ENC_TRIG" --connect-timeout 10 2>/dev/null)
    SERVER_WAF=$(echo "$RESP" | grep -i "server:" 2>/dev/null)
    if echo "$RESP" | grep -qiE "cloudflare|akamai|sucuri|incapsula|awsalb|barra|reblaze|distil|stackpath|fastly|imperva|f5|bigip|citrix|fortinet|barracuda"; then
        echo "WAF detected in headers: $SERVER_WAF" >> "$SESSION/advanced/waf_detected.txt"
        ok "WAF identified: $SERVER_WAF"
        break
    fi
    if echo "$RESP" | grep -qiE "403|406|419|501|503"; then
        BODY=$(curl -s "https://$TARGET/?q=$ENC_TRIG" --connect-timeout 10 2>/dev/null)
        if echo "$BODY" | grep -qiE "cloudflare|ray id|sucuri|incapsula|powered by imperva|blocked|security check|challenge"; then
            echo "WAF detected via response body" >> "$SESSION/advanced/waf_detected.txt"
            ok "WAF detected via challenge/block page"
            break
        fi
    fi
done
[ ! -s "$SESSION/advanced/waf_detected.txt" ] && info "No WAF detected"

# ─── ADV 36. CLICKJACKING / FRAME-BUSTING DETECTION ───
_section "[ADV 36/60] CLICKJACKING TEST"
run "Testing for clickjacking vulnerability..."
FRAME_RESP=$(curl -s -I "https://$TARGET" --connect-timeout 10 2>/dev/null)
XFO=$(echo "$FRAME_RESP" | grep -i "x-frame-options" | awk -F': ' '{print $2}' | tr -d '\r')
CSP_FRAME=$(echo "$FRAME_RESP" | grep -i "content-security-policy" | grep -oi "frame-ancestors[^;]*")
if [ -z "$XFO" ] && [ -z "$CSP_FRAME" ]; then
    echo "⚠️  Clickjacking: No X-Frame-Options or CSP frame-ancestors" >> "$SESSION/advanced/clickjacking.txt"
    ok "Clickjacking vulnerability — page can be framed!"
    ADV_SCORE=$((ADV_SCORE + 10))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 10))
elif [ -n "$XFO" ]; then
    if echo "$XFO" | grep -qiE "deny|sameorigin"; then
        ok "X-Frame-Options properly set: $XFO"
    else
        echo "⚠️  Weak X-Frame-Options: $XFO" >> "$SESSION/advanced/clickjacking.txt"
        ADV_SCORE=$((ADV_SCORE + 5))
    fi
fi

# ─── ADV 37. ROBOTS.TXT DEEP ANALYSIS ───
_section "[ADV 37/60] ROBOTS.TXT DEEP ANALYSIS"
run "Analyzing robots.txt for hidden paths..."
_curl "https://$TARGET/robots.txt" > "$SESSION/web/robots.txt" 2>/dev/null
if [ -s "$SESSION/web/robots.txt" ]; then
    ok "robots.txt retrieved"
    # Extract all disallowed paths
    grep -oiE "Disallow:\s*[^[:space:]]+" "$SESSION/web/robots.txt" | \
