    DIS_CNT=$(wc -l < "$SESSION/advanced/robots_disallowed.txt" 2>/dev/null | tr -d ' ')
    ok "$DIS_CNT disallowed paths discovered in robots.txt"
    # Check for interesting disallow patterns
    grep -iE "admin|api|internal|secret|private|backup|dev|test|staging|config|dashboard" "$SESSION/advanced/robots_disallowed.txt" > "$SESSION/advanced/robots_interesting.txt" 2>/dev/null
    if [ -s "$SESSION/advanced/robots_interesting.txt" ]; then
        ok "Interesting paths found in robots.txt"
        ADV_SCORE=$((ADV_SCORE + 5))
    fi
else
    info "No robots.txt found"
fi

# ─── ADV 38. SECURITY.TXT VALIDATION ───
_section "[ADV 38/60] SECURITY.TXT ANALYSIS"
