fi

# ─── ADV 39. DNSSEC VALIDATION ───
_section "[ADV 39/60] DNSSEC CONFIGURATION AUDIT"
run "Checking DNSSEC validation..."
dig +dnssec "$TARGET" DNSKEY +short > "$SESSION/recon/dnssec_keys.txt" 2>/dev/null
dig +dnssec "$TARGET" DS +short >> "$SESSION/recon/dnssec_keys.txt" 2>/dev/null
if [ -s "$SESSION/recon/dnssec_keys.txt" ]; then
