# ─── ADV 40. SSL/TLS DOWNGRADE ATTACK DETECTION ───
_section "[ADV 40/60] SSL/TLS DOWNGRADE ATTACK TEST"
run "Testing for POODLE/BEAST/CRIME vulnerabilities..."
# POODLE (SSLv3)
echo | openssl s_client -connect "$TARGET:443" -ssl3 2>/dev/null | grep -q "BEGIN CERTIFICATE" && \
    echo "⚠️  POODLE: SSLv3 supported" >> "$SESSION/network/tls_downgrade.txt"
# BEAST (TLS 1.0 with CBC)
CIPHERS=$(echo | openssl s_client -connect "$TARGET:443" -tls1 2>/dev/null | grep "Cipher" | head -1)
echo "$CIPHERS" | grep -qiE "CBC|3DES|RC4" && \
    echo "⚠️  BEAST: TLS 1.0 with CBC cipher" >> "$SESSION/network/tls_downgrade.txt"
# CRIME (compression)
echo | openssl s_client -connect "$TARGET:443" -comp 2>/dev/null | grep -qi "compression" && \
    echo "⚠️  CRIME: TLS compression enabled" >> "$SESSION/network/tls_downgrade.txt"
# Check for export ciphers
EXPORT_CIPHERS=$(echo | openssl s_client -connect "$TARGET:443" -cipher "EXPORT" 2>/dev/null | grep "Cipher" | head -1)
[ -n "$EXPORT_CIPHERS" ] && echo "⚠️  FREAK: Export-grade ciphers accepted" >> "$SESSION/network/tls_downgrade.txt"
if [ -f "$SESSION/network/tls_downgrade.txt" ]; then
    ok "SSL/TLS downgrade vulnerabilities found!"
    ADV_SCORE=$((ADV_SCORE + 15))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 15))
else
    ok "No TLS downgrade vulnerabilities detected"
fi

# ─── ADV 41. HEARTBLEED VULNERABILITY CHECK ───
_section "[ADV 41/60] HEARTBLEED CHECK"
run "Testing for Heartbleed (CVE-2014-0160)..."
HEARTBLEED_TEST=$(timeout 10 bash -c "echo | openssl s_client -connect '$TARGET:443' -tlsextdebug 2>/dev/null" | grep -i "heartbeat")
if echo "$HEARTBLEED_TEST" | grep -qi "heartbeat"; then
    # Send malformed heartbeat request via Python for accuracy
    HB_RESULT=$(python3 -c "
import socket, ssl, sys
try:
    context = ssl.create_default_context()
    with socket.create_connection(('${TARGET}', 443), timeout=10) as sock:
        with context.wrap_socket(sock, server_hostname='${TARGET}') as ssock:
            # TLS heartbeat extension type = 15
            hb = bytes([0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
            ssock.send(hb)
            data = ssock.recv(4096)
            if len(data) > 3:
                print('POTENTIAL')
except Exception:
    pass
" 2>/dev/null)
    if [ "$HB_RESULT" = "POTENTIAL" ]; then
        echo "⚠️  Heartbleed: Server responded to malformed heartbeat" >> "$SESSION/network/heartbleed.txt"
        ok "Heartbleed vulnerability potentially present!"
        ADV_SCORE=$((ADV_SCORE + 25))
        EXPOSURE_SCORE=$((EXPOSURE_SCORE + 25))
    else
        info "Heartbleed not confirmed"
    fi
else
    info "TLS heartbeat extension not advertised"
fi

# ─── ADV 42. HTTP/2 SERVER PUSH ANALYSIS ───
_section "[ADV 42/60] HTTP/2 SERVER PUSH ANALYSIS"
run "Testing HTTP/2 capabilities..."
HTTP2_SUPPORTED=$(curl -s -I --http2 "https://$TARGET" --connect-timeout 10 2>/dev/null | grep -i "HTTP/2")
if [ -n "$HTTP2_SUPPORTED" ]; then
    ok "HTTP/2 supported"
    # Check for server push
    PUSH_TEST=$(curl -s --http2 -I "https://$TARGET" --connect-timeout 10 2>/dev/null)
    if echo "$PUSH_TEST" | grep -qi "link.*rel=.*preload\|x-http2-push\|server-push"; then
        echo "⚠️  HTTP/2 Server Push enabled — cache fingerprinting risk" >> "$SESSION/advanced/http2_push.txt"
        info "HTTP/2 Server Push detected"
    fi
    # Check for HTTP/2 Rapid Reset (CVE-2023-44487)
    # Rapid reset sends RST_STREAM immediately after HEADERS
    RAPID_RESET=$(python3 -c "
import socket, ssl, sys
try:
    context = ssl.create_default_context()
    context.set_alpn_protocols(['h2'])
    with socket.create_connection(('${TARGET}', 443), timeout=10) as sock:
        with context.wrap_socket(sock, server_hostname='${TARGET}') as ssock:
            # Send HTTP/2 connection preface
            ssock.send(b'PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n')
            print('H2_ALPN_SUPPORTED')
except Exception:
    pass
" 2>/dev/null)
    if [ "$RAPID_RESET" = "H2_ALPN_SUPPORTED" ]; then
        echo "HTTP/2 ALPN supported — test for Rapid Reset manually" >> "$SESSION/advanced/http2_rapidreset.txt"
        info "HTTP/2 active — Rapid Reset testing requires manual validation"
    fi
else
    info "HTTP/2 not supported"
fi

