# ─── ADV 45. INSECURE DESERIALIZATION DETECTION ───
_section "[ADV 45/60] INSECURE DESERIALIZATION"
run "Testing for insecure deserialization..."
# PHP deserialization
PHP_PAYLOAD='O:8:"stdClass":1:{s:4:"test";s:3:"yes";}'
PHP_RESP=$(curl -s -X POST -H "Content-Type: application/x-www-form-urlencoded" -d "data=$PHP_PAYLOAD" "https://$TARGET" --connect-timeout 10 2>/dev/null)
if echo "$PHP_RESP" | grep -qiE "unserialize|__wakeup|__destruct|object\(|php object"; then
    echo "⚠️  PHP deserialization detected" >> "$SESSION/advanced/deserialization.txt"
fi
# Java serialized object signature (AC ED 00 05 = magic bytes)
JAVA_MAGIC=$(curl -s -X POST -H "Content-Type: application/x-java-serialized-object" -d $'\xac\xed\x00\x05' "https://$TARGET" --connect-timeout 10 2>/dev/null)
if echo "$JAVA_MAGIC" | grep -qiE "serializ|objectinputstream|classnotfound"; then
    echo "⚠️  Java deserialization endpoint detected" >> "$SESSION/advanced/deserialization.txt"
fi
# Python pickle
PY_RESP=$(curl -s -X POST -H "Content-Type: application/octet-stream" -d $'\x80\x04\x95' "https://$TARGET" --connect-timeout 10 2>/dev/null)
if echo "$PY_RESP" | grep -qiE "pickle|unpickle|loads"; then
    echo "⚠️  Python pickle deserialization detected" >> "$SESSION/advanced/deserialization.txt"
fi
if [ -f "$SESSION/advanced/deserialization.txt" ]; then
    ok "Insecure deserialization indicators found!"
    ADV_SCORE=$((ADV_SCORE + 25))
    EXPOSURE_SCORE=$((EXPOSURE_SCORE + 20))
else
    info "No deserialization indicators detected"
fi

