# Add recommendations based on scores
[ $FIND_SQLI -gt 0 ] && echo "- CRITICAL: SQL Injection confirmed — implement parameterized queries" >> "$SESSION/reports/report.txt"
[ $FIND_XSS -gt 0 ] && echo "- CRITICAL: XSS vulnerabilities found — implement output encoding" >> "$SESSION/reports/report.txt"
[ $FIND_SSRF -gt 0 ] && echo "- CRITICAL: SSRF vectors found — validate and sanitize URLs" >> "$SESSION/reports/report.txt"
[ $FIND_CMDI -gt 0 ] && echo "- CRITICAL: Command Injection — never pass user input to system commands" >> "$SESSION/reports/report.txt"
[ $FIND_LFI -gt 0 ] && echo "- CRITICAL: LFI detected — sanitize file paths and use allowlists" >> "$SESSION/reports/report.txt"
[ $FIND_HEARTBLEED -gt 0 ] && echo "- CRITICAL: Heartbleed vulnerability — update OpenSSL immediately" >> "$SESSION/reports/report.txt"
[ $EXPOSURE_SCORE -ge 20 ] && echo "- Immediate: Address exposed sensitive files/configs" >> "$SESSION/reports/report.txt"
