    [ -f /etc/pam.d/common-auth ] && {
        grep -n "pam_unix" /etc/pam.d/common-auth 2>/dev/null >> "$SESSION/rt/pam_backdoor.txt"
        echo "PAM_CONFIG: /etc/pam.d/common-auth" >> "$SESSION/rt/pam_backdoor.txt"
