}

rt_174_ebpf_rootkit_deploy() {
    local target="${1:-$TARGET}"
    _section "[RT-174] EBPF ROOTKIT DEPLOYMENT"
    run "Checking eBPF capabilities for kernel-level rootkit..."
    > "$SESSION/rt/ebpf_rootkit.txt"
    [ -f /proc/sys/kernel/unprivileged_bpf_disabled ] && {
        local bpf_disabled=$(cat /proc/sys/kernel/unprivileged_bpf_disabled 2>/dev/null)
        echo "BPF_DISABLED: ${bpf_disabled}" >> "$SESSION/rt/ebpf_rootkit.txt"
        [ "$bpf_disabled" = "0" ] && rt "eBPF enabled for unprivileged users!"
    }
    [ -f /sys/kernel/debug/tracing ] && echo "FTRACE_AVAILABLE: yes" >> "$SESSION/rt/ebpf_rootkit.txt"
    which bpftool >/dev/null 2>&1 && { echo "BPFTOOL: available" >> "$SESSION/rt/ebpf_rootkit.txt"; rt "bpftool available"; }
    [ -s "$SESSION/rt/ebpf_rootkit.txt" ] && rt "eBPF rootkit check complete" || info "eBPF not available"
}

