    local cap_sys_module=$(capsh --print 2>/dev/null | grep "cap_sys_module")
    [ -n "$cap_sys_module" ] && { echo "CAP_SYS_MODULE: yes" >> "$SESSION/rt/kmod_rootkit.txt"; rt "CAP_SYS_MODULE available!"; }
    [ -s "$SESSION/rt/kmod_rootkit.txt" ] && rt "Kernel module check complete" || info "Kernel module requires root"
