rt_161_s3_bucket_public_enum() {
    local target="${1:-$TARGET}"
    _section "[RT-161] S3 BUCKET PUBLIC ENUMERATION"
    run "Testing for publicly listable S3 buckets..."
    > "$SESSION/rt/s3_buckets.txt"
    local BUCKETS=("$target" "${target//./-}" "${target//./_}" "${target//.}" "cdn-$target" "media-$target" "static-$target" "assets-$target" "backup-$target" "db-$target" "logs-$target" "dev-$target" "staging-$target")
    for bucket in "${BUCKETS[@]}"; do
        local resp=$(curl -sk --max-time 10 "https://${bucket}.s3.amazonaws.com/?list-type=2&max-keys=10" 2>/dev/null)
        echo "$resp" | grep -q '<ListBucketResult' && {
            local count=$(echo "$resp" | grep -o '<Key>' | wc -l | tr -d ' ')
            echo "PUBLIC S3: ${bucket}.s3.amazonaws.com ($count objects)" >> "$SESSION/rt/s3_buckets.txt"
            rt "PUBLIC S3 BUCKET: ${bucket}.s3.amazonaws.com ($count objects)!"
        }
    done
    [ -s "$SESSION/rt/s3_buckets.txt" ] || info "No public S3 buckets found"
}

rt_162_s3_write_permission_test() {
    local target="${1:-$TARGET}"
    [[ -f "$SESSION/rt/s3_buckets.txt" ]] || return
    _section "[RT-162] S3 BUCKET WRITE PERMISSION TEST"
    run "Testing discovered S3 buckets for write access..."
    > "$SESSION/rt/s3_writable.txt"
    local buckets=$(grep -oP 'PUBLIC S3: \K[^ ]+' "$SESSION/rt/s3_buckets.txt" 2>/dev/null)
    for bucket in $buckets; do
        local test_file="security-test-$(date +%s).txt"
        local put_resp=$(curl -ski -X PUT --max-time 10 \
            -H "Content-Type: text/plain" \
            -d "BB_RECON_SECURITY_TEST" \
            "https://${bucket}/${test_file}" 2>/dev/null)
        echo "$put_resp" | grep -q '200 OK' && {
            echo "WRITABLE S3: ${bucket} — ANYONE can upload/delete!" >> "$SESSION/rt/s3_writable.txt"
            # Delete test file (responsible)
            curl -ski -X DELETE --max-time 5 "https://${bucket}/${test_file}" 2>/dev/null >/dev/null
            rt "WRITABLE S3: ${bucket} — bucket takeover possible!"
        }
    done
    [ -s "$SESSION/rt/s3_writable.txt" ] || info "No writable S3 buckets"
}

rt_163_subdomain_origin_ip_bypass() {
    local target="${1:-$TARGET}"
    _section "[RT-163] SUBDOMAIN ORIGIN IP BYPASS (CDN/WAF Bypass)"
    run "Finding subdomains that bypass CDN/WAF and expose origin IP..."
    > "$SESSION/rt/cdn_bypass_subdomains.txt"
    local SUBS=("mail" "mailserver" "ftp" "direct" "origin" "old" "staging" "dev" "beta"
        "test" "backup" "admin" "webmail" "cpanel" "whm" "webmin" "plesk"
        "mx" "smtp" "pop" "imap" "ns1" "ns2" "dns" "host" "server"
        "cp" "panel" "web" "www2" "www1" "old" "legacy" "git" "svn"
        "jenkins" "gitlab" "registry" "registry-1" "docker" "k8s" "kube"
        "api-internal" "internal" "private" "secure" "vpn" "remote")
    # Get CDN IPs for comparison
    local cdn_ips=$(dig +short "$target" A 2>/dev/null | tr '\n' ' ')
    for sub in "${SUBS[@]}"; do
        local ip=$(dig +short "${sub}.${target}" A 2>/dev/null | head -1)
        [ -n "$ip" ] && [[ " $cdn_ips " != *" $ip "* ]] && \
            ! echo "$ip" | grep -qiE 'cloudflare|akamai|fastly|incapsula|sucuri' && {
            echo "ORIGIN BYPASS: ${sub}.${target} -> $ip (NOT behind CDN)" >> "$SESSION/rt/cdn_bypass_subdomains.txt"
            rt "CDN BYPASS: ${sub}.${target} -> $ip exposes origin!"
        }
    done
    [ -s "$SESSION/rt/cdn_bypass_subdomains.txt" ] || info "No CDN bypass subdomains found"
}

rt_164_openssh_cve_2023_38408() {
    local target="${1:-$TARGET}"
    [[ -f "$SESSION/rt/cdn_bypass_subdomains.txt" ]] || return
    _section "[RT-164] OPENSSH CVE-2023-38408 (Agent Forwarding RCE)"
    run "Testing exposed origin servers for OpenSSH agent forwarding RCE..."
    > "$SESSION/rt/ssh_cve_2023_38408.txt"
    local origins=$(grep -oP '-> \K[0-9.]+' "$SESSION/rt/cdn_bypass_subdomains.txt" 2>/dev/null | sort -u)
    [ -z "$origins" ] && origins=$(dig +short "$target" A 2>/dev/null)
    for ip in $origins; do
        local banner=$(timeout 5 bash -c "echo | nc $ip 22" 2>/dev/null | head -1)
        echo "$banner" | grep -qE 'SSH-2.0-OpenSSH_[0-8]\.|SSH-2.0-OpenSSH_9\.[0-2]' && {
            local version=$(echo "$banner" | grep -oP 'OpenSSH_[0-9.]+')
            echo "CVE-2023-38408: $ip -> $version (Agent Forwarding RCE)" >> "$SESSION/rt/ssh_cve_2023_38408.txt"
            rt "CVE-2023-38408: $ip $version — SSH Agent RCE!"
        }
        echo "$banner" | grep -qE 'SSH-2.0-OpenSSH_9\.3' && {
            echo "CHECK: $ip -> OpenSSH 9.3 (need patch level)" >> "$SESSION/rt/ssh_cve_2023_38408.txt"
        }
    done
    [ -s "$SESSION/rt/ssh_cve_2023_38408.txt" ] || info "No vulnerable OpenSSH found"
}

rt_165_github_org_enum() {
    local target="${1:-$TARGET}"
    _section "[RT-165] GITHUB ORG/REPO ENUMERATION"
    run "Searching for public GitHub orgs and repos..."
    > "$SESSION/rt/github_org.txt"
    local org_name=$(echo "$target" | sed 's/\.[^.]*$//')
    # Check org repos
    local repos=$(curl -sk --max-time 15 \
        "https://api.github.com/orgs/${org_name}/repos?per_page=100" 2>/dev/null)
    echo "$repos" | grep -q '"full_name"' && {
        echo "GITHUB ORG: ${org_name}" >> "$SESSION/rt/github_org.txt"
        echo "$repos" | grep -oP '"full_name":"[^"]+"' | sed 's/.*"//' | head -20 >> "$SESSION/rt/github_org.txt"
        local count=$(echo "$repos" | grep -c '"full_name"')
        rt "GitHub org ${org_name} found with $count repos!"
    }
    # Search for target name in repos
    local search=$(curl -sk --max-time 15 \
        "https://api.github.com/search/repositories?q=${org_name}+in:name&per_page=10" 2>/dev/null)
    echo "$search" | grep -q '"total_count": [1-9]' && {
        echo "$search" | grep -oP '"full_name":"[^"]+"' | sed 's/.*"//' | head -10 >> "$SESSION/rt/github_org.txt"
    }
    [ -s "$SESSION/rt/github_org.txt" ] || info "No GitHub org/repos found"
}

rt_166_domain_redirect_chain_map() {
    local target="${1:-$TARGET}"
    _section "[RT-166] DOMAIN REDIRECT CHAIN MAPPING"
    run "Mapping redirect chains to find origin infrastructure..."
    > "$SESSION/rt/redirect_chain.txt"
    # Check for .com -> .tv redirects and similar
    local tld_com="${target//.tv/.com}"; tld_com="${tld_com//.io/.com}"; tld_com="${tld_com//.app/.com}"
    [ "$tld_com" != "$target" ] && {
        local resp=$(curl -ski --max-time 10 "https://${tld_com}/" 2>/dev/null)
        echo "$resp" | grep -qiE '301|302|redirect|location:' && {
            local loc=$(echo "$resp" | grep -i '^location:' | head -1)
            echo "REDIRECT: ${tld_com} -> ${loc}" >> "$SESSION/rt/redirect_chain.txt"
            rt "Redirect chain: ${tld_com} exposes ${loc}!"
        }
    }
    # Check www -> non-www redirects
    local resp2=$(curl -ski --max-time 10 "https://www.${target}/" 2>/dev/null)
    echo "$resp2" | grep -qiE '301|302' && {
        local loc2=$(echo "$resp2" | grep -i '^location:' | head -1)
        [ -n "$loc2" ] && echo "REDIRECT: www.${target} -> ${loc2}" >> "$SESSION/rt/redirect_chain.txt"
    }
    [ -s "$SESSION/rt/redirect_chain.txt" ] || info "No redirect chains found"
}

