rt_189_s3_object_metadata_leak() {
    local target="${1:-$TARGET}"
    _section "[RT-189] S3 OBJECT METADATA LEAK"
    run "Extracting metadata from S3 objects for intelligence..."
    > "$SESSION/rt/s3_metadata_leak.txt"
    [[ -f "$SESSION/rt/s3_buckets.txt" ]] || { info "No S3 buckets found"; return; }
    local buckets=$(grep -oP 'PUBLIC S3: \K[^ ]+' "$SESSION/rt/s3_buckets.txt" 2>/dev/null)
    for bucket in $buckets; do
        local objs=$(curl -sk --max-time 10 "https://${bucket}/?list-type=2&max-keys=20" 2>/dev/null | \
            grep -oP '(?<=<Key>)[^<]+' | head -10)
        for obj in $objs; do
            local head_resp=$(curl -ski --max-time 8 \
                -X HEAD "https://${bucket}/${obj}" 2>/dev/null)
            local meta=$(echo "$head_resp" | grep -iE 'x-amz-meta-|x-amz-|server|date|etag|content-type|last-modified' | head -10)
            [ -n "$meta" ] && {
                echo "METADATA: ${bucket}/${obj}" >> "$SESSION/rt/s3_metadata_leak.txt"
                echo "$meta" | sed 's/^/  /' >> "$SESSION/rt/s3_metadata_leak.txt"
                local owner=$(echo "$head_resp" | grep -oP 'x-amz-id-2: \K[^ ]+' | head -1)
                [ -n "$owner" ] && echo "  Owner-Token: ${owner:0:40}..." >> "$SESSION/rt/s3_metadata_leak.txt"
            }
        done
    done
    [ -s "$SESSION/rt/s3_metadata_leak.txt" ] && rt "S3 metadata extracted" || info "No S3 metadata leaked"
}

