        local py_test=$(python3 -c "
import socket, ssl
ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE
sock = socket.create_connection(('${ip}', 443))
ssock = ctx.wrap_socket(sock, server_hostname='${target}')
req = b'GET /control/login HTTP/1.1\r\nHost: ${target}\r\nUpgrade: h2c\r\nHTTP2-Settings: AAMAAABkAARAAAAAAAIAAAAA\r\nConnection: Upgrade, HTTP2-Settings\r\n\r\n'
ssock.send(req)
print(ssock.recv(2048).decode()[:500])
ssock.close()
" 2>/dev/null)
        echo "$py_test" | grep -qi 'switching protocols\|h2c' && {
            echo "CVE-2026-32136: Python h2c confirmed at ${ip}" >> "$SESSION/rt/cve_2026_32136.txt"
            rt "CVE-2026-32136 confirmed via Python at ${ip}!"
        }
    done
    [ -s "$SESSION/rt/cve_2026_32136.txt" ] && rt "CVE-2026-32136 test complete" || info "CVE-2026-32136 not exploitable (likely nginx blocks h2c)"
