rt_195_github_osint_recon() {
    local target="${1:-$TARGET}"
    _section "[RT-195] GITHUB OSINT — OPERATOR IDENTIFICATION"
    run "Mining GitHub for operator identities, repos, and leaked configs..."
    > "$SESSION/rt/github_osint.txt"
    # Derive likely GitHub username from domain
    local gh_user="${target%%.*}"
    gh_user="${gh_user//-/}"
    [ -z "$gh_user" ] && gh_user="$target"

    # Check if user exists
    local user_resp=$(curl -sk --max-time 15 "https://api.github.com/users/${gh_user}" 2>/dev/null)
    echo "$user_resp" | grep -q '"login"' && {
        local login=$(echo "$user_resp" | grep -oP '"login":\s*"\K[^"]+' | head -1)
        local name=$(echo "$user_resp" | grep -oP '"name":\s*"\K[^"]+' | head -1)
        local created=$(echo "$user_resp" | grep -oP '"created_at":\s*"\K[^"]+' | head -1)
        local repos=$(echo "$user_resp" | grep -oP '"public_repos":\s*\K[0-9]+' | head -1)
        echo "GITHUB USER: ${login} | Name: ${name} | Repos: ${repos} | Created: ${created}" >> "$SESSION/rt/github_osint.txt"
        [ -n "$name" ] && rt "Operator identified: ${name} (GitHub: ${login})!"

        # Get repositories
        local repos_json=$(curl -sk --max-time 15 "https://api.github.com/users/${login}/repos?per_page=100" 2>/dev/null)
        local repo_names=$(echo "$repos_json" | grep -oP '"name":\s*"\K[^"]+' 2>/dev/null)
        for repo in $repo_names; do
            echo "GITHUB REPO: ${login}/${repo}" >> "$SESSION/rt/github_osint.txt"
            # Check for config files
            for file in "config.json" ".env" "docker-compose.yml" "Dockerfile" "package.json" "nginx.conf" "settings.json" "credentials.json" "AdGuardHome.yaml"; do
                local fstatus=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 6 "https://raw.githubusercontent.com/${login}/${repo}/main/${file}" 2>/dev/null)
                [ "$fstatus" = "200" ] && {
                    echo "LEAKED FILE: ${login}/${repo}/${file} -> HTTP 200" >> "$SESSION/rt/github_osint.txt"
                    rt "LEAKED CONFIG: ${login}/${repo}/${file}!"
                }
            done
        done

        # Get gists
        local gists=$(curl -sk --max-time 15 "https://api.github.com/users/${login}/gists" 2>/dev/null)
        local gist_ids=$(echo "$gists" | grep -oP '"id":\s*"\K[a-f0-9]+' 2>/dev/null)
        for gid in $gist_ids; do
            echo "GITHUB GIST: ${login}/${gid}" >> "$SESSION/rt/github_osint.txt"
            local gist_detail=$(curl -sk --max-time 10 "https://api.github.com/gists/${gid}" 2>/dev/null)
            local gist_files=$(echo "$gist_detail" | grep -oP '"filename":\s*"\K[^"]+' 2>/dev/null)
            for gf in $gist_files; do
                echo "GIST FILE: ${gf}" >> "$SESSION/rt/github_osint.txt"
            done
        done
    }

    # Also search related accounts
    local domain_base="${target%%.*}"
    for suffix in "" "485" "bas" "b" "delhady-cloud" "dul"; do
        local related_resp=$(curl -sk --max-time 8 "https://api.github.com/users/${domain_base}${suffix}" 2>/dev/null)
        echo "$related_resp" | grep -q '"login"' && {
            local rlogin=$(echo "$related_resp" | grep -oP '"login":\s*"\K[^"]+' | head -1)
            [ "$rlogin" != "$gh_user" ] && echo "GITHUB RELATED: ${rlogin}" >> "$SESSION/rt/github_osint.txt"
        }
    done

    [ -s "$SESSION/rt/github_osint.txt" ] && rt "GitHub OSINT complete" || info "No GitHub data found"
}

