    local csp=$(curl -skI --max-time 10 "https://${target}/" 2>/dev/null | grep -i "content-security-policy")
    local csp_workers=$(echo "$csp" | grep -oP '[a-z0-9-]+\.workers\.dev' | sort -u)
    for cw in $csp_workers; do
        local cstatus=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 8 "https://${cw}/" 2>/dev/null)
        echo "WORKER CSP: ${cw} -> HTTP ${cstatus}" >> "$SESSION/rt/workers_dev.txt"
    done
    [ -s "$SESSION/rt/workers_dev.txt" ] && rt "Workers.dev enumeration complete" || info "No active Workers found"
}

rt_198_csp_analysis_injection() {
    local target="${1:-$TARGET}"
    _section "[RT-198] CSP ANALYSIS FOR XSS INJECTION POINTS"
    run "Analyzing Content-Security-Policy for bypass opportunities..."
    > "$SESSION/rt/csp_analysis.txt"
    local csp=$(curl -skI --max-time 10 "https://${target}/" 2>/dev/null | grep -i "content-security-policy")
    [ -n "$csp" ] && {
        echo "CSP HEADER: ${csp}" >> "$SESSION/rt/csp_analysis.txt"
        # Check for dangerous directives
        echo "$csp" | grep -qi "unsafe-inline" && {
            echo "CSP WEAK: 'unsafe-inline' allows inline script injection" >> "$SESSION/rt/csp_analysis.txt"
            rt "CSP 'unsafe-inline' found — XSS injection possible!"
        }
        echo "$csp" | grep -qi "unsafe-eval" && {
            echo "CSP WEAK: 'unsafe-eval' allows eval() injection" >> "$SESSION/rt/csp_analysis.txt"
            rt "CSP 'unsafe-eval' found!"
        }
        # Extract third-party domains
        local domains=$(echo "$csp" | grep -oP 'https?://[^"\s;]+' | sed 's|/$||' | sort -u)
        for domain in $domains; do
            local dstatus=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 8 "${domain}/" 2>/dev/null)
            local dip=$(echo "$domain" | grep -oP '(?<=://)[^/]+' | xargs dig +short 2>/dev/null | head -1)
            echo "CSP DOMAIN: ${domain} -> IP: ${dip} HTTP: ${dstatus}" >> "$SESSION/rt/csp_analysis.txt"
            # Flag ad/malware domains
            echo "$domain" | grep -qiE 'ad|track|analytics|metric|pixel|beacon' && {
                echo "CSP AD DOMAIN: ${domain} — potential injection vector" >> "$SESSION/rt/csp_analysis.txt"
                rt "Ad/malware domain in CSP: ${domain}!"
            }
        done
        # Check frame-src for clickjacking
        local frame_src=$(echo "$csp" | grep -oP 'frame-src[^;]+')
        [ -n "$frame_src" ] && echo "CSP FRAME-SRC: ${frame_src}" >> "$SESSION/rt/csp_analysis.txt"
        # Check for missing default-src
        echo "$csp" | grep -qi "default-src" || {
            echo "CSP WEAK: Missing default-src — falls back to allowing everything" >> "$SESSION/rt/csp_analysis.txt"
            rt "CSP missing default-src!"
        }
    }
    [ -s "$SESSION/rt/csp_analysis.txt" ] && rt "CSP analysis complete" || info "No CSP header found"
}

rt_199_smtp_user_enum() {
    local target="${1:-$TARGET}"
    _section "[RT-199] SMTP USER ENUMERATION"
    run "Enumerating valid email users via SMTP VRFY/RCPT..."
    > "$SESSION/rt/smtp_enum.txt"
    local mx_ip=$(dig +short "mail.${target}" A 2>/dev/null | head -1)
    [ -z "$mx_ip" ] && mx_ip=$(dig +short "${target}" MX 2>/dev/null | head -1 | awk '{print $2}')
    [ -z "$mx_ip" ] && mx_ip=$(dig +short "${target}" A 2>/dev/null | head -1)
    [ -z "$mx_ip" ] && { info "No mail server found"; return; }

    for port in 25 587 465; do
        (timeout 3 bash -c "exec 3<>/dev/tcp/${mx_ip}/${port}" 2>/dev/null) || continue
        local users="admin root postmaster webmaster info support help desk sales marketing hostmaster abuse"
        for user in $users; do
            local vrfy_resp=$(timeout 5 bash -c "exec 3<>/dev/tcp/${mx_ip}/${port}; echo 'VRFY ${user}' >&3; cat <&3" 2>/dev/null | head -3)
            echo "$vrfy_resp" | grep -qi '2[0-9][0-9]\|User OK' && {
                echo "SMTP USER: ${user}@${target} confirmed via VRFY" >> "$SESSION/rt/smtp_enum.txt"
                rt "SMTP user confirmed: ${user}@${target}!"
            }
            # Try RCPT TO
            local rcpt_resp=$(timeout 5 bash -c "exec 3<>/dev/tcp/${mx_ip}/${port};
                read <&3;
                echo 'HELO recon' >&3;
                read <&3;
                echo 'MAIL FROM:<test@example.com>' >&3;
                read <&3;
                echo 'RCPT TO:<${user}@${target}>' >&3;
                cat <&3" 2>/dev/null)
            echo "$rcpt_resp" | grep -qi '2[0-9][0-9]\|OK' && {
                echo "SMTP RCPT: ${user}@${target} confirmed" >> "$SESSION/rt/smtp_enum.txt"
                rt "SMTP RCPT confirmed: ${user}@${target}!"
            }
        done
    done
    [ -s "$SESSION/rt/smtp_enum.txt" ] && rt "SMTP enumeration complete" || info "SMTP user enumeration inconclusive"
}

rt_200_tcp_dns_exfiltration() {
    local target="${1:-$TARGET}"
    _section "[RT-200] TCP DNS EXFILTRATION CHANNEL"
    run "Testing TCP DNS as data exfiltration channel..."
    > "$SESSION/rt/tcp_dns_exfil.txt"
    local dns_ip="${DNS_IP:-$IP}"
    [ -z "$dns_ip" ] && dns_ip=$(dig +short "${target}" A 2>/dev/null | head -1)
    [ -z "$dns_ip" ] && { info "No DNS server IP available"; return; }

    # Test TCP DNS query
    local tcp_result=$(dig +tcp @"${dns_ip}" example.com A +short 2>/dev/null)
    [ -n "$tcp_result" ] && {
        echo "TCP DNS: ${dns_ip} responds to TCP queries" >> "$SESSION/rt/tcp_dns_exfil.txt"
        rt "TCP DNS responder at ${dns_ip}!"
    }
    # Test zone transfer
    local axfr_result=$(dig +tcp @"${dns_ip}" "${target}" AXFR 2>&1)
    echo "$axfr_result" | grep -q 'Transfer failed\; REFUSED\; NOAUTH' || {
        echo "$axfr_result" | grep -q 'SOA\; NS' && {
            echo "TCP DNS AXFR: Zone transfer succeeded!" >> "$SESSION/rt/tcp_dns_exfil.txt"
            rt "CRITICAL: DNS zone transfer enabled on ${dns_ip}!"
        }
    }
    # Test for open resolver
    local random_sub=$(openssl rand -hex 8 2>/dev/null || head -c 16 /dev/urandom | xxd -p | head -c 16)
    local resolve_test=$(dig +tcp @"${dns_ip}" "${random_sub}.test.com" A +short 2>/dev/null)
    [ -n "$resolve_test" ] && {
        echo "TCP DNS: Open resolver confirmed at ${dns_ip}" >> "$SESSION/rt/tcp_dns_exfil.txt"
        rt "Open DNS resolver at ${dns_ip}!"
    }
    [ -s "$SESSION/rt/tcp_dns_exfil.txt" ] && rt "TCP DNS exfiltration test complete" || info "No TCP DNS channel available"
}

