    # Search for common API key patterns
    local patterns=("api[_-]?key['\"\s]*[:=]['\"\s]*[a-zA-Z0-9_-]{16,}" "api[_-]?secret['\"\s]*[:=]['\"\s]*[a-zA-Z0-9_-]{16,}" "aws_access_key_id['\"\s]*[:=]['\"\s]*AKIA" "aws_secret_access_key['\"\s]*[:=]['\"\s]*[a-zA-Z0-9/+=]{40}" "github[_-]?token['\"\s]*[:=]['\"\s]*ghp_[a-zA-Z0-9]{36}" "slack[_-]?token['\"\s]*[:=]['\"\s]*xox[baprs]-" "google[_-]?api[_-]?key['\"\s]*[:=]['\"\s]*AIza" "firebase[_-]?api[_-]?key['\"\s]*[:=]['\"\s]*AIza" "stripe[_-]?key['\"\s]*[:=]['\"\s]*sk_[a-zA-Z0-9]{24,}" "auth[_-]?token['\"\s]*[:=]['\"\s]*eyJ" "private[_-]?key['\"\s]*[:=]['\"\s]*-----BEGIN" "password['\"\s]*[:=]['\"\s]*[^'\"\s]{8,}" "secret['\"\s]*[:=]['\"\s]*[a-zA-Z0-9]{16,}" "token['\"\s]*[:=]['\"\s]*[a-zA-Z0-9_-]{20,}")
