rt_250_live_s3_azure_gcp_hunt() {
    local target="${1:-$TARGET}"
    _section "[RT-250] LIVE CLOUD STORAGE HUNT"
    run "Hunting for exposed S3, Azure, and GCS buckets..."
    > "$SESSION/rt/live_cloud_storage.txt"
    local buckets=("$target" "${target//./-}" "${target//./_}" "$(echo "$target" | cut -d. -f1)")
    for base in "${buckets[@]}"; do
        for region in "" "us-east-1" "us-west-2" "eu-west-1"; do
            local s3_url="https://${base}.s3${region:+.${region}}.amazonaws.com"
            local s3_resp=$(curl -sk --max-time 5 -X GET "$s3_url" 2>/dev/null)
            echo "$s3_resp" | grep -qi "ListBucketResult" && echo "S3_BUCKET: $s3_url" >> "$SESSION/rt/live_cloud_storage.txt" && rt "Exposed S3: $s3_url"
        done
        local azure_url="https://${base}.blob.core.windows.net"
        local azure_resp=$(curl -sk --max-time 5 -I "$azure_url" 2>/dev/null | head -1)
        echo "$azure_resp" | grep -q "200\|404" && echo "AZURE_BLOB: $azure_url" >> "$SESSION/rt/live_cloud_storage.txt"
        local gcs_url="https://storage.googleapis.com/${base}"
        local gcs_resp=$(curl -sk --max-time 5 -I "$gcs_url" 2>/dev/null | head -1)
        echo "$gcs_resp" | grep -q "200\|404" && echo "GCS_BUCKET: $gcs_url" >> "$SESSION/rt/live_cloud_storage.txt"
    done
    [ -s "$SESSION/rt/live_cloud_storage.txt" ] && rt "Cloud storage hunt complete" || info "No exposed buckets"
}

