    local test_resp=$(curl -sk --max-time 8 -X POST -d "<methodCall><methodName>system.listMethods</methodName></methodCall>" "$xmlrpc_url" 2>/dev/null)
    echo "$test_resp" | grep -q "system.multicall" && {
        echo "XMLRPC_MULTICALL: Available" >> "$SESSION/rt/wp_xmlrpc.txt"
        local payload='<methodCall><methodName>system.multicall</methodName><params><param><value><array><data>'
        for i in $(seq 1 20); do
            payload="${payload}<value><struct><member><name>methodName</name><value><string>system.listMethods</string></value></member></struct></value>"
        done
        payload="${payload}</data></array></value></param></params></methodCall>"
        local start=$(date +%s%N)
        local mc_resp=$(curl -sk --max-time 15 -X POST -d "$payload" "$xmlrpc_url" 2>/dev/null)
        local end=$(date +%s%N)
        local elapsed=$(( (end - start) / 1000000 ))
