        [ "$responses" -gt 5 ] && echo "AMPLIFICATION: 20x -> ${responses} responses in ${elapsed}ms" >> "$SESSION/rt/wp_xmlrpc.txt" && rt "XML-RPC 20x amplification confirmed!"
    }
    [ -s "$SESSION/rt/wp_xmlrpc.txt" ] && rt "XML-RPC test complete" || info "XML-RPC not available"
