rt_291_internal_arp_scan() {
    local target="${1:-$TARGET}"
    _section "[RT-291] INTERNAL ARP NETWORK SCAN"
    run "Performing ARP scan on local network segment..."
    > "$SESSION/rt/internal_arp.txt"
    local iface=$(ip route 2>/dev/null | grep default | awk '{print $5}' | head -1)
    [ -n "$iface" ] && {
        local subnet=$(ip addr show "$iface" 2>/dev/null | grep "inet " | awk '{print $2}')
        [ -n "$subnet" ] && {
            echo "LOCAL_SUBNET: ${subnet}" >> "$SESSION/rt/internal_arp.txt"
            which arp-scan >/dev/null 2>&1 && {
                local arp_result=$(arp-scan -l -I "$iface" 2>/dev/null | grep -E '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+')
                [ -n "$arp_result" ] && { echo "ARP_HOSTS:" >> "$SESSION/rt/internal_arp.txt"; echo "$arp_result" >> "$SESSION/rt/internal_arp.txt"; rt "ARP scan found hosts"; }
            }
        }
    }
    local netstat_routes=$(netstat -rn 2>/dev/null | grep -E '^[0-9]+\.' | head -10)
    [ -n "$netstat_routes" ] && echo "ROUTES: ${netstat_routes}" >> "$SESSION/rt/internal_arp.txt"
    [ -s "$SESSION/rt/internal_arp.txt" ] && rt "Internal ARP scan complete" || info "No local network access"
}

