rt_301_subnet_ping_sweep() {
    local target="${1:-$TARGET}"
    _section "[RT-301] SUBNET PING SWEEP"
    run "Performing ICMP ping sweep across target subnet..."
    > "$SESSION/rt/subnet_ping.txt"
    local base_ip="${target%.*}"
    [ "$base_ip" = "$target" ] && base_ip="10.147.122"
    echo "SUBNET: ${base_ip}.0/24" >> "$SESSION/rt/subnet_ping.txt"
    local alive_count=0
    for i in $(seq 1 254); do
        local ip="${base_ip}.${i}"
        timeout 1 bash -c "ping -c 1 -W 1 ${ip} > /dev/null 2>&1" 2>/dev/null && { echo "ALIVE: ${ip}" >> "$SESSION/rt/subnet_ping.txt"; alive_count=$((alive_count+1)); }
        [ "$i" -gt 30 ] && break
    done
    echo "ALIVE_COUNT: ${alive_count}" >> "$SESSION/rt/subnet_ping.txt"
    [ "$alive_count" -gt 0 ] && rt "Subnet ping sweep: ${alive_count} hosts alive" || info "No hosts responded to ping"
}

