    for i in $(seq 1 20); do
        local ip="${base_ip}.${i}"
        for port in "${common_ports[@]}"; do
            timeout 2 bash -c "echo > /dev/tcp/${ip}/${port}" 2>/dev/null && echo "OPEN: ${ip}:${port}" >> "$SESSION/rt/subnet_ports.txt" && rt "Port open: ${ip}:${port}"
