    local ws_endpoints=("/ws" "/socket" "/websocket" "/ws/v1" "/ws/v2" "/realtime" "/live" "/stream")
    for ep in "${ws_endpoints[@]}"; do
        local resp=$(curl -skI --max-time 5 -H "Upgrade: websocket" -H "Connection: Upgrade" -H "Sec-WebSocket-Key: $(openssl rand -base64 16)" -H "Sec-WebSocket-Version: 13" "https://${target}${ep}" 2>/dev/null | head -5)
        [ -n "$resp" ] && echo "${ep}: ${resp}" >> "$SESSION/rt/bb_websocket.txt"
    done
    [ -s "$SESSION/rt/bb_websocket.txt" ] && rt "WebSocket test complete" || info "WebSocket minimal"
}

rt_319_bb_jwt_analysis() {
    local target="${1:-$TARGET}"
    _section "[RT-319] BUG BOUNTY JWT TOKEN ANALYSIS"
    run "Analyzing JWT implementation for vulnerabilities..."
    > "$SESSION/rt/bb_jwt.txt"
    local cookies=$(curl -skI --max-time 8 -A "Mozilla/5.0" "https://${target}/" 2>/dev/null | grep -i "set-cookie")
    echo "$cookies" | grep -qi "eyJ" && {
        echo "JWT IN COOKIE DETECTED" >> "$SESSION/rt/bb_jwt.txt"
        local jwt=$(echo "$cookies" | grep -oP 'eyJ[A-Za-z0-9_-]*\.eyJ[A-Za-z0-9_-]*\.[A-Za-z0-9_-]*' | head -1)
        [ -n "$jwt" ] && {
            echo "JWT: ${jwt:0:50}..." >> "$SESSION/rt/bb_jwt.txt"
            local header=$(echo "$jwt" | cut -d. -f1 | tr '_-' '/+' | base64 -d 2>/dev/null)
            echo "HEADER: $header" >> "$SESSION/rt/bb_jwt.txt"
            echo "$header" | grep -qi "none" && echo "ALGORITHM: NONE SUPPORTED" >> "$SESSION/rt/bb_jwt.txt"
            echo "$header" | grep -qi "HS256" && echo "ALGORITHM: HS256" >> "$SESSION/rt/bb_jwt.txt"
            echo "$header" | grep -qi "RS256" && echo "ALGORITHM: RS256" >> "$SESSION/rt/bb_jwt.txt"
        }
    }
    local auth_resp=$(curl -skI --max-time 8 -X POST -H "Content-Type: application/json" -d '{"username":"test","password":"test"}' "https://${target}/api/auth/login" 2>/dev/null)
    echo "$auth_resp" | grep -qi "eyJ" && echo "JWT IN AUTH RESPONSE" >> "$SESSION/rt/bb_jwt.txt"
    [ -s "$SESSION/rt/bb_jwt.txt" ] && rt "JWT analysis complete" || info "JWT minimal"
}

rt_320_bb_final_report() {
    local target="${1:-$TARGET}"
    _section "[RT-320] BUG BOUNTY PLATFORM FINAL REPORT"
    run "Generating comprehensive bug bounty Red Team report..."
    > "$SESSION/rt/bb_rt_report.txt"
    local ip=$(dig @8.8.8.8 +short "$target" A 2>/dev/null | head -1)
    local subs=$(grep -c "${target}" "$SESSION/rt/bb_subdomains.txt" 2>/dev/null || echo 0)
    local eps=$(wc -l < "$SESSION/rt/bb_endpoints.txt" 2>/dev/null || echo 0)
    local idor=$(grep -c "ACCESSIBLE" "$SESSION/rt/bb_idor.txt" 2>/dev/null || echo 0)
    local xss=$(wc -l < "$SESSION/rt/bb_xss.txt" 2>/dev/null || echo 0)
    local info_disc=$(wc -l < "$SESSION/rt/bb_info_disclosure.txt" 2>/dev/null || echo 0)
    cat >> "$SESSION/rt/bb_rt_report.txt" << 'RTBBEOF'
═══════════════════════════════════════════════════════════════
   BUG BOUNTY RED TEAM ASSESSMENT
═══════════════════════════════════════════════════════════════

RED TEAM MODULES (RT-311 to RT-320):
  [RT-311] Platform Port & Service Scan
  [RT-312] Subdomain Enumeration
  [RT-313] Endpoint Bruteforce (80+ BB paths)
  [RT-314] IDOR Test (reports, users, programs)
  [RT-315] XSS Test (reflected on search params)
  [RT-316] NoSQL Injection Test
  [RT-317] Information Disclosure
  [RT-318] WebSocket Test
  [RT-319] JWT Token Analysis
  [RT-320] Final Report
═══════════════════════════════════════════════════════════════
RTBBEOF
    [ -s "$SESSION/rt/bb_rt_report.txt" ] && rt "Bug bounty RT report generated" || info "BB RT report ready"
}

