# Module RT-490: CVE-2024-31227 - Redis Lua Script Sandbox Escape
rt_490_cve_cve_2024_31227() {
    local CVE_ID="CVE-2024-31227"
    local CVE_TITLE="Redis Lua Script Sandbox Escape"
    local CVE_SEV="CRITICAL"
    cve_banner "$CVE_ID" "$CVE_SEV"
    log_cve_info "$CVE_ID" "$CVE_TITLE" "$CVE_SEV"

    # Smart detection: check_port 6379
    if ! check_port 6379; then
        log_skipped "$CVE_ID" "Target technology not detected"
        return 0
    fi

    echo -e "    $CYAN[*] Testing CVE-2024-31227: Redis Lua Script Sandbox Escape$NC"
    echo -e "    $CYAN[*] Detection: check_port 6379$NC"

    if command -v redis-cli &>/dev/null; then
        local redis_ping; redis_ping=$(timeout 5 redis-cli -h "$TARGET" -p 6379 PING 2>/dev/null)
        if [[ "$redis_ping" == "PONG" ]]; then
            echo -e "    $RED[CRITICAL] Redis server is AUTHENTICATION-LESS and exposed$NC"
            add_vuln "$CVE_ID" "CRITICAL" "$CVE_TITLE" "Redis exposed without auth - CVE-2024-31227 directly exploitable" "redis" "full" "https://nvd.nist.gov/vuln/detail/CVE-2024-31227"
        fi
    else
        local redis_info; redis_info=$(curl -s -m "$CURL_TIMEOUT" "http://$TARGET:6379/" 2>/dev/null | head -1)
        if [[ -n "$redis_info" ]]; then
            echo -e "    $GREEN[+] Redis server responded on port 6379$NC"
            add_vuln "$CVE_ID" "$CVE_SEV" "$CVE_TITLE" "Redis accessible - CVE-2024-31227 applicable" "redis" "full" "https://nvd.nist.gov/vuln/detail/CVE-2024-31227"
        fi
    fi
    cve_done_banner "$CVE_ID"
}

