# Module RT-520: CVE-2024-24560 - GitLab CI/CD Pipeline Remote Code Execution
rt_520_cve_cve_2024_24560() {
    local CVE_ID="CVE-2024-24560"
    local CVE_TITLE="GitLab CI/CD Pipeline Remote Code Execution"
    local CVE_SEV="CRITICAL"
    cve_banner "$CVE_ID" "$CVE_SEV"
    log_cve_info "$CVE_ID" "$CVE_TITLE" "$CVE_SEV"

    # Smart detection: check_port 80 || check_port 443
    if ! check_port 80 || check_port 443; then
        log_skipped "$CVE_ID" "Target technology not detected"
        return 0
    fi

    echo -e "    $CYAN[*] Testing CVE-2024-24560: GitLab CI/CD Pipeline Remote Code Execution$NC"
    echo -e "    $CYAN[*] Detection: check_port 80 || check_port 443$NC"

    local gitlab_headers; gitlab_headers=$(curl -sI -m "$CURL_TIMEOUT" "https://$TARGET/api/v4/version" 2>/dev/null)
    if [[ -n "$gitlab_headers" ]]; then
        echo -e "    $GREEN[+] GitLab API detected - checking version...$NC"
        local gitlab_ver; gitlab_ver=$(curl -s -m "$CURL_TIMEOUT" "https://$TARGET/api/v4/version" 2>/dev/null | grep -oE '"version":"[^"]+"' | head -1)
        echo -e "    $CYAN[*] GitLab version: $gitlab_ver$NC"
        add_vuln "$CVE_ID" "$CVE_SEV" "$CVE_TITLE" "GitLab detected - CVE-2024-24560 applicable" "gitlab" "full" "https://nvd.nist.gov/vuln/detail/CVE-2024-24560"
    fi
    local gitlab_sign; gitlab_sign=$(curl -s -m "$CURL_TIMEOUT" "https://$TARGET/explore" 2>/dev/null | grep -i "gitlab" | head -1)
    if [[ -n "$gitlab_sign" ]]; then
        echo -e "    $GREEN[+] GitLab instance confirmed via page signature$NC"
        add_vuln "$CVE_ID" "$CVE_SEV" "$CVE_TITLE" "GitLab confirmed - CVE-2024-24560 applicable" "gitlab" "full" "https://nvd.nist.gov/vuln/detail/CVE-2024-24560"
    fi
    cve_done_banner "$CVE_ID"
}

