    local CVE_SEV="HIGH"
    cve_banner "$CVE_ID" "$CVE_SEV"
    log_cve_info "$CVE_ID" "$CVE_TITLE" "$CVE_SEV"

    # Smart detection: check_port 443
    if ! check_port 443; then
        log_skipped "$CVE_ID" "Target technology not detected"
        return 0
    fi

    echo -e "    $CYAN[*] Testing CVE-2022-4450: OpenSSL PEM File Buffer Overflow$NC"
    echo -e "    $CYAN[*] Detection: check_port 443$NC"

    if command -v openssl &>/dev/null; then
        local tls_ver; tls_ver=$(timeout 10 openssl s_client -connect "$TARGET:443" -servername "$TARGET" </dev/null 2>/dev/null | grep "Protocol" | awk "{print \$2}")
        if [[ -n "$tls_ver" ]]; then
            echo -e "    $CYAN[*] TLS Protocol version: $tls_ver$NC"
            if [[ "$tls_ver" == *"TLSv1"* || "$tls_ver" == *"SSL"* ]]; then
                echo -e "    $RED[WARNING] Outdated TLS/SSL version detected$NC"
            fi
            add_vuln "$CVE_ID" "$CVE_SEV" "$CVE_TITLE" "TLS/SSL endpoint detected - CVE-2022-4450 applicable" "openssl" "full" "https://nvd.nist.gov/vuln/detail/CVE-2022-4450"
        fi
    fi
    cve_done_banner "$CVE_ID"
}

