# Module RT-609: CVE-2024-53677 - Apache Struts OGNL Expression Injection
rt_609_cve_cve_2024_53677() {
    local CVE_ID="CVE-2024-53677"
    local CVE_TITLE="Apache Struts OGNL Expression Injection"
    local CVE_SEV="CRITICAL"
    cve_banner "$CVE_ID" "$CVE_SEV"
    log_cve_info "$CVE_ID" "$CVE_TITLE" "$CVE_SEV"

    # Smart detection: [[ "$DETECTED_TECH" == *"struts"* ]] || [[ "$DETECTED_TECH" == *"java"* ]]
    if ! [[ "$DETECTED_TECH" == *"struts"* ]] || [[ "$DETECTED_TECH" == *"java"* ]]; then
        log_skipped "$CVE_ID" "Target technology not detected"
        return 0
    fi

    echo -e "    $CYAN[*] Testing CVE-2024-53677: Apache Struts OGNL Expression Injection$NC"
    echo -e "    $CYAN[*] Detection: [ [ "$DETECTED_TECH" == *"struts"* ] ] || [ [ "$DETECTED_TECH" == *"java"* ] ]$NC"

    local struts_headers; struts_headers=$(curl -sI -m "$CURL_TIMEOUT" "https://$TARGET/" 2>/dev/null)
    if [[ -n "$struts_headers" ]]; then
        local struts_sign; struts_sign=$(echo "$struts_headers" | grep -i "struts\|jakarta\|x-work")
        if [[ -n "$struts_sign" ]]; then
            echo -e "    $RED[CRITICAL] Apache Struts detected in headers: $struts_sign$NC"
            add_vuln "$CVE_ID" "$CVE_SEV" "$CVE_TITLE" "Apache Struts detected - CVE-2024-53677 applicable" "java" "full" "https://nvd.nist.gov/vuln/detail/CVE-2024-53677"
        else
            local struts_ext; struts_ext=$(curl -s -m "$CURL_TIMEOUT" "https://$TARGET/" 2>/dev/null | grep -oiE 'href="[^"]*\.(action|do)"' | head -1)
            if [[ -n "$struts_ext" ]]; then
                echo -e "    $RED[CRITICAL] Apache Struts URL patterns detected: $struts_ext$NC"
                add_vuln "$CVE_ID" "$CVE_SEV" "$CVE_TITLE" "Apache Struts confirmed - CVE-2024-53677 applicable" "java" "full" "https://nvd.nist.gov/vuln/detail/CVE-2024-53677"
            fi
        fi
    fi
    cve_done_banner "$CVE_ID"
}

