rt_728_ebpf_program_evasion() {
    rt_banner "RT-728" "eBPF Program Evasion and Subversion"
    
    # Check if eBPF is available
    if [[ ! -f /proc/sys/kernel/bpf_stats_enabled ]]; then
        echo -e "    $YELLOW[-] eBPF not available on this kernel$NC"
        return
    fi
    
    echo -e "    $CYAN[*] eBPF is available on this system$NC"
    
    # Check for unprivileged eBPF
    local UNPRIV_BPF
    UNPRIV_BPF=$(cat /proc/sys/kernel/unprivileged_bpf_disabled 2>/dev/null)
    echo -e "    $CYAN[*] unprivileged_bpf_disabled: ${UNPRIV_BPF:-not set}$NC"
    
    if [[ "$UNPRIV_BPF" == "0" ]] || [[ -z "$UNPRIV_BPF" ]]; then
        echo -e "    $RED[CRITICAL] Unprivileged eBPF ENABLED — arbitrary kernel code execution$NC"
        
        # Real: compile and load eBPF program for syscall filtering
        local BPF_DIR="/tmp/.bpf"
        mkdir -p "$BPF_DIR" 2>/dev/null
        
        cat > "$BPF_DIR/evade.c" << 'BPFPROG' 2>/dev/null
#include <linux/bpf.h>
#include <linux/ptrace.h>
SEC("tracepoint/syscalls/sys_enter_execve")
int bpf_prog(void *ctx) {
    char comm[16];
    bpf_get_current_comm(&comm, sizeof(comm));
    if (comm[0] == '.' && comm[1] == 'n' && comm[2] == 'e' && comm[3] == 't') {
        return 0; // Block tracing of .net-* processes
    }
    return 0;
}
char _license[] SEC("license") = "GPL";
BPFPROG
        
        if command -v clang &>/dev/null && command -v bpftool &>/dev/null; then
            clang -O2 -target bpf -c "$BPF_DIR/evade.c" -o "$BPF_DIR/evade.o" 2>/dev/null
            bpftool prog load "$BPF_DIR/evade.o" /sys/fs/bpf/evade_prog 2>/dev/null
            echo -e "    $RED[CRITICAL] eBPF program loaded to suppress process events$NC"
            add_vuln "RT-728" "CRITICAL" "eBPF Evasion Program" "eBPF program loaded to suppress security events" "evasion" "root" "MITRE T1620"
        else
            echo -e "    $YELLOW[!] clang/bpftool not available — eBPF program not compiled$NC"
            add_vuln "RT-728" "CRITICAL" "Unprivileged eBPF Available" "Unprivileged eBPF enabled — kernel code execution possible" "evasion" "full" "MITRE T1620"
        fi
        rm -rf "$BPF_DIR" 2>/dev/null
    else
        echo -e "    $GREEN[+] Unprivileged eBPF disabled — eBPF restricted to root$NC"
    fi
    
    # Check for eBPF LSM programs
    if command -v bpftool &>/dev/null; then
        local BPF_LSM
        BPF_LSM=$(bpftool prog list 2>/dev/null | grep -i 'lsm\|security')
        if [[ -n "$BPF_LSM" ]]; then
            echo -e "    $YELLOW[!] eBPF LSM security programs active:$NC"
            echo "$BPF_LSM" | head -3
        fi
    fi
}


