        echo -e "    $RED[CRITICAL] SSH agent socket active: $SSH_AUTH_SOCK$NC"
        local SSH_KEYS
        SSH_KEYS=$(ssh-add -l 2>/dev/null)
        if [[ -n "$SSH_KEYS" ]]; then
            echo -e "    $RED[+] Loaded SSH keys:$NC"
            echo "$SSH_KEYS" | head -3 | while read -r k; do echo -e "        $RED$k$NC"; done
            add_vuln "RT-733" "CRITICAL" "SSH Agent Keys" "SSH agent has loaded keys — lateral movement possible" "malware" "full" "MITRE T1550.001"
        fi
    fi
    
    # Check for browser credential databases
    local BROWSERS=("google-chrome" "chromium" "firefox")
    for browser in "${BROWSERS[@]}"; do
        local CREDS_DB
        case "$browser" in
            google-chrome|chromium)
                CREDS_DB="$HOME/.config/$browser/Default/Login Data"
                ;;
            firefox)
                CREDS_DB=$(find "$HOME/.mozilla/firefox" -name 'logins.json' 2>/dev/null | head -1)
                ;;
        esac
        if [[ -f "$CREDS_DB" ]]; then
            echo -e "    $RED[CRITICAL] $browser credential database found: $CREDS_DB$NC"
            add_vuln "RT-733" "CRITICAL" "Browser Credentials" "$browser credential database accessible" "malware" "full" "MITRE T1555.003"
        fi
    done
    
    # Check for cloud credential files
    local CLOUD_CREDS=("$HOME/.aws/credentials" "$HOME/.azure/credentials" "$HOME/.config/gcloud/credentials.db")
    for cc in "${CLOUD_CREDS[@]}"; do
        if [[ -f "$cc" ]]; then
            echo -e "    $RED[CRITICAL] Cloud credentials file: $cc$NC"
            add_vuln "RT-733" "CRITICAL" "Cloud Credentials" "Cloud credential file found: $cc" "malware" "full" "MITRE T1552.001"
        fi
    done
    
    # Check for .netrc files
    if [[ -f "$HOME/.netrc" ]]; then
        echo -e "    $RED[CRITICAL] .netrc file found with stored credentials$NC"
        add_vuln "RT-733" "HIGH" "netrc Credentials" "~/.netrc contains stored credentials" "malware" "full" "MITRE T1552.001"
    fi
}


