        fi
        
        # Check for dangerous mounts
        local DANGER_MOUNTS
        DANGER_MOUNTS=$(mount 2>/dev/null | grep -E '/docker.sock|/proc|/sys|/var/run|/etc|/root')
        if [[ -n "$DANGER_MOUNTS" ]]; then
            echo -e "    $RED[+] Dangerous host mounts detected:$NC"
            echo "$DANGER_MOUNTS" | head -5 | while read -r m; do echo -e "        $RED$m$NC"; done
            add_vuln "RT-738" "CRITICAL" "Container Dangerous Mount" "Host path mounted inside container — escape possible" "lateral" "root" "MITRE T1611"
