                echo -e "    $RED[CRITICAL] cgroup release_agent write SUCCESS — escape achieved$NC"
                add_vuln "RT-738" "CRITICAL" "cgroup Escape" "cgroup release_agent escape successful" "lateral" "root" "CVE-2022-0492"
            fi
        fi
