        # Real: list pods via API
        local K8S_API
        K8S_API=$(curl -sk -H "Authorization: Bearer $(cat /var/run/secrets/kubernetes.io/serviceaccount/token)" \
            "https://kubernetes.default.svc/api/v1/namespaces/default/pods" --connect-timeout 5 2>/dev/null | head -1)
        if [[ -n "$K8S_TOKEN" ]]; then
            echo -e "    $RED[CRITICAL] K8s API accessible — lateral to other pods$NC"
            add_vuln "RT-738" "CRITICAL" "K8s Token Escape" "K8s service account token allows pod lateral movement" "lateral" "full" "MITRE T1613"
        fi
    fi
    
    # Check for cloud metadata API
