# Global APK config
APK_TARGET=""
APK_DECODED_DIR=""
APK_OUTPUT_DIR=""
APK_SMALI_DIR=""
APK_PACKAGE=""
APK_PATCHES_APPLIED=0

# Check if target is an APK file
is_apk_target() {
    if [[ -f "$TARGET" ]] && [[ "$TARGET" == *.apk ]]; then
        return 0
    fi
    return 1
}

# Setup APK environment
apk_setup_env() {
    APK_TARGET="$TARGET"
    APK_DECODED_DIR="$SESSION/apk/decoded"
    APK_OUTPUT_DIR="$SESSION/apk/output"
    APK_SMALI_DIR="$APK_DECODED_DIR/smali"
    mkdir -p "$APK_DECODED_DIR" "$APK_OUTPUT_DIR" "$SESSION/apk/patches"
}

# Module RT-751: APK Detection and Decompilation
rt_751_apk_detect_decompile() {
    rt_banner "RT-751" "APK Detection and Decompilation"
    
    if ! is_apk_target; then
        echo -e "    $YELLOW[-] Target is not an APK file — skipping APK modules$NC"
        return 1
    fi
    
    apk_setup_env
    local APK_SIZE
    APK_SIZE=$(stat -c%s "$APK_TARGET" 2>/dev/null || echo "0")
    echo -e "    $CYAN[*] APK: $(basename "$APK_TARGET") | Size: $((APK_SIZE / 1024)) KB$NC"
    
    # Check if apktool is available
    if ! command -v apktool &>/dev/null; then
        echo -e "    $YELLOW[!] apktool not found — attempting to download$NC"
        # Download apktool
        curl -sL "https://raw.githubusercontent.com/iBotPeaches/Apktool/master/scripts/linux/apktool" -o "$PREFIX/bin/apktool" 2>/dev/null
        curl -sL "https://bitbucket.org/iBotPeaches/apktool/downloads/apktool_2.9.3.jar" -o "$PREFIX/bin/apktool.jar" 2>/dev/null
        chmod +x "$PREFIX/bin/apktool" 2>/dev/null
    fi
    
    # Check for aapt/aapt2
    if ! command -v aapt &>/dev/null && command -v apt &>/dev/null; then
        echo -e "    $YELLOW[!] Installing aapt...$NC"
        apt install -y aapt 2>/dev/null || true
    fi
    
    # Decompile APK
    echo -e "    $CYAN[*] Decompiling APK with apktool...$NC"
    if apktool d -f -o "$APK_DECODED_DIR" "$APK_TARGET" 2>/dev/null; then
        echo -e "    $GREEN[+] APK decompiled to $APK_DECODED_DIR$NC"
    else
        echo -e "    $RED[-] apktool decompilation failed — trying unzip fallback$NC"
        unzip -o "$APK_TARGET" -d "$APK_DECODED_DIR" 2>/dev/null
        echo -e "    $YELLOW[!] Partial extraction via unzip — some features limited$NC"
    fi
    
    # Extract package name
    if [[ -f "$APK_DECODED_DIR/AndroidManifest.xml" ]]; then
        APK_PACKAGE=$(grep -oP 'package="\K[^"]+' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null | head -1)
        echo -e "    $CYAN[*] Package: $APK_PACKAGE$NC"
    fi
    
    # Count smali files
    local SMALI_COUNT
    SMALI_COUNT=$(find "$APK_DECODED_DIR" -name "*.smali" 2>/dev/null | wc -l)
    echo -e "    $CYAN[*] Smali files: $SMALI_COUNT$NC"
    
    # Detect framework
    if [[ -d "$APK_DECODED_DIR/smali/androidx" ]]; then
        echo -e "    $CYAN[*] Framework: AndroidX detected$NC"
    fi
    if [[ -d "$APK_DECODED_DIR/smali/com/google/android/gms" ]]; then
        echo -e "    $YELLOW[!] Google Play Services detected — ads/games likely$NC"
    fi
    if [[ -d "$APK_DECODED_DIR/smali/com/google/android/material" ]]; then
        echo -e "    $CYAN[*] Material Design detected$NC"
    fi
    
    # Extract and show app name
    local APP_NAME
    if [[ -f "$APK_DECODED_DIR/res/values/strings.xml" ]]; then
        APP_NAME=$(grep -oP '(?<=<string name="app_name">)[^<]+' "$APK_DECODED_DIR/res/values/strings.xml" 2>/dev/null | head -1)
        [[ -n "$APP_NAME" ]] && echo -e "    $CYAN[*] App Name: $APP_NAME$NC"
    fi
    
    # Check for native libraries
    local NATIVE_LIBS
    NATIVE_LIBS=$(find "$APK_DECODED_DIR/lib" -name "*.so" 2>/dev/null | wc -l)
    echo -e "    $CYAN[*] Native libraries: $NATIVE_LIBS$NC"
    
    add_vuln "RT-751" "INFO" "APK Decompiled" "APK $(basename "$APK_TARGET") decompiled — package: $APK_PACKAGE, smali: $SMALI_COUNT" "apk" "full" "MITRE T1403"
}

# Module RT-752: Ad Network Detection and Removal
rt_752_ad_network_removal() {
    rt_banner "RT-752" "Ad Network Detection and Removal"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    local ADS_REMOVED=0
    
    # Major ad networks to detect and patch
    declare -A AD_NETWORKS=(
        ["com/google/android/gms/ads"]='Google AdMob'
        ["com/facebook/ads"]='Facebook Audience Network'
        ["com/unity3d/services/ads"]='Unity Ads'
        ["com/applovin"]='AppLovin'
        ["com/chartboost/sdk"]='Chartboost'
        ["com/inmobi"]='InMobi'
        ["com/mopub/mobileads"]='MoPub'
        ["com/vungle/warren"]='Vungle'
        ["com/ironsource/mediationsdk"]='ironSource'
        ["com/adcolony/sdk"]='AdColony'
        ["com/tapjoy"]='Tapjoy'
        ["com/bytedance/sdk/openadsdk"]='Pangle Ads'
        ["com/smaato/sdk"]='Smaato'
        ["com/google/ads"]='Legacy Google Ads'
        ["com/flurry/android"]='Flurry Ads'
        ["com/startapp/android"]='StartApp'
    )
    
    echo -e "    $CYAN[*] Scanning for ad networks...$NC"
    
    for ad_path in "${!AD_NETWORKS[@]}"; do
        local AD_NAME="${AD_NETWORKS[$ad_path]}"
        local AD_FOUND
        AD_FOUND=$(find "$APK_DECODED_DIR" -type d -path "*/$ad_path" 2>/dev/null | head -1)
        
        if [[ -n "$AD_FOUND" ]]; then
            echo -e "    $RED[+] $AD_NAME found at: $AD_FOUND$NC"
            
            # Real: Patch ad loading methods in smali
            local AD_SMALI
            AD_SMALI=$(find "$AD_FOUND" -name "*.smali" 2>/dev/null)
            
            for smali_file in $AD_SMALI; do
                # Patch loadAd, showAd, initialize methods to return void/false
                # AdMob: loadAd -> return-void at method start
                if grep -q "\.method.*loadAd\|\.method.*show\|\.method.*initialize" "$smali_file" 2>/dev/null; then
                    # Find method bodies and add return-void after .locals
                    sed -i 's/\.method public loadAd(.*)/.method public loadAd(\1)\n    return-void/' "$smali_file" 2>/dev/null
                    sed -i 's/\.method public show(.*)/.method public show(\1)\n    return-void/' "$smali_file" 2>/dev/null
                    ADS_REMOVED=$((ADS_REMOVED + 1))
                fi
                
                # Patch isLoaded to always return false
                if grep -q "\.method.*isLoaded\|\.method.*isReady" "$smali_file" 2>/dev/null; then
                    sed -i '/\.method.*isLoaded/,/\.end method/{s/const\/.*/const\/4 v0, 0x0\n    return v0/}' "$smali_file" 2>/dev/null
                    ADS_REMOVED=$((ADS_REMOVED + 1))
                fi
            done
            
            # Generic ad killer: patch common ad method names across all smali
            find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "loadAd\|showInterstitial\|showRewarded\|displayAd" {} \; 2>/dev/null | while read -r f; do
                # Comment out invoke-virtual calls to ad loading
                sed -i 's/invoke-virtual.*loadAd/\n    # AD_REMOVED: &/' "$f" 2>/dev/null
                sed -i 's/invoke-virtual.*showInterstitial/\n    # AD_REMOVED: &/' "$f" 2>/dev/null
            done
            
            add_vuln "RT-752" "HIGH" "$AD_NAME Removed" "Ad network $AD_NAME detected and patched" "apk" "full" "MITRE T1645"
        fi
    done
    
    # Remove ad activity declarations from manifest
    if [[ -f "$APK_DECODED_DIR/AndroidManifest.xml" ]]; then
        # Remove AdActivity declarations
        sed -i '/AdActivity/d; /InterstitialActivity/d; /RewardedVideoActivity/d' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
        echo -e "    $GREEN[+] Ad activities removed from AndroidManifest.xml$NC"
    fi
    
    if [[ "$ADS_REMOVED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $ADS_REMOVED ad methods patched$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
    else
        echo -e "    $YELLOW[!] No ad networks detected — app may be ad-free$NC"
    fi
}

# Module RT-753: VIP/Premium Unlock
rt_753_vip_premium_unlock() {
    rt_banner "RT-753" "VIP and Premium Feature Unlock"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    local VIP_PATCHED=0
    
    echo -e "    $CYAN[*] Searching for premium/VIP checks...$NC"
    
    # Search for common premium/VIP related strings and methods
    local PREMIUM_TERMS="isPremium isVip isPro isPaid isSubscribed isUnlocked hasPurchased isLicensed isFullVersion isAdFree getPremium isMember isGold isDiamond isSubscribed"
    
    for term in $PREMIUM_TERMS; do
        local MATCHES
        MATCHES=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "$term" {} \; 2>/dev/null)
        
        if [[ -n "$MATCHES" ]]; then
            echo -e "    $RED[+] Found '$term' in $(echo "$MATCHES" | wc -l) files$NC"
            
            for smali_file in $MATCHES; do
                # Patch boolean methods that check premium status to always return true
                if grep -q "\.method.*$term" "$smali_file" 2>/dev/null; then
                    # Check if method returns boolean
                    local METHOD_LINE
                    METHOD_LINE=$(grep -n "\.method.*$term" "$smali_file" 2>/dev/null)
                    
                    # Find the method and modify it to return true (const/4 v0, 0x1)
                    sed -i "/\.method.*$term/,/\.end method/{s/\.locals [0-9]/\.locals 1/; s/const\/4 v0, 0x0/const\/4 v0, 0x1/}" "$smali_file" 2>/dev/null
                    
                    # More aggressive: if the method returns boolean, force return true
                    local METHOD_START
                    METHOD_START=$(grep -n "\.method public.*$term" "$smali_file" 2>/dev/null | head -1 | cut -d: -f1)
                    if [[ -n "$METHOD_START" ]]; then
                        local NEXT_LINE=$((METHOD_START + 1))
                        # Insert const/4 v0, 0x1 and return v0 after .locals line
                        sed -i "${NEXT_LINE}a\\    const/4 v0, 0x1\n    return v0" "$smali_file" 2>/dev/null
                        VIP_PATCHED=$((VIP_PATCHED + 1))
                    fi
                fi
                
                # Also patch if-eqz checks that check premium flags
                # Change if-eqz to if-nez (invert the check) so premium path always executes
                sed -i 's/if-eqz v0, :cond_[0-9a-z]\+/if-nez v0, :cond_0/g' "$smali_file" 2>/dev/null
            done
        fi
    done
    
    # Search for purchase validation methods
    local PURCHASE_METHODS="verifyPurchase consumePurchase acknowledgePurchase queryPurchases getPurchasesList"
    for method in $PURCHASE_METHODS; do
        local MATCHES
        MATCHES=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "$method" {} \; 2>/dev/null)
        if [[ -n "$MATCHES" ]]; then
            echo -e "    $RED[+] Found purchase method '$method' — patching$NC"
            for f in $MATCHES; do
                # Patch to always return successful purchase
                sed -i "/\.method.*$method/,/\.end method/{s/const\/4 v0, 0x0/const\/4 v0, 0x1/}" "$f" 2>/dev/null
            done
            VIP_PATCHED=$((VIP_PATCHED + 1))
        fi
    done
    
    # Patch InAppBillingService responses
    find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "InAppBillingService\|IInAppBillingService" {} \; 2>/dev/null | while read -r f; do
        # Change response code to 0 (OK) and purchase state to 0 (purchased)
        sed -i 's/"purchaseState" : 1/"purchaseState" : 0/g' "$f" 2>/dev/null
        sed -i 's/"purchaseState":1/"purchaseState":0/g' "$f" 2>/dev/null
        VIP_PATCHED=$((VIP_PATCHED + 1))
    done
    
    # Patch SharedPreferences checks for premium
    find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "getBoolean.*premium\|getBoolean.*vip\|getBoolean.*pro\|contains.*premium\|contains.*vip" {} \; 2>/dev/null | while read -r f; do
        # Force premium preferences to true
        sed -i 's/invoke-interface.*getBoolean/const\/4 v0, 0x1/g' "$f" 2>/dev/null
        VIP_PATCHED=$((VIP_PATCHED + 1))
    done
    
    if [[ "$VIP_PATCHED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $VIP_PATCHED VIP/premium patches applied$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
        add_vuln "RT-753" "HIGH" "VIP Premium Unlocked" "$VIP_PATCHED premium/VIP checks patched to always return true" "apk" "full" "MITRE T1403"
    else
        echo -e "    $YELLOW[!] No premium checks found in standard patterns$NC"
    fi
}

# Module RT-754: Certificate Pinning Bypass
rt_754_certificate_pinning_bypass() {
    rt_banner "RT-754" "SSL Certificate Pinning Bypass"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    local PINNING_BYPASSED=0
    
    echo -e "    $CYAN[*] Checking for certificate pinning implementations...$NC"
    
    # Common pinning libraries and methods
    local PINNING_LIBS=(
        "okhttp3/CertificatePinner"
        "android/net/http/X509TrustManagerExtensions"
        "javax/net/ssl/TrustManager"
        "javax/net/ssl/X509TrustManager"
        "de/greenrobot/event/EventBus"
        "com/datatheorem/android/trustkit"
        "com/laimiux/android/trustkit"
        "co/elastic/apm/android"
    )
    
    for lib in "${PINNING_LIBS[@]}"; do
        local FOUND
        FOUND=$(find "$APK_DECODED_DIR" -type d -path "*/$lib" 2>/dev/null | head -1)
        if [[ -n "$FOUND" ]]; then
            echo -e "    $RED[+] Pinning library found: $lib$NC"
        fi
    done
    
    # Method 1: Patch OkHttp3 CertificatePinner
    local OKHTTP_PINNER
    OKHTTP_PINNER=$(find "$APK_DECODED_DIR" -name "*.smali" -path "*/okhttp3/*" 2>/dev/null | xargs grep -l "check\|CertificatePinner" 2>/dev/null)
    
    if [[ -n "$OKHTTP_PINNER" ]]; then
        echo -e "    $RED[+] OkHttp3 CertificatePinner found — bypassing$NC"
        for f in $OKHTTP_PINNER; do
            # Find the check() method and make it return void (no exception)
            if grep -q "\.method.*check" "$f" 2>/dev/null; then
                # Get method start line
                local METHOD_START
                METHOD_START=$(grep -n "\.method.*check" "$f" 2>/dev/null | head -1 | cut -d: -f1)
                if [[ -n "$METHOD_START" ]]; then
                    # Find .locals line and add return-void after it
                    local LOCALS_LINE
                    LOCALS_LINE=$(sed -n "$METHOD_START,/^\.end method/p" "$f" 2>/dev/null | grep -n "\.locals" | head -1 | cut -d: -f1)
                    if [[ -n "$LOCALS_LINE" ]]; then
                        local INSERT_LINE=$((METHOD_START + LOCALS_LINE))
                        sed -i "${INSERT_LINE}a\\    return-void" "$f" 2>/dev/null
                        PINNING_BYPASSED=$((PINNING_BYPASSED + 1))
                    fi
                fi
            fi
        done
    fi
    
    # Method 2: Universal X509TrustManager bypass
    # Find all smali files referencing TrustManager and patch them
    local TRUST_FILES
    TRUST_FILES=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "X509TrustManager\|checkServerTrusted\|checkClientTrusted" {} \; 2>/dev/null)
    
    if [[ -n "$TRUST_FILES" ]]; then
        echo -e "    $RED[+] X509TrustManager found — applying universal bypass$NC"
        for f in $TRUST_FILES; do
            # Patch checkServerTrusted to return void (no throw)
            sed -i '/\.method.*checkServerTrusted/,/\.end method/{s/\.locals [0-9]/\.locals 0/; s/new-instance.*CertificateException/# BYPASSED/; s/throw v[0-9]/# BYPASSED/}' "$f" 2>/dev/null
            # Add return-void at beginning of method
            sed -i '/\.method.*checkServerTrusted/,/\.end method/{s/\.locals [0-9]*/\0\n    return-void/; t; }' "$f" 2>/dev/null
            PINNING_BYPASSED=$((PINNING_BYPASSED + 1))
        done
    fi
    
    # Method 3: Patch WebView SSL error handling
    local WEBVIEW_FILES
    WEBVIEW_FILES=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "onReceivedSslError\|SslErrorHandler" {} \; 2>/dev/null)
    
    if [[ -n "$WEBVIEW_FILES" ]]; then
        echo -e "    $RED[+] WebView SSL error handler found — patching to proceed$NC"
        for f in $WEBVIEW_FILES; do
            # Change cancel() to proceed() in SSL error handler
            sed -i 's/invoke-virtual.*cancel/invoke-virtual {p2}, Landroid\/webkit\/SslErrorHandler;->proceed()V/' "$f" 2>/dev/null
            PINNING_BYPASSED=$((PINNING_BYPASSED + 1))
        done
    fi
    
    # Method 4: Network Security Config
    if [[ -f "$APK_DECODED_DIR/res/xml/network_security_config.xml" ]]; then
        echo -e "    $RED[+] Network Security Config found — disabling pinning$NC"
        # Replace with permissive config
        cat > "$APK_DECODED_DIR/res/xml/network_security_config.xml" << 'NETCFG' 2>/dev/null
<?xml version="1.0" encoding="utf-8"?>
<network-security-config>
    <base-config cleartextTrafficPermitted="true">
        <trust-anchors>
            <certificates src="system"/>
            <certificates src="user"/>
        </trust-anchors>
    </base-config>
    <debug-overrides>
        <trust-anchors>
            <certificates src="user"/>
        </trust-anchors>
    </debug-overrides>
</network-security-config>
NETCFG
        PINNING_BYPASSED=$((PINNING_BYPASSED + 1))
    fi
    
    # Method 5: AndroidManifest.xml network_security_config reference
    if [[ -f "$APK_DECODED_DIR/AndroidManifest.xml" ]]; then
        # Ensure network_security_config is declared
        if ! grep -q "networkSecurityConfig" "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null; then
            sed -i 's/<application /<application android:networkSecurityConfig="@xml\/network_security_config" /' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
            # Create the config file if it doesn't exist
            mkdir -p "$APK_DECODED_DIR/res/xml" 2>/dev/null
            if [[ ! -f "$APK_DECODED_DIR/res/xml/network_security_config.xml" ]]; then
                cat > "$APK_DECODED_DIR/res/xml/network_security_config.xml" << 'NETCFG' 2>/dev/null
<?xml version="1.0" encoding="utf-8"?>
<network-security-config>
    <base-config cleartextTrafficPermitted="true">
        <trust-anchors>
            <certificates src="system"/>
            <certificates src="user"/>
        </trust-anchors>
    </base-config>
</network-security-config>
NETCFG
            fi
            PINNING_BYPASSED=$((PINNING_BYPASSED + 1))
        fi
    fi
    
    if [[ "$PINNING_BYPASSED" -gt 0 ]]; then
        echo -e "    $GREEN[+] Certificate pinning bypassed in $PINNING_BYPASSED locations$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
        add_vuln "RT-754" "CRITICAL" "SSL Pinning Bypassed" "Certificate pinning bypassed in $PINNING_BYPASSED locations" "apk" "full" "MITRE T1633"
    else
        echo -e "    $YELLOW[!] No certificate pinning detected$NC"
    fi
}


# Module RT-755: Root Detection Bypass
rt_755_root_detection_bypass() {
    rt_banner "RT-755" "Root Detection and SafetyNet Bypass"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    local ROOT_BYPASSED=0
    
    echo -e "    $CYAN[*] Scanning for root detection methods...$NC"
    
    # Common root detection strings and methods
    local ROOT_CHECKS=(
        "isDeviceRooted"
        "isRooted"
        "isDeviceRoot"
        "isJailbroken"
        "isEmulator"
        "isDebugMode"
        "isMockLocation"
        "test-keys"
        "Superuser.apk"
        "com.koushikdutta.superuser"
        "com.thirdparty.superuser"
        "de.robv.android.xposed"
        "com.saurik.substrate"
        "/sbin/su"
        "/system/bin/su"
        "/system/xbin/su"
        "/data/local/xbin/su"
        "/data/local/bin/su"
        "/system/sd/xbin/su"
        "/system/bin/failsafe/su"
        "/data/local/su"
        "magisk"
        "MagiskManager"
    )
    
    for check in "${ROOT_CHECKS[@]}"; do
        local MATCHES
        MATCHES=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "$check" {} \; 2>/dev/null)
        
        if [[ -n "$MATCHES" ]]; then
            echo -e "    $RED[+] Root check '$check' found in $(echo "$MATCHES" | wc -l) files$NC"
            
            for smali_file in $MATCHES; do
                # Patch boolean methods to return false (not rooted)
                if grep -q "\.method.*isDeviceRooted\|\.method.*isRooted\|\.method.*isEmulator\|\.method.*isDebugMode\|\.method.*isMockLocation" "$smali_file" 2>/dev/null; then
                    # Force return false
                    sed -i '/\.method.*isDeviceRooted/,/\.end method/{s/const\/4 v0, 0x1/const\/4 v0, 0x0/}' "$smali_file" 2>/dev/null
                    sed -i '/\.method.*isRooted/,/\.end method/{s/const\/4 v0, 0x1/const\/4 v0, 0x0/}' "$smali_file" 2>/dev/null
                    sed -i '/\.method.*isEmulator/,/\.end method/{s/const\/4 v0, 0x1/const\/4 v0, 0x0/}' "$smali_file" 2>/dev/null
                    ROOT_BYPASSED=$((ROOT_BYPASSED + 1))
                fi
                
                # Patch file existence checks for su binary paths
                if grep -q "new-instance.*File\|Ljava/io/File;->exists" "$smali_file" 2>/dev/null && grep -q "su" "$smali_file" 2>/dev/null; then
                    # Change exists() result from true to false
                    sed -i '/Ljava\/io\/File;->exists/,/return/{s/const\/4 v0, 0x1/const\/4 v0, 0x0/}' "$smali_file" 2>/dev/null
                    ROOT_BYPASSED=$((ROOT_BYPASSED + 1))
                fi
                
                # Patch package manager checks for root apps
                if grep -q "com.koushikdutta.superuser\|de.robv.android.xposed\|com.saurik.substrate\|com.thirdparty.superuser\|com.topjohnwu.magisk" "$smali_file" 2>/dev/null; then
                    # Change the comparison or method return
                    sed -i 's/const\/4 v[0-9], 0x1/const\/4 v0, 0x0/g' "$smali_file" 2>/dev/null
                    sed -i 's/if-eqz/if-nez/g' "$smali_file" 2>/dev/null
                    ROOT_BYPASSED=$((ROOT_BYPASSED + 1))
                fi
            done
        fi
    done
    
    # SafetyNet / Play Integrity API bypass
    local SAFETYNET_FILES
    SAFETYNET_FILES=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "SafetyNetApi\|safetyNet\|playIntegrity\|IntegrityApi" {} \; 2>/dev/null)
    
    if [[ -n "$SAFETYNET_FILES" ]]; then
        echo -e "    $RED[+] SafetyNet/Play Integrity API found — patching$NC"
        for f in $SAFETYNET_FILES; do
            # Patch SafetyNet result handlers to always pass
            sed -i '/\.method.*onResult\|\.method.*onSuccess/,/\.end method/{s/const\/4 v0, 0x0/const\/4 v0, 0x1/}' "$f" 2>/dev/null
            ROOT_BYPASSED=$((ROOT_BYPASSED + 1))
        done
    fi
    
    # Google API key removal for SafetyNet
    if [[ -f "$APK_DECODED_DIR/res/values/strings.xml" ]]; then
        sed -i 's/google_app_id.*safetyNet/# REMOVED/g' "$APK_DECODED_DIR/res/values/strings.xml" 2>/dev/null
        sed -i 's/safetyNetApiKey/# REMOVED/g' "$APK_DECODED_DIR/res/values/strings.xml" 2>/dev/null
    fi
    
    # Remove common anti-tamper libraries
    local ANTITAMPER
    ANTITAMPER=$(find "$APK_DECODED_DIR" -type d -name "*libmaker*" -o -name "*libchecker*" -o -name "*antitamper*" -o -name "*integritycheck*" 2>/dev/null)
    if [[ -n "$ANTITAMPER" ]]; then
        echo -e "    $RED[+] Anti-tamper library found — removing$NC"
        for d in $ANTITAMPER; do
            rm -rf "$d" 2>/dev/null
            ROOT_BYPASSED=$((ROOT_BYPASSED + 1))
        done
    fi
    
    if [[ "$ROOT_BYPASSED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $ROOT_BYPASSED root detection methods bypassed$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
        add_vuln "RT-755" "CRITICAL" "Root Detection Bypassed" "$ROOT_BYPASSED root/emulator/debug detection methods bypassed" "apk" "full" "MITRE T1636"
    else
        echo -e "    $YELLOW[!] No root detection mechanisms found$NC"
    fi
}

# Module RT-756: Debug Mode and Logging Enable
rt_756_debug_mode_enable() {
    rt_banner "RT-756" "Debug Mode and Logging Enforcement"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    local DEBUG_PATCHED=0
    
    echo -e "    $CYAN[*] Enabling debug mode...$NC"
    
    # AndroidManifest.xml modifications
    if [[ -f "$APK_DECODED_DIR/AndroidManifest.xml" ]]; then
        # Add debuggable flag
        if ! grep -q 'android:debuggable="true"' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null; then
            sed -i 's/<application /<application android:debuggable="true" /' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
            echo -e "    $GREEN[+] android:debuggable="true" added$NC"
            DEBUG_PATCHED=$((DEBUG_PATCHED + 1))
        fi
        
        # Allow backup
        if ! grep -q 'android:allowBackup="true"' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null; then
            sed -i 's/<application /<application android:allowBackup="true" /' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
            echo -e "    $GREEN[+] android:allowBackup="true" added$NC"
            DEBUG_PATCHED=$((DEBUG_PATCHED + 1))
        fi
        
        # Remove exported restrictions if present
        sed -i 's/exported="false"/exported="true"/g' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
        
        # Add debug intent filter if not present
        if ! grep -q "android.intent.action.MAIN" "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null; then
            sed -i '/<activity android:name="\./a <intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter>' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
        fi
    fi
    
    # Patch isDebuggable / isDebuggerConnected checks
    local DEBUG_CHECKS
    DEBUG_CHECKS=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "isDebuggable\|isDebuggerConnected\|BuildConfig.DEBUG" {} \; 2>/dev/null)
    
    if [[ -n "$DEBUG_CHECKS" ]]; then
        echo -e "    $RED[+] Debug checks found — forcing to true$NC"
        for f in $DEBUG_CHECKS; do
            sed -i '/\.method.*isDebuggable/,/\.end method/{s/const\/4 v0, 0x0/const\/4 v0, 0x1/}' "$f" 2>/dev/null
            sed -i '/\.method.*isDebuggerConnected/,/\.end method/{s/const\/4 v0, 0x0/const\/4 v0, 0x1/}' "$f" 2>/dev/null
            sed -i 's/sget-boolean.*BuildConfig;->DEBUG:Z/const\/4 v0, 0x1/' "$f" 2>/dev/null
            DEBUG_PATCHED=$((DEBUG_PATCHED + 1))
        done
    fi
    
    # Enable WebView debugging
    local WEBVIEW_DEBUG
    WEBVIEW_DEBUG=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "setWebContentsDebuggingEnabled\|WebView" {} \; 2>/dev/null | head -5)
    
    if [[ -n "$WEBVIEW_DEBUG" ]]; then
        echo -e "    $CYAN[*] WebView files found — adding debugging$NC"
        for f in $WEBVIEW_DEBUG; do
            # After any new-instance of WebView, add setWebContentsDebuggingEnabled
            if grep -q "Landroid/webkit/WebView;-><init>" "$f" 2>/dev/null; then
                sed -i '/Landroid\/webkit\/WebView;-><init>/a\\n    const\/4 v1, 0x1\n    invoke-virtual {v0, v1}, Landroid\/webkit\/WebView;->setWebContentsDebuggingEnabled(Z)V' "$f" 2>/dev/null
                DEBUG_PATCHED=$((DEBUG_PATCHED + 1))
            fi
        done
    fi
    
    # Force logging to be enabled (even in release builds)
    local LOG_METHODS
    LOG_METHODS=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "isLoggable\|\.method.*canLog\|\.method.*shouldLog" {} \; 2>/dev/null)
    
    if [[ -n "$LOG_METHODS" ]]; then
        echo -e "    $RED[+] Logging gate checks found — forcing enabled$NC"
        for f in $LOG_METHODS; do
            sed -i '/\.method.*isLoggable/,/\.end method/{s/const\/4 v0, 0x0/const\/4 v0, 0x1/}' "$f" 2>/dev/null
            DEBUG_PATCHED=$((DEBUG_PATCHED + 1))
        done
    fi
    
    if [[ "$DEBUG_PATCHED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $DEBUG_PATCHED debug patches applied$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
        add_vuln "RT-756" "MEDIUM" "Debug Mode Enabled" "$DEBUG_PATCHED debug/logging patches applied" "apk" "full" "MITRE T1402"
    fi
}

# Module RT-757: Analytics and Tracking Removal
rt_757_analytics_tracking_removal() {
    rt_banner "RT-757" "Analytics and Tracking Library Removal"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    local TRACKERS_REMOVED=0
    
    # Common analytics/trackers
    declare -A TRACKERS=(
        ["com/google/firebase/analytics"]='Firebase Analytics'
        ["com/google/android/gms/analytics"]='Google Analytics'
        ["com/google/android/gms/measurement"]='Google Measurement'
        ["com/google/firebase/crashlytics"]='Firebase Crashlytics'
        ["com/facebook/appevents"]='Facebook App Events'
        ["com/facebook/login"]='Facebook Login'
        ["com/facebook/share"]='Facebook Share'
        ["com/crashlytics/android"]='Crashlytics'
        ["com/appsflyer"]='AppsFlyer'
        ["com/adjust/sdk"]='Adjust'
        ["io/branch/referral"]='Branch'
        ["com/mixpanel"]='Mixpanel'
        ["com/amplitude/api"]='Amplitude'
        ["com/segment/analytics"]='Segment'
        ["com/braze"]='Braze'
        ["com/bugsnag"]='Bugsnag'
        ["io/sentry"]='Sentry'
        ["com/huawei/hms/analytics"]='Huawei Analytics'
        ["com/umeng/analytics"]='Umeng Analytics'
        ["com/tencent/stat"]='Tencent MTA'
        ["com/tencent/mid"]='Tencent MID'
        ["com/flurry"]='Flurry'
        ["com/countly"]='Countly'
        ["io/intercom"]='Intercom'
    )
    
    echo -e "    $CYAN[*] Scanning for analytics and tracking libraries...$NC"
    
    for tracker_path in "${!TRACKERS[@]}"; do
        local TRACKER_NAME="${TRACKERS[$tracker_path]}"
        local FOUND_DIRS
        FOUND_DIRS=$(find "$APK_DECODED_DIR" -type d -path "*/$tracker_path" 2>/dev/null)
        
        if [[ -n "$FOUND_DIRS" ]]; then
            echo -e "    $RED[+] $TRACKER_NAME found — patching$NC"
            
            for tdir in $FOUND_DIRS; do
                # Find all smali files in tracker directory
                local TRACKER_SMALI
                TRACKER_SMALI=$(find "$tdir" -name "*.smali" 2>/dev/null)
                
                for smali_file in $TRACKER_SMALI; do
                    # Patch event logging methods to return void
                    if grep -q "\.method.*logEvent\|\.method.*track\|\.method.*send\|\.method.*record\|\.method.*report" "$smali_file" 2>/dev/null; then
                        sed -i '/\.method.*logEvent/,/\.end method/{s/\.locals [0-9]*/\.locals 0/; s/invoke-static.*\|invoke-virtual.*/# TRACKER_DISABLED/}' "$smali_file" 2>/dev/null
                        # Add early return
                        local METHOD_START
                        METHOD_START=$(grep -n "\.method.*logEvent\|\.method.*track\|\.method.*send\|\.method.*record" "$smali_file" 2>/dev/null | head -1 | cut -d: -f1)
                        if [[ -n "$METHOD_START" ]]; then
                            local LOCALS_LINE
                            LOCALS_LINE=$(sed -n "$METHOD_START,/^\.end method/p" "$smali_file" 2>/dev/null | grep -n "\.locals" | head -1 | cut -d: -f1)
                            if [[ -n "$LOCALS_LINE" ]]; then
                                sed -i "$((METHOD_START + LOCALS_LINE))a\\    return-void" "$smali_file" 2>/dev/null
                            fi
                        fi
                        TRACKERS_REMOVED=$((TRACKERS_REMOVED + 1))
                    fi
                done
            done
            
            add_vuln "RT-757" "MEDIUM" "$TRACKER_NAME Disabled" "Tracking library $TRACKER_NAME methods patched to no-op" "apk" "full" "MITRE T1631"
        fi
    done
    
    # Remove permissions used only for tracking (ACCESS_FINE_LOCATION if not core feature)
    if [[ -f "$APK_DECODED_DIR/AndroidManifest.xml" ]]; then
        # Remove AD_ID permission
        sed -i '/com.google.android.gms.permission.AD_ID/d' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
        # Remove advertising ID references
        sed -i '/AD_ID/d; /advertising_id/d; /advertisingId/d' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
    fi
    
    if [[ "$TRACKERS_REMOVED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $TRACKERS_REMOVED tracker methods disabled$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
    else
        echo -e "    $YELLOW[!] No tracking libraries detected$NC"
    fi
}

# Module RT-758: License Verification Bypass
rt_758_license_verification_bypass() {
    rt_banner "RT-758" "License and DRM Verification Bypass"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    local LICENSE_BYPASSED=0
    
    echo -e "    $CYAN[*] Scanning for license verification...$NC"
    
    # Google Play License Verification Library (LVL)
    local LVL_FILES
    LVL_FILES=$(find "$APK_DECODED_DIR" -name "*.smali" -path "*com/android/vending/licensing*" 2>/dev/null)
    
    if [[ -n "$LVL_FILES" ]]; then
        echo -e "    $RED[+] Google Play LVL found — bypassing$NC"
        for f in $LVL_FILES; do
            # Patch checkLicense to always return LICENSED (0)
            if grep -q "\.method.*checkLicense\|\.method.*verifyLicense" "$f" 2>/dev/null; then
                sed -i '/\.method.*checkLicense/,/\.end method/{s/const\/4 v[0-9], 0x[0-9a-f]/const\/4 v0, 0x0/}' "$f" 2>/dev/null
                sed -i '/\.method.*checkLicense/,/\.end method/{s/const v[0-9], 0x[0-9a-f]/const v0, 0x0/}' "$f" 2>/dev/null
                LICENSE_BYPASSED=$((LICENSE_BYPASSED + 1))
            fi
            # Allow method
            if grep -q "\.method.*allow\|\.method.*dontAllow" "$f" 2>/dev/null; then
                # Force call allow() instead of dontAllow()
                sed -i 's/invoke-virtual.*dontAllow/invoke-virtual {p0}, Lcom\/android\/vending\/licensing\/LicenseChecker;->allow()V/' "$f" 2>/dev/null
                LICENSE_BYPASSED=$((LICENSE_BYPASSED + 1))
            fi
        done
    fi
    
    # General license check methods
    local LICENSE_TERMS="checkLicense verifyLicense validateLicense isLicensed isPurchased isValidLicense isPremiumUser verifyPurchase authenticateLicense checkActivation"
    
    for term in $LICENSE_TERMS; do
        local MATCHES
        MATCHES=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "$term" {} \; 2>/dev/null)
        
        if [[ -n "$MATCHES" ]]; then
            echo -e "    $RED[+] '$term' found — patching to return true$NC"
            
            for smali_file in $MATCHES; do
                # Find boolean-returning methods and force true
                if grep -q "\.method.*$term" "$smali_file" 2>/dev/null; then
                    # Replace 0x0 (false) with 0x1 (true) in return paths
                    sed -i "/\.method.*$term/,/\.end method/{s/const\/4 v0, 0x0/const\/4 v0, 0x1/}" "$smali_file" 2>/dev/null
                    LICENSE_BYPASSED=$((LICENSE_BYPASSED + 1))
                fi
                
                # If the method invokes something that might return an error, patch the error check
                sed -i '/if-nez.*:cond_licensed/s/if-nez/if-eqz/' "$smali_file" 2>/dev/null
                sed -i '/if-eqz.*:cond_unlicensed/s/if-eqz/if-nez/' "$smali_file" 2>/dev/null
            done
        fi
    done
    
    # Amazon AppStore DRM
    local AMAZON_DRM
    AMAZON_DRM=$(find "$APK_DECODED_DIR" -name "*.smali" -path "*com/amazon*" 2>/dev/null | xargs grep -l "verify\|checkLicense\|DRM" 2>/dev/null)
    if [[ -n "$AMAZON_DRM" ]]; then
        echo -e "    $RED[+] Amazon DRM found — bypassing$NC"
        for f in $AMAZON_DRM; do
            sed -i '/\.method.*verify/,/\.end method/{s/const\/4 v0, 0x0/const\/4 v0, 0x1/}' "$f" 2>/dev/null
            LICENSE_BYPASSED=$((LICENSE_BYPASSED + 1))
        done
    fi
    
    # Samsung Knox / Samsung IAP
    local SAMSUNG_DRM
    SAMSUNG_DRM=$(find "$APK_DECODED_DIR" -name "*.smali" -path "*com/sec/android*" 2>/dev/null | xargs grep -l "verify\|checkLicense" 2>/dev/null)
    if [[ -n "$SAMSUNG_DRM" ]]; then
        echo -e "    $RED[+] Samsung IAP/DRM found — bypassing$NC"
        for f in $SAMSUNG_DRM; do
            sed -i '/\.method.*verify/,/\.end method/{s/const\/4 v0, 0x0/const\/4 v0, 0x1/}' "$f" 2>/dev/null
            LICENSE_BYPASSED=$((LICENSE_BYPASSED + 1))
        done
    fi
    
    if [[ "$LICENSE_BYPASSED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $LICENSE_BYPASSED license checks bypassed$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
        add_vuln "RT-758" "CRITICAL" "License DRM Bypassed" "$LICENSE_BYPASSED license verification checks bypassed" "apk" "full" "MITRE T1641"
    else
        echo -e "    $YELLOW[!] No license verification found$NC"
    fi
}

# Module RT-759: Native Library (.so) Patching
rt_759_native_library_patch() {
    rt_banner "RT-759" "Native Library Patching"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    local NATIVE_PATCHED=0
    
    echo -e "    $CYAN[*] Scanning native libraries...$NC"
    
    local SO_FILES
    SO_FILES=$(find "$APK_DECODED_DIR/lib" -name "*.so" 2>/dev/null)
    
    if [[ -z "$SO_FILES" ]]; then
        echo -e "    $YELLOW[!] No native libraries found$NC"
        return 1
    fi
    
    echo -e "    $CYAN[*] Found $(echo "$SO_FILES" | wc -w) native libraries$NC"
    
    for so_file in $SO_FILES; do
        local SO_NAME
        SO_NAME=$(basename "$so_file")
        
        # Check for interesting strings in the .so file
        if command -v strings &>/dev/null; then
            local INTERESTING
            INTERESTING=$(strings "$so_file" 2>/dev/null | grep -iE 'isPremium|isLicensed|isVip|checkLicense|verifyPurchase|isRooted|isDeviceRooted|ssl_pinning|certificate|ad_request|load_ad|show_ad' | head -10)
            
            if [[ -n "$INTERESTING" ]]; then
                echo -e "    $RED[+] $SO_NAME contains interesting strings:$NC"
                echo "$INTERESTING" | while read -r line; do
                    echo -e "        $RED$line$NC"
                done
                
                # Try to patch strings in the .so file
                # Replace isPremium checks
                if echo "$INTERESTING" | grep -qi 'isPremium\|isLicensed\|isVip'; then
                    sed -i 's/isPremium/1sPr3m1um/g' "$so_file" 2>/dev/null
                    sed -i 's/isLicensed/1sL1c3ns3d/g' "$so_file" 2>/dev/null
                    sed -i 's/isVip/1sV1p/g' "$so_file" 2>/dev/null
                    NATIVE_PATCHED=$((NATIVE_PATCHED + 1))
                fi
                
                # Replace root checks
                if echo "$INTERESTING" | grep -qi 'isRooted\|isDeviceRooted'; then
                    # Patch binary: change return value from true to false
                    # Look for common patterns in ARM/x86 assembly
                    python3 -c "
import sys
with open('$so_file', 'rb') as f:
    data = bytearray(f.read())
# ARM64: mov w0, #1 -> mov w0, #0
# Pattern: 20 00 80 52 (mov w0, #1)
patched = data.replace(b'\x20\x00\x80\x52', b'\x00\x00\x80\x52')
with open('$so_file', 'wb') as f:
    f.write(patched)
" 2>/dev/null
                    NATIVE_PATCHED=$((NATIVE_PATCHED + 1))
                fi
                
                add_vuln "RT-759" "HIGH" "Native Library Patched" "Native library $SO_NAME modified" "apk" "full" "MITRE T1637"
            fi
        fi
    done
    
    if [[ "$NATIVE_PATCHED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $NATIVE_PATCHED native libraries patched$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
    else
        echo -e "    $YELLOW[!] No patchable native library functions found$NC"
    fi
}


# Module RT-760: APK Rebuild and Signing
rt_760_apk_rebuild_sign() {
    rt_banner "RT-760" "APK Rebuild and Signature"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    echo -e "    $CYAN[*] Rebuilding modified APK...$NC"
    
    local MODDED_APK="$APK_OUTPUT_DIR/$(basename "$APK_TARGET" .apk)_modded.apk"
    local ALIGNED_APK="$APK_OUTPUT_DIR/$(basename "$APK_TARGET" .apk)_aligned.apk"
    local SIGNED_APK="$APK_OUTPUT_DIR/$(basename "$APK_TARGET" .apk)_signed.apk"
    
    # Step 1: Rebuild with apktool
    echo -e "    $CYAN[*] Building APK...$NC"
    if apktool b -o "$MODDED_APK" "$APK_DECODED_DIR" 2>/dev/null; then
        echo -e "    $GREEN[+] APK rebuilt: $MODDED_APK$NC"
    else
        echo -e "    $RED[-] apktool build failed$NC"
        # Try with --use-aapt2
        if apktool b --use-aapt2 -o "$MODDED_APK" "$APK_DECODED_DIR" 2>/dev/null; then
            echo -e "    $GREEN[+] APK rebuilt with aapt2: $MODDED_APK$NC"
        else
            echo -e "    $RED[-] Build failed completely — patches may need manual application$NC"
            return 1
        fi
    fi
    
    # Step 2: ZipAlign
    if command -v zipalign &>/dev/null; then
        echo -e "    $CYAN[*] Aligning APK...$NC"
        zipalign -f 4 "$MODDED_APK" "$ALIGNED_APK" 2>/dev/null
        if [[ -f "$ALIGNED_APK" ]]; then
            echo -e "    $GREEN[+] APK aligned: $ALIGNED_APK$NC"
            MODDED_APK="$ALIGNED_APK"
        fi
    else
        echo -e "    $YELLOW[!] zipalign not available — skipping alignment$NC"
    fi
    
    # Step 3: Sign APK
    echo -e "    $CYAN[*] Signing APK...$NC"
    
    # Check for signing tools
    if command -v apksigner &>/dev/null; then
        # Generate key if not exists
        local KEYSTORE="$SESSION/apk/mod_keystore.jks"
        if [[ ! -f "$KEYSTORE" ]]; then
            keytool -genkey -v -keystore "$KEYSTORE" -alias modkey -keyalg RSA -keysize 2048 -validity 10000 -storepass modpass -keypass modpass -dname "CN=Mod, O=Mod, C=US" 2>/dev/null
        fi
        apksigner sign --ks "$KEYSTORE" --ks-pass pass:modpass --key-pass pass:modpass --out "$SIGNED_APK" "$MODDED_APK" 2>/dev/null
        
    elif command -v jarsigner &>/dev/null; then
        local KEYSTORE="$SESSION/apk/mod_keystore.jks"
        if [[ ! -f "$KEYSTORE" ]]; then
            keytool -genkey -v -keystore "$KEYSTORE" -alias modkey -keyalg RSA -keysize 2048 -validity 10000 -storepass modpass -keypass modpass -dname "CN=Mod, O=Mod, C=US" 2>/dev/null
        fi
        cp "$MODDED_APK" "$SIGNED_APK" 2>/dev/null
        jarsigner -verbose -sigalg SHA256withRSA -digestalg SHA-256 -keystore "$KEYSTORE" -storepass modpass "$SIGNED_APK" modkey 2>/dev/null
        
    elif command -v uber-apk-signer &>/dev/null; then
        uber-apk-signer -a "$MODDED_APK" -o "$APK_OUTPUT_DIR" 2>/dev/null
        SIGNED_APK="$APK_OUTPUT_DIR/$(basename "$MODDED_APK" .apk)-aligned-signed.apk"
        
    else
        # Fallback: sign with Android debug key
        local DEBUG_KEY="$HOME/.android/debug.keystore"
        if [[ ! -f "$DEBUG_KEY" ]]; then
            mkdir -p "$HOME/.android" 2>/dev/null
            keytool -genkey -v -keystore "$DEBUG_KEY" -alias androiddebugkey -keyalg RSA -validity 10000 -storepass android -keypass android -dname "CN=Android Debug,O=Android,C=US" 2>/dev/null
        fi
        cp "$MODDED_APK" "$SIGNED_APK" 2>/dev/null
        jarsigner -keystore "$DEBUG_KEY" -storepass android -keypass android "$SIGNED_APK" androiddebugkey 2>/dev/null
    fi
    
    # Step 4: Verify
    if [[ -f "$SIGNED_APK" ]]; then
        local FINAL_SIZE
        FINAL_SIZE=$(stat -c%s "$SIGNED_APK" 2>/dev/null)
        echo -e "    $GREEN[+] Signed APK: $SIGNED_APK$NC"
        echo -e "    $GREEN[+] Size: $((FINAL_SIZE / 1024)) KB$NC"
        
        # Copy to user-friendly location
        cp "$SIGNED_APK" "/sdcard/download/$(basename "$APK_TARGET" .apk)_modded_signed.apk" 2>/dev/null
        echo -e "    $GREEN[+] Also saved to: /sdcard/download/$(basename "$APK_TARGET" .apk)_modded_signed.apk$NC"
        
        # Verify signature
        if command -v apksigner &>/dev/null; then
            apksigner verify -v "$SIGNED_APK" 2>/dev/null
        fi
        
        add_vuln "RT-760" "INFO" "APK Rebuilt and Signed" "Modified APK rebuilt and signed at $SIGNED_APK" "apk" "full" "MITRE T1643"
    else
        echo -e "    $RED[-] Signing failed — unsigned APK at: $MODDED_APK$NC"
        echo -e "    $YELLOW[!] Install unsigned: adb install -r -d $MODDED_APK (requires root)$NC"
    fi
}

# Module RT-761: Resource String Extraction and Modification
rt_761_resource_string_extraction() {
    rt_banner "RT-761" "Resource String Extraction and Hardcoded Secret Discovery"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    echo -e "    $CYAN[*] Extracting strings and searching for secrets...$NC"
    
    local SECRETS_FOUND=0
    local SECRETS_FILE="$SESSION/apk/secrets_found.txt"
    > "$SECRETS_FILE" 2>/dev/null
    
    # Search for API keys and secrets in strings.xml
    if [[ -f "$APK_DECODED_DIR/res/values/strings.xml" ]]; then
        local API_KEYS
        API_KEYS=$(grep -oiE '(api_key|apikey|api_secret|secret|token|password|auth|client_id|client_secret)"[^>]*>[^<]+' "$APK_DECODED_DIR/res/values/strings.xml" 2>/dev/null)
        
        if [[ -n "$API_KEYS" ]]; then
            echo -e "    $RED[CRITICAL] Hardcoded secrets in strings.xml:$NC"
            echo "$API_KEYS" | head -10 | while read -r key; do
                echo -e "        $RED$key$NC"
                echo "strings.xml: $key" >> "$SECRETS_FILE" 2>/dev/null
            done
            SECRETS_FOUND=$((SECRETS_FOUND + 1))
        fi
    fi
    
    # Search for URLs and endpoints
    local URLS
    URLS=$(find "$APK_DECODED_DIR" -name "*.xml" -o -name "*.smali" 2>/dev/null | xargs grep -ohE 'https?://[^"\s<>]+' 2>/dev/null | sort -u | head -20)
    
    if [[ -n "$URLS" ]]; then
        echo -e "    $CYAN[*] URLs/endpoints found:$NC"
        echo "$URLS" | while read -r url; do
            echo -e "        $CYAN$url$NC"
            echo "URL: $url" >> "$SECRETS_FILE" 2>/dev/null
        done
        SECRETS_FOUND=$((SECRETS_FOUND + 1))
    fi
    
    # Search for Firebase URLs
    local FIREBASE_URLS
    FIREBASE_URLS=$(find "$APK_DECODED_DIR" -type f 2>/dev/null | xargs grep -ohE 'https://[^"\s]*firebaseio\.com[^"\s]*' 2>/dev/null | sort -u)
    if [[ -n "$FIREBASE_URLS" ]]; then
        echo -e "    $RED[CRITICAL] Firebase database URLs found:$NC"
        echo "$FIREBASE_URLS" | while read -r url; do
            echo -e "        $RED$url$NC"
            # Test if firebase is open
            local FIREBASE_TEST
            FIREBASE_TEST=$(curl -sk "$url/.json" --connect-timeout 5 2>/dev/null | head -50)
            if [[ -n "$FIREBASE_TEST" ]] && [[ "$FIREBASE_TEST" != "null" ]]; then
                echo -e "            $RED[CRITICAL] Firebase is OPEN — data accessible!$NC"
                echo "OPEN FIREBASE: $url" >> "$SECRETS_FILE" 2>/dev/null
            fi
        done
        SECRETS_FOUND=$((SECRETS_FOUND + 1))
        add_vuln "RT-761" "CRITICAL" "Firebase Exposed" "Firebase database URLs found with potential open access" "apk" "full" "MITRE T1416"
    fi
    
    # Search for AWS keys
    local AWS_KEYS
    AWS_KEYS=$(find "$APK_DECODED_DIR" -type f 2>/dev/null | xargs grep -ohE 'AKIA[0-9A-Z]{16}' 2>/dev/null | sort -u)
    if [[ -n "$AWS_KEYS" ]]; then
        echo -e "    $RED[CRITICAL] AWS Access Keys found:$NC"
        echo "$AWS_KEYS" | while read -r key; do
            echo -e "        $RED$key$NC"
            echo "AWS_KEY: $key" >> "$SECRETS_FILE" 2>/dev/null
        done
        SECRETS_FOUND=$((SECRETS_FOUND + 1))
        add_vuln "RT-761" "CRITICAL" "AWS Keys Leaked" "AWS access keys hardcoded in APK" "apk" "full" "MITRE T1644"
    fi
    
    # Search for private keys
    local PRIV_KEYS
    PRIV_KEYS=$(find "$APK_DECODED_DIR" -type f \( -name "*.pem" -o -name "*.key" -o -name "*.p12" -o -name "*.pkcs12" \) 2>/dev/null)
    if [[ -n "$PRIV_KEYS" ]]; then
        echo -e "    $RED[CRITICAL] Private key files found:$NC"
        echo "$PRIV_KEYS" | while read -r f; do
            echo -e "        $RED$f$NC"
        done
        SECRETS_FOUND=$((SECRETS_FOUND + 1))
        add_vuln "RT-761" "CRITICAL" "Private Keys in APK" "Private key files bundled in APK" "apk" "full" "MITRE T1644"
    fi
    
    # Extract and decode base64 strings
    local B64_STRINGS
    B64_STRINGS=$(find "$APK_DECODED_DIR" -name "*.smali" 2>/dev/null | xargs grep -ohE '[A-Za-z0-9+/]{40,}={0,2}' 2>/dev/null | while read -r b64; do
        decoded=$(echo "$b64" | base64 -d 2>/dev/null)
        if [[ -n "$decoded" ]] && [[ "$decoded" == *"http"* || "$decoded" == *"key"* || "$decoded" == *"token"* || "$decoded" == *"password"* || "$decoded" == *"api"* ]]; then
            echo "BASE64: $b64 -> $decoded"
        fi
    done)
    
    if [[ -n "$B64_STRINGS" ]]; then
        echo -e "    $RED[+] Interesting base64 decoded strings:$NC"
        echo "$B64_STRINGS" | head -5
        SECRETS_FOUND=$((SECRETS_FOUND + 1))
    fi
    
    # Show certificate info
    if [[ -f "$APK_DECODED_DIR/original/META-INF/CERT.RSA" ]] || ls "$APK_DECODED_DIR"/original/META-INF/*.RSA >/dev/null 2>&1; then
        local CERT_FILE
        CERT_FILE=$(find "$APK_DECODED_DIR/original/META-INF" -name "*.RSA" -o -name "*.DSA" 2>/dev/null | head -1)
        if [[ -n "$CERT_FILE" ]] && command -v keytool &>/dev/null; then
            echo -e "    $CYAN[*] Certificate info:$NC"
            keytool -printcert -file "$CERT_FILE" 2>/dev/null | head -10
        fi
    fi
    
    if [[ "$SECRETS_FOUND" -gt 0 ]]; then
        echo -e "    $GREEN[+] $SECRETS_FOUND secret categories found — saved to $SECRETS_FILE$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
    else
        echo -e "    $YELLOW[!] No obvious secrets found in resources$NC"
    fi
}

# Module RT-762: AndroidManifest.xml Permission Analysis and Patching
rt_762_manifest_permission_patch() {
    rt_banner "RT-762" "AndroidManifest Permission Analysis and Patching"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]] || [[ ! -f "$APK_DECODED_DIR/AndroidManifest.xml" ]]; then
        return 1
    fi
    
    local MANIFEST="$APK_DECODED_DIR/AndroidManifest.xml"
    local PERM_PATCHED=0
    
    echo -e "    $CYAN[*] Analyzing AndroidManifest.xml permissions...$NC"
    
    # List all requested permissions
    local PERMISSIONS
    PERMISSIONS=$(grep -oP 'android:name="android\.permission\.\K[^"]+' "$MANIFEST" 2>/dev/null | sort -u)
    
    if [[ -n "$PERMISSIONS" ]]; then
        echo -e "    $CYAN[*] Requested permissions:$NC"
        echo "$PERMISSIONS" | while read -r perm; do
            local LEVEL="NORMAL"
            case "$perm" in
                INTERNET|ACCESS_NETWORK_STATE|ACCESS_WIFI_STATE|BLUETOOTH|NFC|VIBRATE|FLASHLIGHT|RECEIVE_BOOT_COMPLETED|WAKE_LOCK|FOREGROUND_SERVICE)
                    LEVEL="NORMAL"
                    ;;
                READ_EXTERNAL_STORAGE|WRITE_EXTERNAL_STORAGE|READ_CONTACTS|READ_SMS|CAMERA|RECORD_AUDIO|ACCESS_FINE_LOCATION|ACCESS_COARSE_LOCATION|READ_PHONE_STATE|CALL_PHONE|SEND_SMS)
                    LEVEL="DANGEROUS"
                    ;;
                SYSTEM_ALERT_WINDOW|WRITE_SETTINGS|REQUEST_INSTALL_PACKAGES)
                    LEVEL="SIGNATURE"
                    ;;
                READ_PRIVILEGED_PHONE_STATE|MOUNT_UNMOUNT_FILESYSTEMS|WRITE_SECURE_SETTINGS|DELETE_PACKAGES|MASTER_CLEAR)
                    LEVEL="PRIVILEGED"
                    ;;
            esac
            echo -e "        $LEVEL: $perm"
        done
        
        add_vuln "RT-762" "INFO" "Permissions Listed" "$(echo "$PERMISSIONS" | wc -l) permissions found in manifest" "apk" "full" "MITRE T1635"
    fi
    
    # Remove unnecessary permissions
    local DANGEROUS_PERMS_TO_REMOVE="READ_CONTACTS READ_SMS READ_CALL_LOG READ_CALENDAR CAMERA RECORD_AUDIO ACCESS_FINE_LOCATION ACCESS_COARSE_LOCATION READ_PHONE_STATE"
    for perm in $DANGEROUS_PERMS_TO_REMOVE; do
        if grep -q "android.permission.$perm" "$MANIFEST" 2>/dev/null; then
            echo -e "    $YELLOW[!] Removing dangerous permission: $perm$NC"
            sed -i "/android.permission.$perm/d" "$MANIFEST" 2>/dev/null
            PERM_PATCHED=$((PERM_PATCHED + 1))
        fi
    done
    
    # Add useful permissions for modded APK
    local USEFUL_PERMS=(
        '    <uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE"/>'
        '    <uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE"/>'
        '    <uses-permission android:name="android.permission.REQUEST_INSTALL_PACKAGES"/>'
        '    <uses-permission android:name="android.permission.SYSTEM_ALERT_WINDOW"/>'
    )
    
    for perm_line in "${USEFUL_PERMS[@]}"; do
        local PERM_NAME
        PERM_NAME=$(echo "$perm_line" | grep -oP 'name="\K[^"]+')
        if ! grep -q "$PERM_NAME" "$MANIFEST" 2>/dev/null; then
            sed -i "/<\/manifest>/i $perm_line" "$MANIFEST" 2>/dev/null
            PERM_PATCHED=$((PERM_PATCHED + 1))
        fi
    done
    
    # Enable cleartext traffic
    if ! grep -q 'usesCleartextTraffic="true"' "$MANIFEST" 2>/dev/null; then
        sed -i 's/<application /<application android:usesCleartextTraffic="true" /' "$MANIFEST" 2>/dev/null
        echo -e "    $GREEN[+] Cleartext traffic enabled$NC"
        PERM_PATCHED=$((PERM_PATCHED + 1))
    fi
    
    # Add queries for package visibility (Android 11+)
    if ! grep -q "<queries>" "$MANIFEST" 2>/dev/null; then
        sed -i '/<\/manifest>/i \\    <queries>\n        <intent>\n            <action android:name="android.intent.action.MAIN"/>\n        </intent>\n    </queries>' "$MANIFEST" 2>/dev/null
    fi
    
    if [[ "$PERM_PATCHED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $PERM_PATCHED manifest permission changes applied$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
    fi
}

# Module RT-763: Signature Verification Bypass
rt_763_signature_verification_bypass() {
    rt_banner "RT-763" "APK Signature Verification Bypass"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    local SIG_BYPASSED=0
    
    echo -e "    $CYAN[*] Bypassing signature verification checks...$NC"
    
    # Find signature check methods
    local SIG_CHECKS
    SIG_CHECKS=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "getPackageSignature\|getPackageSign\|checkSignature\|verifySignature\|getApkSign\|signatures\|SigningCertificates" {} \; 2>/dev/null)
    
    if [[ -n "$SIG_CHECKS" ]]; then
        echo -e "    $RED[+] Signature verification found in $(echo "$SIG_CHECKS" | wc -l) files$NC"
        
        for smali_file in $SIG_CHECKS; do
            # Patch signature comparison to always match
            if grep -q "invoke-virtual.*compare\|invoke-static.*compare\|invoke-virtual.*equals" "$smali_file" 2>/dev/null; then
                # Change move-result to always true after comparison
                sed -i '/invoke-virtual.*compare.*signature/,/move-result/{s/move-result v[0-9]*/const\/4 v0, 0x1/}' "$smali_file" 2>/dev/null
                SIG_BYPASSED=$((SIG_BYPASSED + 1))
            fi
            
            # Patch getPackageSignature to return empty or hardcoded value
            if grep -q "\.method.*getPackageSignature\|\.method.*getSignatures" "$smali_file" 2>/dev/null; then
                # Force the method to return success
                sed -i '/\.method.*getPackageSignature/,/\.end method/{s/const\/4 v0, 0x0/const\/4 v0, 0x1/}' "$smali_file" 2>/dev/null
                SIG_BYPASSED=$((SIG_BYPASSED + 1))
            fi
            
            # Patch PackageManager.getPackageSignatures
            sed -i 's/invoke-virtual.*getPackageSignatures/const\/4 v0, 0x0  # BYPASSED: &/' "$smali_file" 2>/dev/null
        done
    fi
    
    # Patch PackageManager signature check for self
    local PM_CHECKS
    PM_CHECKS=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "getPackageManager\|Landroid/content/pm/PackageManager" {} \; 2>/dev/null)
    
    if [[ -n "$PM_CHECKS" ]]; then
        for f in $PM_CHECKS; do
            # Find signature verification using PackageManager
            if grep -q "GET_SIGNATURES\|GET_SIGNING_CERTIFICATES\|PackageInfo.*signatures" "$f" 2>/dev/null; then
                # Replace signature array access with null
                sed -i 's/iget-object.*signatures/const\/4 v0, 0x0  # BYPASSED/' "$f" 2>/dev/null
                SIG_BYPASSED=$((SIG_BYPASSED + 1))
            fi
        done
    fi
    
    # Remove signature files from META-INF for rebuild
    if [[ -d "$APK_DECODED_DIR/original/META-INF" ]]; then
        rm -f "$APK_DECODED_DIR/original/META-INF"/*.RSA 2>/dev/null
        rm -f "$APK_DECODED_DIR/original/META-INF"/*.DSA 2>/dev/null
        rm -f "$APK_DECODED_DIR/original/META-INF"/*.SF 2>/dev/null
        echo -e "    $GREEN[+] Old signature files removed from META-INF$NC"
        SIG_BYPASSED=$((SIG_BYPASSED + 1))
    fi
    
    if [[ "$SIG_BYPASSED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $SIG_BYPASSED signature checks bypassed$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
        add_vuln "RT-763" "CRITICAL" "Signature Verification Bypassed" "$SIG_BYPASSED signature verification checks bypassed" "apk" "full" "MITRE T1635"
    else
        echo -e "    $YELLOW[!] No signature verification found$NC"
    fi
}

# Module RT-764: Smali Code Injection for Feature Unlock
rt_764_smali_feature_injection() {
    rt_banner "RT-764" "Smali Feature Unlock Code Injection"
    
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then
        return 1
    fi
    
    local INJECTED=0
    
    echo -e "    $CYAN[*] Injecting feature unlocks into smali...$NC"
    
    # Find onCreate method of MainActivity and inject hooks
    local MAIN_ACTIVITY
    MAIN_ACTIVITY=$(grep -oP 'android:name="\K[^"]+"' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null | grep -i "mainactivity\|launcher" | head -1 | tr -d '"')
    
    if [[ -z "$MAIN_ACTIVITY" ]]; then
        MAIN_ACTIVITY=$(grep -A2 'android.intent.action.MAIN' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null | grep 'android:name' | head -1 | grep -oP 'android:name="\K[^"]+')
    fi
    
    if [[ -n "$MAIN_ACTIVITY" ]]; then
        local ACTIVITY_PATH
        ACTIVITY_PATH=$(echo "$MAIN_ACTIVITY" | tr '.' '/') 
        local SMALI_ACTIVITY
        SMALI_ACTIVITY=$(find "$APK_DECODED_DIR" -name "${ACTIVITY_PATH##*/}.smali" 2>/dev/null | head -1)
        
        if [[ -f "$SMALI_ACTIVITY" ]]; then
            echo -e "    $CYAN[*] MainActivity: $SMALI_ACTIVITY$NC"
            
            # Find onCreate method and inject after super.onCreate call
            local ONCREATE_LINE
            ONCREATE_LINE=$(grep -n "invoke-super.*onCreate\|Landroid/app/Activity;->onCreate" "$SMALI_ACTIVITY" 2>/dev/null | tail -1 | cut -d: -f1)
            
            if [[ -n "$ONCREATE_LINE" ]]; then
                # Inject logging toast to confirm mod is active
                sed -i "$((ONCREATE_LINE + 1))a\\\n    # MOD INJECTION START\n    const-string v0, \"MOD ACTIVE\"\n    const/4 v1, 0x1\n    invoke-static {v0, v1}, Landroid/widget/Toast;->makeText(Landroid/content/Context;Ljava/lang/CharSequence;I)Landroid/widget/Toast;\n    move-result-object v0\n    invoke-virtual {v0}, Landroid/widget/Toast;->show()V\n    # MOD INJECTION END" "$SMALI_ACTIVITY" 2>/dev/null
                
                INJECTED=$((INJECTED + 1))
                echo -e "    $GREEN[+] Mod toast injected into onCreate$NC"
            fi
        fi
    fi
    
    # Universal feature unlock: find setEnabled/setVisible gates and force them
    local FEATURE_GATES
    FEATURE_GATES=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "setEnabled.*false\|setVisible.*false\|GONE\|INVISIBLE" {} \; 2>/dev/null)
    
    if [[ -n "$FEATURE_GATES" ]]; then
        echo -e "    $CYAN[*] Feature gates found — forcing enabled$NC"
        for f in $FEATURE_GATES; do
            # Change setEnabled(false) to setEnabled(true)
            sed -i 's/const\/4 v[0-9], 0x0\n.*setEnabled/const\/4 v0, 0x1\n    invoke-virtual {p0, v0}, Landroid\/view\/View;->setEnabled(Z)V/' "$f" 2>/dev/null
            # Change visibility GONE to VISIBLE
            sed -i 's/const\/16 v[0-9], 0x8\n.*setVisibility/const\/16 v0, 0x0\n    invoke-virtual {p0, v0}, Landroid\/view\/View;->setVisibility(I)V/' "$f" 2>/dev/null
            INJECTED=$((INJECTED + 1))
        done
    fi
    
    # Force menu items to be visible (premium menu items)
    local MENU_FILES
    MENU_FILES=$(find "$APK_DECODED_DIR/res/menu" -name "*.xml" 2>/dev/null)
    if [[ -n "$MENU_FILES" ]]; then
        echo -e "    $CYAN[*] Menu files found — making all items visible$NC"
        for menu in $MENU_FILES; do
            sed -i 's/android:visible="false"/android:visible="true"/g' "$menu" 2>/dev/null
            sed -i 's/android:enabled="false"/android:enabled="true"/g' "$menu" 2>/dev/null
        done
        INJECTED=$((INJECTED + 1))
    fi
    
    if [[ "$INJECTED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $INJECTED feature unlock injections applied$NC"
        APK_PATCHES_APPLIED=$((APK_PATCHES_APPLIED + 1))
        add_vuln "RT-764" "HIGH" "Feature Unlock Injected" "$INJECTED feature unlock injections applied" "apk" "full" "MITRE T1638"
    fi
}

# Module RT-765: APK Modification Report
rt_765_apk_mod_report() {
    rt_banner "RT-765" "APK Modification Summary Report"
    
    if ! is_apk_target; then
        return 1
    fi
    
    local REPORT="$SESSION/apk/modification_report.txt"
    cat > "$REPORT" 2>/dev/null << APKREPORT
═══════════════════════════════════════════════════════════════
   APK MODIFICATION REPORT
═══════════════════════════════════════════════════════════════
APK: $(basename "$APK_TARGET")
Package: ${APK_PACKAGE:-unknown}
Output: $APK_OUTPUT_DIR
Total Patches Applied: $APK_PATCHES_APPLIED

Modules Executed:
  RT-751: APK Detection and Decompilation
  RT-752: Ad Network Detection and Removal
  RT-753: VIP and Premium Feature Unlock
  RT-754: SSL Certificate Pinning Bypass
