rt_766_apk_clone_repackage() {
    rt_banner "RT-766" "APK Clone and Full Repackage"
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then return 1; fi
    local CLONE_DIR="$APK_DECODED_DIR"
    echo -e "    $CYAN[*] Cloning APK with new identity...$NC"
    # Generate random package suffix to avoid signature conflict
    local RAND_SUFFIX="$(tr -dc 'a-z0-9' </dev/urandom 2>/dev/null | head -c6)"
    local ORIG_PKG="$APK_PACKAGE"
    local NEW_PKG="${ORIG_PKG}.${RAND_SUFFIX}"
    # Change package in manifest
    if [[ -f "$CLONE_DIR/AndroidManifest.xml" ]] && [[ -n "$ORIG_PKG" ]]; then
        sed -i "s/\"${ORIG_PKG}\"/\"${NEW_PKG}\"/g" "$CLONE_DIR/AndroidManifest.xml" 2>/dev/null
        echo -e "    $GREEN[+] Package changed: $ORIG_PKG → $NEW_PKG$NC"
    fi
    # Change application label to indicate mod
    if [[ -f "$CLONE_DIR/res/values/strings.xml" ]]; then
        sed -i 's/<string name=\"app_name\">\([^<]*\)/<string name=\"app_name\">\1 [MOD]/' "$CLONE_DIR/res/values/strings.xml" 2>/dev/null
        echo -e "    $GREEN[+] App label marked as [MOD]$NC"
    fi
    # Update smali package paths
    local PKG_PATH="$(echo "$ORIG_PKG" | tr '.' '/')"
    local NEW_PKG_PATH="$(echo "$NEW_PKG" | tr '.' '/')"
    if [[ -d "$CLONE_DIR/smali/$PKG_PATH" ]]; then
        mkdir -p "$CLONE_DIR/smali/$(dirname "$NEW_PKG_PATH")" 2>/dev/null
        cp -r "$CLONE_DIR/smali/$PKG_PATH" "$CLONE_DIR/smali/$NEW_PKG_PATH" 2>/dev/null
        echo -e "    $GREEN[+] Smali paths cloned$NC"
    fi
    # Update R.java references in all smali
    find "$CLONE_DIR" -name "*.smali" -exec sed -i "s/L${PKG_PATH}\//L${NEW_PKG_PATH}\//g" {} \; 2>/dev/null
    echo -e "    $GREEN[+] All smali references updated$NC"
    APK_PACKAGE="$NEW_PKG"
    add_vuln "RT-766" "HIGH" "APK Cloned" "Package renamed from $ORIG_PKG to $NEW_PKG" "apk" "full" "MITRE T1403"
}

rt_767_multi_apk_bundle_mod() {
