        echo "$SPLASH" | while read -r s; do echo -e "        $CYAN$s$NC"; done
    fi
    # Remove app watermark or branding overlays
    local WATERMARK
    WATERMARK=$(find "$APK_DECODED_DIR/res/layout" -name "*.xml" 2>/dev/null | xargs grep -l "watermark\|branding\|logo.*overlay\|beta\|trial" 2>/dev/null)
    if [[ -n "$WATERMARK" ]]; then
        echo -e "    $RED[+] Watermark/branding layouts found — removing$NC"
        for w in $WATERMARK; do
            # Set visibility to gone
            sed -i 's/android:visibility=\"visible\"/android:visibility=\"gone\"/g' "$w" 2>/dev/null
