            sed -i 's/android:alpha=\"1\"/android:alpha=\"0\"/g' "$w" 2>/dev/null
        done
        add_vuln "RT-768" "MEDIUM" "Watermark Removed" "Branding watermarks set to invisible" "apk" "full" "MITRE T1631"
    fi
