rt_769_apk_version_code_override() {
    rt_banner "RT-769" "Version Code Override and Force Update Bypass"
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then return 1; fi
    echo -e "    $CYAN[*] Overriding version information...$NC"
    local AXML="$APK_DECODED_DIR/apktool.yml"
    if [[ -f "$AXML" ]]; then
        # Bump versionCode to max
        sed -i 's/versionCode: .*/versionCode: '99999999'/g' "$AXML" 2>/dev/null
        sed -i 's/versionName: .*/versionName: '999.9.9'/g' "$AXML" 2>/dev/null
        echo -e "    $GREEN[+] Version bumped to 999.9.9 [code: 99999999]$NC"
    fi
    # Also patch in manifest if present
    if [[ -f "$APK_DECODED_DIR/AndroidManifest.xml" ]]; then
        sed -i 's/android:versionCode=\"[^\"]*\"/android:versionCode=\"99999999\"/g' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
        sed -i 's/android:versionName=\"[^\"]*\"/android:versionName=\"999.9.9\"/g' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
        echo -e "    $GREEN[+] Manifest version overridden$NC"
    fi
    # Patch in-app update check to always return latest
    local UPDATE_CHECKS
    UPDATE_CHECKS=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "versionCode\|versionName\|needsUpdate\|forceUpdate\|checkUpdate" {} \; 2>/dev/null)
    if [[ -n "$UPDATE_CHECKS" ]]; then
        echo -e "    $RED[+] Update check methods found — patching to no-op$NC"
        for f in $UPDATE_CHECKS; do
            sed -i '/\.method.*checkUpdate\|\.method.*needsUpdate/,/\.end method/{s/const\/4 v0, 0x1/const\/4 v0, 0x0/}' "$f" 2>/dev/null
        done
        add_vuln "RT-769" "HIGH" "Update Check Bypassed" "Version code set to max, update checks disabled" "apk" "full" "MITRE T1631"
    fi
}

rt_770_apk_auto_install_script() {
    rt_banner "RT-770" "Auto-Install ADB Script Generator"
    if ! is_apk_target; then return 1; fi
    local INSTALL_SCRIPT="$APK_OUTPUT_DIR/install_modded.sh"
    cat > "$INSTALL_SCRIPT" << 'INSTSCRIPT' 2>/dev/null
#!/bin/bash
# Auto-install script for modded APK
echo "[+] Installing modded APK..."
adb devices | grep -q "device$" || { echo "[-] No ADB device connected"; exit 1; }
# Uninstall original if exists
adb shell pm list packages | grep -i "ORIGINAL_PACKAGE" && adb uninstall "ORIGINAL_PACKAGE" 2>/dev/null
# Install modded
adb install -r -d "MODDED_APK_PATH" && echo "[+] Installation successful" || echo "[-] Install failed"
# Grant all permissions
for perm in $(aapt d permissions "MODDED_APK_PATH" 2>/dev/null | grep "uses-permission:" | cut -d: -f2 | tr -d ' '); do
    adb shell pm grant "NEW_PACKAGE" "$perm" 2>/dev/null || true
done
echo "[+] All permissions granted"
INSTSCRIPT
    # Replace placeholders
    sed -i "s|ORIGINAL_PACKAGE|${APK_PACKAGE%%.*}|g" "$INSTALL_SCRIPT" 2>/dev/null
    sed -i "s|MODDED_APK_PATH|\$1|g" "$INSTALL_SCRIPT" 2>/dev/null
    sed -i "s|NEW_PACKAGE|$APK_PACKAGE|g" "$INSTALL_SCRIPT" 2>/dev/null
    chmod +x "$INSTALL_SCRIPT" 2>/dev/null
    echo -e "    $GREEN[+] Install script: $INSTALL_SCRIPT$NC"
    add_vuln "RT-770" "INFO" "Install Script Generated" "ADB auto-install script created" "apk" "full" "MITRE T1403"
}

