rt_771_smali_method_hook_inject() {
    rt_banner "RT-771" "Smali Method Hook and Intercept Injection"
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then return 1; fi
    echo -e "    $CYAN[*] Injecting method hooks into smali...$NC"
    local HOOKED=0
    # Find all methods returning boolean that look like gates
    local GATE_METHODS
    GATE_METHODS=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "isPro\|isPremium\|isVip\|isSubscribed\|isLicensed\|isValid\|isPaid\|canUse\|hasFeature\|isUnlocked" {} \; 2>/dev/null)
    if [[ -n "$GATE_METHODS" ]]; then
        for f in $GATE_METHODS; do
            # For each .method that returns boolean, inject const/4 v0, 0x1 and return immediately
            local METHOD_LINES
            METHOD_LINES=$(grep -n "\.method.*public.*is[A-Z].*Z\|\.method.*public.*has[A-Z].*Z\|\.method.*public.*can[A-Z].*Z" "$f" 2>/dev/null | cut -d: -f1)
            for mline in $METHOD_LINES; do
                # Find .end method line
                local END_LINE
                END_LINE=$(sed -n "$mline,/\.end method/p" "$f" 2>/dev/null | grep -n "\.end method" | head -1 | cut -d: -f1)
                if [[ -n "$END_LINE" ]]; then
                    # Find locals line and insert after it
                    local REL_LOCALS
                    REL_LOCALS=$(sed -n "$mline,$((mline + END_LINE))p" "$f" 2>/dev/null | grep -n "\.locals" | head -1 | cut -d: -f1)
                    if [[ -n "$REL_LOCALS" ]]; then
                        local INSERT=$((mline + REL_LOCALS))
                        sed -i "${INSERT}a\\    const/4 v0, 0x1\n    return v0\n    # HOOK_INJECTED" "$f" 2>/dev/null
                        HOOKED=$((HOOKED + 1))
                    fi
                fi
            done
        done
    fi
    if [[ "$HOOKED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $HOOKED boolean gate methods hooked to return true$NC"
        add_vuln "RT-771" "CRITICAL" "Method Hooks Injected" "$HOOKED premium gate methods intercepted" "apk" "full" "MITRE T1638"
    else
        echo -e "    $YELLOW[!] No boolean gate methods found$NC"
    fi
}

rt_772_smali_toast_logger_inject() {
