        local MATCHES
        MATCHES=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "\.method.*${method}" {} \; 2>/dev/null | head -10)
        for f in $MATCHES; do
            # Only inject once per file
            if ! grep -q "TOAST_LOGGER" "$f" 2>/dev/null; then
                local MLINE
                MLINE=$(grep -n "\.method.*${method}" "$f" 2>/dev/null | head -1 | cut -d: -f1)
