    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then return 1; fi
    echo -e "    $CYAN[*] Patching network calls to enable logging...$NC"
    local NET_PATCHED=0
    # Find OkHttp and HttpURLConnection usage
    local NET_FILES
    NET_FILES=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "okhttp3\|HttpURLConnection\|URL;->openConnection\|Retrofit" {} \; 2>/dev/null)
    if [[ -n "$NET_FILES" ]]; then
        echo -e "    $RED[+] Network libraries found in $(echo "$NET_FILES" | wc -l) files$NC"
        for f in $NET_FILES; do
            # Enable OkHttp logging interceptor
            if grep -q "OkHttpClient\$Builder" "$f" 2>/dev/null; then
                # Add logging level to BODY
                sed -i '/new-instance.*Builder/a\\n    # INTERCEPTOR: Logging enabled\n    sget-object v0, Lokhttp3/logging/HttpLoggingInterceptor$Level;->BODY:Lokhttp3/logging/HttpLoggingInterceptor$Level;\n    # END_INTERCEPTOR' "$f" 2>/dev/null
                NET_PATCHED=$((NET_PATCHED + 1))
            fi
        done
    fi
    # Enable WebView console logging
    local WV_FILES
    WV_FILES=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "setWebContentsDebuggingEnabled\|WebView" {} \; 2>/dev/null)
    if [[ -n "$WV_FILES" ]]; then
        for f in $WV_FILES; do
            if grep -q "Landroid/webkit/WebView;-><init>" "$f" 2>/dev/null; then
                sed -i '/Landroid\/webkit\/WebView;-><init>/a\\\n    # WEBVIEW_DEBUG\n    const/4 v1, 0x1\n    invoke-static {v1}, Landroid/webkit/WebView;->setWebContentsDebuggingEnabled(Z)V' "$f" 2>/dev/null
                NET_PATCHED=$((NET_PATCHED + 1))
            fi
        done
    fi
    if [[ "$NET_PATCHED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $NET_PATCHED network debug patches applied$NC"
        add_vuln "RT-773" "MEDIUM" "Network Debug Enabled" "OkHttp logging and WebView debugging enabled" "apk" "full" "MITRE T1638"
    fi
}

rt_774_smali_string_decryptor() {
