    local B64_STRINGS
    B64_STRINGS=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -ohE 'const-string.*\"[A-Za-z0-9+/]{20,}={0,2}\"' {} \; 2>/dev/null)
    if [[ -n "$B64_STRINGS" ]]; then
