    # Look for hex-encoded strings
    local HEX_STRINGS
    HEX_STRINGS=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -ohE 'const-string.*\"[0-9a-fA-F]{40,}\"' {} \; 2>/dev/null)
    if [[ -n "$HEX_STRINGS" ]]; then
        echo -e "    $RED[+] Hex-encoded strings found$NC"
        DECRYPTED=$((DECRYPTED + 1))
    fi
    # XOR-decoded string detection
    local XOR_PATTERNS
    XOR_PATTERNS=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "xor-int\|xor-long" {} \; 2>/dev/null)
