rt_775_smali_dead_code_removal() {
    rt_banner "RT-775" "Dead Code and Unused Method Removal"
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then return 1; fi
    echo -e "    $CYAN[*] Removing dead code and anti-tamper checks...$NC"
    local REMOVED=0
    # Find and remove unused anonymous classes ($1, $2, etc. that are anti-tamper)
    local ANON_CLASSES
    ANON_CLASSES=$(find "$APK_DECODED_DIR" -name "*\$Verify*.smali" -o -name "*\$Checksum*.smali" -o -name "*\$Tamper*.smali" -o -name "*\$Integrity*.smali" 2>/dev/null)
    if [[ -n "$ANON_CLASSES" ]]; then
        echo -e "    $RED[+] Anti-tamper classes found:$NC"
        for c in $ANON_CLASSES; do
            echo -e "        $RED$(basename "$c")$NC"
            rm -f "$c" 2>/dev/null
            REMOVED=$((REMOVED + 1))
        done
    fi
    # Remove CRC/signature verification methods
    local SIG_VERIFY
    SIG_VERIFY=$(find "$APK_DECODED_DIR" -name "*.smali" -exec grep -l "CRC32\|MessageDigest.*MD5\|MessageDigest.*SHA.*verify\|Signature.*verify\|checkIntegrity\|verifyIntegrity" {} \; 2>/dev/null)
    if [[ -n "$SIG_VERIFY" ]]; then
        echo -e "    $RED[+] Integrity verification methods found — patching$NC"
        for f in $SIG_VERIFY; do
            # Replace verification methods with return-void
            sed -i '/\.method.*verifyCRC\|\.method.*checkIntegrity\|\.method.*verifySignature/,/\.end method/{s/\.locals [0-9]*/\.locals 0/; s/new-instance.*MessageDigest/# REMOVED/; s/invoke-.*MessageDigest;->/# REMOVED/; s/invoke-.*Signature;->/# REMOVED/; /\.method/,/\.end method/{s/return-void/return-void/}}' "$f" 2>/dev/null
            # Add early return to integrity check methods
            local MLINE
            MLINE=$(grep -n "\.method.*verifyCRC\|\.method.*checkIntegrity\|\.method.*verifySignature\|\.method.*verifyFile" "$f" 2>/dev/null | head -1 | cut -d: -f1)
            if [[ -n "$MLINE" ]]; then
                sed -i "${MLINE}a\\    return-void\n    # DEAD_CODE_REMOVED" "$f" 2>/dev/null
                REMOVED=$((REMOVED + 1))
            fi
        done
    fi
    if [[ "$REMOVED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $REMOVED anti-tamper elements removed$NC"
        add_vuln "RT-775" "HIGH" "Anti-Tamper Removed" "$REMOVED integrity verification elements removed" "apk" "full" "MITRE T1637"
    else
        echo -e "    $YELLOW[!] No dead code/anti-tamper found$NC"
    fi
}

