rt_776_so_arm64_binary_patch() {
    rt_banner "RT-776" "ARM64 Binary Direct Patching"
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then return 1; fi
    echo -e "    $CYAN[*] Patching ARM64 native libraries...$NC"
    local ARM64_DIR="$APK_DECODED_DIR/lib/arm64-v8a"
    local PATCHED=0
    if [[ -d "$ARM64_DIR" ]]; then
        for so in "$ARM64_DIR"/*.so; do
            if [[ -f "$so" ]]; then
                local SO_NAME
                SO_NAME=$(basename "$so")
                # Search for interesting strings
                local STRINGS
                STRINGS=$(strings "$so" 2>/dev/null | grep -iE 'license.*check|is.*premium|is.*pro|ad.*load|ad.*show|root.*detect' | head -5)
                if [[ -n "$STRINGS" ]]; then
                    echo -e "    $RED[+] $SO_NAME contains: $STRINGS$NC"
                    # ARM64 patch: mov w0, #1 → mov w0, #0 for root detection
                    # Pattern: 20 00 80 52 (mov w0, #1)
                    if command -v python3 &>/dev/null; then
                        python3 -c "
import sys
with open('$so', 'rb') as f: data = bytearray(f.read())
# Patch mov w0, #1 to mov w0, #0 in functions near 'isRooted' or 'isPremium'
count = data.count(b'\x20\x00\x80\x52')
if count > 0:
    patched = data.replace(b'\x20\x00\x80\x52', b'\x00\x00\x80\x52', 5)
    with open('$so', 'wb') as f: f.write(patched)
    print(f'    ARM64 patched {count} mov w0, #1 -> mov w0, #0')
" 2>/dev/null
                        PATCHED=$((PATCHED + 1))
