rt_804_obfuscation_removal() {
    rt_banner "RT-804" "Code Obfuscation Detection and Removal"
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then return 1; fi
    echo -e "    $CYAN[*] Checking for obfuscation patterns...$NC"
    local OBFUSCATED=0
    # Check for ProGuard/R8 obfuscation (short names like a, b, c)
    local SHORT_CLASSES
    SHORT_CLASSES=$(find "$APK_DECODED_DIR/smali" -name "a.smali" -o -name "b.smali" -o -name "c.smali" 2>/dev/null | wc -l)
    if [[ "$SHORT_CLASSES" -gt 20 ]]; then
        echo -e "    $RED[+] ProGuard/R8 obfuscation detected ($SHORT_CLASSES single-letter classes)$NC"
        OBFUSCATED=$((OBFUSCATED + 1))
    fi
    # Check for Allatori
    if find "$APK_DECODED_DIR" -name "*.smali" 2>/dev/null | xargs grep -l "allatori" 2>/dev/null | head -1 | grep -q .; then
        echo -e "    $RED[+] Allatori obfuscation detected$NC"
        OBFUSCATED=$((OBFUSCATED + 1))
    fi
    # Check for Stringer (encrypted strings)
    local STRINGER
    STRINGER=$(find "$APK_DECODED_DIR" -name "*.smali" 2>/dev/null | xargs grep -l "invoke-static.*decrypt\|invoke-static.*decode" 2>/dev/null | head -5)
    if [[ -n "$STRINGER" ]]; then
        echo -e "    $RED[+] String encryption (Stringer) detected$NC"
        OBFUSCATED=$((OBFUSCATED + 1))
    fi
    # Check for control flow obfuscation
    local CF_OBF
    CF_OBF=$(find "$APK_DECODED_DIR" -name "*.smali" 2>/dev/null | xargs grep -c "goto.*:goto_\|if-eqz.*:cond_\|if-nez.*:cond_" 2>/dev/null)
    if [[ "$CF_OBF" -gt 1000 ]]; then
        echo -e "    $RED[+] Heavy control flow obfuscation detected$NC"
        OBFUSCATED=$((OBFUSCATED + 1))
    fi
    # Check for DexGuard/DexProtector
    local DEXGUARD
