        for f in $LOC_FILES; do
            # Patch getLatitude to return fixed value
            sed -i '/\.method.*getLatitude/,/\.end method/{s/const-wide.*0x[0-9a-f]*/const-wide v0, 0x404a633333333333/g}' "$f" 2>/dev/null
            # Patch getLongitude to return fixed value
            sed -i '/\.method.*getLongitude/,/\.end method/{s/const-wide.*0x[0-9a-f]*/const-wide v0, 0x405e99999999999a/g}' "$f" 2>/dev/null
        done
        echo -e "    $GREEN[+] GPS patched to return spoofed coordinates$NC"
        add_vuln "RT-819" "HIGH" "GPS Location Spoofed" "Location services patched to return fake coordinates" "apk" "full" "MITRE T1638"
    fi
}

